async def ensure_control_panel(bot, chat_id: int) -> None:
    """Mantiene la mesa visible y estable salvo que esté minimizada manualmente.

    Version final: ningún refresco automático, cambio de canción, panel fijado ni botón
    normal debe ocultar la mesa. Si está minimizada por el usuario, no se recrea.
    """
    cfg = admin_cfg(chat_id)
    state = get_state(chat_id)

    # Solo el botón explícito de minimizar activa este estado.
    if bool(cfg.get("dj_mesa_minimized", False)):
        return

    # Si no está minimizada, la mesa debe estar visible: editar si existe o crear si falta.
    cfg["dj_mesa_visible"] = True
    cfg["dj_mesa_minimized"] = False
    save_all_states()
    try:
        await _dj_show_or_edit_mesa_v25(bot, chat_id)
    except NameError:
        # Fallback por si cambia el orden de parches en futuras versiones.
        await _old_ensure_control_panel_v23(bot, chat_id)


