# =========================
# V29 DJ: LIVE abre directo + aviso canción independiente funcionando
# =========================
# Ajustes:
# - panel_join_live intenta iniciar/asegurar videochat y abrir enlace.
# - panel_live_toggle, al activar LIVE, intenta abrir el enlace directamente; si no hay URL,
#   deja un mensaje con instrucciones/botón cuando sea posible.
# - panel_announce_now se intercepta al final de la cadena para que siempre funcione.
# - Al activar aviso canción, si ya hay una canción sonando, manda el aviso inmediatamente.
# - El aviso solo lleva ❤️ Me gusta.


def _dj_now_announce_markup_v24() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[InlineKeyboardButton("❤️ Me gusta", callback_data="djlike|current")]])


async def _dj_open_or_explain_live_v29(context: ContextTypes.DEFAULT_TYPE, chat_id: int, *, start_call: bool = True) -> tuple[bool, Optional[str]]:
    """Intenta asegurar el videochat y devolver URL para abrirlo.

    Devuelve (ok, url). Si no hay URL, deja un aviso temporal en el grupo explicando
    que debe abrirse el videochat desde Telegram o configurar VOICE_CHAT_LINKS.
    """
    if start_call:
        try:
            await VOICE.ensure_videochat_started(chat_id)
        except Exception:
            logger.exception("No se pudo iniciar/asegurar videochat en chat %s", chat_id)

    url = await build_live_join_url(context.bot, chat_id)
    if url:
        return True, url

    try:
        await send_temp_message(
            context.bot,
            chat_id,
            (
                "🎧 <b>Directo musical activo</b>\n\n"
                "No puedo abrir el videochat automáticamente porque este grupo no tiene "
                "enlace público/directo configurado.\n\n"
                "Abre el videochat desde la barra superior de Telegram o configura "
                "<code>VOICE_CHAT_LINK</code> / <code>VOICE_CHAT_LINKS</code> en Railway."
            ),
            ttl=45,
        )
    except Exception:
        pass
    return False, None


async def _toggle_dj_announce_now_v29(context: ContextTypes.DEFAULT_TYPE, query, chat_id: int) -> None:
    cfg = admin_cfg(chat_id)
    enabled = not bool(cfg.get("dj_announce_now_enabled", False))
    cfg["dj_announce_now_enabled"] = enabled
    save_all_states()

    await query.answer("Aviso canción " + ("ON" if enabled else "OFF"), show_alert=True)

    # Refrescar mesa sin tocar/minimizar.
    try:
        if not bool(cfg.get("dj_mesa_minimized", False)):
            await ensure_control_panel(context.bot, chat_id)
    except Exception:
        logger.exception("No se pudo refrescar mesa tras cambiar aviso canción")

    # Si se activa con una canción ya sonando, mandar aviso inmediatamente.
    if enabled:
        try:
            state = get_state(chat_id)
            if state.now_playing:
                await _send_dj_now_announce_v24(context.bot, chat_id, Track(**state.now_playing))
        except Exception:
            logger.exception("No se pudo enviar aviso inmediato de canción actual")


_old_callback_router_v29 = callback_router
async def callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    data = q.data if q else ""

    if q and update.effective_chat and update.effective_user:
        chat_id = int(update.effective_chat.id)
        user_id = int(update.effective_user.id)

        # Botón de aviso canción: independiente del panel fijado superior.
        if data == "panel_announce_now":
            if not await is_controller(context, chat_id, user_id):
                await q.answer("Solo DJ/admin.", show_alert=True)
                return
            await _toggle_dj_announce_now_v29(context, q, chat_id)
            return

        # Ir directo: intenta iniciar/asegurar el videochat y abrirlo.
        if data in ("panel_join_live", "panel_voice_info"):
            ok, url = await _dj_open_or_explain_live_v29(context, chat_id, start_call=True)
            if url:
                await q.answer(url=url)
            else:
                await q.answer("Directo activo. Abre el videochat desde arriba o configura enlace del directo.", show_alert=True)
            return

        # LIVE ON/OFF: al activar, arranca videochat y abre enlace si existe.
        if data in ("panel_live_toggle", "panel_pause_resume"):
            if not await is_controller(context, chat_id, user_id):
                await q.answer("Solo el DJ asignado o admin puede controlar el directo.", show_alert=True)
                return
            try:
                live_result = await VOICE.toggle_live(chat_id)
                # Limpieza conservadora: no tocar mesa si está visible.
                try:
                    await cleanup_bot_messages_keep_core(context.bot, chat_id)
                except Exception:
                    pass
                if live_result:
                    ok, url = await _dj_open_or_explain_live_v29(context, chat_id, start_call=True)
                    if url:
                        await q.answer("LIVE ON", url=url)
                    else:
                        await q.answer("LIVE ON. Abre el videochat desde arriba.", show_alert=True)
                    try:
                        await ensure_panel(context.bot, chat_id)
                        await ensure_control_panel(context.bot, chat_id)
                    except Exception:
                        pass
                    return
                else:
                    await q.answer("LIVE OFF")
                    try:
                        await ensure_panel(context.bot, chat_id)
                        await ensure_control_panel(context.bot, chat_id)
                    except Exception:
                        pass
                    return
            except Exception:
                logger.exception("Fallo al ejecutar LIVE ON/OFF en chat %s", chat_id)
                await q.answer("Error al cambiar LIVE.", show_alert=True)
                return

    return await _old_callback_router_v29(update, context)

