# =========================================================
# V30 - Pregonero auto anti-duplicados, validación reforzada,
# previews HTML renderizadas y frase del día con siguiente.
# Mantiene /data/state.json y no resetea configuraciones.
# =========================================================

# --- Helpers de fecha/hora local reutilizables ---
def _v30_local_dt(now_ts: Optional[int] = None):
    try:
        return _local_dt_v15(now_ts)
    except Exception:
        return _dt_v15.fromtimestamp(now_ts or time.time())


def _v30_schedule_key(schedule: Dict[str, Any], now_ts: int) -> str:
    d = _v30_local_dt(now_ts)
    stype = str((schedule or {}).get("type") or "daily")
    if stype == "weekly":
        return f"weekly:{d.strftime('%G-%V')}:{d.weekday()}"
    if stype == "date":
        return f"date:{schedule.get('date') or d.strftime('%Y-%m-%d')}"
    return f"daily:{d.strftime('%Y-%m-%d')}"


# --- Pregonero automático: marcar antes de enviar para que no se repita varias veces. ---
PREGONERO_AUTO_RUNNING_V30: set[str] = set()

async def pregonero_auto_loop(application: Application) -> None:
    """Ejecuta cada pregonero automático una sola vez por vencimiento.

    Importante: marcamos el job como enviado ANTES de llamar a todos. Si el envío tarda
    por ir de 4 en 4, el siguiente tick no vuelve a dispararlo.
    """
    while True:
        await asyncio.sleep(30)
        now = int(time.time())
        for chat_id in list(STATE_CACHE.keys()):
            try:
                cfg = hot_cfg(chat_id)
                jobs = pregonero_auto_jobs(chat_id)
                # Migración blanda de configuraciones antiguas si no hay jobs.
                if bool(cfg.get("pregonero_auto_enabled", False)) and not jobs:
                    sched = cfg.get("pregonero_auto_schedule") if isinstance(cfg.get("pregonero_auto_schedule"), dict) else None
                    if not sched:
                        hhmm = str(cfg.get("pregonero_auto_time", "21:00"))
                        sched = {"type": "daily", "time": hhmm, "label": f"diario {hhmm}"}
                    pregonero_auto_add_job(chat_id, sched)
                    jobs = pregonero_auto_jobs(chat_id)

                for job in list(jobs):
                    if not bool(job.get("pregonero_auto_enabled", job.get("enabled", True))):
                        continue
                    schedule = job.get("pregonero_auto_schedule") if isinstance(job.get("pregonero_auto_schedule"), dict) else {}
                    due_key = _v30_schedule_key(schedule, now)
                    run_key = f"{chat_id}:{int(job.get('id', 0) or 0)}:{due_key}"
                    if run_key in PREGONERO_AUTO_RUNNING_V30:
                        continue
                    if job.get("pregonero_auto_last_key") == due_key or job.get("pregonero_auto_last_day") == due_key:
                        continue
                    if not pregonero_auto_due(job, now):
                        continue

                    # Bloqueo y marca ANTES de enviar para evitar duplicado por tick/reinicio rápido.
                    PREGONERO_AUTO_RUNNING_V30.add(run_key)
                    job["pregonero_auto_last_key"] = due_key
                    job["pregonero_auto_last_day"] = due_key
                    job["pregonero_auto_last_ts"] = now
                    if str(schedule.get("type") or "") == "date":
                        job["pregonero_auto_enabled"] = False
                    save_all_states()
                    try:
                        await send_pregonero(application, chat_id, job=job)
                    finally:
                        PREGONERO_AUTO_RUNNING_V30.discard(run_key)
                    await asyncio.sleep(1)
            except asyncio.CancelledError:
                raise
            except Exception:
                logger.exception("Error en pregonero_auto_loop chat %s", chat_id)


# --- Validación reforzada: cualquier entrada detectada entra en validación. ---
async def validation_new_member(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not validation_is_active_for_chat(chat_id):
        return
    remember_chat_title(chat_id, update.effective_chat.title or "")
    for user in getattr(update.message, "new_chat_members", []) or []:
        if user and not getattr(user, "is_bot", False):
            await start_validation_for_user(
                update,
                context,
                chat_id,
                user,
                reply_to_message_id=update.message.message_id,
                source="service_new_chat_member_v30",
                force=True,
            )


async def validation_chat_join_request(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    req = update.chat_join_request
    if not req or not req.chat or not req.from_user:
        return
    chat_id = int(req.chat.id)
    remember_chat_title(chat_id, getattr(req.chat, "title", "") or "")
    if not validation_is_active_for_chat(chat_id):
        return
    user = req.from_user

    if bool(cfg_value(chat_id, "validation_auto_approve_join_requests", True)):
        try:
            await context.bot.approve_chat_join_request(chat_id=chat_id, user_id=user.id)
        except Exception:
            logger.exception("No pude aprobar la solicitud de entrada de %s en %s", user.id, chat_id)
            try:
                await context.bot.send_message(
                    chat_id=chat_id,
                    text=(
                        f"⚠️ Solicitud detectada de {user.mention_html()}, pero no pude aprobarla. "
                        "Revisa que el bot sea admin con permiso para aprobar solicitudes."
                    ),
                    parse_mode=ParseMode.HTML,
                )
            except Exception:
                pass
            return
        await start_validation_for_user(update, context, chat_id, user, reply_to_message_id=None, source="join_request_auto_approved_v30", force=True)
        return

    # Autoaprobación OFF: queda pendiente de botón admin, pero al aprobar se validará sí o sí.
    remember_entry(chat_id, user, source="join_request_pending_admin_v30")
    key = f"{chat_id}:{user.id}"
    VALIDATION_JOIN_REQUESTS[key] = {
        "chat_id": int(chat_id),
        "user_id": int(user.id),
        "first_name": getattr(user, "first_name", "") or display_name(user),
        "last_name": getattr(user, "last_name", "") or "",
        "username": getattr(user, "username", None),
        "name": display_name(user),
        "ts": _now_ts(),
    }
    keyboard = InlineKeyboardMarkup([[
        InlineKeyboardButton("✅ Aprobar y validar", callback_data=f"valreq|approve|{user.id}"),
        InlineKeyboardButton("❌ Rechazar", callback_data=f"valreq|decline|{user.id}"),
    ]])
    try:
        await context.bot.send_message(
            chat_id=chat_id,
            text=(
                f"🕵️ <b>Solicitud de entrada detectada</b>\n\n"
                f"Usuario: {user.mention_html()}\n"
                "Autoaprobación está desactivada. Si pulsas <b>Aprobar y validar</b>, "
                "el bot aprobará la solicitud e iniciará la validación."
            ),
            parse_mode=ParseMode.HTML,
            reply_markup=keyboard,
        )
    except Exception:
        pass


async def validation_chat_member_update(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Detecta altas aunque no llegue el mensaje de servicio, y conserva avisos de salida."""
    # Primero ejecuta despedidas/salidas de versiones anteriores si existen.
    try:
        if '_old_validation_chat_member_update_v21' in globals():
            await _old_validation_chat_member_update_v21(update, context)
    except Exception:
        logger.exception("Error ejecutando compatibilidad de validación/salida")

    cmu = getattr(update, "chat_member", None)
    if not cmu or not getattr(cmu, "chat", None):
        return
    chat_id = int(cmu.chat.id)
    if not chat_is_allowed(chat_id):
        return
    remember_chat_title(chat_id, getattr(cmu.chat, "title", "") or "")
    old_member = getattr(cmu, "old_chat_member", None)
    new_member = getattr(cmu, "new_chat_member", None)
    user = getattr(new_member, "user", None) or getattr(old_member, "user", None)
    if not user or getattr(user, "is_bot", False):
        return
    old_status = str(getattr(old_member, "status", "") or "")
    new_status = str(getattr(new_member, "status", "") or "")

    # Entrada: left/kicked/no-status -> member/restricted/administrator/creator.
    if validation_is_active_for_chat(chat_id) and new_status in ("member", "restricted", "administrator", "creator") and old_status in ("left", "kicked", ""):
        await start_validation_for_user(update, context, chat_id, user, reply_to_message_id=None, source="chat_member_join_v30", force=True)
        return

    # Salida/expulsión: mantener aviso de despedida aunque sea otro bot/admin.
    if old_status not in ("left", "kicked", "") and new_status in ("left", "kicked"):
        try:
            await _send_farewell_notice_v21(context, chat_id, user, source="chat_member_left_v30")
        except Exception:
            logger.exception("No se pudo enviar despedida desde ChatMemberHandler")


