# PATCH V32: Encuestas anónimas con resultados ocultos hasta finalizar
# =========================

POLL_TASK: Optional[asyncio.Task] = None


def _v32_polls(chat_id: int) -> List[Dict[str, Any]]:
    cfg = admin_cfg(chat_id)
    data = cfg.setdefault("bot_polls", [])
    if not isinstance(data, list):
        data = []
        cfg["bot_polls"] = data
    return data


def _v32_poll_find(chat_id: int, poll_id: int) -> Optional[Dict[str, Any]]:
    for poll in _v32_polls(chat_id):
        try:
            if int(poll.get("id", 0) or 0) == int(poll_id):
                return poll
        except Exception:
            continue
    return None


def _v32_next_poll_id(chat_id: int) -> int:
    ids = []
    for poll in _v32_polls(chat_id):
        try:
            ids.append(int(poll.get("id", 0) or 0))
        except Exception:
            pass
    return (max(ids) + 1) if ids else 1


def _v32_parse_duration_seconds(value: str, default: int = 3600) -> int:
    raw = (value or "").strip().lower().replace(" ", "")
    if not raw:
        return default
    # admite 30m, 1h, 2d, 45s o minutos sueltos.
    try:
        if raw.endswith("s"):
            return max(10, int(raw[:-1]))
        if raw.endswith("m"):
            return max(60, int(raw[:-1]) * 60)
        if raw.endswith("h"):
            return max(60, int(raw[:-1]) * 3600)
        if raw.endswith("d"):
            return max(60, int(raw[:-1]) * 86400)
        return max(60, int(raw) * 60)
    except Exception:
        return default


def _v32_duration_label(seconds: int) -> str:
    try:
        seconds = int(seconds)
    except Exception:
        seconds = 0
    if seconds % 86400 == 0 and seconds >= 86400:
        n = seconds // 86400
        return f"{n} día" if n == 1 else f"{n} días"
    if seconds % 3600 == 0 and seconds >= 3600:
        n = seconds // 3600
        return f"{n} hora" if n == 1 else f"{n} horas"
    if seconds % 60 == 0 and seconds >= 60:
        n = seconds // 60
        return f"{n} minuto" if n == 1 else f"{n} minutos"
    return f"{seconds} segundos"


def _v32_parse_poll_spec(text: str) -> Tuple[str, List[str], int, bool]:
    raw = (text or "").strip()
    if raw.startswith("/encuesta"):
        raw = raw.split(maxsplit=1)[1].strip() if len(raw.split(maxsplit=1)) > 1 else ""
    if not raw:
        raise ValueError("Formato: Pregunta | Opción 1 | Opción 2 | 30m")
    parts = [p.strip() for p in raw.split("|") if p.strip()]
    multi = False
    if parts and parts[0].lower() in ("multi", "multiple", "múltiple", "varias"):
        multi = True
        parts = parts[1:]
    if len(parts) < 3:
        raise ValueError("Necesito pregunta y mínimo 2 opciones. Ejemplo: ¿Plan de hoy? | Bar | Música | Casa | 30m")
    close_seconds = 3600
    # Si la última parte parece duración, úsala.
    last = parts[-1].lower().replace(" ", "")
    if last.endswith(("s", "m", "h", "d")) or last.isdigit():
        close_seconds = _v32_parse_duration_seconds(parts[-1], 3600)
        parts = parts[:-1]
    question = parts[0].strip()
    options = [p.strip() for p in parts[1:] if p.strip()]
    if len(options) < 2:
        raise ValueError("Añade al menos 2 opciones.")
    if len(options) > 10:
        raise ValueError("Máximo 10 opciones, como Telegram.")
    question = question[:250]
    options = [o[:90] for o in options]
    return question, options, close_seconds, multi


def _v32_poll_counts(poll: Dict[str, Any]) -> List[int]:
    opts = poll.get("options") if isinstance(poll.get("options"), list) else []
    counts = [0 for _ in opts]
    votes = poll.get("votes") if isinstance(poll.get("votes"), dict) else {}
    for raw in votes.values():
        indexes = raw if isinstance(raw, list) else [raw]
        for idx in indexes:
            try:
                idx = int(idx)
                if 0 <= idx < len(counts):
                    counts[idx] += 1
            except Exception:
                continue
    return counts


def _v32_poll_text(poll: Dict[str, Any], *, results: bool = False) -> str:
    q = h(poll.get("question", "Encuesta"))
    multi = bool(poll.get("multi", False))
    status = str(poll.get("status") or "open")
    close_ts = int(poll.get("close_ts", 0) or 0)
    now = int(time.time())
    remaining = max(0, close_ts - now) if close_ts else 0
    lines = ["📊 <b>Encuesta anónima</b>", "", f"<b>{q}</b>", ""]
    lines.append("Tipo: <b>respuesta múltiple</b>" if multi else "Tipo: <b>una respuesta</b>")
    if status == "open":
        lines.append(f"Estado: <b>abierta</b> · cierra en <b>{h(_v32_duration_label(remaining))}</b>")
        lines.append("<i>Los resultados se mostrarán solo cuando finalice.</i>")
    else:
        lines.append("Estado: <b>finalizada</b>")
    if results or status != "open":
        opts = poll.get("options") if isinstance(poll.get("options"), list) else []
        counts = _v32_poll_counts(poll)
        total = sum(counts)
        lines.extend(["", "<b>Resultados finales:</b>"])
        for idx, opt in enumerate(opts):
            c = counts[idx] if idx < len(counts) else 0
            pct = int(round((c / total) * 100)) if total else 0
            bar = "█" * max(1, min(10, pct // 10)) if c else "░"
            lines.append(f"{idx+1}. {h(opt)} — <b>{c}</b> votos · <b>{pct}%</b> {bar}")
        lines.append(f"\nTotal votos: <b>{total}</b>")
    else:
        opts = poll.get("options") if isinstance(poll.get("options"), list) else []
        lines.extend(["", "<b>Opciones:</b>"])
        for idx, opt in enumerate(opts):
            lines.append(f"{idx+1}. {h(opt)}")
    return "\n".join(lines)


def _v32_poll_markup(chat_id: int, poll: Dict[str, Any]) -> Optional[InlineKeyboardMarkup]:
    if str(poll.get("status") or "open") != "open":
        return None
    poll_id = int(poll.get("id", 0) or 0)
    opts = poll.get("options") if isinstance(poll.get("options"), list) else []
    rows: List[List[InlineKeyboardButton]] = []
    for idx, opt in enumerate(opts):
        rows.append([InlineKeyboardButton(f"{idx+1}. {str(opt)[:48]}", callback_data=f"poll|vote|{chat_id}|{poll_id}|{idx}")])
    rows.append([InlineKeyboardButton("✅ Terminar encuesta", callback_data=f"poll|close|{chat_id}|{poll_id}")])
    return InlineKeyboardMarkup(rows)


async def _v32_create_poll(context: ContextTypes.DEFAULT_TYPE, chat_id: int, question: str, options: List[str], close_seconds: int, multi: bool, creator_id: int = 0) -> Dict[str, Any]:
    poll_id = _v32_next_poll_id(chat_id)
    now = int(time.time())
    poll = {
        "id": poll_id,
        "question": question,
        "options": options,
        "multi": bool(multi),
        "anonymous": True,
        "status": "open",
        "creator_id": int(creator_id or 0),
        "created_ts": now,
        "close_ts": now + int(close_seconds),
        "message_id": 0,
        "votes": {},
    }
    msg = await context.bot.send_message(
        chat_id=chat_id,
        text=_v32_poll_text(poll, results=False),
        parse_mode=ParseMode.HTML,
        reply_markup=_v32_poll_markup(chat_id, poll),
    )
    poll["message_id"] = msg.message_id
    _v32_polls(chat_id).insert(0, poll)
    save_all_states()
    return poll


async def _v32_close_poll(context: ContextTypes.DEFAULT_TYPE, chat_id: int, poll: Dict[str, Any], *, silent: bool = False) -> None:
    if str(poll.get("status") or "open") != "open":
        return
    poll["status"] = "closed"
    poll["closed_ts"] = int(time.time())
    save_all_states()
    msg_id = int(poll.get("message_id", 0) or 0)
    if msg_id:
        try:
            await context.bot.edit_message_text(
                chat_id=chat_id,
                message_id=msg_id,
                text=_v32_poll_text(poll, results=True),
                parse_mode=ParseMode.HTML,
                reply_markup=None,
            )
        except Exception:
            logger.exception("No se pudo cerrar/edit encuesta %s en chat %s", poll.get("id"), chat_id)
    if not silent:
        try:
            await context.bot.send_message(chat_id, f"📊 Encuesta finalizada: <b>{h(poll.get('question',''))}</b>", parse_mode=ParseMode.HTML)
        except Exception:
            pass


async def poll_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ""
    parts = data.split("|")
    if len(parts) < 4:
        await q.answer()
        return
    action = parts[1]
    try:
        chat_id = int(parts[2])
        poll_id = int(parts[3])
    except Exception:
        await q.answer("Encuesta inválida", show_alert=True)
        return
    poll = _v32_poll_find(chat_id, poll_id)
    if not poll:
        await q.answer("No encuentro esa encuesta", show_alert=True)
        return
    if action == "vote":
        if str(poll.get("status") or "open") != "open":
            await q.answer("La encuesta ya terminó", show_alert=True)
            return
        if int(time.time()) >= int(poll.get("close_ts", 0) or 0):
            await _v32_close_poll(context, chat_id, poll, silent=True)
            await q.answer("La encuesta acaba de finalizar", show_alert=True)
            return
        try:
            opt_idx = int(parts[4])
        except Exception:
            await q.answer("Opción inválida", show_alert=True)
            return
        opts = poll.get("options") if isinstance(poll.get("options"), list) else []
        if not (0 <= opt_idx < len(opts)):
            await q.answer("Opción inválida", show_alert=True)
            return
        uid = str(q.from_user.id)
        votes = poll.setdefault("votes", {})
        if bool(poll.get("multi", False)):
            current = votes.get(uid, [])
            if not isinstance(current, list):
                current = [current]
            current = [int(x) for x in current if str(x).lstrip('-').isdigit()]
            if opt_idx in current:
                current = [x for x in current if x != opt_idx]
                votes[uid] = current
                msg = "Opción quitada ✅"
            else:
                current.append(opt_idx)
                votes[uid] = sorted(set(current))
                msg = "Voto añadido ✅"
        else:
            votes[uid] = [opt_idx]
            msg = "Voto guardado ✅"
        save_all_states()
        await q.answer(msg, show_alert=False)
        return
    if action == "close":
        # Solo admin o creador.
        allowed = False
        try:
            allowed = int(q.from_user.id) == int(poll.get("creator_id", 0) or 0) or await is_admin(context, chat_id, q.from_user.id)
        except Exception:
            allowed = False
        if not allowed:
            await q.answer("Solo admin o creador puede finalizarla", show_alert=True)
            return
        await _v32_close_poll(context, chat_id, poll, silent=True)
        await q.answer("Encuesta finalizada ✅")
        return
    await q.answer()


async def poll_close_loop(context: ContextTypes.DEFAULT_TYPE) -> None:
    now = int(time.time())
    for chat_id, state in list(STATE_CACHE.items()):
        try:
            for poll in list(_v32_polls(chat_id)):
                if str(poll.get("status") or "open") == "open" and int(poll.get("close_ts", 0) or 0) <= now:
                    await _v32_close_poll(context, chat_id, poll, silent=True)
        except Exception:
            logger.exception("Error revisando encuestas del chat %s", chat_id)


async def encuesta_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not update.effective_user:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_admin(context, chat_id, update.effective_user.id):
        await update.message.reply_text("Solo administradores pueden crear encuestas.")
        return
    raw = update.message.text or ""
    if " " not in raw:
        await update.message.reply_html(
            "📊 <b>Crear encuesta anónima</b>\n\n"
            "Formato:\n<code>/encuesta Pregunta | Opción 1 | Opción 2 | 30m</code>\n\n"
            "Respuesta múltiple:\n<code>/encuesta multi | Pregunta | Opción 1 | Opción 2 | 1h</code>\n\n"
            "Los porcentajes se muestran solo al finalizar."
        )
        return
    try:
        question, options, close_seconds, multi = _v32_parse_poll_spec(raw)
    except ValueError as e:
        await update.message.reply_html(f"⚠️ {h(str(e))}")
        return
    poll = await _v32_create_poll(context, chat_id, question, options, close_seconds, multi, update.effective_user.id)
    await update.message.reply_html(f"✅ Encuesta creada. Cierra en <b>{h(_v32_duration_label(close_seconds))}</b>.")


async def encuestas_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not update.effective_user:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_admin(context, chat_id, update.effective_user.id):
        await update.message.reply_text("Solo administradores.")
        return
    await update.message.reply_html(admin_private_block_text(chat_id, "polls"), reply_markup=admin_private_block_markup(chat_id, "polls"))


