def _v47_onoff(value: Any) -> str:
    return "ON" if bool(value) else "OFF"


def _v47_bool_button(label: str, chat_id: int, key: str, default: bool) -> InlineKeyboardButton:
    return InlineKeyboardButton(f"{cfg_status(cfg_value(chat_id, key, default))} {label}", callback_data=f"cfg|impconf|{chat_id}|toggle|{key}|{1 if default else 0}")


def _v47_seconds_label(seconds: Any) -> str:
    try:
        s = int(seconds)
    except Exception:
        s = 120
    if s <= 0:
        return "no borrar"
    if s < 60:
        return f"{s}s"
    if s % 60 == 0:
        m = s // 60
        return f"{m} min" if m != 1 else "1 min"
    return f"{s}s"


_old_admin_block_icon_v47 = admin_block_icon
def admin_block_icon(chat_id: int, block: str) -> str:  # type: ignore[override]
    if block == "impostor_settings":
        return cfg_status(cfg_value(chat_id, "imp_cleanup_enabled", True))
    return _old_admin_block_icon_v47(chat_id, block)


_old_admin_private_block_text_v47 = admin_private_block_text
def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:  # type: ignore[override]
    if block == "impostor_settings":
        return "\n".join([
            "<b>🎭 Configuración Impostor</b>",
            f"Grupo: <b>{h(get_chat_title(chat_id))}</b>",
            "",
            f"Limpieza general: <b>{_v47_onoff(cfg_value(chat_id, 'imp_cleanup_enabled', True))}</b>",
            f"Borrar pistas escritas por jugadores: <b>{_v47_onoff(cfg_value(chat_id, 'imp_delete_player_clues', True))}</b>",
            f"Borrar mensajes del juego al finalizar: <b>{_v47_onoff(cfg_value(chat_id, 'imp_delete_on_finish', True))}</b>",
            f"Borrar sala si se cancela: <b>{_v47_onoff(cfg_value(chat_id, 'imp_delete_on_cancel', True))}</b>",
            f"Tiempo antes de borrar al finalizar: <b>{h(_v47_seconds_label(cfg_value(chat_id, 'imp_finish_delete_ttl', 120)))}</b>",
            "",
            "La partida usa un mensaje principal que se va editando. Si activas borrar pistas, cuando un jugador escriba su pista se guarda y el mensaje se borra para que el grupo quede limpio.",
        ])
    if block == "ai":
        base = _old_admin_private_block_text_v47(chat_id, block, page)
        cmds = cfg_value(chat_id, "ai_custom_commands", {})
        count = len(cmds) if isinstance(cmds, dict) else 0
        extra = ["", "<b>Comandos IA personalizados:</b> " + str(count)]
        if count:
            for name in sorted(list(cmds.keys()))[:8]:
                extra.append(f"• <code>/{h(name)}</code>")
            if count > 8:
                extra.append(f"… y {count-8} más")
        extra.extend(["", "Puedes crear comandos tipo <code>/consejo</code>, <code>/frase</code>, <code>/salseo</code>, etc."])
        return base + "\n" + "\n".join(extra)
    return _old_admin_private_block_text_v47(chat_id, block, page)


_old_admin_private_block_markup_v47 = admin_private_block_markup
def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    if block == "impostor_settings":
        rows = [
            [_v47_bool_button("Limpieza Impostor", chat_id, "imp_cleanup_enabled", True)],
            [_v47_bool_button("Borrar pistas de jugadores", chat_id, "imp_delete_player_clues", True)],
            [_v47_bool_button("Borrar al finalizar", chat_id, "imp_delete_on_finish", True)],
            [_v47_bool_button("Borrar al cancelar", chat_id, "imp_delete_on_cancel", True)],
            [InlineKeyboardButton("30s", callback_data=f"cfg|impconf|{chat_id}|ttl|30"), InlineKeyboardButton("2 min", callback_data=f"cfg|impconf|{chat_id}|ttl|120"), InlineKeyboardButton("5 min", callback_data=f"cfg|impconf|{chat_id}|ttl|300"), InlineKeyboardButton("No borrar", callback_data=f"cfg|impconf|{chat_id}|ttl|0")],
            [InlineKeyboardButton("🔄 Reload", callback_data=f"cfg|block|{chat_id}|impostor_settings"), InlineKeyboardButton("🔙 Volver", callback_data=f"cfg|home|{chat_id}")],
        ]
        return InlineKeyboardMarkup(rows)
    if block == "ai":
        old = _old_admin_private_block_markup_v47(chat_id, block, page)
        rows = [list(r) for r in getattr(old, "inline_keyboard", [])]
        extra = [
            [InlineKeyboardButton("➕ Nuevo comando IA", callback_data=f"cfg|ai_cmd_new|{chat_id}"), InlineKeyboardButton("📋 Comandos IA", callback_data=f"cfg|ai_cmd_list|{chat_id}")],
            [InlineKeyboardButton("🧠 Prompt extra", callback_data=f"cfg|ai_custom_prompt|{chat_id}"), InlineKeyboardButton("🧪 Probar IA", callback_data=f"cfg|ai_test_prompt|{chat_id}")],
        ]
        # Inserta antes del último volver si existe.
        if rows and any("home" in str(getattr(btn, "callback_data", "")) for btn in rows[-1]):
            rows = rows[:-1] + extra + rows[-1:]
        else:
            rows.extend(extra)
        return InlineKeyboardMarkup(rows)
    return _old_admin_private_block_markup_v47(chat_id, block, page)


async def _v47_delete_game_messages_later(bot, chat_id: int, ids: List[int], delay: int) -> None:
    if delay > 0:
        await asyncio.sleep(delay)
    for mid in sorted({int(x) for x in ids if x}, reverse=True):
        try:
            await bot.delete_message(chat_id=chat_id, message_id=mid)
        except Exception:
            pass


def _v47_game_message_ids(game: Dict[str, Any]) -> List[int]:
    ids: List[int] = []
    for key in ("message_id", "turn_message_id", "secret_message_id", "final_message_id"):
        try:
            mid = int(game.get(key) or 0)
            if mid:
                ids.append(mid)
        except Exception:
            pass
    extra = game.get("bot_message_ids")
    if isinstance(extra, list):
        for x in extra:
            try:
                if int(x): ids.append(int(x))
            except Exception:
                pass
    return ids


# Refuerzo: guarda el mensaje final y borra todos los mensajes del juego si está configurado.
async def _imp_finish(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], reason: str = "") -> None:  # type: ignore[override]
    game["status"] = "finished"
    imp_id = int(game.get("impostor_id", 0) or 0)
    imp = _imp_player(game, imp_id) or {"id": imp_id, "name": "Impostor"}
    word = h(game.get("word") or "")
    winner_side = str(game.get("winner_side") or "")
    if not winner_side:
        votes = game.get("votes") if isinstance(game.get("votes"), dict) else {}
        counts: Dict[int, int] = {}
        for target in votes.values():
            try:
                counts[int(target)] = counts.get(int(target), 0) + 1
            except Exception:
                pass
        if counts:
            top_id, _top_votes = sorted(counts.items(), key=lambda x: x[1], reverse=True)[0]
            winner_side = "crew" if int(top_id) == imp_id else "impostor"
        else:
            winner_side = "impostor"
        game["winner_side"] = winner_side
    score_txt = ""
    try:
        score_txt = _imp_score_game(chat_id, game, winner_side)
    except Exception:
        logger.exception("No se pudo puntuar partida Impostor")
    if score_txt and score_txt not in reason:
        reason = (reason or "") + score_txt
    votes = game.get("votes") if isinstance(game.get("votes"), dict) else {}
    counts: Dict[int, int] = {}
    for target in votes.values():
        try: counts[int(target)] = counts.get(int(target), 0) + 1
        except Exception: pass
    voted_txt = ""
    if counts:
        top_id, top_votes = sorted(counts.items(), key=lambda x: x[1], reverse=True)[0]
        top = _imp_player(game, top_id) or {"id": top_id, "name": str(top_id)}
        voted_txt = f"\nEl más votado fue {_imp_mention(top)} con <b>{top_votes}</b> votos."
    txt = (
        "🎭 <b>Fin del juego del Impostor</b>\n\n"
        f"La palabra era: <b>{word}</b>\n"
        f"El impostor era: {_imp_mention(imp)} 😈"
        f"{voted_txt}"
    )
    if reason:
        txt += f"\n\n{reason}"
    save_all_states()
    msg = await context.bot.send_message(chat_id, txt, parse_mode=ParseMode.HTML)
    game["final_message_id"] = int(msg.message_id)
    save_all_states()
    if bool(cfg_value(chat_id, "imp_cleanup_enabled", True)) and bool(cfg_value(chat_id, "imp_delete_on_finish", True)):
        try:
            ttl = int(cfg_value(chat_id, "imp_finish_delete_ttl", 120) or 0)
        except Exception:
            ttl = 120
        ids = _v47_game_message_ids(game)
        asyncio.create_task(_v47_delete_game_messages_later(context.bot, chat_id, ids, ttl))


# Limpia pistas escritas por jugadores si está configurado.
_old_impostor_clue_text_handler_v47 = impostor_clue_text_handler
async def impostor_clue_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    uid = int(update.effective_user.id)
    before = len(_imp_games(chat_id))
    await _old_impostor_clue_text_handler_v47(update, context)
    # Si existía pendiente para ese jugador y ya no existe, la pista se ha aceptado.
    if bool(cfg_value(chat_id, "imp_cleanup_enabled", True)) and bool(cfg_value(chat_id, "imp_delete_player_clues", True)):
        key = _imp_pending_key(chat_id, uid)
        if key not in PENDING_ACTIONS:
            # Solo borra mensajes normales de texto/caption que no sean comandos.
            txt = (update.message.text or update.message.caption or "").strip()
            if txt and not txt.startswith("/"):
                try:
                    await context.bot.delete_message(chat_id=chat_id, message_id=update.message.message_id)
                except Exception:
                    pass


# Captura cancelaciones para limpiar la sala si el admin lo desea.
_old_impostor_callback_router_v47 = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    q = update.callback_query
    data = q.data if q else ""
    # Deja actuar al router principal primero.
    if not (q and data.startswith("imp|")):
        return await _old_impostor_callback_router_v47(update, context)
    parts = data.split("|")
    chat_id = gid = 0
    action = ""
    try:
        if len(parts) >= 4:
            action = parts[1]
            chat_id = int(parts[2]); gid = int(parts[3])
            game_before = _imp_find(chat_id, gid)
        else:
            game_before = None
    except Exception:
        game_before = None
    await _old_impostor_callback_router_v47(update, context)
    try:
        game = _imp_find(chat_id, gid) if chat_id and gid else game_before
        if not game:
            return
        # Guarda id de mensaje actual de turno/lobby cuando haya interacción.
        if q.message:
            mid = int(q.message.message_id)
            if action in ("join", "leave", "start", "instructions", "ranking") and not int(game.get("message_id") or 0):
                game["message_id"] = mid
            if action in ("respond", "next", "show_turn", "vote_menu", "accuse_menu"):
                game["turn_message_id"] = mid
            save_all_states()
        if action == "cancel" and bool(cfg_value(chat_id, "imp_cleanup_enabled", True)) and bool(cfg_value(chat_id, "imp_delete_on_cancel", True)):
            ids = _v47_game_message_ids(game)
            if q.message and int(q.message.message_id) not in ids:
                ids.append(int(q.message.message_id))
            asyncio.create_task(_v47_delete_game_messages_later(context.bot, chat_id, ids, 2))
    except Exception:
        logger.exception("Error post-callback Impostor v47")


# -------------------------
# IA: comandos configurables
# -------------------------
def _ai_custom_commands(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(chat_id)
    cmds = cfg.setdefault("ai_custom_commands", {})
    if not isinstance(cmds, dict):
        cmds = {}
        cfg["ai_custom_commands"] = cmds
    return cmds


def _ai_clean_command_name(name: str) -> str:
    name = (name or "").strip().lower().lstrip("/")
    name = name.split("@", 1)[0]
    name = _re_v47.sub(r"[^a-z0-9_]+", "", name)
    return name[:32]


async def ai_custom_command_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    text = (update.message.text or "").strip()
    if not text.startswith("/"):
        return
    first, _, rest = text.partition(" ")
    cmd = _ai_clean_command_name(first)
    if not cmd:
        return
    chat_id = int(update.effective_chat.id)
    data = _ai_custom_commands(chat_id).get(cmd)
    if not isinstance(data, dict):
        return
    if not bool(cfg_value(chat_id, "ai_enabled", True)):
        await update.message.reply_html("🤖 La IA está desactivada en este grupo.")
        return
    if _ai_limit_reached(chat_id, int(update.effective_user.id), "planecito", "ai_planecito_daily_limit"):
        await update.message.reply_html("⏳ Has agotado tus usos de IA de hoy en este grupo.")
        return
    instr = str(data.get("prompt") or "Responde de forma breve y útil.").strip()
    if not rest.strip():
        await update.message.reply_html(f"Usa: <code>/{h(cmd)} tu texto</code>")
        return
    waiting = await update.message.reply_html(f"🧠 Cerebrito ejecuta <code>/{h(cmd)}</code>...")
    prompt = f"Comando personalizado /{cmd}. Instrucciones del admin: {instr}\n\nPetición del usuario: {rest.strip()}"
    ans = await _ai_openai_response(chat_id, prompt, max_output_tokens=int(cfg_value(chat_id, "ai_custom_command_tokens", 500) or 500))
    _ai_usage_inc(chat_id, int(update.effective_user.id), "planecito")
    try:
        await waiting.edit_text(ans[:3900])
    except Exception:
        await update.message.reply_text(ans[:3900])


_old_admin_private_config_callback_v47 = admin_private_config_callback
async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    q = update.callback_query
    data = q.data if q else ""
    if q and data.startswith("cfg|impconf|"):
        await q.answer()
        parts = data.split("|")
        chat_id = int(parts[2])
        action = parts[3]
        if action == "toggle":
            key = parts[4]
            default = bool(int(parts[5])) if len(parts) > 5 and parts[5].isdigit() else False
            cfg_set(chat_id, key, not bool(cfg_value(chat_id, key, default)))
        elif action == "ttl":
            cfg_set(chat_id, "imp_finish_delete_ttl", int(parts[4]))
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, "impostor_settings"), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, "impostor_settings"))
        except Exception:
            await q.message.reply_html(admin_private_block_text(chat_id, "impostor_settings"), reply_markup=admin_private_block_markup(chat_id, "impostor_settings"))
        return
    if q and data.startswith("cfg|ai_cmd_new|"):
        await q.answer()
        chat_id = int(data.split("|")[2])
        set_config_pending(q.from_user.id, {"kind": "ai_custom_command", "chat_id": chat_id})
        await q.message.reply_html(
            "➕ <b>Nuevo comando IA</b>\n\n"
            "Escribe en este formato:\n"
            "<code>nombre | instrucciones</code>\n\n"
            "Ejemplo:\n<code>consejo | Da un consejo corto, divertido y útil para el grupo.</code>"
        )
        return
    if q and data.startswith("cfg|ai_custom_prompt|"):
        await q.answer()
        chat_id = int(data.split("|")[2])
        set_config_pending(q.from_user.id, {"kind": "ai_custom_prompt", "chat_id": chat_id})
        await q.message.reply_html("🧠 Escribe las instrucciones extra para Cerebrito en este grupo. Escribe <code>off</code> para borrar.")
        return
    if q and data.startswith("cfg|ai_test_prompt|"):
        await q.answer("Probando IA…")
        chat_id = int(data.split("|")[2])
        ans = await _ai_openai_response(chat_id, "Dame una frase corta para animar el grupo hoy.", max_output_tokens=120)
        await q.message.reply_text(ans[:1200])
        return
    if q and data.startswith("cfg|ai_cmd_list|"):
        await q.answer()
        chat_id = int(data.split("|")[2])
        cmds = _ai_custom_commands(chat_id)
        if not cmds:
            await q.message.reply_html("📋 No hay comandos IA personalizados todavía.")
            return
        rows = []
        for name in sorted(cmds.keys())[:40]:
            rows.append([InlineKeyboardButton(f"🗑 /{name}", callback_data=f"cfg|ai_cmd_del|{chat_id}|{name}")])
        rows.append([InlineKeyboardButton("🔙 IA", callback_data=f"cfg|block|{chat_id}|ai")])
        await q.message.reply_html("📋 <b>Comandos IA personalizados</b>\nPulsa uno para borrarlo.", reply_markup=InlineKeyboardMarkup(rows))
        return
    if q and data.startswith("cfg|ai_cmd_del|"):
        await q.answer()
        parts = data.split("|")
        chat_id = int(parts[2]); name = _ai_clean_command_name(parts[3] if len(parts) > 3 else "")
        _ai_custom_commands(chat_id).pop(name, None)
        save_all_states()
        await q.message.reply_html(f"✅ Comando <code>/{h(name)}</code> eliminado.")
        return
    return await _old_admin_private_config_callback_v47(update, context)


_old_admin_private_config_text_v47 = admin_private_config_text
async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:  # type: ignore[override]
    if update.effective_user and update.message and update.effective_chat.type == "private":
        pending = get_config_pending(update.effective_user.id)
        if pending and pending.get("kind") == "ai_custom_command":
            chat_id = int(pending.get("chat_id"))
            raw = plain_text_from_message(update.message).strip()
            if "|" not in raw:
                await update.message.reply_html("Formato incorrecto. Usa: <code>nombre | instrucciones</code>")
                return True
            name_raw, prompt = raw.split("|", 1)
            name = _ai_clean_command_name(name_raw)
            prompt = prompt.strip()
            if not name or not prompt:
                await update.message.reply_html("Falta nombre o instrucciones. Ejemplo: <code>consejo | Da un consejo corto.</code>")
                return True
            reserved = {"start", "help", "ajustes", "plan", "djplan", "ping", "preguntita", "retito", "examen", "privadito", "impostor", "cerebrito", "planecito", "tiempo"}
            if name in reserved:
                await update.message.reply_html("Ese comando ya existe en el bot. Elige otro nombre.")
                return True
            _ai_custom_commands(chat_id)[name] = {"prompt": prompt[:1500], "created_by": int(update.effective_user.id), "created_ts": int(_time_v47.time())}
            pop_config_pending(update.effective_user.id)
            save_all_states()
            await update.message.reply_html(f"✅ Comando IA creado: <code>/{h(name)}</code>\n\n" + admin_private_block_text(chat_id, "ai"), reply_markup=admin_private_block_markup(chat_id, "ai"))
            return True
        if pending and pending.get("kind") == "ai_custom_prompt":
            chat_id = int(pending.get("chat_id"))
            raw = telegram_html_from_message(update.message).strip()
            if raw.lower() in ("off", "borrar", "quitar"):
                raw = ""
            cfg_set(chat_id, "ai_custom_prompt", raw[:2500])
            pop_config_pending(update.effective_user.id)
            await update.message.reply_html("✅ Prompt extra guardado.\n\n" + admin_private_block_text(chat_id, "ai"), reply_markup=admin_private_block_markup(chat_id, "ai"))
            return True
    return await _old_admin_private_config_text_v47(update, context)


