_old_build_application_v47 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v47()
    app.add_handler(CallbackQueryHandler(admin_private_config_callback, pattern="^cfg\|(impconf|ai_cmd_|ai_custom_prompt|ai_test_prompt)"), group=-140)
    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern="^imp\|"), group=-145)
    app.add_handler(MessageHandler((filters.TEXT | filters.Caption()) & ~filters.COMMAND, impostor_clue_text_handler), group=-150)
    app.add_handler(MessageHandler(filters.COMMAND, ai_custom_command_handler), group=-74)
    return app



# =========================================================
# V48 - FIX MENÚ PRIVADO IA CEREBRITO / IMPOSTOR
# Intercepta directamente los botones de bloque antes del router general.
# Corrige también botones antiguos cfg|home|... que no existían en el router base.
# =========================================================

async def cfg_private_block_direct_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ""
    if not data.startswith("cfg|"):
        return
    parts = data.split("|")
    action = parts[1] if len(parts) > 1 else ""

    # Solo interceptamos lo necesario para no romper el resto del panel.
    if action not in ("block", "home"):
        return

    await q.answer()
    if not is_global_admin_user(update.effective_user.id):
        await q.answer("Solo ADMIN_IDS.", show_alert=True)
        return

    try:
        chat_id = int(parts[2]) if len(parts) > 2 else 0
    except Exception:
        await q.answer("Grupo inválido.", show_alert=True)
        return

    try:
        if action == "home":
            text = admin_private_main_text(chat_id)
            markup = admin_private_main_markup(chat_id)
        else:
            block = parts[3] if len(parts) > 3 else ""
            if block not in ADMIN_PRIVATE_BLOCK_IDS:
                text = admin_private_main_text(chat_id)
                markup = admin_private_main_markup(chat_id)
            else:
                text = admin_private_block_text(chat_id, block)
                markup = admin_private_block_markup(chat_id, block)

        try:
            await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
        except BadRequest as e:
            # Si el mensaje viejo ya no se puede editar, abrimos panel nuevo en privado.
            if "message is not modified" in str(e).lower():
                return
            await q.message.reply_html(text, reply_markup=markup)
        except Exception:
            await q.message.reply_html(text, reply_markup=markup)
    except Exception:
        logger.exception("Error abriendo bloque privado directo: %s", data)
        await q.answer("No pude abrir ese menú. Reintenta con /ajustes.", show_alert=True)


_old_build_application_v48 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v48()
    # Muy prioritario: evita que el router general deje pensando los botones de Cerebrito/Impostor.
    app.add_handler(CallbackQueryHandler(cfg_private_block_direct_router, pattern=r"^cfg\|(block|home)\|"), group=-500)
    return app



# =========================================================
# V49 - FIX CRÍTICO: NO BORRAR MENSAJES NORMALES DE MIEMBROS
# Causa: el handler del Impostor borraba cualquier texto si no había pendiente
# después de procesarlo. Ahora SOLO borra la pista cuando REALMENTE era el turno
# del jugador y existía una acción pendiente antes de escribir.
# =========================================================

try:
    _previous_impostor_clue_text_handler_v49 = impostor_clue_text_handler
except NameError:
    _previous_impostor_clue_text_handler_v49 = None

async def impostor_clue_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    if not update.effective_chat or not update.effective_user or not update.message:
        return

    chat_id = int(update.effective_chat.id)
    uid = int(update.effective_user.id)
    key = _imp_pending_key(chat_id, uid) if '_imp_pending_key' in globals() else f"{chat_id}:{uid}:imp_clue"

    # Punto clave: solo puede borrarse si ANTES existía una pista pendiente.
    had_pending_before = key in PENDING_ACTIONS

    if _previous_impostor_clue_text_handler_v49:
        await _previous_impostor_clue_text_handler_v49(update, context)

    # Si no era una respuesta de turno del Impostor, no tocar el mensaje del miembro.
    if not had_pending_before:
        return

    # Si sigue pendiente, la pista no se aceptó; tampoco borrar.
    if key in PENDING_ACTIONS:
        return

    # Solo entonces, y solo si está configurado, borra la pista del jugador.
    if bool(cfg_value(chat_id, "imp_cleanup_enabled", True)) and bool(cfg_value(chat_id, "imp_delete_player_clues", False)):
        txt = (getattr(update.message, 'text', None) or getattr(update.message, 'caption', None) or '').strip()
        if txt and not txt.startswith('/'):
            try:
                await context.bot.delete_message(chat_id=chat_id, message_id=update.message.message_id)
            except Exception:
                pass


# Refuerza valores seguros por defecto para que el grupo pueda escribir.
def _apply_safe_member_message_defaults_v49(chat_id: int) -> None:
    try:
        cfg = admin_cfg(chat_id)
        # No borrar mensajes de validación por defecto mientras esperan admin.
        cfg.setdefault('validation_delete_wrong_messages', False)
        # No borrar pistas de jugadores por defecto; si se activa, solo se borra en turno real.
        cfg.setdefault('imp_delete_player_clues', False)
        save_all_states()
    except Exception:
        logger.exception('No pude aplicar defaults seguros de borrado')

_old_get_state_v49 = get_state
def get_state(chat_id: int) -> ChatState:  # type: ignore[override]
    state = _old_get_state_v49(chat_id)
    # No llamamos siempre a save agresivamente salvo cuando falten claves.
    try:
        cfg = state.admin_config
        changed = False
        if 'validation_delete_wrong_messages' not in cfg:
            cfg['validation_delete_wrong_messages'] = False; changed = True
        if 'imp_delete_player_clues' not in cfg:
            cfg['imp_delete_player_clues'] = False; changed = True
        if changed:
            save_all_states()
    except Exception:
        pass
    return state

# Comando de emergencia: desbloquea el chat si se quedó una config agresiva.
async def desbloquear_chat_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not await is_admin(context, chat_id, update.effective_user.id):
        await update.message.reply_text('Solo administradores.')
        return
    cfg = admin_cfg(chat_id)
    cfg['validation_delete_wrong_messages'] = False
    cfg['imp_delete_player_clues'] = False
    cfg['service_cleanup_enabled'] = False
    cfg['command_cleanup_mode'] = 'off'
    cfg['hot_command_delete_mode'] = 'off'
    save_all_states()
    await update.message.reply_text('✅ Chat desbloqueado: ya no borraré mensajes normales de miembros. He desactivado limpieza agresiva, borrado de pistas y borrado de comandos.')

_old_build_application_v49 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v49()
    # Handler prioritario para que el texto del impostor use la versión corregida.
    app.add_handler(MessageHandler((filters.TEXT | filters.Caption()) & ~filters.COMMAND, impostor_clue_text_handler), group=-700)
    app.add_handler(CommandHandler('desbloquearchat', desbloquear_chat_command), group=-700)
    return app



# =========================================================
# V50 DEFINITIVA - Router privado robusto para /ajustes + seguridad de menús
# =========================================================
from telegram.ext import ApplicationHandlerStop

# Asegura que todos los bloques nuevos estén visibles antes de construir menús.
def _v50_ensure_private_blocks() -> None:
    wanted = [
        ("service_cleanup", "🧽 Mensajes servicio"),
        ("command_cleanup", "🧹 Borrado comandos"),
        ("owner_alerts", "🔔 Alertas privadas"),
        ("impostor_settings", "🎭 Impostor"),
        ("ai", "🧠 IA Cerebrito"),
        ("polls", "📊 Encuestas"),
    ]
    existing = {k for k, _ in ADMIN_PRIVATE_BLOCKS}
    # Inserta antes de Listados y control cuando sea posible.
    try:
        insert_at = next((i for i, (k, _l) in enumerate(ADMIN_PRIVATE_BLOCKS) if k == "lists"), len(ADMIN_PRIVATE_BLOCKS))
    except Exception:
        insert_at = len(ADMIN_PRIVATE_BLOCKS)
    for key, label in wanted:
        if key not in existing:
            ADMIN_PRIVATE_BLOCKS.insert(insert_at, (key, label))
            insert_at += 1
            existing.add(key)
        ADMIN_PRIVATE_BLOCK_IDS.add(key)

_v50_ensure_private_blocks()


def _v50_block_title(block: str) -> str:
    try:
        return dict(ADMIN_PRIVATE_BLOCKS).get(block, block)
    except Exception:
        return block


async def _v50_send_or_edit(query, text: str, markup: Optional[InlineKeyboardMarkup] = None) -> None:
    """Edita el panel si puede; si Telegram no deja, manda panel nuevo."""
    try:
        await query.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
        return
    except BadRequest as e:
        if "message is not modified" in str(e).lower():
            return
    except Exception:
        pass
    try:
        await query.message.reply_html(text, reply_markup=markup)
    except Exception:
        logger.exception("No se pudo enviar/editar panel privado V50")


def _v50_known_chats() -> List[int]:
    try:
        chats = list(known_admin_chats_for_private())
        chats = [int(c) for c in chats if int(c) < 0]
        # Deduplicado conservando orden
        seen = set(); out = []
        for c in chats:
            if c not in seen:
                seen.add(c); out.append(c)
        return out
    except Exception:
        try:
            return sorted([int(k) for k in STATE_CACHE.keys() if int(k) < 0])
        except Exception:
            return []


def _v50_chat_selector_markup() -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    for chat_id in _v50_known_chats():
        try:
            title = str(cfg_value(chat_id, "chat_title", "") or chat_id)
        except Exception:
            title = str(chat_id)
        rows.append([InlineKeyboardButton(f"⚙️ {title}", callback_data=f"cfgsafe|open|{chat_id}")])
    rows.append([InlineKeyboardButton("🔄 Actualizar lista", callback_data="cfgsafe|list")])
    return InlineKeyboardMarkup(rows)


async def _v50_ajustes_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        raise ApplicationHandlerStop
    if not is_global_admin_user(update.effective_user.id):
        await update.message.reply_text("Solo ADMIN_IDS puede abrir la configuración privada.")
        raise ApplicationHandlerStop
    if update.effective_chat and update.effective_chat.type != "private":
        await update.message.reply_text("Escríbeme /ajustes por privado para configurar sin ensuciar el grupo.")
        raise ApplicationHandlerStop
    load_all_states()
    _v50_ensure_private_blocks()
    if not _v50_known_chats():
        await update.message.reply_text("Todavía no tengo grupos registrados. Usa /plan una vez dentro del grupo o espera a que entre alguien.")
        raise ApplicationHandlerStop
    await update.message.reply_html("<b>Elige el grupo que quieres configurar:</b>", reply_markup=_v50_chat_selector_markup())
    raise ApplicationHandlerStop


async def _v50_render_main(query, chat_id: int) -> None:
    await _v50_send_or_edit(query, admin_private_main_text(chat_id), admin_private_main_markup(chat_id))


async def _v50_render_block(query, chat_id: int, block: str, page: int = 0) -> None:
    _v50_ensure_private_blocks()
    if block not in ADMIN_PRIVATE_BLOCK_IDS:
        block = "validation"
    await _v50_send_or_edit(query, admin_private_block_text(chat_id, block, page), admin_private_block_markup(chat_id, block, page))


async def _v50_cfg_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ""
    if not (data.startswith("cfgsafe|") or data.startswith("cfg|")):
        return
    try:
        await q.answer()
    except Exception:
        pass
    if not is_global_admin_user(update.effective_user.id):
        try:
            await q.answer("Solo ADMIN_IDS.", show_alert=True)
        except Exception:
            pass
        raise ApplicationHandlerStop

    _v50_ensure_private_blocks()
    parts = data.split("|")
    prefix = parts[0]
    action = parts[1] if len(parts) > 1 else ""

    # Selector independiente nuevo y selector viejo compatible.
    if (prefix == "cfgsafe" and action == "list") or (prefix == "cfg" and action == "list"):
        load_all_states()
        await _v50_send_or_edit(q, "<b>Elige el grupo que quieres configurar:</b>", _v50_chat_selector_markup())
        raise ApplicationHandlerStop

    if len(parts) < 3:
        try:
            await q.answer("Acción inválida.", show_alert=True)
        except Exception:
            pass
        raise ApplicationHandlerStop
    try:
        chat_id = int(parts[2])
    except Exception:
        try:
            await q.answer("Grupo inválido.", show_alert=True)
        except Exception:
            pass
        raise ApplicationHandlerStop

    # Acciones principales de navegación, siempre directas.
    if action in ("open", "home", "reload"):
        await _v50_render_main(q, chat_id)
        raise ApplicationHandlerStop
    if action == "close":
        try:
            await q.message.delete()
        except Exception:
            await _v50_send_or_edit(q, "Panel cerrado.", None)
        raise ApplicationHandlerStop
    if action in ("save",):
        save_all_states()
        try:
            await q.answer("✅ Guardado")
        except Exception:
            pass
        await _v50_render_main(q, chat_id)
        raise ApplicationHandlerStop

    if action in ("block", "block_reload", "block_save"):
        block = parts[3] if len(parts) >= 4 else "validation"
        if action == "block_save":
            save_all_states()
        await _v50_render_block(q, chat_id, block)
        raise ApplicationHandlerStop

    # Menú de limpieza de mensajes de servicio.
    if action == "svc_toggle":
        cfg_set(chat_id, "service_cleanup_enabled", not bool(cfg_value(chat_id, "service_cleanup_enabled", False)))
        await _v50_render_block(q, chat_id, "service_cleanup")
        raise ApplicationHandlerStop
    if action == "svc_type" and len(parts) >= 4:
        kind = parts[3]
        service_cleanup_set_type(chat_id, kind, not service_cleanup_type_enabled(chat_id, kind))
        await _v50_render_block(q, chat_id, "service_cleanup")
        raise ApplicationHandlerStop
    if action == "svc_preset":
        mode = parts[3] if len(parts) >= 4 else "off"
        if mode == "off":
            cfg_set(chat_id, "service_cleanup_enabled", False)
            cfg_set(chat_id, "service_cleanup_types", {key: False for key in SERVICE_CLEANUP_LABELS})
        else:
            recommended = service_cleanup_types(chat_id)
            for key in recommended:
                recommended[key] = key not in ("new_members", "left_member")
            cfg_set(chat_id, "service_cleanup_enabled", True)
            cfg_set(chat_id, "service_cleanup_types", recommended)
        await _v50_render_block(q, chat_id, "service_cleanup")
        raise ApplicationHandlerStop

    # Menú Impostor.
    if action == "impconf":
        if len(parts) >= 5:
            sub = parts[3]
            if sub == "toggle" and len(parts) >= 6:
                key = parts[4]
                default = bool(int(parts[5])) if str(parts[5]).isdigit() else False
                # Seguridad: borrar pistas no se activa accidentalmente si no lo pides.
                cfg_set(chat_id, key, not bool(cfg_value(chat_id, key, default)))
            elif sub == "ttl" and len(parts) >= 5:
                try:
                    cfg_set(chat_id, "imp_finish_delete_ttl", int(parts[4]))
                except Exception:
                    cfg_set(chat_id, "imp_finish_delete_ttl", 120)
        await _v50_render_block(q, chat_id, "impostor_settings")
        raise ApplicationHandlerStop

    # Menú Alertas privadas.
    if action == "alert_toggle":
        # cfg|alert_toggle|chat|owner_alerts|key
        key = parts[4] if len(parts) >= 5 else "owner_private_alerts_enabled"
        cfg_set(chat_id, key, not bool(cfg_value(chat_id, key, True)))
        await _v50_render_block(q, chat_id, "owner_alerts")
        raise ApplicationHandlerStop

    # Menú IA Cerebrito. Mantiene los mismos callbacks ya creados.
    if action.startswith("ai_"):
        try:
            if action == "ai_toggle":
                flag = parts[3] if len(parts) > 3 else "enabled"
                keymap = {"enabled": "ai_enabled", "auto": "ai_auto_enabled", "good": "ai_good_morning_enabled", "image": "ai_good_morning_image"}
                key = keymap.get(flag, "ai_enabled")
                cfg_set(chat_id, key, not bool(cfg_value(chat_id, key, key == "ai_enabled")))
            elif action == "ai_freq" and len(parts) > 3:
                cfg_set(chat_id, "ai_auto_frequency", int(parts[3]))
            elif action == "ai_tone" and len(parts) > 3:
                cfg_set(chat_id, "ai_tone", parts[3])
            elif action == "ai_plimit" and len(parts) > 3:
                cfg_set(chat_id, "ai_planecito_daily_limit", int(parts[3]))
            elif action == "ai_alimit" and len(parts) > 3:
                cfg_set(chat_id, "ai_auto_daily_limit", int(parts[3]))
            elif action == "ai_set_time":
                set_config_pending(q.from_user.id, {"kind": "ai_good_morning_time", "chat_id": chat_id})
                await q.message.reply_html("🕘 Escribe la hora de buenos días, por ejemplo <code>09:00</code>.")
                raise ApplicationHandlerStop
            elif action == "ai_test_good":
                await q.message.reply_html("🌞 Enviando prueba de buenos días IA…")
                try:
                    await _ai_send_good_morning(context.bot, chat_id, manual=True)
                except Exception:
                    logger.exception("Fallo enviando prueba IA")
            elif action == "ai_cmd_new":
                set_config_pending(q.from_user.id, {"kind": "ai_custom_command", "chat_id": chat_id})
                await q.message.reply_html(
                    "➕ <b>Nuevo comando IA</b>\n\nEscribe:\n<code>nombre | instrucciones</code>\n\nEjemplo:\n<code>consejo | Da un consejo corto y divertido para el grupo.</code>"
                )
                raise ApplicationHandlerStop
            elif action == "ai_custom_prompt":
                set_config_pending(q.from_user.id, {"kind": "ai_custom_prompt", "chat_id": chat_id})
                await q.message.reply_html("🧠 Escribe el prompt extra para Cerebrito. Escribe <code>off</code> para borrar.")
                raise ApplicationHandlerStop
            elif action == "ai_test_prompt":
                await q.message.reply_html("🧪 Probando Cerebrito…")
                try:
                    ans = await _ai_openai_response(chat_id, "Dame una frase corta para animar el grupo hoy.", max_output_tokens=120)
                    await q.message.reply_text(ans[:1200])
                except Exception:
                    await q.message.reply_text("No pude probar la IA. Revisa OPENAI_API_KEY en Railway.")
            elif action == "ai_cmd_list":
                cmds = _ai_custom_commands(chat_id)
                if cmds:
                    text = "<b>📋 Comandos IA</b>\n\n" + "\n".join(f"• <code>/{h(k)}</code>" for k in sorted(cmds.keys()))
                else:
                    text = "<b>📋 Comandos IA</b>\n\nNo hay comandos personalizados."
                await q.message.reply_html(text)
                raise ApplicationHandlerStop
        except ApplicationHandlerStop:
            raise
        except Exception:
            logger.exception("Error en acción IA V50")
            try:
                await q.answer("Error en acción IA. Revisa logs.", show_alert=True)
            except Exception:
                pass
        await _v50_render_block(q, chat_id, "ai")
        raise ApplicationHandlerStop

    # Borrado de comandos global.
    if action == "cleanup_set" and len(parts) >= 4:
        cfg_set(chat_id, "command_cleanup_mode", parts[3])
        await _v50_render_block(q, chat_id, "command_cleanup")
        raise ApplicationHandlerStop

    # Dejamos pasar el resto al sistema antiguo.
    return


# Refuerzo: los textos/menús de los bloques nuevos deben existir aunque una redefinición previa no los haya conectado bien.
_old_v50_admin_private_block_text = admin_private_block_text
def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:  # type: ignore[override]
    _v50_ensure_private_blocks()
    try:
        return _old_v50_admin_private_block_text(chat_id, block, page)
    except Exception:
        logger.exception("Fallo renderizando texto bloque %s; usando fallback", block)
        return f"<b>{h(_v50_block_title(block))}</b>\nGrupo: <b>{h(get_chat_title(chat_id))}</b>\n\nPanel disponible. Usa los botones inferiores."

_old_v50_admin_private_block_markup = admin_private_block_markup
def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    _v50_ensure_private_blocks()
    try:
        return _old_v50_admin_private_block_markup(chat_id, block, page)
    except Exception:
        logger.exception("Fallo renderizando botones bloque %s; usando fallback", block)
        return InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Volver", callback_data=f"cfgsafe|open|{chat_id}")]])

# Versión final de build_application: registra router privado antes que todos los routers cfg viejos.
_old_build_application_v50 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v50()
    app.add_handler(command_handler("ajustes", _v50_ajustes_command), group=-10000)
    app.add_handler(command_handler("config", _v50_ajustes_command), group=-10000)
    app.add_handler(command_handler("admin", _v50_ajustes_command), group=-10000)
    app.add_handler(CallbackQueryHandler(_v50_cfg_router, pattern=r"^(cfgsafe|cfg)\|"), group=-10000)
    return app

# Arranque real del bot, siempre al final para que todos los parches anteriores estén cargados.
def main() -> None:
    _v50_ensure_private_blocks()
    app = build_application()
    app.run_polling(drop_pending_updates=False)

# =========================================================
# V51 - Router definitivo y único para menús nuevos + antídoto de callbacks duplicados
# =========================================================
# Este bloque se carga ANTES del arranque. Su objetivo es:
# - que Alertas privadas, Impostor, Cerebrito, Mensajes servicio y Borrado comandos entren siempre;
# - que los botones no ejecuten dos veces la misma acción;
# - que los callbacks del Impostor no se dupliquen.

try:
    from telegram.ext import ApplicationHandlerStop as _V51Stop
except Exception:  # fallback defensivo
    _V51Stop = Exception

_V51_CFG_BLOCKS = [
    ("service_cleanup", "🧽 Mensajes servicio"),
    ("command_cleanup", "🧹 Borrado comandos"),
    ("owner_alerts", "🔔 Alertas privadas"),
    ("impostor_settings", "🎭 Impostor"),
    ("ai", "🧠 IA Cerebrito"),
    ("polls", "📊 Encuestas"),
]


def _v51_ensure_blocks() -> None:
    global ADMIN_PRIVATE_BLOCKS, ADMIN_PRIVATE_BLOCK_IDS
    try:
        seen = {k for k, _ in ADMIN_PRIVATE_BLOCKS}
        insert_at = next((i for i, (k, _l) in enumerate(ADMIN_PRIVATE_BLOCKS) if k == "lists"), len(ADMIN_PRIVATE_BLOCKS))
        for key, label in _V51_CFG_BLOCKS:
            if key not in seen:
                ADMIN_PRIVATE_BLOCKS.insert(insert_at, (key, label))
                insert_at += 1
                seen.add(key)
            ADMIN_PRIVATE_BLOCK_IDS.add(key)
    except Exception:
        logger.exception("V51 no pudo asegurar bloques privados")


_v51_ensure_blocks()


def _v51_title(chat_id: int) -> str:
    try:
        return str(get_chat_title(chat_id) or cfg_value(chat_id, "chat_title", "") or chat_id)
    except Exception:
        return str(chat_id)


def _v51_onoff(value: Any) -> str:
    return "ON" if bool(value) else "OFF"


def _v51_check(value: Any) -> str:
    try:
        return cfg_status(value)
    except Exception:
        return "✅" if bool(value) else "❌"


def _v51_bool_label(value: Any) -> str:
    try:
        return bool_label(value)
    except Exception:
        return "ON" if bool(value) else "OFF"


def _v51_ai_limit(value: Any) -> str:
    try:
        n = int(value)
        return "Ilimitado" if n < 0 else str(n)
    except Exception:
        return str(value)


