def _v51_command_cleanup_markup(chat_id: int) -> InlineKeyboardMarkup:
    def st(v: str) -> str:
        try:
            return command_cleanup_status(chat_id, v)
        except Exception:
            mode = str(cfg_value(chat_id, "command_cleanup_mode", "off"))
            ttl = int(cfg_value(chat_id, "command_cleanup_ttl_seconds", 0) or 0)
            if v == "off": return "✅" if mode == "off" else "❌"
            if v == "instant": return "✅" if mode == "instant" else "❌"
            return "✅" if mode == "ttl" and ttl == int(v) else "❌"
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(f"{st('off')} No borrar", callback_data=f"cfg|cleanup_set|{chat_id}|off|command_cleanup"), InlineKeyboardButton(f"{st('instant')} Al ejecutar", callback_data=f"cfg|cleanup_set|{chat_id}|instant|command_cleanup")],
        [InlineKeyboardButton(f"{st('5')} A los 5s", callback_data=f"cfg|cleanup_set|{chat_id}|5|command_cleanup"), InlineKeyboardButton(f"{st('30')} A los 30s", callback_data=f"cfg|cleanup_set|{chat_id}|30|command_cleanup")],
        [InlineKeyboardButton("🔙 Volver", callback_data=f"cfg|home|{chat_id}")],
    ])


