_V79_NORMAL_WORDS = [
    'playa','discoteca','cita','pizza','karaoke','viaje','secreto','fiesta','beso','coqueteo','cine','terraza','hotel','misterio','mensaje','noche',
    'canción','mirada','café','plan','verano','chisme','bar','confesión','brindis','tatuaje','perfume','ascensor','desayuno','after','whatsapp','selfie',
    'risa','botella','cóctel','tren','aeropuerto','maleta','piscina','sofá','domingo','cumpleaños','concierto','amigo','ex','vecino','playlist','señal',
    'playback','taxi','secreto','playa','pulsera','llamada','foto','mensaje','sorpresa','barbacoa','montaña','lluvia','paraguas','helado','gafas',
    'maquillaje','zapatos','camisa','vestido','reloj','llaves','portal','azotea','terraza','copas','baile','ronda','meme','reto','pregunta','regalo',
    'sueño','mentira','verdad','rumor','grupo','fiestón','madrugada','amanecer','lío','atrevimiento','mirador','playa','tardeo','chupito','brillo',
]

# Modo HOT para adultos: palabras explícitas configurable solo desde ajustes.
_V79_HOT_WORDS = [
    'mamada','felación','trío','follar','polla','pene','sexo','orgasmo','chupar','correrse','penetración','postura','calentón','deseo','morbo','fantasía',
    'gemido','lencería','desnudo','culo','pechos','tetas','lengua','cama','ducha','juguete','dominación','sumisión','beso negro','porno','erección',
    'eyaculación','masturbación','sexo oral','polvo','rapidito','noches calientes','calentura','lubricante','condón','placer','provocar','perversión',
]


def _v79_word_bank(chat_id: int) -> list[str]:
    return list(_V79_HOT_WORDS if bool(cfg_value(chat_id, 'imp_hot_words_enabled', False)) else _V79_NORMAL_WORDS)


def _v79_pick_word(chat_id: int) -> str:
    cfg = admin_cfg(chat_id)
    words = [w for w in _v79_word_bank(chat_id) if str(w).strip()]
    if not words:
        words = list(IMPOSTOR_WORDS)
    hist = cfg.setdefault('imp_word_history', [])
    if not isinstance(hist, list):
        hist = []
        cfg['imp_word_history'] = hist
    recent = {str(x).lower() for x in hist[-40:]}
    available = [w for w in words if str(w).lower() not in recent]
    if not available:
        available = words[:]
        hist.clear()
    word = secrets.choice(available)
    hist.append(word)
    del hist[:-80]
    save_all_states()
    return word


async def _v79_pin_lobby(context: ContextTypes.DEFAULT_TYPE, chat_id: int, message_id: int) -> None:
    if not message_id:
        return
    cfg = admin_cfg(chat_id)
    old = int(cfg.get('imp_current_lobby_pin_id') or 0)
    if old and old != int(message_id):
        try:
            await context.bot.unpin_chat_message(chat_id=chat_id, message_id=old)
        except Exception:
            pass
    cfg['imp_current_lobby_pin_id'] = int(message_id)
    save_all_states()
    try:
        await context.bot.pin_chat_message(chat_id=chat_id, message_id=int(message_id), disable_notification=True)
    except Exception:
        pass


async def _v79_unpin_lobby(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Optional[Dict[str, Any]] = None) -> None:
    cfg = admin_cfg(chat_id)
    mid = int((game or {}).get('message_id') or cfg.get('imp_current_lobby_pin_id') or 0)
    if mid:
        try:
            await context.bot.unpin_chat_message(chat_id=chat_id, message_id=mid)
        except Exception:
            pass
    cfg['imp_current_lobby_pin_id'] = 0
    save_all_states()


# Texto del turno limpio: una sola línea de tiempo.
def _v58_imp_prompt_text(game: Dict[str, Any]) -> str:  # type: ignore[override]
    current = _imp_current_player(game)
    ronda = int(game.get('round', 1) or 1)
    if not current:
        return '🎭 No hay jugador de turno.'
    try:
        chat_id = int(game.get('chat_id') or 0)
    except Exception:
        chat_id = 0
    seconds = _v61_turn_seconds(chat_id) if chat_id and '_v61_turn_seconds' in globals() else 60
    ayudas = {
        1: 'Da una pista suave, una palabra o frase corta.',
        2: 'Da una pista un poco más clara, pero sin regalar la palabra.',
        3: 'Última pista. Puedes arriesgar un poco más, pero no digas la palabra exacta.',
    }
    count = _v60_current_timeout_count(game, int(current.get('id', 0) or 0)) if '_v60_current_timeout_count' in globals() else 0
    warn = 'Si no responde, pierde <b>1 punto</b> y se salta turno.' if count <= 0 else 'Si vuelve a no responder, queda <b>expulsado</b> y pierde <b>3 puntos más</b>.'
    return (
        f'✍️ {_imp_mention(current)}, <b>te toca.</b>\n\n'
        f'{h(ayudas.get(ronda, ayudas[3]))}\n'
        'Pulsa <b>Responder pista</b> y escribe tu pista en el grupo.\n\n'
        f'⏱ <b>Tiempo:</b> {_v60_format_remaining(seconds) if "_v60_format_remaining" in globals() else str(seconds) + "s"} · {warn}'
    )


def _v58_imp_prompt_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:  # type: ignore[override]
    gid = int(game.get('id', 0) or 0)
    return InlineKeyboardMarkup([[InlineKeyboardButton('✍️ Responder pista', callback_data=f'imp|respond|{chat_id}|{gid}')]])


# Panel de pistas: limpio, pero con acusar visible cuando toque por configuración.
def _v58_imp_card_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:  # type: ignore[override]
    gid = int(game.get('id', 0) or 0)
    status = str(game.get('status') or 'lobby')
    if status == 'lobby':
        return _imp_lobby_markup(chat_id, game)
    if status == 'voting':
        return InlineKeyboardMarkup([
            [InlineKeyboardButton('🗳 Votar', callback_data=f'imp|vote_menu|{chat_id}|{gid}')],
            [InlineKeyboardButton('🔐 Ver mi palabra', callback_data=f'imp|mysecret|{chat_id}|{gid}')],
        ])
    rows: List[List[InlineKeyboardButton]] = [[InlineKeyboardButton('🔐 Ver mi palabra', callback_data=f'imp|mysecret|{chat_id}|{gid}')]]
    try:
        can_accuse, reason = _v61_can_accuse_now(chat_id, game)
    except Exception:
        can_accuse, reason = True, ''
    if can_accuse:
        rows.append([InlineKeyboardButton('🚨 Acusar impostor', callback_data=f'imp|accuse_menu|{chat_id}|{gid}')])
    else:
        # Si solo está bloqueado por ronda, mostramos un botón informativo para que se vea cuándo se podrá acusar.
        try:
            if not _v61_final_vote_only(chat_id):
                rows.append([InlineKeyboardButton(f'🚨 Acusar: {reason}', callback_data=f'imp|accuse_locked|{chat_id}|{gid}')])
        except Exception:
            pass
    try:
        if not _v61_final_vote_only(chat_id):
            rows.append([InlineKeyboardButton('🗳 Votación final', callback_data=f'imp|vote_menu|{chat_id}|{gid}')])
    except Exception:
        rows.append([InlineKeyboardButton('🗳 Votación final', callback_data=f'imp|vote_menu|{chat_id}|{gid}')])
    return InlineKeyboardMarkup(rows)


# Lobby fijado cuando se crea partida por comando.
async def impostor_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    if not update.effective_chat or not update.message or not update.effective_user:
        return
    if update.effective_chat.type == 'private':
        await update.message.reply_text('Usa /impostor dentro del grupo.')
        return
    chat_id = int(update.effective_chat.id)
    active = next((g for g in _imp_games(chat_id) if str(g.get('status')) in ('lobby', 'active', 'voting')), None)
    if active:
        await update.message.reply_html('Ya hay una partida de Impostor activa. Cancélala o termínala antes de crear otra.')
        return
    raw = ' '.join(context.args).strip() if getattr(context, 'args', None) else ''
    word = raw[:60] if raw else _v79_pick_word(chat_id)
    gid = _imp_next_id(chat_id)
    creator = update.effective_user
    game = {
        'id': gid,
        'status': 'lobby',
        'word': word,
        'creator_id': int(creator.id),
        'created_ts': int(time.time()),
        'players': [{'id': int(creator.id), 'name': display_name(creator), 'username': getattr(creator, 'username', '') or ''}],
        'round': 1,
        'turn_idx': 0,
        'votes': {},
        'impostor_id': 0,
        'message_id': 0,
    }
    msg = await update.message.reply_html(_imp_lobby_text(game), reply_markup=_imp_lobby_markup(chat_id, game))
    game['message_id'] = int(msg.message_id)
    _imp_games(chat_id).insert(0, game)
    save_all_states()
    await _v79_pin_lobby(context, chat_id, msg.message_id)


# Asegura despin al empezar.
_old_v79_v58_imp_start_game = _v58_imp_start_game
async def _v58_imp_start_game(update: Update, context: ContextTypes.DEFAULT_TYPE, chat_id: int, gid: int, game: Dict[str, Any]) -> None:  # type: ignore[override]
    await _v79_unpin_lobby(context, chat_id, game)
    game['chat_id'] = int(chat_id)
    save_all_states()
    return await _old_v79_v58_imp_start_game(update, context, chat_id, gid, game)


