# Configuración HOT en ajustes -> Impostor.
_old_v79_admin_private_block_text = admin_private_block_text
def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:  # type: ignore[override]
    txt = _old_v79_admin_private_block_text(chat_id, block, page)
    if block == 'impostor_settings':
        hot = 'ON ✅' if bool(cfg_value(chat_id, 'imp_hot_words_enabled', False)) else 'OFF ❌'
        mode = 'HOT adulto' if bool(cfg_value(chat_id, 'imp_hot_words_enabled', False)) else 'Normal variado'
        txt += f'\n\n<b>Palabras del juego</b>\nModo actual: <b>{h(mode)}</b>\nModo HOT: <b>{hot}</b>\n<i>El modo HOT usa palabras adultas/sexuales y solo debería activarse en grupos adultos.</i>'
    return txt


_old_v79_admin_private_block_markup = admin_private_block_markup
def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    markup = _old_v79_admin_private_block_markup(chat_id, block, page)
    if block != 'impostor_settings':
        return markup
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    back = None
    if rows and any('Volver' in getattr(b, 'text', '') for b in rows[-1]):
        back = rows.pop()
    hot = bool(cfg_value(chat_id, 'imp_hot_words_enabled', False))
    rows.append([InlineKeyboardButton(('✅ ' if hot else '❌ ') + 'Modo HOT adulto', callback_data=f'cfg|imp79_hot|{chat_id}')])
    rows.append([InlineKeyboardButton('🧹 Reiniciar historial palabras', callback_data=f'cfg|imp79_clearwords|{chat_id}')])
    rows.append(back or [InlineKeyboardButton('🔙 Volver', callback_data=f'cfg|home|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v79_admin_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('cfg|imp79_'):
        return
    try:
        parts = data.split('|')
        action = parts[1]
        chat_id = int(parts[2])
        if action == 'imp79_hot':
            cfg_set(chat_id, 'imp_hot_words_enabled', not bool(cfg_value(chat_id, 'imp_hot_words_enabled', False)))
            await q.answer('Modo de palabras actualizado ✅', show_alert=True)
        elif action == 'imp79_clearwords':
            admin_cfg(chat_id)['imp_word_history'] = []
            save_all_states()
            await q.answer('Historial de palabras reiniciado ✅', show_alert=True)
        else:
            await q.answer()
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, 'impostor_settings'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'impostor_settings'))
        except Exception:
            await q.message.reply_html(admin_private_block_text(chat_id, 'impostor_settings'), reply_markup=admin_private_block_markup(chat_id, 'impostor_settings'))
        raise _V79Stop
    except _V79Stop:
        raise
    except Exception:
        logger.exception('Error config Impostor V79: %s', data)
        try:
            await q.answer('Error. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V79Stop


_old_impostor_callback_router_v79 = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('imp|'):
        return await _old_impostor_callback_router_v79(update, context)
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        if action == 'new':
            chat_id = int(parts[2])
            active = next((g for g in _imp_games(chat_id) if str(g.get('status')) in ('lobby','active','voting')), None)
            if active:
                await q.answer('Ya hay una partida activa.', show_alert=True)
                raise _V79Stop
            await _v79_create_game(context, chat_id, q.from_user)
            await q.answer('Nueva partida creada y fijada arriba 🎭', show_alert=True)
            raise _V79Stop
        if action == 'accuse_locked':
            chat_id = int(parts[2]); gid = int(parts[3])
            game = _imp_find(chat_id, gid)
            reason = 'Todavía no se puede acusar.'
            if game:
                try:
                    _ok, reason = _v61_can_accuse_now(chat_id, game)
                except Exception:
                    pass
            await q.answer(reason, show_alert=True)
            raise _V79Stop
    except _V79Stop:
        raise
    except Exception:
        logger.exception('Error router V79 Impostor: %s', data)
        try:
            await q.answer('Error en Impostor. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V79Stop
    return await _old_impostor_callback_router_v79(update, context)


_old_build_application_v79 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v79()
    app.add_handler(CallbackQueryHandler(_v79_admin_config_callback, pattern=r'^cfg\|imp79_'), group=-4200000)
    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern=r'^imp\|'), group=-4200000)
    logger.info('V79 Impostor acusar/hot/pin/ranking cargado')
    return app

def main() -> None:
    try:
        _v63_ensure_private_blocks()
    except Exception:
        pass
    _v77_ensure_private_blocks()
    app = build_application()
    app.run_polling(drop_pending_updates=False)


# =========================================================
# V80 - Impostor: acusar abajo, puntuación avanzada e instrucciones
# =========================================================
try:
    from telegram.ext import ApplicationHandlerStop as _V80Stop
except Exception:
    _V80Stop = Exception


def _v80_add_delta(chat_id: int, player: Dict[str, Any], points: int) -> None:
    """Suma/resta puntos sin incrementar partidas jugadas."""
    try:
        if '_v60_add_delta_no_game' in globals():
            _v60_add_delta_no_game(chat_id, player, int(points))
            return
    except Exception:
        pass
    try:
        uid = str(int(player.get('id', 0) or 0))
    except Exception:
        return
    if not uid or uid == '0':
        return
    name = str(player.get('name') or uid)
    store = _imp_score_store(chat_id)
    for scope, key in (("general", "all"), ("daily", _v44_today_key()), ("weekly", _v44_week_key())):
        bucket = store.setdefault(scope, {})
        period = bucket.setdefault(key, {})
        row = period.setdefault(uid, {'name': name, 'points': 0, 'games': 0})
        row['name'] = name
        row['points'] = int(row.get('points', 0) or 0) + int(points)


def _v80_accuse_points(ronda: int, correct: bool) -> int:
    ronda = max(1, min(3, int(ronda or 1)))
    if correct:
        return {1: 6, 2: 5, 3: 4}.get(ronda, 4)
    return {1: -3, 2: -4, 3: -5}.get(ronda, -5)


def _v80_apply_event_score(chat_id: int, game: Dict[str, Any], user_id: int, points: int, key: str) -> None:
    applied = game.setdefault('v80_event_scores_applied', {})
    unique = f'{key}:{int(user_id)}:{int(points)}'
    if applied.get(unique):
        return
    p = _imp_player(game, int(user_id)) or {'id': int(user_id), 'name': str(user_id)}
    _v80_add_delta(chat_id, p, int(points))
    applied[unique] = True
    save_all_states()


# Mensaje inferior de turno: aquí va acusar cuando toque. Tiempo una sola vez.
def _v58_imp_prompt_text(game: Dict[str, Any]) -> str:  # type: ignore[override]
    current = _imp_current_player(game)
    ronda = int(game.get('round', 1) or 1)
    if not current:
        return '🎭 No hay jugador de turno.'
    try:
        chat_id = int(game.get('chat_id') or 0)
    except Exception:
        chat_id = 0
    seconds = _v61_turn_seconds(chat_id) if chat_id and '_v61_turn_seconds' in globals() else 60
    ayudas = {
        1: 'Da una pista suave, una palabra o frase corta.',
        2: 'Da una pista un poco más clara, pero sin regalar la palabra.',
        3: 'Última pista. Puedes arriesgar un poco más, pero no digas la palabra exacta.',
    }
    count = _v60_current_timeout_count(game, int(current.get('id', 0) or 0)) if '_v60_current_timeout_count' in globals() else 0
    warn = 'Si no responde, pierde <b>1 punto</b> y se salta turno.' if count <= 0 else 'Si vuelve a no responder, queda <b>expulsado</b> y pierde <b>3 puntos más</b>.'
    can_accuse = False
    reason = ''
    if chat_id:
        try:
            can_accuse, reason = _v61_can_accuse_now(chat_id, game)
        except Exception:
            can_accuse, reason = True, ''
    accuse_line = '\n\n🚨 Ya puedes acusar si crees saber quién es el impostor.' if can_accuse else ''
    if reason and not can_accuse and 'ronda' in reason.lower():
        accuse_line = f'\n\n🚨 Acusar todavía no está activo: {h(reason)}'
    return (
        f'✍️ {_imp_mention(current)}, <b>te toca.</b>\n\n'
        f'{h(ayudas.get(ronda, ayudas[3]))}\n'
        'Pulsa <b>Responder pista</b> y escribe tu pista en el grupo.\n\n'
        f'⏱ <b>Tiempo:</b> {_v60_format_remaining(seconds) if "_v60_format_remaining" in globals() else str(seconds) + "s"} · {warn}'
        f'{accuse_line}'
    )


def _v58_imp_prompt_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:  # type: ignore[override]
    gid = int(game.get('id', 0) or 0)
    rows: List[List[InlineKeyboardButton]] = [
        [InlineKeyboardButton('✍️ Responder pista', callback_data=f'imp|respond|{chat_id}|{gid}')]
    ]
    try:
        can_accuse, _reason = _v61_can_accuse_now(chat_id, game)
    except Exception:
        can_accuse, _reason = True, ''
    if can_accuse:
        rows.append([InlineKeyboardButton('🚨 Acusar impostor', callback_data=f'imp|accuse_menu|{chat_id}|{gid}')])
    return InlineKeyboardMarkup(rows)


# Panel de pistas: sin acusar; acusar solo aparece en mensaje inferior de responder.
def _v58_imp_card_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:  # type: ignore[override]
    gid = int(game.get('id', 0) or 0)
    status = str(game.get('status') or 'lobby')
    if status == 'lobby':
        return _imp_lobby_markup(chat_id, game)
    if status == 'voting':
        return InlineKeyboardMarkup([
            [InlineKeyboardButton('🗳 Votar', callback_data=f'imp|vote_menu|{chat_id}|{gid}')],
            [InlineKeyboardButton('🔐 Ver mi palabra', callback_data=f'imp|mysecret|{chat_id}|{gid}')],
        ])
    rows: List[List[InlineKeyboardButton]] = [[InlineKeyboardButton('🔐 Ver mi palabra', callback_data=f'imp|mysecret|{chat_id}|{gid}')]]
    try:
        if not _v61_final_vote_only(chat_id):
            rows.append([InlineKeyboardButton('🗳 Votación final', callback_data=f'imp|vote_menu|{chat_id}|{gid}')])
    except Exception:
        rows.append([InlineKeyboardButton('🗳 Votación final', callback_data=f'imp|vote_menu|{chat_id}|{gid}')])
    return InlineKeyboardMarkup(rows)


_old_v80_imp_score_game = _imp_score_game

def _imp_score_game(chat_id: int, game: Dict[str, Any], winner_side: str) -> str:  # type: ignore[override]
    txt = _old_v80_imp_score_game(chat_id, game, winner_side)
    extra_lines: List[str] = []
    # Votación final: +3 si vota al impostor, -2 si falla. Impostor +3 por llegar al final.
    votes = game.get('votes') if isinstance(game.get('votes'), dict) else {}
    if votes and not game.get('v80_final_vote_scores_applied'):
        imp_id = int(game.get('impostor_id', 0) or 0)
        ok = 0
        fail = 0
        for voter_raw, target_raw in votes.items():
            try:
                voter_id = int(voter_raw)
                target_id = int(target_raw)
            except Exception:
                continue
            voter = _imp_player(game, voter_id)
            if not voter:
                continue
            if target_id == imp_id:
                _v80_add_delta(chat_id, voter, 3)
                ok += 1
            else:
                _v80_add_delta(chat_id, voter, -2)
                fail += 1
        imp = _imp_player(game, imp_id)
        if imp:
            _v80_add_delta(chat_id, imp, 3)
            extra_lines.append('😈 El impostor llegó al final: <b>+3 pts</b>.')
        if ok or fail:
            extra_lines.append(f'🗳 Votación final: acierto <b>+3</b> ({ok}); fallo <b>-2</b> ({fail}).')
        game['v80_final_vote_scores_applied'] = True
        save_all_states()
    if extra_lines:
        txt += '\n' + '\n'.join(extra_lines)
    return txt


def _imp_instructions_text() -> str:  # type: ignore[override]
    return (
        '📘 <b>Instrucciones · Juego del Impostor</b>\n\n'
        '1. Todos los jugadores reciben una palabra secreta menos el impostor.\n'
        '2. En cada turno, cada jugador da una pista corta.\n'
        '3. El impostor debe disimular y seguir el hilo sin saber la palabra.\n'
        '4. El botón <b>Acusar impostor</b> aparece en el mensaje inferior de turno cuando esté permitido por configuración.\n'
        '5. Si pasan las rondas configuradas, puede abrirse votación final.\n\n'
        '<b>🏆 Puntuación especial</b>\n'
        '• Votación final: acertar quién es el impostor suma <b>+3</b>.\n'
        '• Votación final: votar mal resta <b>-2</b>.\n'
        '• El impostor, si llega al final, suma <b>+3</b>.\n\n'
        '<b>🚨 Acusación directa por ronda</b>\n'
        '• Ronda 1: acertar <b>+6</b>; fallar <b>-3</b> y quedas eliminado.\n'
        '• Ronda 2: acertar <b>+5</b>; fallar <b>-4</b> y quedas eliminado.\n'
        '• Ronda 3: acertar <b>+4</b>; fallar <b>-5</b> y quedas eliminado.\n\n'
        'Si un jugador no responde a tiempo, se aplican las penalizaciones de inactividad configuradas.'
    )


_old_impostor_callback_router_v80 = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('imp|'):
        return await _old_impostor_callback_router_v80(update, context)
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    if action not in ('accuse_menu', 'accuse'):
        return await _old_impostor_callback_router_v80(update, context)
    try:
        chat_id = int(parts[2]); gid = int(parts[3])
    except Exception:
        await q.answer('Partida inválida', show_alert=True)
        raise _V80Stop
    game = _imp_find(chat_id, gid)
    if not game:
        await q.answer('No encuentro la partida.', show_alert=True)
        raise _V80Stop
    uid = int(q.from_user.id)
    try:
        allowed, reason = _v61_can_accuse_now(chat_id, game)
    except Exception:
        allowed, reason = True, ''
    if not allowed:
        await q.answer(reason or 'Todavía no se puede acusar.', show_alert=True)
        raise _V80Stop

    if action == 'accuse_menu':
        if str(game.get('status')) not in ('active', 'voting'):
            await q.answer('La partida no está activa.', show_alert=True); raise _V80Stop
        active_ids = [int(p.get('id', 0) or 0) for p in _imp_active_players(game)]
        if uid not in active_ids:
            await q.answer('Estás eliminado o no juegas esta partida.', show_alert=True); raise _V80Stop
        await q.answer('Elige a quién acusas')
        await q.edit_message_text(
            '🚨 <b>Acusar impostor</b>\n\n'
            'Elige a quién acusas. Si fallas, quedas eliminado y pierdes puntos según la ronda.',
            parse_mode=ParseMode.HTML,
            reply_markup=_imp_accuse_markup(chat_id, game, uid),
        )
        raise _V80Stop

    # action == accuse
    if len(parts) < 6:
        await q.answer('Acusación inválida.', show_alert=True); raise _V80Stop
    try:
        accuser_id = int(parts[4]); target_id = int(parts[5])
    except Exception:
        await q.answer('Acusación inválida.', show_alert=True); raise _V80Stop
    if uid != accuser_id:
        await q.answer('Esta acusación no es tuya.', show_alert=True); raise _V80Stop
    active_ids = [int(p.get('id', 0) or 0) for p in _imp_active_players(game)]
    if accuser_id not in active_ids:
        await q.answer('Ya estás eliminado.', show_alert=True); raise _V80Stop

    ronda = int(game.get('round', 1) or 1)
    correct = target_id == int(game.get('impostor_id', 0) or 0)
    pts = _v80_accuse_points(ronda, correct)
    _v80_apply_event_score(chat_id, game, accuser_id, pts, f'accuse_r{ronda}_{"ok" if correct else "fail"}')
    game.setdefault('accusations', []).append({'by': accuser_id, 'target': target_id, 'round': ronda, 'correct': bool(correct), 'points': pts, 'ts': int(time.time())})

    acc = _imp_player(game, accuser_id) or {'id': accuser_id, 'name': str(accuser_id)}
    target = _imp_player(game, target_id) or {'id': target_id, 'name': str(target_id)}
    if correct:
        game['winner_side'] = 'crew'
        save_all_states()
        await q.answer(f'¡Correcto! +{pts} puntos ✅', show_alert=True)
        await _imp_finish(context, chat_id, game, reason=f'\n{_imp_mention(acc)} acertó acusando a {_imp_mention(target)} en ronda {ronda}: <b>+{pts} pts</b>.')
        try:
            await q.edit_message_reply_markup(reply_markup=None)
        except Exception:
            pass
        raise _V80Stop

    # Fallo: penalización y eliminado.
    eliminated = game.setdefault('eliminated', [])
    if accuser_id not in [int(x) for x in eliminated if str(x).lstrip('-').isdigit()]:
        eliminated.append(accuser_id)
    active = _imp_active_players(game)
    game['turn_idx'] = int(game.get('turn_idx', 0) or 0) % max(1, len(active))
    save_all_states()
    if len(active) <= 2:
        game['winner_side'] = 'impostor'
        await q.answer(f'Fallaste: {pts} puntos y eliminado. Fin de partida.', show_alert=True)
        await _imp_finish(context, chat_id, game, reason=f'\n{_imp_mention(acc)} acusó a {_imp_mention(target)} y falló en ronda {ronda}: <b>{pts} pts</b> y eliminado.')
        raise _V80Stop
    await q.answer(f'Fallaste: {pts} puntos y eliminado ❌', show_alert=True)
    await q.edit_message_text(
        f'❌ {_imp_mention(acc)} acusó a {_imp_mention(target)} y falló en ronda {ronda}.\n'
        f'Penalización: <b>{pts} pts</b>. Queda eliminado.\n\nSigue el juego.',
        parse_mode=ParseMode.HTML,
    )
    try:
        await _v58_imp_render_down(context, chat_id, game, delete_previous=True)
    except Exception:
        logger.exception('No se pudo refrescar Impostor tras acusación fallida V80')
    raise _V80Stop


_old_build_application_v80 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v80()
    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern=r'^imp\|'), group=-4300000)
    logger.info('V80 Impostor acusar abajo y puntuación avanzada cargado')
    return app



# =========================================================
# V81 - Botón recurrente cmd:impostor lanza partida real
# =========================================================
# Corrige que un botón en mensaje recurrente tipo:
#   🎭 Impostor=cmd:impostor
# abra/una una sala del Impostor sin borrar el recurrente y sin pasar por
# el simulador genérico de comandos.

try:
    from telegram.ext import ApplicationHandlerStop as _V81Stop
except Exception:
    _V81Stop = Exception


def _v81_allowed_commands(chat_id: int) -> set[str]:
    try:
        allowed = set(_v66_allowed_rec_commands(chat_id))
    except Exception:
        allowed = set()
    if not allowed:
        try:
            allowed = set(_V65_ALLOWED_REC_COMMANDS)
        except Exception:
            allowed = set()
    return {str(x).lower().lstrip('/') for x in allowed}


async def _v81_can_use_impostor_button(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user) -> tuple[bool, str]:
    if not bool(cfg_value(chat_id, 'impostor_enabled', True)):
        return False, '🎭 El juego del Impostor está desactivado en este grupo.'
    try:
        if '_v67_allowed' in globals():
            ok = await _v67_allowed(context, chat_id, user, 'impostor')
        elif '_v62_allowed' in globals():
            ok = await _v62_allowed(context, chat_id, int(user.id), 'impostor')
        else:
            ok = True
        if not ok:
            return False, 'No estás autorizado para iniciar el Impostor.'
    except Exception:
        # Si falla el sistema de permisos, no bloqueamos el uso de un botón permitido por admin.
        pass
    return True, ''


async def _v81_reccmd_impostor_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('reccmd|'):
        return
    parts = data.split('|', 2)
    if len(parts) < 3:
        return
    try:
        chat_id = int(parts[1])
    except Exception:
        return
    try:
        cmd = _v66_clean_cmd_name(parts[2]) if '_v66_clean_cmd_name' in globals() else _v65_clean_rec_cmd(parts[2])
    except Exception:
        cmd = str(parts[2] or '').lower().lstrip('/').replace('cmd:', '').strip()
    if cmd != 'impostor':
        return

    # Respeta la lista configurable de comandos permitidos en botones.
    allowed = _v81_allowed_commands(chat_id)
    if allowed and 'impostor' not in allowed:
        await q.answer('/impostor no está permitido en botones recurrentes. Actívalo en Ajustes → Recurrentes → Comandos permitidos.', show_alert=True)
        raise _V81Stop

    ok, reason = await _v81_can_use_impostor_button(context, chat_id, q.from_user)
    if not ok:
        await q.answer(reason, show_alert=True)
        raise _V81Stop

    active = next((g for g in _imp_games(chat_id) if str(g.get('status')) in ('lobby', 'active', 'voting')), None)
    if active:
        status = str(active.get('status'))
        if status == 'lobby':
            players = active.setdefault('players', [])
            uid = int(q.from_user.id)
            if not any(int(p.get('id', 0) or 0) == uid for p in players):
                players.append({'id': uid, 'name': display_name(q.from_user), 'username': getattr(q.from_user, 'username', '') or ''})
                save_all_states()
                try:
                    mid = int(active.get('message_id') or 0)
                    if mid:
                        await context.bot.edit_message_text(
                            chat_id=chat_id,
                            message_id=mid,
                            text=_imp_lobby_text(active),
                            parse_mode=ParseMode.HTML,
                            reply_markup=_imp_lobby_markup(chat_id, active),
                        )
                except Exception:
                    logger.exception('No pude actualizar lobby al unirse desde recurrente')
                await q.answer('Te has unido a la partida 🎭', show_alert=True)
            else:
                await q.answer('Ya estás dentro de la partida 🎭', show_alert=True)
            raise _V81Stop
        await q.answer('Ya hay una partida de Impostor en marcha.', show_alert=True)
        raise _V81Stop

    try:
        game = await _v79_create_game(context, chat_id, q.from_user)
        await q.answer('Partida de Impostor creada y fijada arriba 🎭', show_alert=True)
        # El recurrente NO se borra: solo se crea el lobby nuevo.
    except Exception:
        logger.exception('Error creando Impostor desde botón recurrente')
        await q.answer('Error creando la partida. Revisa logs.', show_alert=True)
    raise _V81Stop


_old_build_application_v81 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v81()
    # Más prioritario que los routers genéricos reccmd V66/V69, para no simular /impostor.
    app.add_handler(CallbackQueryHandler(_v81_reccmd_impostor_callback, pattern=r'^reccmd\|'), group=-4400000)
    logger.info('V81 recurrente cmd:impostor lanza Impostor real cargado')
    return app

def main() -> None:
    try:
        _v63_ensure_private_blocks()
    except Exception:
        pass
    _v77_ensure_private_blocks()
    app = build_application()
    app.run_polling(drop_pending_updates=False)


# =========================================================
# V83 - Impostor: mensaje fijado solo para unirse + auto inicio lobby
# =========================================================
# - El mensaje fijado superior del Impostor es SOLO un aviso para unirse.
# - Al cancelar o empezar la partida se desfija y se borra ese aviso.
# - Se puede configurar auto-inicio del lobby: OFF / 1 / 2 / 5 minutos.

try:
    from telegram.ext import ApplicationHandlerStop as _V83Stop
except Exception:
    _V83Stop = Exception

IMPOSTOR_LOBBY_START_TASKS: Dict[str, asyncio.Task] = {}


def _v83_game_key(chat_id: int, gid: int) -> str:
    return f"{int(chat_id)}:{int(gid)}"


def _v83_lobby_timer_label(chat_id: int) -> str:
    sec = int(cfg_value(chat_id, 'imp_lobby_auto_start_sec', 0) or 0)
    if sec <= 0:
        return 'OFF'
    mins = max(1, sec // 60)
    return f'{mins} min'


def _v83_cancel_lobby_task(chat_id: int, gid: int) -> None:
    key = _v83_game_key(chat_id, gid)
    task = IMPOSTOR_LOBBY_START_TASKS.pop(key, None)
    if task and not task.done():
        task.cancel()


async def _v83_delete_lobby_invite(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Optional[Dict[str, Any]] = None) -> None:
    """Desfija y borra el aviso superior usado solo para unirse."""
    cfg = admin_cfg(chat_id)
    candidates = []
    for v in [
        (game or {}).get('v83_invite_pin_id'),
        cfg.get('imp_current_lobby_pin_id'),
        cfg.get('v83_imp_invite_pin_id'),
    ]:
        try:
            mid = int(v or 0)
            if mid and mid not in candidates:
                candidates.append(mid)
        except Exception:
            pass
    for mid in candidates:
        try:
            await context.bot.unpin_chat_message(chat_id=chat_id, message_id=mid)
        except Exception:
            pass
        try:
            await context.bot.delete_message(chat_id=chat_id, message_id=mid)
        except Exception:
            pass
    cfg['imp_current_lobby_pin_id'] = 0
    cfg['v83_imp_invite_pin_id'] = 0
    if game is not None:
        game['v83_invite_pin_id'] = 0
    save_all_states()


async def _v79_unpin_lobby(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Optional[Dict[str, Any]] = None) -> None:  # type: ignore[override]
    # Desde V83 ya no se desfija solo: se borra el aviso superior.
    try:
        gid = int((game or {}).get('id', 0) or 0)
        if gid:
            _v83_cancel_lobby_task(chat_id, gid)
    except Exception:
        pass
    await _v83_delete_lobby_invite(context, chat_id, game)


async def _v79_pin_lobby(context: ContextTypes.DEFAULT_TYPE, chat_id: int, message_id: int) -> None:  # type: ignore[override]
    """En vez de fijar el lobby completo, crea/fija un aviso limpio solo con botón Unirme."""
    if not message_id:
        return
    game = next((g for g in _imp_games(chat_id) if str(g.get('status')) == 'lobby' and int(g.get('message_id', 0) or 0) == int(message_id)), None)
    if not game:
        # fallback: no fijamos el lobby completo para no llenar arriba de botones.
        return
    await _v83_delete_lobby_invite(context, chat_id, game)
    gid = int(game.get('id', 0) or 0)
    text = (
        '🎭 <b>Partida de Impostor abierta</b>\n\n'
        'Pulsa <b>Unirme</b> para entrar a la sala.\n'
        'Este aviso se quitará al empezar o cancelar la partida.'
    )
    try:
        msg = await context.bot.send_message(
            chat_id,
            text,
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🙋 Unirme', callback_data=f'imp|join|{chat_id}|{gid}')]]),
        )
        game['v83_invite_pin_id'] = int(msg.message_id)
        cfg = admin_cfg(chat_id)
        cfg['imp_current_lobby_pin_id'] = int(msg.message_id)
        cfg['v83_imp_invite_pin_id'] = int(msg.message_id)
        save_all_states()
        try:
            await context.bot.pin_chat_message(chat_id=chat_id, message_id=msg.message_id, disable_notification=True)
        except Exception:
            pass
        _v83_schedule_lobby_autostart(context, chat_id, game)
    except Exception:
        logger.exception('No se pudo crear/fijar aviso de lobby Impostor V83')


def _v83_lobby_public_text(game: Dict[str, Any]) -> str:
    base = _imp_lobby_text(game)
    try:
        timer = int(game.get('v83_auto_start_sec') or 0)
        if timer > 0:
            base += f"\n\n⏱ Inicio automático: <b>{max(1, timer//60)} min</b> desde apertura del lobby."
    except Exception:
        pass
    return base


def _v83_schedule_lobby_autostart(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any]) -> None:
    gid = int(game.get('id', 0) or 0)
    if not gid:
        return
    _v83_cancel_lobby_task(chat_id, gid)
    sec = int(cfg_value(chat_id, 'imp_lobby_auto_start_sec', 0) or 0)
    game['v83_auto_start_sec'] = sec
    save_all_states()
    if sec <= 0:
        return
    task = asyncio.create_task(_v83_lobby_autostart_later(context, chat_id, gid, sec))
    IMPOSTOR_LOBBY_START_TASKS[_v83_game_key(chat_id, gid)] = task


async def _v83_lobby_autostart_later(context: ContextTypes.DEFAULT_TYPE, chat_id: int, gid: int, seconds: int) -> None:
    try:
        await asyncio.sleep(max(5, int(seconds)))
        game = _imp_find(chat_id, gid)
        if not game or str(game.get('status')) != 'lobby':
            return
        players = game.get('players') if isinstance(game.get('players'), list) else []
        if len(players) < 3:
            try:
                await context.bot.send_message(chat_id, '🎭 No se inició el Impostor: hacen falta mínimo 3 jugadores. El lobby sigue abierto.')
            except Exception:
                pass
            return
        await _v83_start_lobby_game(context, chat_id, game, automatic=True)
    except asyncio.CancelledError:
        return
    except Exception:
        logger.exception('Error auto-iniciando lobby Impostor V83')
    finally:
        IMPOSTOR_LOBBY_START_TASKS.pop(_v83_game_key(chat_id, gid), None)


async def _v83_start_lobby_game(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], *, automatic: bool = False) -> None:
    players = game.get('players') if isinstance(game.get('players'), list) else []
    if len(players) < 3:
        if automatic:
            await context.bot.send_message(chat_id, '🎭 No se puede iniciar: mínimo 3 jugadores.')
        return
    gid = int(game.get('id', 0) or 0)
    _v83_cancel_lobby_task(chat_id, gid)
    await _v83_delete_lobby_invite(context, chat_id, game)
    # Borra el lobby público al empezar, para que abajo quede solo el juego visual.
    try:
        mid = int(game.get('message_id', 0) or 0)
        if mid:
            await context.bot.delete_message(chat_id=chat_id, message_id=mid)
    except Exception:
        pass
    game['status'] = 'active'
    game['round'] = 1
    game['turn_idx'] = secrets.randbelow(len(players)) if bool(cfg_value(chat_id, 'imp_random_start', True)) and players else 0
    game['votes'] = {}
    game['eliminated'] = []
    game['accusations'] = []
    game['clues'] = []
    game['timeout_counts'] = {}
    game['score_penalties'] = {}
    game['impostor_id'] = int(secrets.choice(players).get('id'))
    game['chat_id'] = int(chat_id)
    save_all_states()
    if automatic:
        try:
            await context.bot.send_message(chat_id, '🎭 <b>La partida empieza automáticamente.</b>', parse_mode=ParseMode.HTML)
        except Exception:
            pass
    try:
        await _v58_imp_render_down(context, chat_id, game, delete_previous=True)
    except Exception:
        logger.exception('No se pudo renderizar partida auto-iniciada V83')


# Override de creación por comando para usar lobby público + aviso fijado limpio.
async def impostor_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    if not update.effective_chat or not update.message or not update.effective_user:
        return
    if update.effective_chat.type == 'private':
        await update.message.reply_text('Usa /impostor dentro del grupo.')
        return
    chat_id = int(update.effective_chat.id)
    active = next((g for g in _imp_games(chat_id) if str(g.get('status')) in ('lobby', 'active', 'voting')), None)
    if active:
        await update.message.reply_html('Ya hay una partida de Impostor activa. Cancélala o termínala antes de crear otra.')
        return
    raw = ' '.join(context.args).strip() if getattr(context, 'args', None) else ''
    word = raw[:60] if raw else _v79_pick_word(chat_id)
    gid = _imp_next_id(chat_id)
    creator = update.effective_user
    game = {
        'id': gid,
        'status': 'lobby',
        'word': word,
        'creator_id': int(creator.id),
        'created_ts': int(time.time()),
        'players': [{'id': int(creator.id), 'name': display_name(creator), 'username': getattr(creator, 'username', '') or ''}],
        'round': 1,
        'turn_idx': 0,
        'votes': {},
        'impostor_id': 0,
        'message_id': 0,
    }
    game['v83_auto_start_sec'] = int(cfg_value(chat_id, 'imp_lobby_auto_start_sec', 0) or 0)
    msg = await update.message.reply_html(_v83_lobby_public_text(game), reply_markup=_imp_lobby_markup(chat_id, game))
    game['message_id'] = int(msg.message_id)
    _imp_games(chat_id).insert(0, game)
    save_all_states()
    await _v79_pin_lobby(context, chat_id, msg.message_id)


# Override de creación por botón recurrente / botón Nueva partida.
async def _v79_create_game(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user) -> Dict[str, Any]:  # type: ignore[override]
    gid = _imp_next_id(chat_id)
    game = {
        'id': gid,
        'status': 'lobby',
        'word': _v79_pick_word(chat_id),
        'creator_id': int(user.id),
        'created_ts': int(time.time()),
        'players': [{'id': int(user.id), 'name': display_name(user), 'username': getattr(user, 'username', '') or ''}],
        'round': 1,
        'turn_idx': 0,
        'votes': {},
        'impostor_id': 0,
        'message_id': 0,
    }
    game['v83_auto_start_sec'] = int(cfg_value(chat_id, 'imp_lobby_auto_start_sec', 0) or 0)
    msg = await context.bot.send_message(chat_id, _v83_lobby_public_text(game), parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, game))
    game['message_id'] = int(msg.message_id)
    _imp_games(chat_id).insert(0, game)
    save_all_states()
    await _v79_pin_lobby(context, chat_id, msg.message_id)
    return game


# Configuración del tiempo de inicio automático en Ajustes -> Impostor.
_old_admin_private_block_text_v83 = admin_private_block_text
def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:  # type: ignore[override]
    txt = _old_admin_private_block_text_v83(chat_id, block, page)
    if block == 'impostor_settings':
        txt += (
            '\n\n<b>Lobby del Impostor</b>'
            f'\nInicio automático: <b>{h(_v83_lobby_timer_label(chat_id))}</b>'
            '\nEl aviso fijado superior será solo para unirse y se borrará al empezar/cancelar.'
        )
    return txt


_old_admin_private_block_markup_v83 = admin_private_block_markup
def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    markup = _old_admin_private_block_markup_v83(chat_id, block, page)
    if block != 'impostor_settings':
        return markup
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    back = None
    if rows and any('Volver' in getattr(b, 'text', '') for b in rows[-1]):
        back = rows.pop()
    current = int(cfg_value(chat_id, 'imp_lobby_auto_start_sec', 0) or 0)
    def b(label: str, sec: int):
        return InlineKeyboardButton(('✅ ' if current == sec else '') + label, callback_data=f'cfg|imp83_lobbytimer|{chat_id}|{sec}')
    rows.append([InlineKeyboardButton('⏱ Inicio lobby', callback_data=f'cfg|noop|{chat_id}|impostor_settings')])
    rows.append([b('OFF', 0), b('1 min', 60), b('2 min', 120), b('5 min', 300)])
    rows.append(back or [InlineKeyboardButton('🔙 Volver', callback_data=f'cfg|home|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v83_admin_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('cfg|imp83_lobbytimer|'):
        return
    try:
        _p, _a, chat_s, sec_s = data.split('|', 3)
        chat_id = int(chat_s); sec = int(sec_s)
    except Exception:
        await q.answer('Configuración inválida', show_alert=True)
        raise _V83Stop
    cfg_set(chat_id, 'imp_lobby_auto_start_sec', max(0, sec))
    await q.answer('Tiempo de lobby actualizado ✅')
    try:
        await q.edit_message_text(admin_private_block_text(chat_id, 'impostor_settings'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'impostor_settings'))
    except Exception:
        await q.message.reply_html(admin_private_block_text(chat_id, 'impostor_settings'), reply_markup=admin_private_block_markup(chat_id, 'impostor_settings'))
    raise _V83Stop


_old_impostor_callback_router_v83 = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('imp|'):
        return await _old_impostor_callback_router_v83(update, context)
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    if action not in ('start', 'cancel', 'join', 'leave', 'new'):
        return await _old_impostor_callback_router_v83(update, context)
    # Nueva partida desde resultado: usa nuestra creación con aviso fijado limpio.
    if action == 'new':
        try:
            chat_id = int(parts[2])
        except Exception:
            await q.answer('Grupo inválido', show_alert=True); raise _V83Stop
        active = next((g for g in _imp_games(chat_id) if str(g.get('status')) in ('lobby', 'active', 'voting')), None)
        if active:
            await q.answer('Ya hay una partida activa.', show_alert=True); raise _V83Stop
        await _v79_create_game(context, chat_id, q.from_user)
        await q.answer('Nueva partida creada y fijada arriba 🎭', show_alert=True)
        raise _V83Stop
    try:
        chat_id = int(parts[2]); gid = int(parts[3])
    except Exception:
        await q.answer('Partida inválida', show_alert=True); raise _V83Stop
    game = _imp_find(chat_id, gid)
    if not game:
        await q.answer('No encuentro la partida.', show_alert=True); raise _V83Stop
    if action == 'cancel':
        _v83_cancel_lobby_task(chat_id, gid)
        await _v83_delete_lobby_invite(context, chat_id, game)
        # dejar que el router antiguo cancele/borre lobby según config
        return await _old_impostor_callback_router_v83(update, context)
    if action == 'start':
        # Control manual para asegurar que se borre el fijado antes de iniciar.
        uid = int(q.from_user.id)
        allowed = uid == int(game.get('creator_id', 0) or 0) or await is_admin(context, chat_id, uid)
        if not allowed:
            await q.answer('Solo creador/admin puede empezar', show_alert=True); raise _V83Stop
        players = game.get('players') if isinstance(game.get('players'), list) else []
        if len(players) < 3:
            await q.answer('Mínimo 3 jugadores', show_alert=True); raise _V83Stop
        await q.answer('Partida iniciada 🎭')
        await _v83_start_lobby_game(context, chat_id, game, automatic=False)
        raise _V83Stop
    if action in ('join', 'leave'):
        result = await _old_impostor_callback_router_v83(update, context)
        # Si el lobby sigue activo, asegura que el aviso fijado exista y sea solo de unirse.
        game2 = _imp_find(chat_id, gid)
        if game2 and str(game2.get('status')) == 'lobby':
            try:
                mid = int(game2.get('message_id', 0) or 0)
                if mid and not int(game2.get('v83_invite_pin_id') or 0):
                    await _v79_pin_lobby(context, chat_id, mid)
            except Exception:
                pass
        return result
    return await _old_impostor_callback_router_v83(update, context)


_old_build_application_v83 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v83()
    app.add_handler(command_handler('impostor', impostor_command), group=-4500000)
    app.add_handler(CallbackQueryHandler(_v83_admin_callback, pattern=r'^cfg\|imp83_lobbytimer\|'), group=-4500000)
    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern=r'^imp\|'), group=-4500000)
    logger.info('V83 Impostor lobby pin limpio y auto-inicio configurado')
    return app


# =========================================================
# V84 - Comandos IA: pregunta configurable y mensaje mínimo
# =========================================================
# Si un comando IA se ejecuta sin dato, muestra exactamente el texto
# configurado en el comando, por ejemplo: "Escribe tu ciudad y envía.".
# No añade "pulsa responder" ni textos largos; ForceReply ya marca responder.

try:
    from telegram.ext import ApplicationHandlerStop as _V84Stop
except Exception:
    _V84Stop = Exception


def _v84_ai_command_ask_text(data: Dict[str, Any]) -> str:
    txt = str(
        data.get('ask')
        or data.get('ask_message')
        or data.get('question')
        or data.get('missing_data_message')
        or ''
    ).strip()
    # Evita que comandos antiguos sigan mostrando textos poco elegantes.
    bad_defaults = {
        '¿qué quieres consultar?',
        'que quieres consultar?',
        'pulsa responder y escribe el dato que falta.',
        'pulsa responder y escribe el dato que falta',
    }
    if not txt or txt.lower() in bad_defaults:
        txt = 'Escribe el dato que falta y envía.'
    return txt[:500]


async def _v84_ai_custom_command_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user:
        return
    text = (update.message.text or '').strip()
    if not text.startswith('/'):
        return
    first, *rest = text.split(maxsplit=1)
    cmd = (_ai_clean_command_name(first) if '_ai_clean_command_name' in globals() else first.lstrip('/').lower())
    reserved = {
        'start','help','ajustes','plan','djplan','ping','preguntita','retito','examen',
        'privadito','impostor','impostorstop','cerebrito','planecito','tiempo','iatest'
    }
    if cmd in reserved:
        return
    preferred = int(update.effective_chat.id) if update.effective_chat and int(update.effective_chat.id) in STATE_CACHE else None
    try:
        chat_id, data = _v71_find_ai_command(cmd, preferred)
    except Exception:
        chat_id, data = None, None
    if not chat_id or not isinstance(data, dict):
        return
    if not bool(cfg_value(chat_id, 'ai_enabled', True)):
        await update.message.reply_text('🧠 Cerebrito está desactivado en ese grupo.')
        raise _V84Stop
    arg = rest[0].strip() if rest else ''
    if not arg:
        set_config_pending(update.effective_user.id, {
            'kind': 'ai_custom_command_query_v71',
            'chat_id': int(chat_id),
            'cmd': cmd,
        })
        msg = await update.message.reply_html(
            h(_v84_ai_command_ask_text(data)),
            reply_markup=ForceReply(selective=True),
        )
        try:
            if update.effective_chat and update.effective_chat.type == 'private' and '_v71_track_private_message' in globals():
                _v71_track_private_message(update.effective_user.id, msg.message_id)
        except Exception:
            pass
        raise _V84Stop

    wait = await update.message.reply_text('🧠 Pensando…')
    try:
        prompt = _v71_format_ai_custom_prompt(data, arg, display_name(update.effective_user))
        ans = await _ai_openai_response(
            int(chat_id),
            prompt,
            max_output_tokens=int(cfg_value(int(chat_id), 'ai_custom_command_tokens', 500) or 500),
        )
        try:
            await wait.edit_text(ans[:3900])
        except Exception:
            await update.message.reply_text(ans[:3900])
        _ai_usage_inc(int(chat_id), int(update.effective_user.id), 'planecito')
    except Exception as e:
        logger.exception('Error comando IA personalizado V84 /%s', cmd)
        try:
            await wait.edit_text(f'❌ Error IA: {type(e).__name__}\n{str(e)[:500]}')
        except Exception:
            await update.message.reply_text(f'❌ Error IA: {type(e).__name__}')
    raise _V84Stop


# Mejora del texto de ayuda al crear comandos IA guiados.
_old_build_application_v84 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v84()
    # Prioridad superior al handler V71 para que use la pregunta configurable.
    app.add_handler(MessageHandler(filters.COMMAND, _v84_ai_custom_command_handler), group=-5100000)
    logger.info('V84 comandos IA con pregunta configurable cargado')
    return app


# =========================================================
# V85 - Comandos IA: borrados configurables y edición
# =========================================================
# - Borra el mensaje del comando tras X segundos.
# - Borra el mensaje de petición de dato y la respuesta del dato tras X segundos.
# - Deja el resultado visible X segundos.
# - Añade edición de comandos IA existentes desde ajustes.

try:
    from telegram.ext import ApplicationHandlerStop as _V85Stop
except Exception:
    _V85Stop = Exception


def _v85_int_cfg(chat_id: int, key: str, default: int) -> int:
    try:
        return max(0, int(cfg_value(chat_id, key, default) or default))
    except Exception:
        return int(default)


def _v85_cmd_delete_seconds(chat_id: int) -> int:
    return _v85_int_cfg(chat_id, 'ai_cmd_delete_command_seconds', 5)


def _v85_ask_delete_seconds(chat_id: int) -> int:
    return _v85_int_cfg(chat_id, 'ai_cmd_delete_ask_seconds', 5)


def _v85_result_delete_seconds(chat_id: int) -> int:
    return _v85_int_cfg(chat_id, 'ai_cmd_delete_result_seconds', 300)


def _v85_label_seconds(sec: int) -> str:
    sec = int(sec or 0)
    if sec <= 0:
        return 'No borrar'
    if sec % 60 == 0 and sec >= 60:
        m = sec // 60
        return f'{m} min' if m == 1 else f'{m} min'
    return f'{sec}s'


async def _v85_delete_later(bot, chat_id: int, message_id: int, seconds: int) -> None:
    try:
        seconds = int(seconds or 0)
    except Exception:
        seconds = 0
    if seconds <= 0 or not message_id:
        return
    try:
        await asyncio.sleep(seconds)
        await bot.delete_message(chat_id=chat_id, message_id=message_id)
    except Exception:
        pass


def _v85_schedule_delete(context: ContextTypes.DEFAULT_TYPE, chat_id: int, message_id: Optional[int], seconds: int) -> None:
    if not message_id or int(seconds or 0) <= 0:
        return
    try:
        asyncio.create_task(_v85_delete_later(context.bot, int(chat_id), int(message_id), int(seconds)))
    except Exception:
        pass


def _v85_ai_command_settings_text(chat_id: int) -> str:
    return (
        '<b>⚙️ Ajustes de comandos IA</b>\n'
        f'Grupo: <b>{h(get_chat_title(chat_id)) if "get_chat_title" in globals() else h(chat_id)}</b>\n\n'
        f'Borrar comando ejecutado: <b>{h(_v85_label_seconds(_v85_cmd_delete_seconds(chat_id)))}</b>\n'
        f'Borrar petición/dato faltante: <b>{h(_v85_label_seconds(_v85_ask_delete_seconds(chat_id)))}</b>\n'
        f'Duración del resultado: <b>{h(_v85_label_seconds(_v85_result_delete_seconds(chat_id)))}</b>\n\n'
        'Recomendado:\n'
        '• Comando: <b>2s</b>\n'
        '• Petición/dato: <b>2s</b>\n'
        '• Resultado: <b>5 min</b>'
    )


def _v85_ai_command_settings_markup(chat_id: int) -> InlineKeyboardMarkup:
    rows = [
        [InlineKeyboardButton('🧾 Comando 5s', callback_data=f'cfg|ai_cmd_time|{chat_id}|command|5'), InlineKeyboardButton('10s', callback_data=f'cfg|ai_cmd_time|{chat_id}|command|10'), InlineKeyboardButton('30s', callback_data=f'cfg|ai_cmd_time|{chat_id}|command|30')],
        [InlineKeyboardButton('❓ Petición 5s', callback_data=f'cfg|ai_cmd_time|{chat_id}|ask|5'), InlineKeyboardButton('10s', callback_data=f'cfg|ai_cmd_time|{chat_id}|ask|10'), InlineKeyboardButton('30s', callback_data=f'cfg|ai_cmd_time|{chat_id}|ask|30')],
        [InlineKeyboardButton('📌 Resultado 1m', callback_data=f'cfg|ai_cmd_time|{chat_id}|result|60'), InlineKeyboardButton('5m', callback_data=f'cfg|ai_cmd_time|{chat_id}|result|300'), InlineKeyboardButton('10m', callback_data=f'cfg|ai_cmd_time|{chat_id}|result|600')],
        [InlineKeyboardButton('Resultado no borrar', callback_data=f'cfg|ai_cmd_time|{chat_id}|result|0')],
        [InlineKeyboardButton('🔙 IA Cerebrito', callback_data=f'cfg|block|{chat_id}|ai')],
    ]
    return InlineKeyboardMarkup(rows)


_old_v85_admin_private_block_text = admin_private_block_text

def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:  # type: ignore[override]
    text = _old_v85_admin_private_block_text(chat_id, block, page)
    if block == 'ai':
        extra = (
            '\n\n<b>Comandos IA · limpieza</b>\n'
            f'Comando: <b>{h(_v85_label_seconds(_v85_cmd_delete_seconds(chat_id)))}</b> · '
            f'Petición/dato: <b>{h(_v85_label_seconds(_v85_ask_delete_seconds(chat_id)))}</b> · '
            f'Resultado: <b>{h(_v85_label_seconds(_v85_result_delete_seconds(chat_id)))}</b>'
        )
        if 'Comandos IA · limpieza' not in text:
            text += extra
    return text


_old_v85_admin_private_block_markup = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    markup = _old_v85_admin_private_block_markup(chat_id, block, page)
    if block != 'ai':
        return markup
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    extra = [
        [InlineKeyboardButton('✏️ Editar comando IA', callback_data=f'cfg|ai_cmd_edit_menu|{chat_id}'), InlineKeyboardButton('⚙️ Limpieza comandos IA', callback_data=f'cfg|ai_cmd_settings|{chat_id}')],
    ]
    # Evitar duplicados si se renderiza muchas veces.
    flat = ' '.join(str(getattr(b, 'callback_data', '')) for row in rows for b in row)
    if 'ai_cmd_edit_menu' not in flat:
        # antes del volver si existe
        if rows and any('home' in str(getattr(b, 'callback_data', '')) for b in rows[-1]):
            rows = rows[:-1] + extra + rows[-1:]
        else:
            rows.extend(extra)
    return InlineKeyboardMarkup(rows)


async def _v85_render_ai_block(q, chat_id: int) -> None:
    try:
        await q.edit_message_text(admin_private_block_text(chat_id, 'ai'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'ai'))
    except Exception:
        await q.message.reply_html(admin_private_block_text(chat_id, 'ai'), reply_markup=admin_private_block_markup(chat_id, 'ai'))


def _v85_command_summary(data: Dict[str, Any]) -> str:
    ask = str(data.get('ask') or data.get('ask_message') or '').strip()
    prompt = str(data.get('prompt') or data.get('instructions') or '').strip()
    return f"Pregunta: {ask[:45] or '—'} | Prompt: {prompt[:45] or '—'}"


async def _v85_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('cfg|'):
        return
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        if action == 'ai_cmd_settings':
            chat_id = int(parts[2])
            await q.answer()
            await q.edit_message_text(_v85_ai_command_settings_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v85_ai_command_settings_markup(chat_id))
            raise _V85Stop
        if action == 'ai_cmd_time':
            chat_id = int(parts[2]); kind = parts[3]; sec = int(parts[4])
            keymap = {
                'command': 'ai_cmd_delete_command_seconds',
                'ask': 'ai_cmd_delete_ask_seconds',
                'result': 'ai_cmd_delete_result_seconds',
            }
            key = keymap.get(kind)
            if not key:
                await q.answer('Opción no válida', show_alert=True); raise _V85Stop
            cfg_set(chat_id, key, max(0, sec)); save_all_states()
            await q.answer('Guardado ✅')
            await q.edit_message_text(_v85_ai_command_settings_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v85_ai_command_settings_markup(chat_id))
            raise _V85Stop
        if action == 'ai_cmd_edit_menu':
            chat_id = int(parts[2])
            cmds = _ai_custom_commands(chat_id) if '_ai_custom_commands' in globals() else {}
            rows = []
            for name in sorted(cmds.keys()):
                rows.append([InlineKeyboardButton(f'✏️ /{name}', callback_data=f'cfg|ai_cmd_edit|{chat_id}|{name}')])
            rows.append([InlineKeyboardButton('🔙 IA Cerebrito', callback_data=f'cfg|block|{chat_id}|ai')])
            txt = '<b>✏️ Editar comando IA</b>\n\nElige el comando que quieres editar.' if cmds else '<b>✏️ Editar comando IA</b>\n\nNo tienes comandos IA creados.'
            await q.answer()
            await q.edit_message_text(txt, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(rows))
            raise _V85Stop
        if action == 'ai_cmd_edit':
            chat_id = int(parts[2]); name = parts[3].lower()
            cmds = _ai_custom_commands(chat_id)
            if name not in cmds:
                await q.answer('No encuentro ese comando', show_alert=True); raise _V85Stop
            set_config_pending(q.from_user.id, {'kind': 'ai_custom_command_edit_v85', 'chat_id': chat_id, 'name': name})
            cur = cmds.get(name) or {}
            await q.answer()
            await q.message.reply_html(
                f'✏️ <b>Editando /{h(name)}</b>\n\n'
                f'Actual:\n<blockquote>{h(_v85_command_summary(cur))}</blockquote>\n\n'
                'Envíame el nuevo formato:\n'
                '<code>mensaje que pedirá | prompt</code>\n\n'
                'Ejemplo:\n'
                '<code>Escribe tu ciudad y envía. | Da el tiempo actual de {query}, claro y breve.</code>'
            )
            raise _V85Stop
    except _V85Stop:
        raise
    except Exception:
        logger.exception('Error callback V85 %s', data)
        try:
            await q.answer('Error. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V85Stop


async def _v85_ai_custom_command_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user:
        return
    text = (update.message.text or '').strip()
    if not text.startswith('/'):
        return
    first, *rest = text.split(maxsplit=1)
    cmd = (_ai_clean_command_name(first) if '_ai_clean_command_name' in globals() else first.lstrip('/').lower())
    reserved = {
        'start','help','ajustes','plan','djplan','ping','preguntita','retito','examen',
        'privadito','impostor','impostorstop','cerebrito','planecito','tiempo','iatest'
    }
    if cmd in reserved:
        return
    preferred = int(update.effective_chat.id) if update.effective_chat and int(update.effective_chat.id) in STATE_CACHE else None
    try:
        chat_id, data = _v71_find_ai_command(cmd, preferred)
    except Exception:
        chat_id, data = None, None
    if not chat_id or not isinstance(data, dict):
        return
    if not bool(cfg_value(chat_id, 'ai_enabled', True)):
        await update.message.reply_text('🧠 Cerebrito está desactivado en ese grupo.')
        raise _V85Stop

    # Borrar comando del usuario según configuración.
    if update.effective_chat:
        _v85_schedule_delete(context, update.effective_chat.id, update.message.message_id, _v85_cmd_delete_seconds(chat_id))

    arg = rest[0].strip() if rest else ''
    if not arg:
        set_config_pending(update.effective_user.id, {
            'kind': 'ai_custom_command_query_v85',
            'chat_id': int(chat_id),
            'cmd': cmd,
        })
        msg = await update.message.reply_html(h(_v84_ai_command_ask_text(data)), reply_markup=ForceReply(selective=True))
        _v85_schedule_delete(context, update.effective_chat.id, msg.message_id, _v85_ask_delete_seconds(chat_id))
        try:
            if update.effective_chat and update.effective_chat.type == 'private' and '_v71_track_private_message' in globals():
                _v71_track_private_message(update.effective_user.id, msg.message_id)
        except Exception:
            pass
        raise _V85Stop

    wait = await update.message.reply_text('🧠 Pensando…')
    try:
        prompt = _v71_format_ai_custom_prompt(data, arg, display_name(update.effective_user))
        ans = await _ai_openai_response(int(chat_id), prompt, max_output_tokens=int(cfg_value(int(chat_id), 'ai_custom_command_tokens', 500) or 500))
        try:
            await wait.edit_text(ans[:3900])
        except Exception:
            try:
                await wait.delete()
            except Exception:
                pass
            wait = await update.message.reply_text(ans[:3900])
        _v85_schedule_delete(context, update.effective_chat.id, wait.message_id, _v85_result_delete_seconds(chat_id))
        _ai_usage_inc(int(chat_id), int(update.effective_user.id), 'planecito')
    except Exception as e:
        logger.exception('Error comando IA personalizado V85 /%s', cmd)
        try:
            await wait.edit_text(f'❌ Error IA: {type(e).__name__}\n{str(e)[:500]}')
            _v85_schedule_delete(context, update.effective_chat.id, wait.message_id, _v85_result_delete_seconds(chat_id))
        except Exception:
            msg = await update.message.reply_text(f'❌ Error IA: {type(e).__name__}')
            _v85_schedule_delete(context, update.effective_chat.id, msg.message_id, _v85_result_delete_seconds(chat_id))
    raise _V85Stop


async def _v85_pending_ai_query_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending:
        return
    kind = pending.get('kind')
    uid = int(update.effective_user.id)
    raw = (plain_text_from_message(update.message) if 'plain_text_from_message' in globals() else (update.message.text or '')).strip()

    if kind == 'ai_custom_command_query_v85':
        chat_id = int(pending.get('chat_id') or 0)
        cmd = str(pending.get('cmd') or '')
        data = _v71_ai_commands_for_chat(chat_id).get(cmd) if '_v71_ai_commands_for_chat' in globals() else _ai_custom_commands(chat_id).get(cmd)
        pop_config_pending(uid)
        # Borrar dato enviado por el usuario.
        if update.effective_chat:
            _v85_schedule_delete(context, update.effective_chat.id, update.message.message_id, _v85_ask_delete_seconds(chat_id))
        if not isinstance(data, dict):
            msg = await update.message.reply_html('No encuentro ese comando IA.')
            _v85_schedule_delete(context, update.effective_chat.id, msg.message_id, _v85_result_delete_seconds(chat_id))
            raise _V85Stop
        wait = await update.message.reply_text('🧠 Pensando…')
        try:
            prompt = _v71_format_ai_custom_prompt(data, raw, display_name(update.effective_user))
            ans = await _ai_openai_response(chat_id, prompt, max_output_tokens=int(cfg_value(chat_id, 'ai_custom_command_tokens', 500) or 500))
            await wait.edit_text(ans[:3900])
            _v85_schedule_delete(context, update.effective_chat.id, wait.message_id, _v85_result_delete_seconds(chat_id))
        except Exception as e:
            logger.exception('Error respuesta guiada IA V85')
            await wait.edit_text(f'❌ Error IA: {type(e).__name__}\n{str(e)[:500]}')
            _v85_schedule_delete(context, update.effective_chat.id, wait.message_id, _v85_result_delete_seconds(chat_id))
        raise _V85Stop

    if kind == 'ai_custom_command_edit_v85':
        chat_id = int(pending.get('chat_id') or 0)
        name = str(pending.get('name') or '').lower()
        cmds = _ai_custom_commands(chat_id)
        if name not in cmds:
            pop_config_pending(uid)
            await update.message.reply_html('No encuentro ese comando IA.')
            raise _V85Stop
        parts = [p.strip() for p in raw.split('|', 1)]
        if len(parts) < 2:
            await update.message.reply_html('Formato inválido. Usa:\n<code>mensaje que pedirá | prompt</code>')
            raise _V85Stop
        ask, prompt = parts[0], parts[1]
        old = cmds.get(name) if isinstance(cmds.get(name), dict) else {}
        cmds[name] = {
            **old,
            'ask': ask[:500],
            'prompt': prompt[:2000],
            'edited_by': uid,
            'edited_ts': int(time.time()),
        }
        cfg_set(chat_id, 'ai_custom_commands', cmds); save_all_states(); pop_config_pending(uid)
        await update.message.reply_html(f'✅ Comando IA editado: <code>/{h(name)}</code>')
        raise _V85Stop


_old_build_application_v85 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v85()
    app.add_handler(CallbackQueryHandler(_v85_config_callback, pattern=r'^cfg\|(ai_cmd_settings|ai_cmd_time|ai_cmd_edit_menu|ai_cmd_edit)\|'), group=-5200000)
    # Prioridad superior a V84/V71.
    app.add_handler(MessageHandler(filters.COMMAND, _v85_ai_custom_command_handler), group=-5200000)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _v85_pending_ai_query_handler), group=-5200000)
    logger.info('V85 comandos IA con limpieza configurable y edición cargado')
    return app


# =========================================================
# V87 - Botones recurrentes ejecutan comandos IA personalizados
# =========================================================
# Problema: el handler genérico de reccmd simulaba "/comando". Eso funcionaba para
# /impostor, pero los comandos IA personalizados podían no entrar bien o quedarse
# esperando dato. Este router detecta si el cmd del botón es un comando IA creado
# por el admin y lo ejecuta directamente.

try:
    from telegram.ext import ApplicationHandlerStop as _V87Stop
except Exception:
    _V87Stop = Exception


def _v87_allowed_rec_button_command(chat_id: int, cmd: str) -> bool:
    try:
        allowed = set(_v66_allowed_rec_commands(int(chat_id)))
        return not allowed or _v66_clean_cmd_name(cmd) in allowed
    except Exception:
        return True


def _v87_cmd_uses_query(data: Dict[str, Any]) -> bool:
    prompt = str(data.get('prompt') or data.get('instructions') or '')
    ask = str(data.get('ask') or data.get('ask_message') or '')
    return bool(ask.strip()) or any(x in prompt for x in ('{query}', '{consulta}', '{texto}'))


async def _v87_execute_ai_custom_from_recurrent(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data_raw = q.data or ''
    if not data_raw.startswith('reccmd|'):
        return
    parts = data_raw.split('|', 2)
    if len(parts) < 3:
        return
    try:
        chat_id = int(parts[1])
    except Exception:
        return
    try:
        cmd = _v66_clean_cmd_name(parts[2]) if '_v66_clean_cmd_name' in globals() else str(parts[2]).lower().lstrip('/').replace('cmd:', '').strip()
    except Exception:
        cmd = str(parts[2] or '').lower().lstrip('/').replace('cmd:', '').strip()
    if not cmd:
        return

    # Si no es comando IA personalizado, no paramos: que lo gestionen V81/V69/V66.
    try:
        cmds = _ai_custom_commands(chat_id) if '_ai_custom_commands' in globals() else {}
    except Exception:
        cmds = {}
    data = cmds.get(cmd)
    if not isinstance(data, dict):
        return

    # Respeta la lista de comandos permitidos en botones recurrentes.
    if not _v87_allowed_rec_button_command(chat_id, cmd):
        await q.answer(f'/{cmd} no está permitido en botones recurrentes. Actívalo en Ajustes → Recurrentes → Comandos permitidos.', show_alert=True)
        raise _V87Stop

    if not bool(cfg_value(chat_id, 'ai_enabled', True)):
        await q.answer('Cerebrito está desactivado en este grupo.', show_alert=True)
        raise _V87Stop

    try:
        await q.answer('Ejecutando IA…')
    except Exception:
        pass

    # Si el comando necesita dato, preguntamos al usuario con ForceReply y dejamos pendiente.
    if _v87_cmd_uses_query(data):
        set_config_pending(q.from_user.id, {
            'kind': 'ai_custom_command_query_v85',
            'chat_id': int(chat_id),
            'cmd': cmd,
        })
        ask_text = _v84_ai_command_ask_text(data) if '_v84_ai_command_ask_text' in globals() else str(data.get('ask') or data.get('ask_message') or 'Escribe el dato y envía.')
        try:
            msg = await context.bot.send_message(
                chat_id=chat_id,
                text=h(ask_text),
                parse_mode=ParseMode.HTML,
                reply_markup=ForceReply(selective=True),
                reply_to_message_id=q.message.message_id if q.message else None,
            )
        except Exception:
            msg = await context.bot.send_message(chat_id=chat_id, text=h(ask_text), parse_mode=ParseMode.HTML, reply_markup=ForceReply(selective=True))
        try:
            _v85_schedule_delete(context, chat_id, msg.message_id, _v85_ask_delete_seconds(chat_id))
        except Exception:
            pass
        raise _V87Stop

    # Si no necesita dato, ejecuta directamente el prompt del comando.
    wait = await context.bot.send_message(chat_id=chat_id, text='🧠 Pensando…')
    try:
        prompt = str(data.get('prompt') or data.get('instructions') or '').strip()
        if not prompt:
            await wait.edit_text('❌ Este comando IA no tiene prompt configurado.')
            raise _V87Stop
        ans = await _ai_openai_response(int(chat_id), prompt, max_output_tokens=int(cfg_value(int(chat_id), 'ai_custom_command_tokens', 500) or 500))
        try:
            await wait.edit_text(ans[:3900])
        except Exception:
            try:
                await wait.delete()
            except Exception:
                pass
            wait = await context.bot.send_message(chat_id=chat_id, text=ans[:3900])
        try:
            _v85_schedule_delete(context, chat_id, wait.message_id, _v85_result_delete_seconds(chat_id))
            _ai_usage_inc(int(chat_id), int(q.from_user.id), 'planecito')
        except Exception:
            pass
    except _V87Stop:
        raise
    except Exception as e:
        logger.exception('Error ejecutando comando IA desde botón recurrente /%s', cmd)
        try:
            await wait.edit_text(f'❌ Error IA: {type(e).__name__}\n{str(e)[:500]}')
            _v85_schedule_delete(context, chat_id, wait.message_id, _v85_result_delete_seconds(chat_id))
        except Exception:
            await context.bot.send_message(chat_id=chat_id, text=f'❌ Error IA: {type(e).__name__}')
    raise _V87Stop


_old_build_application_v87 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v87()
    # Más prioritario que V81/V69/V66 para capturar SOLO comandos IA personalizados.
    app.add_handler(CallbackQueryHandler(_v87_execute_ai_custom_from_recurrent, pattern=r'^reccmd\|'), group=-5300000)
    logger.info('V87 comandos IA personalizados desde botones recurrentes cargado')
    return app


# =========================================================
# V88 - Exportar / clonar mensajes recurrentes a otro grupo
# =========================================================
# Añade en el detalle de cada recurrente un botón para copiarlo a otro grupo
# conservando nombre, texto, multimedia, botones, horario y configuración.

try:
    from telegram.ext import ApplicationHandlerStop as _V88Stop
except Exception:
    _V88Stop = Exception


def _v88_known_chats() -> List[int]:
    try:
        ids = list(known_admin_chats_for_private())
    except Exception:
        ids = list(STATE_CACHE.keys())
    out: List[int] = []
    for cid in ids:
        try:
            icid = int(cid)
        except Exception:
            continue
        if icid not in out:
            out.append(icid)
    return out


def _v88_chat_title(chat_id: int) -> str:
    try:
        return str(get_chat_title(chat_id))
    except Exception:
        try:
            return str(cfg_value(chat_id, 'chat_title', '') or chat_id)
        except Exception:
            return str(chat_id)


def _v88_clone_recurring_row(row: Dict[str, Any], dest_chat_id: int) -> Dict[str, Any]:
    # Deepcopy sin depender de imports: JSON basta para dict/list/string/int/bool usados en recurrentes.
    try:
        new_row = json.loads(json.dumps(row, ensure_ascii=False))
    except Exception:
        import copy as _copy
        new_row = _copy.deepcopy(row)
    new_id = recurring_next_id(dest_chat_id)
    new_row['id'] = int(new_id)
    # El clon no debe heredar últimos envíos del grupo origen.
    for key in [
        'last_message_id', 'last_message_link', 'last_sent_ts', 'last_day', 'last_week_key',
        'last_date_key', 'v69_started', 'v69_start_day', 'v69_start_week_key', 'v69_start_date_key',
        'runtime_message_id', 'sending_key', 'last_sent_label'
    ]:
        if key in new_row:
            if key.endswith('_ts') or key.endswith('_id'):
                new_row[key] = 0
            elif key in ('v69_started',):
                new_row[key] = False
            else:
                new_row[key] = ''
    new_row['copied_from_chat_id'] = int(row.get('copied_from_chat_id') or 0) or None
    new_row['exported_from_chat_id'] = int(row.get('source_chat_id') or 0) if row.get('source_chat_id') else None
    return new_row


_old_v88_recurring_detail_markup = recurring_detail_markup

def recurring_detail_markup(chat_id: int, rid: int) -> InlineKeyboardMarkup:  # type: ignore[override]
    markup = _old_v88_recurring_detail_markup(chat_id, rid)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    btn = [InlineKeyboardButton('📤 Exportar a otro grupo', callback_data=f'cfg|rec_export_menu|{chat_id}|{rid}|recurrentes')]
    # Insertar antes de volver, si existe.
    insert_at = max(0, len(rows) - 1)
    rows.insert(insert_at, btn)
    return InlineKeyboardMarkup(rows)


def _v88_export_menu_markup(source_chat_id: int, rid: int) -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    for dest in _v88_known_chats():
        if int(dest) == int(source_chat_id):
            continue
        title = _v88_chat_title(dest)
        rows.append([InlineKeyboardButton(f'➡️ {title}', callback_data=f'cfg|rec_export_to|{source_chat_id}|{rid}|{dest}')])
    if not rows:
        rows.append([InlineKeyboardButton('No hay otros grupos configurados', callback_data=f'cfg|noop|{source_chat_id}|recurrentes')])
    rows.append([InlineKeyboardButton('🔙 Volver al recurrente', callback_data=f'cfg|rec_edit|{source_chat_id}|{rid}|recurrentes')])
    return InlineKeyboardMarkup(rows)


async def _v88_recurring_export_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    parts = data.split('|')
    try:
        action = parts[1]
    except Exception:
        return
    try:
        if action == 'rec_export_menu':
            source_chat_id = int(parts[2]); rid = int(parts[3])
            row = recurring_find(source_chat_id, rid)
            if not row:
                await q.answer('No encuentro ese recurrente.', show_alert=True)
                raise _V88Stop
            # Validación mínima: debe ser admin del grupo origen.
            try:
                if not await is_admin(context, source_chat_id, q.from_user.id):
                    await q.answer('Solo administradores.', show_alert=True)
                    raise _V88Stop
            except _V88Stop:
                raise
            except Exception:
                pass
            title = str(row.get('name') or f'Recurrente #{rid}')
            await q.answer()
            await q.edit_message_text(
                '<b>📤 Exportar mensaje recurrente</b>\n\n'
                f'Origen: <b>{h(_v88_chat_title(source_chat_id))}</b>\n'
                f'Recurrente: <b>{h(title)}</b>\n\n'
                'Elige el grupo de destino. Se copiará con la misma configuración: título, texto, multimedia, botones, horario, fijado, borrado anterior y demás opciones.',
                parse_mode=ParseMode.HTML,
                reply_markup=_v88_export_menu_markup(source_chat_id, rid),
            )
            raise _V88Stop

        if action == 'rec_export_to':
            source_chat_id = int(parts[2]); rid = int(parts[3]); dest_chat_id = int(parts[4])
            row = recurring_find(source_chat_id, rid)
            if not row:
                await q.answer('No encuentro ese recurrente.', show_alert=True)
                raise _V88Stop
            # Validación en origen y destino.
            try:
                if not await is_admin(context, source_chat_id, q.from_user.id):
                    await q.answer('Solo administradores del grupo origen.', show_alert=True)
                    raise _V88Stop
                if not await is_admin(context, dest_chat_id, q.from_user.id):
                    await q.answer('Tienes que ser admin del grupo destino.', show_alert=True)
                    raise _V88Stop
            except _V88Stop:
                raise
            except Exception:
                # Si Telegram no permite comprobar, no bloqueamos para no romper flujos privados.
                pass
            new_row = _v88_clone_recurring_row(row, dest_chat_id)
            new_row['exported_from_chat_id'] = int(source_chat_id)
            new_row['exported_from_rid'] = int(rid)
            recurring_list(dest_chat_id).append(new_row)
            save_all_states()
            await q.answer('Recurrente exportado ✅', show_alert=True)
            await q.edit_message_text(
                '<b>✅ Recurrente exportado</b>\n\n'
                f'De: <b>{h(_v88_chat_title(source_chat_id))}</b>\n'
                f'A: <b>{h(_v88_chat_title(dest_chat_id))}</b>\n'
                f'Nuevo ID: <b>#{int(new_row.get("id") or 0)}</b>\n\n'
                'Se ha copiado texto, multimedia, botones, horario y configuración.',
                parse_mode=ParseMode.HTML,
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton('👁 Ver en destino', callback_data=f'cfg|rec_edit|{dest_chat_id}|{int(new_row.get("id") or 0)}|recurrentes')],
                    [InlineKeyboardButton('🔙 Volver al origen', callback_data=f'cfg|rec_edit|{source_chat_id}|{rid}|recurrentes')],
                ]),
            )
            raise _V88Stop
    except _V88Stop:
        raise
    except Exception:
        logger.exception('Error exportando recurrente V88: %s', data)
        try:
            await q.answer('Error exportando. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V88Stop


_old_build_application_v88 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v88()
    app.add_handler(CallbackQueryHandler(_v88_recurring_export_callback, pattern=r'^cfg\|rec_export_'), group=-5400000)
    logger.info('V88 exportar mensajes recurrentes a otros grupos cargado')
    return app


# =========================================================
# V89 - Exportar comandos IA y listas DJ a otros grupos
# =========================================================
# Añade:
# - En IA Cerebrito: botón para exportar todos los comandos IA al grupo que elijas.
# - En Permisos DJ/Listados: botón para exportar listas DJ guardadas, una o todas.

try:
    from telegram.ext import ApplicationHandlerStop as _V89Stop
except Exception:
    _V89Stop = Exception


def _v89_deepcopy_json(obj: Any) -> Any:
    try:
        return json.loads(json.dumps(obj, ensure_ascii=False))
    except Exception:
        import copy as _copy
        return _copy.deepcopy(obj)


def _v89_known_chats() -> List[int]:
    try:
        return _v88_known_chats()
    except Exception:
        return [int(x) for x in STATE_CACHE.keys()]


def _v89_chat_title(chat_id: int) -> str:
    try:
        return _v88_chat_title(chat_id)
    except Exception:
        try:
            return str(get_chat_title(chat_id))
        except Exception:
            return str(chat_id)


async def _v89_check_admin_both(context: ContextTypes.DEFAULT_TYPE, user_id: int, source_chat_id: int, dest_chat_id: Optional[int] = None) -> bool:
    try:
        if not await is_admin(context, int(source_chat_id), int(user_id)):
            return False
        if dest_chat_id is not None and not await is_admin(context, int(dest_chat_id), int(user_id)):
            return False
    except Exception:
        # En privado, si Telegram no permite comprobar, no bloqueamos para no romper flujos ya existentes.
        return True
    return True


def _v89_ai_export_dest_markup(source_chat_id: int) -> InlineKeyboardMarkup:
    rows: List[List[InlineKeyboardButton]] = []
    for dest in _v89_known_chats():
        if int(dest) == int(source_chat_id):
            continue
        rows.append([InlineKeyboardButton(f'➡️ {_v89_chat_title(dest)}', callback_data=f'cfg|ai_export_to|{source_chat_id}|{int(dest)}')])
    if not rows:
        rows.append([InlineKeyboardButton('No hay otros grupos configurados', callback_data=f'cfg|noop|{source_chat_id}|ai')])
    rows.append([InlineKeyboardButton('🔙 Volver a IA', callback_data=f'cfg|block|{source_chat_id}|ai')])
    return InlineKeyboardMarkup(rows)


def _v89_dj_lists_source_markup(source_chat_id: int) -> InlineKeyboardMarkup:
    state = get_state(source_chat_id)
    names = sorted(state.saved_lists.keys())
    rows: List[List[InlineKeyboardButton]] = []
    if names:
        rows.append([InlineKeyboardButton('📦 Todas las listas', callback_data=f'cfg|djlist_export_dest|{source_chat_id}|-1')])
    for idx, name in enumerate(names[:40]):
        rows.append([InlineKeyboardButton(f'🎵 {name[:42]} ({len(state.saved_lists.get(name, []))})', callback_data=f'cfg|djlist_export_dest|{source_chat_id}|{idx}')])
