def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v89()
    app.add_handler(CallbackQueryHandler(_v89_export_callback, pattern=r'^cfg\|(ai_export_|djlist_export_)'), group=-5500000)
    logger.info('V89 exportar comandos IA y listas DJ cargado')
    return app



# =========================================================
# V90 - Comandos IA: menciona al usuario en petición y resultado
# =========================================================
# Cuando un comando IA necesita un dato, el bot menciona al usuario que debe responder.
# Cuando entrega el resultado, también menciona al usuario que hizo la consulta.

try:
    from telegram.ext import ApplicationHandlerStop as _V90Stop
except Exception:
    _V90Stop = Exception


def _v90_user_mention(user) -> str:
    try:
        return user.mention_html()
    except Exception:
        return h(display_name(user) if user else 'Usuario')


def _v90_ask_text(user, data: Dict[str, Any]) -> str:
    ask = _v84_ai_command_ask_text(data) if '_v84_ai_command_ask_text' in globals() else str(data.get('ask') or data.get('ask_message') or 'Escribe el dato y envía.')
    return f"{_v90_user_mention(user)} {h(ask)}"


def _v90_result_text(user, answer: str) -> str:
    return f"{_v90_user_mention(user)}\n\n{h(answer)}"


def _v90_find_ai_command_from_update(update: Update, cmd: str):
    preferred = int(update.effective_chat.id) if update.effective_chat and int(update.effective_chat.id) in STATE_CACHE else None
    try:
        return _v71_find_ai_command(cmd, preferred)
    except Exception:
        return None, None


async def _v90_ai_custom_command_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user:
        return
    text = (update.message.text or '').strip()
    if not text.startswith('/'):
        return
    first, *rest = text.split(maxsplit=1)
    cmd = (_ai_clean_command_name(first) if '_ai_clean_command_name' in globals() else first.lstrip('/').lower())
    reserved = {
        'start','help','ajustes','plan','djplan','ping','preguntita','retito','examen',
        'privadito','impostor','impostorstop','cerebrito','planecito','tiempo','iatest'
    }
    if cmd in reserved:
        return
    chat_id, data = _v90_find_ai_command_from_update(update, cmd)
    if not chat_id or not isinstance(data, dict):
        return
    if not bool(cfg_value(chat_id, 'ai_enabled', True)):
        await update.message.reply_text('🧠 Cerebrito está desactivado en ese grupo.')
        raise _V90Stop

    if update.effective_chat:
        try:
            _v85_schedule_delete(context, update.effective_chat.id, update.message.message_id, _v85_cmd_delete_seconds(chat_id))
        except Exception:
            pass

    arg = rest[0].strip() if rest else ''
    if not arg:
        set_config_pending(update.effective_user.id, {
            'kind': 'ai_custom_command_query_v90',
            'chat_id': int(chat_id),
            'cmd': cmd,
        })
        msg = await update.message.reply_html(_v90_ask_text(update.effective_user, data), reply_markup=ForceReply(selective=True))
        try:
            _v85_schedule_delete(context, update.effective_chat.id, msg.message_id, _v85_ask_delete_seconds(chat_id))
        except Exception:
            pass
        try:
            if update.effective_chat and update.effective_chat.type == 'private' and '_v71_track_private_message' in globals():
                _v71_track_private_message(update.effective_user.id, msg.message_id)
        except Exception:
            pass
        raise _V90Stop

    wait = await update.message.reply_text('🧠 Pensando…')
    try:
        prompt = _v71_format_ai_custom_prompt(data, arg, display_name(update.effective_user))
        ans = await _ai_openai_response(int(chat_id), prompt, max_output_tokens=int(cfg_value(int(chat_id), 'ai_custom_command_tokens', 500) or 500))
        final = _v90_result_text(update.effective_user, ans)[:3900]
        try:
            await wait.edit_text(final, parse_mode=ParseMode.HTML)
        except Exception:
            try:
                await wait.delete()
            except Exception:
                pass
            wait = await update.message.reply_html(final)
        try:
            _v85_schedule_delete(context, update.effective_chat.id, wait.message_id, _v85_result_delete_seconds(chat_id))
            _ai_usage_inc(int(chat_id), int(update.effective_user.id), 'planecito')
        except Exception:
            pass
    except Exception as e:
        logger.exception('Error comando IA personalizado V90 /%s', cmd)
        try:
            await wait.edit_text(f'❌ Error IA: {type(e).__name__}\n{str(e)[:500]}')
        except Exception:
            pass
    raise _V90Stop


async def _v90_pending_ai_query_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'ai_custom_command_query_v90':
        return
    uid = int(update.effective_user.id)
    chat_id = int(pending.get('chat_id') or 0)
    cmd = str(pending.get('cmd') or '')
    data = _v71_ai_commands_for_chat(chat_id).get(cmd) if '_v71_ai_commands_for_chat' in globals() else _ai_custom_commands(chat_id).get(cmd)
    raw = (plain_text_from_message(update.message) if 'plain_text_from_message' in globals() else (update.message.text or '')).strip()
    pop_config_pending(uid)
    if update.effective_chat:
        try:
            _v85_schedule_delete(context, update.effective_chat.id, update.message.message_id, _v85_ask_delete_seconds(chat_id))
        except Exception:
            pass
    if not isinstance(data, dict):
        msg = await update.message.reply_html(f'{_v90_user_mention(update.effective_user)} No encuentro ese comando IA.')
        try:
            _v85_schedule_delete(context, update.effective_chat.id, msg.message_id, _v85_result_delete_seconds(chat_id))
        except Exception:
            pass
        raise _V90Stop
    wait = await update.message.reply_text('🧠 Pensando…')
    try:
        prompt = _v71_format_ai_custom_prompt(data, raw, display_name(update.effective_user))
        ans = await _ai_openai_response(chat_id, prompt, max_output_tokens=int(cfg_value(chat_id, 'ai_custom_command_tokens', 500) or 500))
        await wait.edit_text(_v90_result_text(update.effective_user, ans)[:3900], parse_mode=ParseMode.HTML)
        try:
            _v85_schedule_delete(context, update.effective_chat.id, wait.message_id, _v85_result_delete_seconds(chat_id))
        except Exception:
            pass
    except Exception as e:
        logger.exception('Error respuesta guiada IA V90')
        await wait.edit_text(f'❌ Error IA: {type(e).__name__}\n{str(e)[:500]}')
        try:
            _v85_schedule_delete(context, update.effective_chat.id, wait.message_id, _v85_result_delete_seconds(chat_id))
        except Exception:
            pass
    raise _V90Stop


async def _v90_execute_ai_custom_from_recurrent(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data_raw = q.data or ''
    if not data_raw.startswith('reccmd|'):
        return
    parts = data_raw.split('|', 2)
    if len(parts) < 3:
        return
    try:
        chat_id = int(parts[1])
    except Exception:
        return
    try:
        cmd = _v66_clean_cmd_name(parts[2]) if '_v66_clean_cmd_name' in globals() else str(parts[2]).lower().lstrip('/').replace('cmd:', '').strip()
    except Exception:
        cmd = str(parts[2] or '').lower().lstrip('/').replace('cmd:', '').strip()
    if not cmd:
        return
    try:
        cmds = _ai_custom_commands(chat_id) if '_ai_custom_commands' in globals() else {}
    except Exception:
        cmds = {}
    data = cmds.get(cmd)
    if not isinstance(data, dict):
        return
    if '_v87_allowed_rec_button_command' in globals() and not _v87_allowed_rec_button_command(chat_id, cmd):
        await q.answer(f'/{cmd} no está permitido en botones recurrentes.', show_alert=True)
        raise _V90Stop
    if not bool(cfg_value(chat_id, 'ai_enabled', True)):
        await q.answer('Cerebrito está desactivado en este grupo.', show_alert=True)
        raise _V90Stop
    try:
        await q.answer('Ejecutando IA…')
    except Exception:
        pass

    uses_query = _v87_cmd_uses_query(data) if '_v87_cmd_uses_query' in globals() else any(x in str(data.get('prompt','')) for x in ('{query}','{consulta}','{texto}'))
    if uses_query:
        set_config_pending(q.from_user.id, {
            'kind': 'ai_custom_command_query_v90',
            'chat_id': int(chat_id),
            'cmd': cmd,
        })
        try:
            msg = await context.bot.send_message(
                chat_id=chat_id,
                text=_v90_ask_text(q.from_user, data),
                parse_mode=ParseMode.HTML,
                reply_markup=ForceReply(selective=True),
                reply_to_message_id=q.message.message_id if q.message else None,
            )
        except Exception:
            msg = await context.bot.send_message(chat_id=chat_id, text=_v90_ask_text(q.from_user, data), parse_mode=ParseMode.HTML, reply_markup=ForceReply(selective=True))
        try:
            _v85_schedule_delete(context, chat_id, msg.message_id, _v85_ask_delete_seconds(chat_id))
        except Exception:
            pass
        raise _V90Stop

    wait = await context.bot.send_message(chat_id=chat_id, text='🧠 Pensando…')
    try:
        prompt = str(data.get('prompt') or data.get('instructions') or '').strip()
        if not prompt:
            await wait.edit_text(f'{_v90_user_mention(q.from_user)}\n\n❌ Este comando IA no tiene prompt configurado.', parse_mode=ParseMode.HTML)
            raise _V90Stop
        ans = await _ai_openai_response(int(chat_id), prompt, max_output_tokens=int(cfg_value(int(chat_id), 'ai_custom_command_tokens', 500) or 500))
        final = _v90_result_text(q.from_user, ans)[:3900]
        try:
            await wait.edit_text(final, parse_mode=ParseMode.HTML)
        except Exception:
            try:
                await wait.delete()
            except Exception:
                pass
            wait = await context.bot.send_message(chat_id=chat_id, text=final, parse_mode=ParseMode.HTML)
        try:
            _v85_schedule_delete(context, chat_id, wait.message_id, _v85_result_delete_seconds(chat_id))
            _ai_usage_inc(int(chat_id), int(q.from_user.id), 'planecito')
        except Exception:
            pass
    except _V90Stop:
        raise
    except Exception as e:
        logger.exception('Error ejecutando comando IA desde botón recurrente V90 /%s', cmd)
        try:
            await wait.edit_text(f'{_v90_user_mention(q.from_user)}\n\n❌ Error IA: {type(e).__name__}\n{str(e)[:500]}', parse_mode=ParseMode.HTML)
            _v85_schedule_delete(context, chat_id, wait.message_id, _v85_result_delete_seconds(chat_id))
        except Exception:
            pass
    raise _V90Stop


_old_build_application_v90 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v90()
    app.add_handler(CallbackQueryHandler(_v90_execute_ai_custom_from_recurrent, pattern=r'^reccmd\|'), group=-5600000)
    app.add_handler(MessageHandler(filters.COMMAND, _v90_ai_custom_command_handler), group=-5600000)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _v90_pending_ai_query_handler), group=-5600000)
    logger.info('V90 comandos IA mencionan usuario en petición y resultado cargado')
    return app



# =========================================================
# V91 - Orden manual de mensajes recurrentes
# =========================================================
# Permite colocar un recurrente arriba/abajo en la lista. Si dos recurrentes
# vencen a la misma hora, se ejecutará primero el que esté más arriba.

try:
    from telegram.ext import ApplicationHandlerStop as _V91Stop
except Exception:
    _V91Stop = Exception


def _v91_rec_index(chat_id: int, rid: int) -> int:
    rows = recurring_list(chat_id)
    for i, row in enumerate(rows):
        try:
            if int(row.get('id', 0) or 0) == int(rid):
                return i
        except Exception:
            continue
    return -1


def _v91_swap_rec(chat_id: int, rid: int, direction: str) -> tuple[bool, str]:
    rows = recurring_list(chat_id)
    idx = _v91_rec_index(chat_id, rid)
    if idx < 0:
        return False, 'No encuentro ese recurrente.'
    if direction == 'up':
        if idx == 0:
            return False, 'Ya está arriba del todo.'
        rows[idx-1], rows[idx] = rows[idx], rows[idx-1]
        save_all_states()
        return True, 'Subido en la lista ✅'
    if direction == 'down':
        if idx >= len(rows) - 1:
            return False, 'Ya está abajo del todo.'
        rows[idx+1], rows[idx] = rows[idx], rows[idx+1]
        save_all_states()
        return True, 'Bajado en la lista ✅'
    if direction == 'top':
        row = rows.pop(idx)
        rows.insert(0, row)
        save_all_states()
        return True, 'Movido arriba del todo ✅'
    if direction == 'bottom':
        row = rows.pop(idx)
        rows.append(row)
        save_all_states()
        return True, 'Movido abajo del todo ✅'
    return False, 'Movimiento no válido.'


_old_v91_admin_private_block_text = admin_private_block_text

def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:  # type: ignore[override]
    text = _old_v91_admin_private_block_text(chat_id, block, page)
    if block == 'recurrentes':
        text += (
            "\n\n<b>Orden:</b> si varios recurrentes coinciden a la misma hora, "
            "se enviará primero el que esté más arriba en esta lista."
        )
    return text


_old_v91_admin_private_block_markup = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    markup = _old_v91_admin_private_block_markup(chat_id, block, page)
    if block != 'recurrentes':
        return markup
    try:
        rows = [list(r) for r in markup.inline_keyboard]
        new_rows: List[List[InlineKeyboardButton]] = []
        for row in rows:
            new_rows.append(row)
            # Después de cada fila de título recurrente añadimos controles de orden.
            if len(row) == 1:
                btn = row[0]
                cd = getattr(btn, 'callback_data', '') or ''
                # cfg|rec_edit|chat_id|rid|recurrentes
                if cd.startswith('cfg|rec_edit|'):
                    parts = cd.split('|')
                    if len(parts) >= 4:
                        try:
                            rid = int(parts[3])
                            idx = _v91_rec_index(chat_id, rid)
                            total = len(recurring_list(chat_id))
                            label = f'📍 Orden {idx+1}/{total}' if idx >= 0 else '📍 Orden'
                            new_rows.append([
                                InlineKeyboardButton('⬆️ Subir', callback_data=f'cfg|rec_move|{chat_id}|{rid}|up|recurrentes'),
                                InlineKeyboardButton(label, callback_data=f'cfg|noop|{chat_id}|recurrentes'),
                                InlineKeyboardButton('⬇️ Bajar', callback_data=f'cfg|rec_move|{chat_id}|{rid}|down|recurrentes'),
                            ])
                        except Exception:
                            pass
        return InlineKeyboardMarkup(new_rows)
    except Exception:
        logger.exception('No se pudo dibujar orden recurrentes V91')
        return markup


_old_v91_recurring_detail_markup = recurring_detail_markup

def recurring_detail_markup(chat_id: int, rid: int) -> InlineKeyboardMarkup:  # type: ignore[override]
    markup = _old_v91_recurring_detail_markup(chat_id, rid)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    idx = _v91_rec_index(chat_id, rid)
    total = len(recurring_list(chat_id))
    order_text = f'📍 Orden {idx+1}/{total}' if idx >= 0 and total else '📍 Orden'
    order_rows = [
        [
            InlineKeyboardButton('⬆️ Subir', callback_data=f'cfg|rec_move|{chat_id}|{rid}|up|detail'),
            InlineKeyboardButton('⬇️ Bajar', callback_data=f'cfg|rec_move|{chat_id}|{rid}|down|detail'),
        ],
        [
            InlineKeyboardButton('⏫ Primero', callback_data=f'cfg|rec_move|{chat_id}|{rid}|top|detail'),
            InlineKeyboardButton(order_text, callback_data=f'cfg|noop|{chat_id}|recurrentes'),
            InlineKeyboardButton('⏬ Último', callback_data=f'cfg|rec_move|{chat_id}|{rid}|bottom|detail'),
        ],
    ]
    # Insertar antes de la fila de volver si existe.
    insert_at = max(0, len(rows) - 1)
    for r in reversed(order_rows):
        rows.insert(insert_at, r)
    return InlineKeyboardMarkup(rows)


async def _v91_rec_move_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    parts = data.split('|')
    # cfg|rec_move|chat_id|rid|direction|return_mode
    try:
        chat_id = int(parts[2])
        rid = int(parts[3])
        direction = str(parts[4])
        return_mode = str(parts[5]) if len(parts) > 5 else 'detail'
    except Exception:
        await q.answer('Movimiento inválido.', show_alert=True)
        raise _V91Stop
    try:
        if not await is_admin(context, chat_id, q.from_user.id):
            await q.answer('Solo administradores.', show_alert=True)
            raise _V91Stop
    except _V91Stop:
        raise
    except Exception:
        pass

    ok, msg = _v91_swap_rec(chat_id, rid, direction)
    await q.answer(msg, show_alert=not ok)
    try:
        if return_mode == 'detail':
            await q.edit_message_text(
                recurring_detail_text(chat_id, rid) + "\n\n<i>Orden actualizado: si coincide horario, se enviará según esta posición.</i>",
                parse_mode=ParseMode.HTML,
                reply_markup=recurring_detail_markup(chat_id, rid),
            )
        else:
            await q.edit_message_text(
                admin_private_block_text(chat_id, 'recurrentes'),
                parse_mode=ParseMode.HTML,
                reply_markup=admin_private_block_markup(chat_id, 'recurrentes'),
            )
    except Exception:
        try:
            await q.message.reply_html(
                recurring_detail_text(chat_id, rid),
                reply_markup=recurring_detail_markup(chat_id, rid),
            )
        except Exception:
            logger.exception('No se pudo refrescar recurrente tras moverlo V91')
    raise _V91Stop


_old_build_application_v91 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v91()
    app.add_handler(CallbackQueryHandler(_v91_rec_move_callback, pattern=r'^cfg\|rec_move\|'), group=-5700000)
    logger.info('V91 orden manual de recurrentes cargado')
    return app


# =========================================================
# V92 - Botón para limpiar el chat privado del bot
# =========================================================
# Telegram no permite al bot recorrer todo el historial del privado.
# Esta limpieza borra paneles y mensajes que el bot tiene registrados/rastreados,
# además de comandos/textos recientes del usuario. No borra música/multimedia.

try:
    from telegram.ext import ApplicationHandlerStop as _V92Stop
except Exception:
    _V92Stop = Exception


async def _v92_delete_message_safe(bot, chat_id: int, message_id: int) -> None:
    try:
        await bot.delete_message(chat_id=int(chat_id), message_id=int(message_id))
    except Exception:
        pass


async def _v92_clean_private_chat(bot, private_chat_id: int, user_id: int, *, also_current: Optional[int] = None) -> int:
    """Borra paneles/mensajes privados rastreados, sin tocar multimedia no registrada."""
    private_chat_id = int(private_chat_id)
    user_id = int(user_id)
    ids: set[int] = set()

    # Paneles antiguos rastreados por V67.
    try:
        ids.update(int(x) for x in PRIVATE_PANEL_MESSAGES_V67.get(private_chat_id, set()))
    except Exception:
        pass

    # Basura privada rastreada por IA/recurrentes V71+.
    try:
        ids.update(int(x) for x in _V71_PRIVATE_GARBAGE.get(user_id, []))
    except Exception:
        pass

    # Mensaje actual del panel/botón.
    if also_current:
        try:
            ids.add(int(also_current))
        except Exception:
            pass

    deleted = 0
    for mid in sorted(ids, reverse=True):
        try:
            await bot.delete_message(chat_id=private_chat_id, message_id=int(mid))
            deleted += 1
        except Exception:
            pass

    try:
        PRIVATE_PANEL_MESSAGES_V67[private_chat_id] = set()
    except Exception:
        pass
    try:
        _V71_PRIVATE_GARBAGE[user_id] = []
    except Exception:
        pass
    return deleted


_old_v92_admin_private_main_markup = admin_private_main_markup

def admin_private_main_markup(chat_id: int) -> InlineKeyboardMarkup:  # type: ignore[override]
    try:
        rows = [list(r) for r in _old_v92_admin_private_main_markup(chat_id).inline_keyboard]
    except Exception:
        rows = []

    # Insertamos el botón antes de los botones finales de guardar/cerrar si es posible.
    clean_row = [InlineKeyboardButton('🧹 Limpiar privado del bot', callback_data=f'cfg|clean_private|{chat_id}')]
    # Evitar duplicado.
    flat_labels = [getattr(b, 'text', '') for r in rows for b in r]
    if not any('Limpiar privado' in label for label in flat_labels):
        insert_at = max(0, len(rows) - 1)
        rows.insert(insert_at, clean_row)
    return InlineKeyboardMarkup(rows)


async def _v92_clean_private_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not q.message:
        return
    data = q.data or ''
    if not data.startswith('cfg|clean_private|'):
        return
    if getattr(q.message.chat, 'type', '') != 'private':
        await q.answer('Esta limpieza solo funciona en el privado del bot.', show_alert=True)
        raise _V92Stop
    try:
        await q.answer('Limpiando privado…')
    except Exception:
        pass
    deleted = await _v92_clean_private_chat(
        context.bot,
        int(q.message.chat_id),
        int(q.from_user.id),
        also_current=int(q.message.message_id),
    )
    # Enviar aviso corto y borrarlo también.
    try:
        msg = await context.bot.send_message(
            chat_id=q.message.chat_id,
            text=f'🧹 Privado limpiado. Paneles/mensajes borrados: {deleted}.',
        )
        await asyncio.sleep(3)
        await _v92_delete_message_safe(context.bot, q.message.chat_id, msg.message_id)
    except Exception:
        pass
    raise _V92Stop


async def limpiarprivado_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not update.effective_user:
        return
    if update.effective_chat.type != 'private':
        await update.message.reply_text('Este comando solo se usa en el privado del bot.')
        return
    # Borrar también el comando /limpiarprivado.
    current = int(update.message.message_id)
    deleted = await _v92_clean_private_chat(
        context.bot,
        int(update.effective_chat.id),
        int(update.effective_user.id),
        also_current=current,
    )
    try:
        msg = await context.bot.send_message(update.effective_chat.id, f'🧹 Limpieza hecha. Borrados: {deleted}.')
        await asyncio.sleep(3)
        await _v92_delete_message_safe(context.bot, update.effective_chat.id, msg.message_id)
    except Exception:
        pass


async def _v92_private_text_cleanup_tracker(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Borra textos/comandos del usuario en privado tras unos segundos, sin tocar multimedia."""
    if not update.effective_chat or update.effective_chat.type != 'private' or not update.message:
        return
    # Solo textos/captions. No fotos, audios, documentos, vídeos.
    if not (getattr(update.message, 'text', None) or getattr(update.message, 'caption', None)):
        return
    try:
        await asyncio.sleep(10)
        await context.bot.delete_message(update.effective_chat.id, update.message.message_id)
    except Exception:
        pass


_old_build_application_v92 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v92()
    app.add_handler(CallbackQueryHandler(_v92_clean_private_callback, pattern=r'^cfg\|clean_private\|'), group=-5800000)
    app.add_handler(CommandHandler('limpiarprivado', limpiarprivado_command), group=-5800000)
    # Limpieza pasiva de texto/comandos del usuario en privado; no toca música ni multimedia.
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()), _v92_private_text_cleanup_tracker), group=999998)
    logger.info('V92 limpieza de privado del bot cargada')
    return app



# =========================================================
# V93 - Recurrentes: activar/desactivar borrar mensaje anterior
# =========================================================
# En cada mensaje recurrente añade un botón visible para decidir si, al repetirse,
# se borra el envío anterior o se conservan todos los envíos.

try:
    from telegram.ext import ApplicationHandlerStop as _V93Stop
except Exception:
    _V93Stop = Exception


def _v93_rec_delete_prev_label(row: Dict[str, Any]) -> str:
    return '🧹 Borra anterior: ON' if bool(row.get('delete_previous', True)) else '📌 Conserva anteriores: ON'


_old_recurring_detail_text_v93 = recurring_detail_text

def recurring_detail_text(chat_id: int, rid: int) -> str:  # type: ignore[override]
    text = _old_recurring_detail_text_v93(chat_id, rid)
    row = recurring_find(chat_id, rid)
    if not row:
        return text
    # Si versiones antiguas ya muestran el campo, no duplicamos demasiado; reforzamos explicación al final.
    state = 'Sí, borra el envío anterior' if bool(row.get('delete_previous', True)) else 'No, conserva cada envío publicado'
    if 'Comportamiento al repetirse:' not in text:
        text += f"\n<b>Comportamiento al repetirse:</b> {h(state)}\n"
    return text


_old_recurring_detail_markup_v93 = recurring_detail_markup

def recurring_detail_markup(chat_id: int, rid: int) -> InlineKeyboardMarkup:  # type: ignore[override]
    markup = _old_recurring_detail_markup_v93(chat_id, rid)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    row = recurring_find(chat_id, rid)
    if not row:
        return markup
    # Evita duplicados si se recarga.
    filtered = []
    for r in rows:
        if any(str(getattr(b, 'callback_data', '')).startswith('cfg|rec_delete_prev|') for b in r):
            continue
        filtered.append(r)
    btn = InlineKeyboardButton(_v93_rec_delete_prev_label(row), callback_data=f'cfg|rec_delete_prev|{chat_id}|{rid}|recurrentes')
    # Lo ponemos cerca de ON/OFF/Fijar, antes de volver si existe.
    insert_at = max(0, len(filtered) - 1)
    filtered.insert(insert_at, [btn])
    return InlineKeyboardMarkup(filtered)


async def _v93_rec_delete_prev_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('cfg|rec_delete_prev|'):
        return
    parts = data.split('|')
    try:
        chat_id = int(parts[2])
        rid = int(parts[3])
    except Exception:
        await q.answer('Recurrente inválido.', show_alert=True)
        raise _V93Stop
    row = recurring_find(chat_id, rid)
    if not row:
        await q.answer('No encuentro ese recurrente.', show_alert=True)
        raise _V93Stop
    row['delete_previous'] = not bool(row.get('delete_previous', True))
    save_all_states()
    await q.answer('Configuración actualizada ✅')
    try:
        await q.edit_message_text(recurring_detail_text(chat_id, rid), parse_mode=ParseMode.HTML, reply_markup=recurring_detail_markup(chat_id, rid))
    except Exception:
        await q.message.reply_html(recurring_detail_text(chat_id, rid), reply_markup=recurring_detail_markup(chat_id, rid))
    raise _V93Stop


_old_build_application_v93 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v93()
    app.add_handler(CallbackQueryHandler(_v93_rec_delete_prev_callback, pattern=r'^cfg\|rec_delete_prev\|'), group=-5900000)
    logger.info('V93 toggle borrar anterior en recurrentes cargado')
    return app


# =========================================================
# V94 - Impostor: puntuación definitiva, votación con timeout,
# prompt corto y pistas visibles durante votación
# =========================================================
try:
    from telegram.ext import ApplicationHandlerStop as _V94Stop
except Exception:
    _V94Stop = Exception

IMPOSTOR_VOTE_TASKS_V94: Dict[str, asyncio.Task] = {}


def _v94_game_key(chat_id: int, gid: int) -> str:
    return f"{int(chat_id)}:{int(gid)}"


def _v94_vote_seconds(chat_id: int) -> int:
    try:
        return int(cfg_value(chat_id, 'imp_vote_seconds', 120) or 0)
    except Exception:
        return 120


def _v94_cancel_vote_task(chat_id: int, gid: int) -> None:
    key = _v94_game_key(chat_id, gid)
    task = IMPOSTOR_VOTE_TASKS_V94.pop(key, None)
    if task and not task.done():
        task.cancel()


def _v94_player_name(game: Dict[str, Any], uid: int) -> str:
    p = _imp_player(game, int(uid)) or {'id': uid, 'name': str(uid)}
    return str(p.get('name') or uid)


def _v94_point_map(game: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
    mp = game.setdefault('v94_points', {})
    if not isinstance(mp, dict):
        mp = {}
        game['v94_points'] = mp
    return mp


def _v94_add_game_points(game: Dict[str, Any], player: Dict[str, Any], points: int, reason: str) -> None:
    try:
        uid = str(int(player.get('id', 0) or 0))
    except Exception:
        return
    if not uid or uid == '0':
        return
    mp = _v94_point_map(game)
    row = mp.setdefault(uid, {'name': str(player.get('name') or uid), 'points': 0, 'reasons': []})
    row['name'] = str(player.get('name') or uid)
    row['points'] = int(row.get('points', 0) or 0) + int(points)
    if reason:
        row.setdefault('reasons', []).append(f'{int(points):+d} {reason}')


def _v94_add_global_points_once(chat_id: int, game: Dict[str, Any]) -> None:
    if game.get('v94_ranking_applied'):
        return
    players = game.get('players', []) if isinstance(game.get('players'), list) else []
    by_id = {}
    for p in players:
        try:
            by_id[str(int(p.get('id', 0) or 0))] = p
        except Exception:
            pass
    mp = _v94_point_map(game)
    store = _imp_score_store(chat_id)
    for uid, rowdata in mp.items():
        try:
            uid_i = int(uid)
            points = int(rowdata.get('points', 0) or 0)
        except Exception:
            continue
        player = by_id.get(str(uid_i), {'id': uid_i, 'name': str(rowdata.get('name') or uid_i)})
        name = str(player.get('name') or rowdata.get('name') or uid_i)
        for scope, key in (("general", "all"), ("daily", _v44_today_key()), ("weekly", _v44_week_key())):
            bucket = store.setdefault(scope, {})
            period = bucket.setdefault(key, {})
            r = period.setdefault(str(uid_i), {'name': name, 'points': 0, 'games': 0})
            r['name'] = name
            r['points'] = int(r.get('points', 0) or 0) + points
            # cuenta una partida por jugador solo una vez al cierre.
            r['games'] = int(r.get('games', 0) or 0) + 1
    game['v94_ranking_applied'] = True
    save_all_states()


def _v94_accuse_points(ronda: int, correct: bool) -> int:
    ronda = max(1, min(3, int(ronda or 1)))
    if correct:
        return {1: 4, 2: 3, 3: 2}.get(ronda, 2)
    return -5


# Override de puntos de acusación usado por el router V80.
def _v80_accuse_points(ronda: int, correct: bool) -> int:  # type: ignore[override]
    return _v94_accuse_points(ronda, correct)


# Evita que las acusaciones sumen al ranking inmediatamente. Se computa todo al final.
def _v80_apply_event_score(chat_id: int, game: Dict[str, Any], user_id: int, points: int, key: str) -> None:  # type: ignore[override]
    applied = game.setdefault('v94_event_scores_seen', {})
    unique = f'{key}:{int(user_id)}'
    if applied.get(unique):
        return
    applied[unique] = True
    save_all_states()


# Mensaje inferior muy corto. Acusar va abajo cuando toque.
def _v58_imp_prompt_text(game: Dict[str, Any]) -> str:  # type: ignore[override]
    current = _imp_current_player(game)
    if not current:
        return '🎭 Sin turno.'
    try:
        chat_id = int(game.get('chat_id') or 0)
    except Exception:
        chat_id = 0
    seconds = _v61_turn_seconds(chat_id) if chat_id and '_v61_turn_seconds' in globals() else 60
    ronda = int(game.get('round', 1) or 1)
    return (
        f'✍️ {_imp_mention(current)}, pista R{ronda}.\n'
        f'⏱ {fmt_duration(seconds) if seconds >= 60 else str(seconds) + "s"}'
    )


def _v58_imp_prompt_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:  # type: ignore[override]
    gid = int(game.get('id', 0) or 0)
    rows: List[List[InlineKeyboardButton]] = [[InlineKeyboardButton('✍️ Responder pista', callback_data=f'imp|respond|{chat_id}|{gid}')]]
    try:
        can_accuse, _ = _v61_can_accuse_now(chat_id, game)
    except Exception:
        can_accuse = True
    if can_accuse:
        rows.append([InlineKeyboardButton('🚨 Acusar', callback_data=f'imp|accuse_menu|{chat_id}|{gid}')])
    return InlineKeyboardMarkup(rows)


# Primer mensaje más claro y permanente.
def _v58_imp_card_text(game: Dict[str, Any]) -> str:  # type: ignore[override]
    status = str(game.get('status') or 'lobby')
    players = _imp_active_players(game) if status in ('active', 'voting') else (game.get('players', []) if isinstance(game.get('players'), list) else [])
    ronda = int(game.get('round', 1) or 1)
    if status == 'lobby':
        return (
            '<b>EL JUEGO DEL IMPOSTOR</b>\n\n'
            'Todos tienen palabra secreta menos el impostor.\n\n'
            f'👥 Jugadores: <b>{len(players)}</b>\n'
            f'{_v58_imp_players_lines(game)}\n\n'
            'Pulsa Unirme para entrar. Mínimo 3 jugadores.'
        )
    # En votación mantenemos las pistas visibles, no convertimos este mensaje en la votación.
    return (
        '<b>EL JUEGO DEL IMPOSTOR</b>\n'
        f'Ronda <b>{ronda}/3</b> · Activos: <b>{len(players)}</b>\n\n'
        '<b>🧩 Pistas acumuladas</b>\n'
        f'{_v78_clues_lines(game, limit=14) if "_v78_clues_lines" in globals() else ""}'
    )


def _v58_imp_card_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:  # type: ignore[override]
    gid = int(game.get('id', 0) or 0)
    status = str(game.get('status') or 'lobby')
    if status == 'lobby':
        return _imp_lobby_markup(chat_id, game)
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('🔐 Ver mi palabra', callback_data=f'imp|mysecret|{chat_id}|{gid}')],
        [InlineKeyboardButton('🗳 Abrir votación final', callback_data=f'imp|vote_menu|{chat_id}|{gid}')],
    ])


def _v94_active_voters(game: Dict[str, Any]) -> List[Dict[str, Any]]:
    return _imp_active_players(game)


def _v94_vote_status_text(game: Dict[str, Any]) -> str:
    active = _v94_active_voters(game)
    votes = game.get('votes') if isinstance(game.get('votes'), dict) else {}
    counts = _v78_vote_counts(game) if '_v78_vote_counts' in globals() else {}
    voted_names = []
    for raw in votes.keys():
        try:
            p = _imp_player(game, int(raw))
            if p:
                voted_names.append(_imp_mention(p))
        except Exception:
            pass
    lines = []
    for p in active:
        uid = int(p.get('id', 0) or 0)
        lines.append(f'{_imp_mention(p)}: <b>{counts.get(uid, 0)}</b>')
    sec = int(game.get('v94_vote_seconds') or _v94_vote_seconds(int(game.get('chat_id') or 0)))
    return (
        '🗳 <b>Votación final</b>\n\n'
        f'⏱ Máximo: <b>{fmt_duration(sec)}</b>\n'
        f'📊 Votos: <b>{len(votes)}/{len(active)}</b>\n'
        f'👥 Han votado: {", ".join(voted_names) if voted_names else "<i>nadie todavía</i>"}\n\n'
        '<b>Recuento:</b>\n' + ('\n'.join(lines) if lines else '<i>sin votos</i>')
    )


def _v78_vote_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:  # type: ignore[override]
    gid = int(game.get('id', 0) or 0)
    counts = _v78_vote_counts(game) if '_v78_vote_counts' in globals() else {}
    rows: List[List[InlineKeyboardButton]] = []
    for p in _v94_active_voters(game):
        uid = int(p.get('id', 0) or 0)
        name = str(p.get('name') or uid)[:22]
        rows.append([InlineKeyboardButton(f'{name} · {counts.get(uid, 0)}', callback_data=f'imp|vote|{chat_id}|{gid}|{uid}')])
    rows.append([InlineKeyboardButton('🔄 Actualizar votos', callback_data=f'imp|vote_refresh|{chat_id}|{gid}')])
    return InlineKeyboardMarkup(rows)


async def _v94_send_or_update_vote_message(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any]) -> None:
    mid = int(game.get('v94_vote_message_id') or 0)
    text = _v94_vote_status_text(game)
    markup = _v78_vote_markup(chat_id, game)
    if mid:
        try:
            await context.bot.edit_message_text(chat_id=chat_id, message_id=mid, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
            return
        except Exception:
            pass
    msg = await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=markup)
    game['v94_vote_message_id'] = int(msg.message_id)
    save_all_states()


async def _v94_vote_timeout_later(context: ContextTypes.DEFAULT_TYPE, chat_id: int, gid: int, seconds: int) -> None:
    try:
        await asyncio.sleep(max(10, int(seconds)))
        game = _imp_find(chat_id, gid)
        if not game or str(game.get('status')) != 'voting':
            return
        votes = game.get('votes') if isinstance(game.get('votes'), dict) else {}
        non_voters = []
        for p in _v94_active_voters(game):
            uid = int(p.get('id', 0) or 0)
            if str(uid) not in votes:
                non_voters.append(uid)
        if non_voters:
            game['v94_voting_timed_out'] = True
            eliminated = game.setdefault('eliminated', [])
            for uid in non_voters:
                if uid not in [int(x) for x in eliminated if str(x).lstrip('-').isdigit()]:
                    eliminated.append(uid)
            save_all_states()
        await _imp_finish(context, chat_id, game, reason='\n⏱ Se cerró la votación por tiempo.')
    except asyncio.CancelledError:
        return
    except Exception:
        logger.exception('Error timeout votación Impostor V94')
    finally:
        IMPOSTOR_VOTE_TASKS_V94.pop(_v94_game_key(chat_id, gid), None)


def _v94_schedule_vote_timeout(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any]) -> None:
    gid = int(game.get('id', 0) or 0)
    _v94_cancel_vote_task(chat_id, gid)
    sec = _v94_vote_seconds(chat_id)
    game['v94_vote_seconds'] = sec
    save_all_states()
    if sec <= 0:
        return
    IMPOSTOR_VOTE_TASKS_V94[_v94_game_key(chat_id, gid)] = asyncio.create_task(_v94_vote_timeout_later(context, chat_id, gid, sec))


def _v94_system_text() -> str:
    return (
        '<b>Sistema de puntuación</b>\n'
        '• Por jugar: <b>+1</b>\n'
        '• Por no ser eliminado: <b>+1</b>\n'
        '• Impostor que llega al final: <b>+3</b>\n'
        '• Impostor: cada acusación fallida que no sea contra él: <b>+2</b>\n'
        '• Impostor: si en votación final no es el más votado: <b>+5</b>\n'
        '• Acusar y acertar: ronda 1 <b>+4</b>, ronda 2 <b>+3</b>, ronda 3 <b>+2</b>\n'
        '• Acusar y fallar: <b>-5</b> y eliminado\n'
        '• No votar a tiempo: <b>-5</b> y <b>-1</b> por tiempo\n'
        '• Votación final: acertar <b>+3</b>, fallar <b>-3</b>\n'
        '• Inocente votado al final: <b>+2</b> por cada voto recibido'
    )


def _v94_compute_score(chat_id: int, game: Dict[str, Any], winner_side: str) -> str:
    if game.get('v94_scored'):
        return game.get('v94_result_text', '') or ''
    players = game.get('players', []) if isinstance(game.get('players'), list) else []
    by_id = {}
    for p in players:
        try:
            by_id[int(p.get('id', 0) or 0)] = p
        except Exception:
            pass
    imp_id = int(game.get('impostor_id', 0) or 0)
    eliminated = {int(x) for x in game.get('eliminated', []) if str(x).lstrip('-').isdigit()}
    votes = game.get('votes') if isinstance(game.get('votes'), dict) else {}
    final_vote_reached = bool(votes) or bool(game.get('v94_voting_timed_out')) or str(game.get('status')) == 'voting'

    # base
    for p in players:
        pid = int(p.get('id', 0) or 0)
        _v94_add_game_points(game, p, 1, 'por jugar')
        if pid not in eliminated:
            _v94_add_game_points(game, p, 1, 'por no ser eliminado')

    # acusaciones directas
    for acc in game.get('accusations', []) if isinstance(game.get('accusations'), list) else []:
        if not isinstance(acc, dict):
            continue
        by = int(acc.get('by', 0) or acc.get('accuser_id', 0) or 0)
        target = int(acc.get('target', 0) or acc.get('target_id', 0) or 0)
        ronda = int(acc.get('round', 1) or 1)
        correct = bool(acc.get('correct')) or target == imp_id
        p = by_id.get(by)
        if p:
            pts = _v94_accuse_points(ronda, correct)
            _v94_add_game_points(game, p, pts, f'acusación {"correcta" if correct else "fallida"} R{ronda}')
        if not correct and target != imp_id and imp_id in by_id:
            _v94_add_game_points(game, by_id[imp_id], 2, 'acusación fallida contra otro')

    # votación final
    if final_vote_reached:
        counts: Dict[int, int] = {}
        for voter_raw, target_raw in votes.items():
            try:
                voter = int(voter_raw); target = int(target_raw)
            except Exception:
                continue
            # eliminados por acusación fallida no votan/puntúan voto
            if voter in eliminated and not game.get('v94_voting_timed_out'):
                continue
            vp = by_id.get(voter)
            if vp:
                if target == imp_id:
                    _v94_add_game_points(game, vp, 3, 'voto final correcto')
                else:
                    _v94_add_game_points(game, vp, -3, 'voto final fallido')
            counts[target] = counts.get(target, 0) + 1
            if target != imp_id and target in by_id:
                _v94_add_game_points(game, by_id[target], 2, 'voto recibido siendo inocente')
        # no votantes si hubo timeout
        if game.get('v94_voting_timed_out'):
            for p in players:
                pid = int(p.get('id', 0) or 0)
                if pid not in eliminated:
                    continue
                if str(pid) not in votes:
                    _v94_add_game_points(game, p, -5, 'no votar a tiempo')
                    _v94_add_game_points(game, p, -1, 'pasarse del tiempo')
        if imp_id in by_id:
            _v94_add_game_points(game, by_id[imp_id], 3, 'impostor llegó al final')
            if counts:
                max_votes = max(counts.values())
                imp_votes = counts.get(imp_id, 0)
                if imp_votes < max_votes:
                    _v94_add_game_points(game, by_id[imp_id], 5, 'no fue el más votado')

    _v94_add_global_points_once(chat_id, game)
    mp = _v94_point_map(game)
    rows = []
    for uid, r in mp.items():
        rows.append((int(r.get('points', 0) or 0), str(r.get('name') or uid), r.get('reasons', [])))
    rows.sort(key=lambda x: x[0], reverse=True)
    lines = ['<b>🏆 Puntos de esta partida</b>']
    for i, (pts, name, reasons) in enumerate(rows, 1):
        detail = '; '.join([h(x) for x in reasons[:5]])
        more = '…' if len(reasons) > 5 else ''
        lines.append(f'{i}. <b>{h(name)}</b>: <b>{pts:+d}</b> pts' + (f' — <i>{detail}{more}</i>' if detail else ''))
    lines.append('\n' + _v94_system_text())
    result = '\n'.join(lines)
    game['v94_scored'] = True
    game['v94_result_text'] = result
    save_all_states()
    return result


# Override total de scoring final, sin arrastrar puntuaciones antiguas.
def _imp_score_game(chat_id: int, game: Dict[str, Any], winner_side: str) -> str:  # type: ignore[override]
    return _v94_compute_score(chat_id, game, winner_side)


def _imp_instructions_text() -> str:  # type: ignore[override]
    return (
        '📘 <b>Instrucciones · EL JUEGO DEL IMPOSTOR</b>\n\n'
        'Da pistas cortas. El impostor debe disimular sin conocer la palabra.\n'
        'Cuando esté permitido, puedes acusar desde el mensaje inferior del turno.\n'
        'Al final se puede abrir votación final.\n\n' + _v94_system_text()
    )


async def _v94_send_finished_result(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], reason: str = '') -> None:
    if game.get('v94_finished_sent'):
        return
    game['status'] = 'finished'
    game['v94_finished_sent'] = True
    gid = int(game.get('id', 0) or 0)
    _v94_cancel_vote_task(chat_id, gid)
    imp_id = int(game.get('impostor_id', 0) or 0)
    imp = _imp_player(game, imp_id) or {'id': imp_id, 'name': 'Impostor'}
    word = h(game.get('word') or '')
    counts = _v78_vote_counts(game) if '_v78_vote_counts' in globals() else {}
    winner_side = str(game.get('winner_side') or '')
    if counts and not winner_side:
        top_id, top_votes = sorted(counts.items(), key=lambda x: x[1], reverse=True)[0]
        winner_side = 'crew' if int(top_id) == imp_id else 'impostor'
    if not winner_side:
        winner_side = 'impostor'
    game['winner_side'] = winner_side
    score_txt = _imp_score_game(chat_id, game, winner_side)
    voted_txt = ''
    if counts:
        top_id, top_votes = sorted(counts.items(), key=lambda x: x[1], reverse=True)[0]
        top = _imp_player(game, top_id) or {'id': top_id, 'name': str(top_id)}
        voted_txt = f'\nMás votado: {_imp_mention(top)} con <b>{top_votes}</b> voto(s).'
    txt = (
        '🎭 <b>Resultado · EL JUEGO DEL IMPOSTOR</b>\n\n'
        f'Palabra: <b>{word}</b>\n'
        f'Impostor: {_imp_mention(imp)} 😈'
        f'{voted_txt}'
    )
    if reason:
        txt += f'\n{reason}'
    if score_txt:
        txt += f'\n\n{score_txt}'
    save_all_states()
    # No borramos la tarjeta de pistas. Solo quitamos prompt y votación.
    try:
        await _v58_delete_if_exists(context.bot, chat_id, game.get('v58_prompt_message_id'))
        await _v58_delete_if_exists(context.bot, chat_id, game.get('v94_vote_message_id'))
    except Exception:
        pass
    await context.bot.send_message(
        chat_id,
        txt[:3900],
        parse_mode=ParseMode.HTML,
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton('🎭 Iniciar otra partida', callback_data=f'imp|new|{chat_id}')],
            [InlineKeyboardButton('🏆 Ver ranking', callback_data=f'imp|ranking|{chat_id}|{gid}')],
        ])
    )


async def _imp_finish(context: ContextTypes.DEFAULT_TYPE, chat_id: int, game: Dict[str, Any], reason: str = '') -> None:  # type: ignore[override]
    await _v94_send_finished_result(context, chat_id, game, reason)


# Configuración de tiempo de votación en ajustes del Impostor.
_old_admin_private_block_text_v94 = admin_private_block_text

def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:  # type: ignore[override]
    txt = _old_admin_private_block_text_v94(chat_id, block, page)
    if block == 'impostor_settings' and 'Tiempo votación final:' not in txt:
        sec = _v94_vote_seconds(chat_id)
        label = 'OFF' if sec <= 0 else fmt_duration(sec)
        txt += f'\nTiempo votación final: <b>{label}</b>\n'
    return txt


_old_admin_private_block_markup_v94 = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    markup = _old_admin_private_block_markup_v94(chat_id, block, page)
    if block != 'impostor_settings':
        return markup
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    # Evita duplicar.
    rows = [r for r in rows if not any(str(getattr(b, 'callback_data', '')).startswith('cfg|impvote|') for b in r)]
    rows.insert(max(0, len(rows)-1), [
        InlineKeyboardButton('🗳 Voto OFF', callback_data=f'cfg|impvote|{chat_id}|0'),
        InlineKeyboardButton('1m', callback_data=f'cfg|impvote|{chat_id}|60'),
        InlineKeyboardButton('2m', callback_data=f'cfg|impvote|{chat_id}|120'),
        InlineKeyboardButton('3m', callback_data=f'cfg|impvote|{chat_id}|180'),
    ])
    return InlineKeyboardMarkup(rows)


_old_admin_private_config_callback_v94 = admin_private_config_callback
async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    q = update.callback_query
    data = q.data if q else ''
    if q and data.startswith('cfg|impvote|'):
        try:
            _a, _b, chat_raw, sec_raw = data.split('|')[:4]
            chat_id = int(chat_raw); sec = int(sec_raw)
        except Exception:
            await q.answer('Valor inválido', show_alert=True); raise _V94Stop
        cfg_set(chat_id, 'imp_vote_seconds', max(0, sec))
        await q.answer('Tiempo de votación actualizado ✅')
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, 'impostor_settings'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'impostor_settings'))
        except Exception:
            pass
        raise _V94Stop
    return await _old_admin_private_config_callback_v94(update, context)


_old_impostor_callback_router_v94 = impostor_callback_router
async def impostor_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('imp|'):
        return await _old_impostor_callback_router_v94(update, context)
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    if action not in ('vote_menu', 'vote', 'vote_refresh'):
        return await _old_impostor_callback_router_v94(update, context)
    try:
        chat_id = int(parts[2]); gid = int(parts[3])
    except Exception:
        await q.answer('Partida inválida', show_alert=True); raise _V94Stop
    game = _imp_find(chat_id, gid)
    if not game:
        await q.answer('No encuentro la partida.', show_alert=True); raise _V94Stop
    uid = int(q.from_user.id)

    if action == 'vote_menu':
        if str(game.get('status')) not in ('active', 'voting'):
            await q.answer('La partida no está activa.', show_alert=True); raise _V94Stop
        game['status'] = 'voting'
        game['chat_id'] = int(chat_id)
        save_all_states()
        # No borramos el primer mensaje de pistas. Solo quitamos prompt inferior.
        try:
            await _v58_delete_if_exists(context.bot, chat_id, game.get('v58_prompt_message_id'))
            game['v58_prompt_message_id'] = 0
        except Exception:
            pass
        await _v94_send_or_update_vote_message(context, chat_id, game)
        _v94_schedule_vote_timeout(context, chat_id, game)
        await q.answer('Votación abierta')
        raise _V94Stop

    if action == 'vote_refresh':
        await _v94_send_or_update_vote_message(context, chat_id, game)
        await q.answer('Actualizado')
        raise _V94Stop

    # vote
    if len(parts) < 5:
        await q.answer('Voto inválido.', show_alert=True); raise _V94Stop
    try:
        target_id = int(parts[4])
    except Exception:
        await q.answer('Voto inválido.', show_alert=True); raise _V94Stop
    active_ids = [int(p.get('id', 0) or 0) for p in _v94_active_voters(game)]
    if uid not in active_ids:
        await q.answer('No puedes votar: no estás activo en la partida.', show_alert=True); raise _V94Stop
    votes = game.setdefault('votes', {})
    votes[str(uid)] = target_id
    save_all_states()
    await q.answer('Voto guardado ✅')
    await _v94_send_or_update_vote_message(context, chat_id, game)
    # Si ya han votado todos los activos, termina sin esperar al timeout.
    active_ids = [int(p.get('id', 0) or 0) for p in _v94_active_voters(game)]
    if active_ids and all(str(x) in votes for x in active_ids):
        _v94_cancel_vote_task(chat_id, gid)
        await _imp_finish(context, chat_id, game)
    raise _V94Stop


_old_build_application_v94 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v94()
    app.add_handler(CallbackQueryHandler(impostor_callback_router, pattern=r'^imp\|'), group=-6100000)
    app.add_handler(CallbackQueryHandler(admin_private_config_callback, pattern=r'^cfg\|impvote\|'), group=-6100000)
    logger.info('V94 Impostor puntuación definitiva y votación persistente cargado')
    return app



# =========================================================
# V95 - Impostor: mensaje inferior con botón Responder e instrucciones en 2 líneas
# =========================================================
# Mantiene el botón Responder pista y, cuando toque por configuración, el botón Acusar.
# El texto queda corto pero claro: dos líneas de instrucciones y una línea de tiempo.

try:
    from telegram.ext import ApplicationHandlerStop as _V95Stop
except Exception:
    _V95Stop = Exception


def _v58_imp_prompt_text(game: Dict[str, Any]) -> str:  # type: ignore[override]
    current = _imp_current_player(game)
    if not current:
        return '🎭 Sin turno.'
    try:
        chat_id = int(game.get('chat_id') or 0)
    except Exception:
        chat_id = 0
    seconds = _v61_turn_seconds(chat_id) if chat_id and '_v61_turn_seconds' in globals() else 60
    ronda = int(game.get('round', 1) or 1)
    tiempo = fmt_duration(seconds) if int(seconds) >= 60 else f'{int(seconds)}s'
    return (
        f'✍️ {_imp_mention(current)}, te toca la pista R{ronda}.\n'
        f'Pulsa <b>Responder pista</b> y escribe una pista corta.\n'
        f'⏱ {tiempo}'
    )


def _v58_imp_prompt_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:  # type: ignore[override]
    gid = int(game.get('id', 0) or 0)
    rows: List[List[InlineKeyboardButton]] = [
        [InlineKeyboardButton('✍️ Responder pista', callback_data=f'imp|respond|{chat_id}|{gid}')]
    ]
    try:
        can_accuse, _reason = _v61_can_accuse_now(chat_id, game)
    except Exception:
        can_accuse = True
    if can_accuse:
        rows.append([InlineKeyboardButton('🚨 Acusar', callback_data=f'imp|accuse_menu|{chat_id}|{gid}')])
    return InlineKeyboardMarkup(rows)


