# V98 - Recurrentes multimedia/botones + DJ cola/listas + menú temporal + panel fijado editable
# =========================================================

try:
    from telegram.ext import ApplicationHandlerStop as _V98Stop
except Exception:
    _V98Stop = Exception


def _v98_bool_label(v: bool) -> str:
    return 'ON ✅' if bool(v) else 'OFF ❌'


def _v98_markup_for_rec(row: Dict[str, Any], *, self_url: Optional[str] = None, chat_id: Optional[int] = None):
    try:
        return recurring_buttons_markup(row, self_url=self_url, chat_id=chat_id)
    except TypeError:
        try:
            return recurring_buttons_markup(row, self_url=self_url)
        except TypeError:
            return recurring_buttons_markup(row)


def _v98_message_link(chat_id: int, message_id: int) -> str:
    try:
        return _message_link_v20(chat_id, message_id) if '_message_link_v20' in globals() else ''
    except Exception:
        return ''


async def _v98_delete_message_ids(bot, chat_id: int, ids: List[int]) -> None:
    for mid in list(dict.fromkeys([int(x) for x in ids if x])):
        try:
            await safe_delete(bot, chat_id, mid)
        except Exception:
            try:
                await bot.delete_message(chat_id, mid)
            except Exception:
                pass


async def _v98_send_media_only(bot, chat_id: int, media: Dict[str, str], *, markup=None):
    fid = media.get('file_id')
    mtype = media.get('type')
    if mtype == 'photo':
        return await bot.send_photo(chat_id, photo=fid, reply_markup=markup)
    if mtype == 'video':
        return await bot.send_video(chat_id, video=fid, reply_markup=markup)
    if mtype == 'animation':
        return await bot.send_animation(chat_id, animation=fid, reply_markup=markup)
    return await bot.send_document(chat_id, document=fid, reply_markup=markup)


_old_send_recurring_message_v98 = send_recurring_message
async def send_recurring_message(context, chat_id: int, row: Dict[str, Any]) -> Optional[int]:  # type: ignore[override]
    media = row.get('media') if isinstance(row.get('media'), dict) else None
    # Si no hay multimedia, dejamos intacta toda la lógica anterior, incluido IA recurrente.
    if not media or not media.get('file_id'):
        return await _old_send_recurring_message_v98(context, chat_id, row)

    text = str(row.get('text') or '').strip()
    pos = str(row.get('media_position') or row.get('rec_media_position') or 'above').lower()
    if pos not in ('above', 'below'):
        pos = 'above'
    previous_ids: List[int] = []
    if isinstance(row.get('last_message_ids'), list):
        previous_ids.extend([int(x) for x in row.get('last_message_ids') if x])
    if int(row.get('last_message_id') or 0):
        previous_ids.append(int(row.get('last_message_id')))
    delete_previous = bool(row.get('delete_previous', True))

    sent_ids: List[int] = []
    main_msg = None
    try:
        if pos == 'above':
            # Multimedia arriba, texto y botones debajo.
            media_msg = await _v98_send_media_only(context.bot, chat_id, media)
            sent_ids.append(int(media_msg.message_id))
            await register_bot_message(chat_id, media_msg.message_id)
            if text:
                markup = _v98_markup_for_rec(row, self_url=_v98_message_link(chat_id, media_msg.message_id), chat_id=chat_id)
                main_msg = await context.bot.send_message(chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)
                sent_ids.append(int(main_msg.message_id))
                await register_bot_message(chat_id, main_msg.message_id)
            else:
                main_msg = media_msg
                # si no hay texto, intentamos poner botones en la media editando markup
                markup = _v98_markup_for_rec(row, self_url=_v98_message_link(chat_id, media_msg.message_id), chat_id=chat_id)
                if markup:
                    try:
                        await context.bot.edit_message_reply_markup(chat_id=chat_id, message_id=media_msg.message_id, reply_markup=markup)
                    except Exception:
                        pass
        else:
            # Texto arriba, multimedia y botones debajo.
            if text:
                txt_msg = await context.bot.send_message(chat_id, text=text, parse_mode=ParseMode.HTML, disable_web_page_preview=True)
                sent_ids.append(int(txt_msg.message_id))
                await register_bot_message(chat_id, txt_msg.message_id)
                markup = _v98_markup_for_rec(row, self_url=_v98_message_link(chat_id, txt_msg.message_id), chat_id=chat_id)
            else:
                markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id)
            media_msg = await _v98_send_media_only(context.bot, chat_id, media, markup=markup)
            sent_ids.append(int(media_msg.message_id))
            await register_bot_message(chat_id, media_msg.message_id)
            main_msg = media_msg

        if main_msg is None:
            return None
        row['last_message_id'] = int(main_msg.message_id)
        row['last_message_ids'] = sent_ids
        row['last_message_link'] = _v98_message_link(chat_id, int(main_msg.message_id))
        row['delete_previous'] = delete_previous
        save_all_states()
        if bool(row.get('pin', False)):
            try:
                await context.bot.pin_chat_message(chat_id, sent_ids[0], disable_notification=True)
            except Exception:
                pass
        if delete_previous:
            await _v98_delete_message_ids(context.bot, chat_id, [x for x in previous_ids if x not in sent_ids])
        return int(main_msg.message_id)
    except Exception:
        logger.exception('No se pudo enviar recurrente multimedia V98 %s en chat %s', row.get('id'), chat_id)
        return None


_old_recurring_detail_text_v98 = recurring_detail_text
def recurring_detail_text(chat_id: int, rid: int) -> str:  # type: ignore[override]
    text = _old_recurring_detail_text_v98(chat_id, rid)
    row = recurring_find(chat_id, rid)
    if not row:
        return text
    if isinstance(row.get('media'), dict) and row.get('media', {}).get('file_id'):
        pos = str(row.get('media_position') or 'above')
        label = 'multimedia arriba del texto' if pos == 'above' else 'texto arriba y multimedia debajo'
        text += f"\n📍 Posición multimedia: <b>{h(label)}</b>"
    return text


_old_recurring_detail_markup_v98 = recurring_detail_markup
def recurring_detail_markup(chat_id: int, rid: int) -> InlineKeyboardMarkup:  # type: ignore[override]
    markup = _old_recurring_detail_markup_v98(chat_id, rid)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', []) or []]
    row = recurring_find(chat_id, rid) or {}
    insert_at = max(0, len(rows) - 1)
    if isinstance(row.get('media'), dict) and row.get('media', {}).get('file_id'):
        pos = str(row.get('media_position') or 'above')
        txt = '🖼 Multimedia arriba' if pos == 'above' else '📝 Texto arriba'
        rows.insert(insert_at, [InlineKeyboardButton(txt, callback_data=f'cfg|rec_media_pos|{chat_id}|{rid}')])
    return InlineKeyboardMarkup(rows)


def _v98_buttons_text(row: Dict[str, Any]) -> str:
    buttons = row.get('buttons') if isinstance(row.get('buttons'), list) else []
    if not buttons:
        return 'No hay botones configurados.'
    lines = []
    for i, b in enumerate(buttons, 1):
        if not isinstance(b, dict):
            continue
        label = str(b.get('text') or '')
        target = str(b.get('url') or b.get('cmd') or '')
        lines.append(f'{i}. <b>{h(label)}</b> → <code>{h(target)}</code>')
    return '\n'.join(lines) or 'No hay botones configurados.'


def _v98_buttons_menu_markup(chat_id: int, rid: int) -> InlineKeyboardMarkup:
    row = recurring_find(chat_id, rid) or {}
    buttons = row.get('buttons') if isinstance(row.get('buttons'), list) else []
    rows: List[List[InlineKeyboardButton]] = [
        [InlineKeyboardButton('➕ Añadir botón', callback_data=f'cfg|rec_button_add|{chat_id}|{rid}'), InlineKeyboardButton('🧹 Vaciar botones', callback_data=f'cfg|rec_button_clear|{chat_id}|{rid}')]
    ]
    for idx, b in enumerate(buttons[:30]):
        label = str(b.get('text') if isinstance(b, dict) else f'Botón {idx+1}')[:24]
        rows.append([
            InlineKeyboardButton('⬆️', callback_data=f'cfg|rec_button_up|{chat_id}|{rid}|{idx}'),
            InlineKeyboardButton('⬇️', callback_data=f'cfg|rec_button_down|{chat_id}|{rid}|{idx}'),
            InlineKeyboardButton(f'🗑 {idx+1}. {label}', callback_data=f'cfg|rec_button_del|{chat_id}|{rid}|{idx}'),
        ])
    rows.append([InlineKeyboardButton('🔙 Volver al recurrente', callback_data=f'cfg|rec_edit|{chat_id}|{rid}|recurrentes')])
    return InlineKeyboardMarkup(rows)

# Sobrescribir los nombres que usan versiones anteriores si existen.
_v71_buttons_menu_markup = _v98_buttons_menu_markup


async def _v98_recurring_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    parts = data.split('|')
    try:
        action = parts[1]
    except Exception:
        return
    if action not in {'rec_media_pos','rec_button_up','rec_button_down','rec_buttons_menu'}:
        return
    try:
        chat_id = int(parts[2]); rid = int(parts[3])
        row = recurring_find(chat_id, rid)
        if not row:
            await q.answer('No encuentro ese recurrente.', show_alert=True); raise _V98Stop
        if action == 'rec_media_pos':
            cur = str(row.get('media_position') or 'above')
            row['media_position'] = 'below' if cur == 'above' else 'above'
            save_all_states()
            await q.answer('Posición multimedia actualizada ✅')
            await q.edit_message_text(recurring_detail_text(chat_id, rid), parse_mode=ParseMode.HTML, reply_markup=recurring_detail_markup(chat_id, rid))
            raise _V98Stop
        if action == 'rec_buttons_menu':
            await q.answer('Botones')
            await q.edit_message_text('⌨️ <b>Botones del recurrente</b>\n\n' + _v98_buttons_text(row), parse_mode=ParseMode.HTML, reply_markup=_v98_buttons_menu_markup(chat_id, rid))
            raise _V98Stop
        if action in {'rec_button_up','rec_button_down'}:
            idx = int(parts[4])
            buttons = row.get('buttons') if isinstance(row.get('buttons'), list) else []
            if 0 <= idx < len(buttons):
                new_idx = idx - 1 if action == 'rec_button_up' else idx + 1
                if 0 <= new_idx < len(buttons):
                    buttons[idx], buttons[new_idx] = buttons[new_idx], buttons[idx]
                    row['buttons'] = buttons
                    save_all_states()
            await q.answer('Orden actualizado ✅')
            await q.edit_message_text('⌨️ <b>Botones del recurrente</b>\n\n' + _v98_buttons_text(row), parse_mode=ParseMode.HTML, reply_markup=_v98_buttons_menu_markup(chat_id, rid))
            raise _V98Stop
    except _V98Stop:
        raise
    except Exception:
        logger.exception('Error recurrentes V98: %s', data)
        try: await q.answer('Error. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V98Stop


