# Carga de listas sin duplicar cola.
async def _v98_saved_list_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if not data.startswith('lst|'):
        return
    parts = data.split('|')
    if len(parts) < 3 or parts[1] not in {'a','p'}:
        return
    chat_id = int(update.effective_chat.id)
    user_id = int(update.effective_user.id)
    if not await is_controller(context, chat_id, user_id):
        await q.answer('Solo el DJ asignado puede cargar listas.', show_alert=True); raise _V98Stop
    state = get_state(chat_id)
    names = sorted(state.saved_lists.keys())
    try: idx = int(parts[2])
    except Exception: idx = -1
    if not (0 <= idx < len(names)):
        await q.answer('Lista no válida', show_alert=True); raise _V98Stop
    name = names[idx]
    items = [dict(item) for item in state.saved_lists.get(name, [])]
    if parts[1] == 'a':
        state.queue = dedupe_track_items([dict(x) for x in state.queue] + items)
        save_all_states()
        await ensure_panel(context.bot, chat_id); await ensure_control_panel(context.bot, chat_id)
        await q.answer('Lista añadida sin duplicar ✅')
        await send_temp_message(context.bot, chat_id, f'➕ Lista añadida sin duplicar: <b>{h(name)}</b>', ttl=15)
    else:
        if items:
            first = Track(**items[0])
            state.queue = dedupe_track_items([dict(x) for x in state.queue] + items[1:])
            save_all_states()
            await play_selected_track(context, chat_id, first)
            await ensure_panel(context.bot, chat_id); await ensure_control_panel(context.bot, chat_id)
            await q.answer('Lista reproduciendo sin duplicar ✅')
    set_control_view(state, 'saved_lists', 0); save_all_states(); await ensure_control_panel(context.bot, chat_id)
    raise _V98Stop


async def _v98_djpriv_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_user:
        return
    data = q.data or ''
    parts = data.split('|')
    if len(parts) < 2:
        return
    action = parts[1]
    if action not in {'loadlist','recentq'}:
        return
    try:
        chat_id = int(parts[2]) if len(parts) > 2 else int(dj_selected_private_group(update.effective_user.id) or 0)
    except Exception:
        await q.answer('Grupo no válido', show_alert=True); raise _V98Stop
    if not chat_id:
        await q.answer('Primero vincula un grupo con /djgrupo.', show_alert=True); raise _V98Stop
    if not (await is_admin(context, chat_id, update.effective_user.id) or await is_controller(context, chat_id, update.effective_user.id)):
        await q.answer('Solo admin o DJ asignado.', show_alert=True); raise _V98Stop
    state = get_state(chat_id)
    if action == 'loadlist':
        try: idx = int(parts[3])
        except Exception: idx = -1
        names = sorted(state.saved_lists.keys())[:30]
        if not (0 <= idx < len(names)):
            await q.answer('Lista no válida', show_alert=True); raise _V98Stop
        name = names[idx]
        state.queue = dedupe_track_items([dict(x) for x in state.queue] + [dict(x) for x in state.saved_lists.get(name, [])])
        save_all_states(); await ensure_panel(context.bot, chat_id); await ensure_control_panel(context.bot, chat_id)
        await q.answer('Lista cargada sin duplicar ✅')
        await q.edit_message_text(dj_private_text(chat_id), reply_markup=dj_private_markup(chat_id), parse_mode=ParseMode.HTML)
        raise _V98Stop
    if action == 'recentq':
        private_chat_id = int(q.message.chat_id)
        recent = list((TRACK_REGISTRY.get(private_chat_id, {}) or {}).values())[-80:]
        if not recent:
            await q.answer('No hay canciones recientes en este privado.', show_alert=True); raise _V98Stop
        state.queue = dedupe_track_items([dict(x) for x in state.queue] + [dict(x) for x in recent])
        save_all_states(); await ensure_panel(context.bot, chat_id); await ensure_control_panel(context.bot, chat_id)
        await q.answer(f'{len(recent)} recientes añadidas sin duplicar ✅', show_alert=True)
        await q.edit_message_text(dj_private_text(chat_id), reply_markup=dj_private_markup(chat_id), parse_mode=ParseMode.HTML)
        raise _V98Stop


