async def _v98_cfg_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    parts = data.split('|')
    try:
        action = parts[1]
    except Exception:
        return
    if action not in {'djpanel_text','djpanel_reset'}:
        return
    try:
        chat_id = int(parts[2])
        if action == 'djpanel_text':
            set_config_pending(q.from_user.id, {'kind':'dj_panel_text_v98','chat_id':chat_id})
            await q.answer('Envíame el texto')
            await q.message.reply_html(
                '✏️ <b>Mensaje fijado superior DJ</b>\n\n'
                'Envíame el texto. Puedes usar HTML, emojis premium y variables:\n'
                '<code>{estado}</code> <code>{cancion}</code> <code>{siguiente}</code> <code>{dj}</code> <code>{cola}</code>\n\n'
                'Escribe <code>DEFECTO</code> para volver al mensaje actual.'
            )
            raise _V98Stop
        if action == 'djpanel_reset':
            admin_cfg(chat_id).pop('dj_panel_custom_text_html', None)
            save_all_states()
            await q.answer('Mensaje por defecto restaurado ✅')
            await q.edit_message_text(admin_private_block_text(chat_id, 'dj_permissions'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'dj_permissions'))
            raise _V98Stop
    except _V98Stop:
        raise
    except Exception:
        logger.exception('Error config DJ panel V98')
        try: await q.answer('Error. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V98Stop


async def _v98_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'dj_panel_text_v98':
        return
    chat_id = int(pending.get('chat_id') or 0)
    raw_plain = (update.message.text or '').strip()
    if raw_plain.upper() in {'DEFECTO','DEFAULT','QUITAR'}:
        admin_cfg(chat_id).pop('dj_panel_custom_text_html', None)
    else:
        admin_cfg(chat_id)['dj_panel_custom_text_html'] = telegram_html_from_message(update.message)
    pop_config_pending(update.effective_user.id)
    save_all_states()
    try:
        await ensure_panel(context.bot, chat_id)
    except Exception:
        pass
    await update.message.reply_html('✅ Mensaje fijado actualizado.\n\n' + admin_private_block_text(chat_id, 'dj_permissions'), reply_markup=admin_private_block_markup(chat_id, 'dj_permissions'))
    raise _V98Stop


_old_build_application_v98 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v98()
    app.add_handler(CallbackQueryHandler(_v98_recurring_callback, pattern=r'^cfg\|(rec_media_pos|rec_button_up|rec_button_down|rec_buttons_menu)\|'), group=-9000000)
    app.add_handler(CallbackQueryHandler(_v98_dj_menu_close, pattern=r'^dj_menu_close$'), group=-9000000)
    app.add_handler(CallbackQueryHandler(_v98_saved_list_callback, pattern=r'^lst\|[ap]\|'), group=-9000000)
    app.add_handler(CallbackQueryHandler(_v98_djpriv_callback, pattern=r'^djpriv\|(loadlist|recentq)\|'), group=-9000000)
    app.add_handler(CallbackQueryHandler(_v98_cfg_callback, pattern=r'^cfg\|djpanel_'), group=-9000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & filters.TEXT & ~filters.COMMAND, _v98_pending_text), group=-9000000)
    logger.info('V98 recurrentes multimedia/botones, DJ listas, privados recientes y panel fijado editable cargado')
    return app




