_old_v99_dj_private_markup = dj_private_markup
def dj_private_markup(chat_id: int) -> InlineKeyboardMarkup:  # type: ignore[override]
    markup = _old_v99_dj_private_markup(chat_id)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    insert_at = max(0, len(rows) - 1)
    rows.insert(insert_at, [
        InlineKeyboardButton('✏️ Editar fijado dinámico', callback_data=f'djpriv|djpaneltext|{chat_id}'),
        InlineKeyboardButton('↩️ Fijado por defecto', callback_data=f'djpriv|djpanelreset|{chat_id}'),
    ])
    return InlineKeyboardMarkup(rows)


async def _v99_dj_private_panel_text_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('djpriv|djpanel'):
        return
    parts = data.split('|')
    try:
        action = parts[1]; chat_id = int(parts[2])
    except Exception:
        await q.answer('Acción inválida', show_alert=True)
        raise _V99Stop
    if action == 'djpanelreset':
        admin_cfg(chat_id).pop('dj_panel_custom_text_html', None)
        save_all_states()
        try:
            await ensure_panel(context.bot, chat_id)
        except Exception:
            pass
        await q.answer('Fijado por defecto restaurado ✅')
        try:
            await q.edit_message_text(dj_private_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=dj_private_markup(chat_id))
        except Exception:
            pass
        raise _V99Stop
    if action == 'djpaneltext':
        set_config_pending(q.from_user.id, {'kind':'dj_panel_text_v98','chat_id':chat_id})
        await q.answer('Envíame el texto')
        msg = await q.message.reply_html(
            '✏️ <b>Editar mensaje fijado dinámico DJ</b>\n\n'
            'Puedes usar HTML y emojis premium de Telegram.\n\n'
            '<b>Variables disponibles:</b>\n'
            '<code>{estado}</code> directo ON/OFF\n'
            '<code>{cancion}</code> canción actual o próxima\n'
            '<code>{actual}</code> canción actual\n'
            '<code>{siguiente}</code> próxima canción\n'
            '<code>{dj}</code> DJ actual\n'
            '<code>{cola}</code> nº canciones en cola\n'
            '<code>{biblioteca}</code> nº canciones en biblioteca\n\n'
            '<b>Ejemplo:</b>\n'
            '<code>🔴 {estado} | ▶️ {actual} | ⏭ {siguiente} | DJ: {dj}</code>\n\n'
            'Escribe <code>DEFECTO</code> para volver al mensaje actual.'
        )
        _v99_track_private(q.from_user.id, msg.message_id)
        raise _V99Stop


# ---------- Limpieza privado reforzada ----------
async def _v99_clean_private_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or update.effective_chat.type != 'private' or not update.effective_user:
        return
    deleted = await _v99_clean_private(context.bot, update.effective_chat.id, update.effective_user.id)
    msg = await update.message.reply_html(f'🧹 Privado limpiado. Mensajes eliminados: <b>{deleted}</b>.')
    _v99_track_private(update.effective_user.id, msg.message_id)
    try:
        await context.bot.delete_message(update.effective_chat.id, update.message.message_id)
    except Exception:
        pass


async def _v99_clean_private_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not q.message or getattr(q.message.chat, 'type', '') != 'private':
        return
    data = q.data or ''
    if 'clean_private' not in data and 'limpiarprivado' not in data:
        return
    await q.answer('Limpiando…')
    await _v99_clean_private(context.bot, q.message.chat_id, q.from_user.id)
    try:
        await q.message.delete()
    except Exception:
        pass
    raise _V99Stop


async def _v99_track_private_callback_messages(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    # Rastrea paneles privados que se vayan tocando para que /limpiarprivado pueda borrarlos luego.
    q = update.callback_query
    if q and q.message and getattr(q.message.chat, 'type', '') == 'private':
        _v99_track_private(q.from_user.id, q.message.message_id)


_old_build_application_v99 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v99()
    app.add_handler(CallbackQueryHandler(_v99_modes_router, pattern=r'^(dj_easy_menu|menu_panel)$'), group=-9900000)
    app.add_handler(CallbackQueryHandler(_v99_dj_private_panel_text_callback, pattern=r'^djpriv\|djpanel'), group=-9900000)
    app.add_handler(command_handler('limpiarprivado', _v99_clean_private_command), group=-9900000)
    app.add_handler(CallbackQueryHandler(_v99_clean_private_callback, pattern=r'.*(clean_private|limpiarprivado).*'), group=-9900000)
    app.add_handler(CallbackQueryHandler(_v99_track_private_callback_messages, pattern=r'.*'), group=9900000)
    logger.info('V99 mesa visible, próxima hora recurrentes, fijado DJ privado y limpieza reforzada cargado')
    return app



# =========================================================
# V100 - Recurrentes: fijado con preview correcto + envío manual reinicia ciclo
# =========================================================
# - Si un recurrente tiene multimedia y está fijado, se envía/pinea como media con caption,
#   para que arriba no aparezca solo "Foto", sino miniatura + texto.
# - El botón ▶️ Enviar actualiza el último envío al momento actual para que la repetición
#   continúe desde ese instante, respetando fijado, botones, borrado anterior, etc.

try:
    from telegram.ext import ApplicationHandlerStop as _V100Stop
except Exception:
    _V100Stop = Exception


def _v100_now_ts() -> int:
    try:
        return int(time.time())
    except Exception:
        import time as _time
        return int(_time.time())


def _v100_mark_manual_start(row: Dict[str, Any]) -> None:
    """Hace que la próxima repetición cuente desde este envío manual."""
    now = _v100_now_ts()
    row['last_sent_ts'] = now
    row['manual_sent_ts'] = now
    sched = row.get('schedule') if isinstance(row.get('schedule'), dict) else {}
    stype = str(sched.get('type') or '')
    # Para horarios tipo inicio + cada Xh, saltamos la fase de esperar el inicio.
    if stype == 'start_interval':
        row['v69_started'] = True
        try:
            now_dt = _local_dt_v15(now) if '_local_dt_v15' in globals() else datetime.datetime.fromtimestamp(now)
            start_sched = sched.get('start') if isinstance(sched.get('start'), dict) else {}
            start_type = str(start_sched.get('type') or '')
            if start_type == 'daily':
                row['v69_start_day'] = now_dt.strftime('%Y-%m-%d')
            elif start_type == 'weekly':
                row['v69_start_week_key'] = f"{now_dt.strftime('%G-%V')}-{now_dt.weekday()}"
            elif start_type == 'date':
                row['v69_start_date_key'] = str(start_sched.get('date') or now_dt.strftime('%Y-%m-%d'))
        except Exception:
            pass


async def _v100_send_media_with_caption(bot, chat_id: int, media: Dict[str, Any], text: str, markup=None):
    fid = media.get('file_id')
    mtype = media.get('type')
    caption = (text or '').strip()[:1024] or None
    if mtype == 'photo':
        return await bot.send_photo(chat_id, photo=fid, caption=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
    if mtype == 'video':
        return await bot.send_video(chat_id, video=fid, caption=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
    if mtype == 'animation':
        return await bot.send_animation(chat_id, animation=fid, caption=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
    return await bot.send_document(chat_id, document=fid, caption=caption, parse_mode=ParseMode.HTML, reply_markup=markup)


_old_send_recurring_message_v100 = send_recurring_message
async def send_recurring_message(context, chat_id: int, row: Dict[str, Any]) -> Optional[int]:  # type: ignore[override]
    media = row.get('media') if isinstance(row.get('media'), dict) else None
    # Solo cambiamos el caso problemático: multimedia + fijado.
    if not (media and media.get('file_id') and bool(row.get('pin', False))):
        sent = await _old_send_recurring_message_v100(context, chat_id, row)
        if sent:
            # Asegura timestamp para repetición desde el envío real.
            row['last_sent_ts'] = _v100_now_ts()
            save_all_states()
        return sent

    text = str(row.get('text') or '').strip()
    previous_ids: List[int] = []
    if isinstance(row.get('last_message_ids'), list):
        previous_ids.extend([int(x) for x in row.get('last_message_ids') if x])
    if int(row.get('last_message_id') or 0):
        previous_ids.append(int(row.get('last_message_id')))
    delete_previous = bool(row.get('delete_previous', True))

    try:
        # Al estar fijado, la media debe llevar caption para que el fijado muestre miniatura + texto.
        markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
        msg = await _v100_send_media_with_caption(context.bot, chat_id, media, text, markup=markup)
        await register_bot_message(chat_id, msg.message_id)
        link = _v98_message_link(chat_id, msg.message_id) if '_v98_message_link' in globals() else (_message_link_v20(chat_id, msg.message_id) if '_message_link_v20' in globals() else '')
        # Si hay self-url en botones, actualizamos markup con enlace real.
        try:
            markup2 = _v98_markup_for_rec(row, self_url=link, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, self_url=link, chat_id=chat_id)
            if markup2:
                await context.bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=markup2)
        except Exception:
            pass
        row['last_message_id'] = int(msg.message_id)
        row['last_message_ids'] = [int(msg.message_id)]
        row['last_message_link'] = link
        row['delete_previous'] = delete_previous
        row['last_sent_ts'] = _v100_now_ts()
        save_all_states()
        try:
            await context.bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
        except Exception:
            pass
        if delete_previous:
            ids = [x for x in previous_ids if x != int(msg.message_id)]
            if '_v98_delete_message_ids' in globals():
                await _v98_delete_message_ids(context.bot, chat_id, ids)
            else:
                for mid in ids:
                    try: await safe_delete(context.bot, chat_id, mid)
                    except Exception: pass
        return int(msg.message_id)
    except Exception:
        logger.exception('No se pudo enviar recurrente multimedia fijado V100 %s en chat %s', row.get('id'), chat_id)
        return None


async def _v100_rec_send_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    if not data.startswith('cfg|rec_send|'):
        return
    parts = data.split('|')
    try:
        chat_id = int(parts[2]); rid = int(parts[3])
    except Exception:
        await q.answer('Recurrente inválido.', show_alert=True)
        raise _V100Stop
    try:
        if not await is_admin(context, chat_id, q.from_user.id):
            await q.answer('Solo administradores.', show_alert=True)
            raise _V100Stop
        row = recurring_find(chat_id, rid)
        if not row:
            await q.answer('No encuentro ese recurrente.', show_alert=True)
            raise _V100Stop
        # Marcar antes y después: si es start_interval, ya queda funcionando desde ahora.
        _v100_mark_manual_start(row)
        sent = await send_recurring_message(context, chat_id, row)
        _v100_mark_manual_start(row)
        save_all_states()
        await q.answer('Enviado ✅ Próxima repetición contará desde ahora.')
        try:
            await q.edit_message_text(recurring_detail_text(chat_id, rid), parse_mode=ParseMode.HTML, reply_markup=recurring_detail_markup(chat_id, rid))
        except Exception:
            pass
        raise _V100Stop
    except _V100Stop:
        raise
    except Exception:
        logger.exception('Error enviando recurrente manual V100: %s', data)
        try:
            await q.answer('Error al enviar. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V100Stop


_old_build_application_v100 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v100()
    app.add_handler(CallbackQueryHandler(_v100_rec_send_router, pattern=r'^cfg\|rec_send\|'), group=-10000050)
    logger.info('V100 recurrentes fijado con caption y envío manual reinicia repetición cargado')
    return app



# =========================================================
# V101 - Recurrentes con multimedia SIEMPRE en un solo mensaje
# =========================================================
# Telegram no permite poner texto por encima de una foto dentro del mismo mensaje:
# el texto de una foto/video/documento siempre es caption y va debajo.
# Por eso, cuando hay multimedia, enviamos SIEMPRE media + caption + botones en un único mensaje.
# Así, al fijarlo, Telegram muestra miniatura + texto y no aparecen dos mensajes separados.

_old_send_recurring_message_v101 = send_recurring_message
async def send_recurring_message(context, chat_id: int, row: Dict[str, Any]) -> Optional[int]:  # type: ignore[override]
    media = row.get('media') if isinstance(row.get('media'), dict) else None
    if not (media and media.get('file_id')):
        sent = await _old_send_recurring_message_v101(context, chat_id, row)
        if sent:
            try:
                row['last_sent_ts'] = _v100_now_ts() if '_v100_now_ts' in globals() else int(time.time())
                save_all_states()
            except Exception:
                pass
        return sent

    text = str(row.get('text') or '').strip()
    previous_ids: List[int] = []
    try:
        if isinstance(row.get('last_message_ids'), list):
            previous_ids.extend([int(x) for x in row.get('last_message_ids') if x])
        if int(row.get('last_message_id') or 0):
            previous_ids.append(int(row.get('last_message_id')))
    except Exception:
        pass
    delete_previous = bool(row.get('delete_previous', True))

    try:
        # Primer envío sin self_url real.
        markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
        msg = await _v100_send_media_with_caption(context.bot, chat_id, media, text, markup=markup)
        await register_bot_message(chat_id, msg.message_id)

        link = ''
        try:
            link = _v98_message_link(chat_id, msg.message_id) if '_v98_message_link' in globals() else (_message_link_v20(chat_id, msg.message_id) if '_message_link_v20' in globals() else '')
        except Exception:
            link = ''

        # Segundo paso: si algún botón usa self/auto, actualizamos el markup ya con enlace real.
        try:
            markup2 = _v98_markup_for_rec(row, self_url=link, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, self_url=link, chat_id=chat_id)
            if markup2:
                await context.bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=markup2)
        except Exception:
            pass

        row['last_message_id'] = int(msg.message_id)
        row['last_message_ids'] = [int(msg.message_id)]
        row['last_message_link'] = link
        row['delete_previous'] = delete_previous
        try:
            row['last_sent_ts'] = _v100_now_ts() if '_v100_now_ts' in globals() else int(time.time())
        except Exception:
            pass
        save_all_states()

        if bool(row.get('pin', False)):
            try:
                await context.bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
            except Exception:
                pass

        if delete_previous:
            ids = [x for x in previous_ids if x != int(msg.message_id)]
            if '_v98_delete_message_ids' in globals():
                await _v98_delete_message_ids(context.bot, chat_id, ids)
            else:
                for mid in ids:
                    try:
                        await safe_delete(context.bot, chat_id, mid)
                    except Exception:
                        pass
        return int(msg.message_id)
    except Exception:
        logger.exception('No se pudo enviar recurrente multimedia en un solo mensaje V101 %s en chat %s', row.get('id'), chat_id)
        return None


_old_recurring_detail_text_v101 = recurring_detail_text
def recurring_detail_text(chat_id: int, rid: int) -> str:  # type: ignore[override]
    txt = _old_recurring_detail_text_v101(chat_id, rid)
    row = recurring_find(chat_id, rid)
    media = row.get('media') if isinstance(row, dict) and isinstance(row.get('media'), dict) else None
    if media and media.get('file_id'):
        txt += "\n\nℹ️ Multimedia + texto se envían en <b>un solo mensaje</b>. En Telegram el texto de la foto/video siempre aparece como caption debajo."
    return txt


_old_build_application_v101 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v101()
    logger.info('V101 recurrentes multimedia en un solo mensaje cargado')
    return app



# =========================================================
# V102 - Recurrentes: "Texto arriba" en un solo mensaje para FOTOS
# =========================================================
# Limitación real de Telegram:
# - Una foto/video/documento con texto en el mismo mensaje usa caption y Telegram lo muestra debajo.
# - Para que visualmente el texto aparezca arriba y la foto abajo en UN solo mensaje,
#   se genera una imagen compuesta: texto arriba + foto debajo.
# - Esto se aplica solo a fotos. Vídeo/GIF/documento mantienen el formato Telegram: media + caption.

from io import BytesIO as _V102BytesIO
import re as _v102_re


def _v102_plain_text(html_text: str) -> str:
    txt = str(html_text or '')
    txt = _v102_re.sub(r'<br\s*/?>', '\n', txt, flags=_v102_re.I)
    txt = _v102_re.sub(r'</p\s*>', '\n', txt, flags=_v102_re.I)
    txt = _v102_re.sub(r'<[^>]+>', '', txt)
    try:
        import html as _html_v102
        txt = _html_v102.unescape(txt)
    except Exception:
        pass
    return txt.strip()


def _v102_wrap_text(draw, text: str, font, max_width: int) -> list[str]:
    lines: list[str] = []
    for para in (text or '').split('\n'):
        words = para.split()
        if not words:
            lines.append('')
            continue
        cur = ''
        for w in words:
            test = (cur + ' ' + w).strip()
            try:
                bbox = draw.textbbox((0, 0), test, font=font)
                width = bbox[2] - bbox[0]
            except Exception:
                width = len(test) * 12
            if width <= max_width or not cur:
                cur = test
            else:
                lines.append(cur)
                cur = w
        if cur:
            lines.append(cur)
    return lines


async def _v102_download_photo_as_image(bot, file_id: str):
    try:
        from PIL import Image
        f = await bot.get_file(file_id)
        data = await f.download_as_bytearray()
        img = Image.open(_V102BytesIO(bytes(data))).convert('RGB')
        return img
    except Exception:
        logger.exception('No se pudo descargar foto para composición V102')
        return None


def _v102_build_text_above_photo_image(photo_img, html_text: str):
    try:
        from PIL import Image, ImageDraw, ImageFont
        text = _v102_plain_text(html_text)
        if not text:
            return None
        max_w = 1080
        margin = 54
        bg_color = (255, 255, 255)
        fg_color = (20, 20, 20)
        # Redimensionar foto manteniendo proporción.
        w, h = photo_img.size
        if w > max_w:
            new_h = int(h * (max_w / w))
            photo_img = photo_img.resize((max_w, new_h))
        canvas_w = max(photo_img.width, 720)
        # Fuente interna del sistema, no se entrega al usuario.
        font_path_candidates = [
            '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
            '/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf',
        ]
        bold_path_candidates = [
            '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',
            '/usr/share/fonts/truetype/liberation2/LiberationSans-Bold.ttf',
        ]
        fp = next((p for p in font_path_candidates if Path(p).exists()), None)
        bp = next((p for p in bold_path_candidates if Path(p).exists()), fp)
        font = ImageFont.truetype(fp, 38) if fp else ImageFont.load_default()
        small = ImageFont.truetype(fp, 32) if fp else ImageFont.load_default()
        draw_probe = ImageDraw.Draw(Image.new('RGB', (canvas_w, 100), bg_color))
        lines = _v102_wrap_text(draw_probe, text, font, canvas_w - margin * 2)
        line_h = 48
        text_h = max(90, len(lines) * line_h + margin * 2)
        canvas_h = text_h + photo_img.height
        out = Image.new('RGB', (canvas_w, canvas_h), bg_color)
        draw = ImageDraw.Draw(out)
        y = margin
        for line in lines:
            draw.text((margin, y), line, fill=fg_color, font=font if line else small)
            y += line_h
        x_photo = (canvas_w - photo_img.width) // 2
        out.paste(photo_img, (x_photo, text_h))
        bio = _V102BytesIO()
        out.save(bio, format='JPEG', quality=92, optimize=True)
        bio.seek(0)
        bio.name = 'recurrente_texto_arriba.jpg'
        return bio
    except Exception:
        logger.exception('No se pudo crear imagen compuesta V102')
        return None


_old_send_recurring_message_v102 = send_recurring_message
async def send_recurring_message(context, chat_id: int, row: Dict[str, Any]) -> Optional[int]:  # type: ignore[override]
    media = row.get('media') if isinstance(row.get('media'), dict) else None
    text = str(row.get('text') or '').strip()
    pos = str(row.get('media_position') or row.get('rec_media_position') or 'above').lower()
    # Solo cuando el usuario pide texto arriba + multimedia abajo y es FOTO.
    # En Telegram puro eso no existe; aquí lo convertimos a una única imagen compuesta.
    if not (media and media.get('file_id') and media.get('type') == 'photo' and text and pos == 'below'):
        return await _old_send_recurring_message_v102(context, chat_id, row)

    previous_ids: List[int] = []
    try:
        if isinstance(row.get('last_message_ids'), list):
            previous_ids.extend([int(x) for x in row.get('last_message_ids') if x])
        if int(row.get('last_message_id') or 0):
            previous_ids.append(int(row.get('last_message_id')))
    except Exception:
        pass
    delete_previous = bool(row.get('delete_previous', True))

    try:
        photo = await _v102_download_photo_as_image(context.bot, str(media.get('file_id')))
        composed = _v102_build_text_above_photo_image(photo, text) if photo is not None else None
        if composed is None:
            # Fallback seguro: formato Telegram normal, caption debajo.
            return await _old_send_recurring_message_v102(context, chat_id, row)

        markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
        msg = await context.bot.send_photo(chat_id, photo=composed, reply_markup=markup)
        await register_bot_message(chat_id, msg.message_id)

        link = ''
        try:
            link = _v98_message_link(chat_id, msg.message_id) if '_v98_message_link' in globals() else (_message_link_v20(chat_id, msg.message_id) if '_message_link_v20' in globals() else '')
        except Exception:
            pass
        try:
            markup2 = _v98_markup_for_rec(row, self_url=link, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, self_url=link, chat_id=chat_id)
            if markup2:
                await context.bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=markup2)
        except Exception:
            pass

        row['last_message_id'] = int(msg.message_id)
        row['last_message_ids'] = [int(msg.message_id)]
        row['last_message_link'] = link
        row['delete_previous'] = delete_previous
        try:
            row['last_sent_ts'] = _v100_now_ts() if '_v100_now_ts' in globals() else int(time.time())
        except Exception:
            pass
        save_all_states()

        if bool(row.get('pin', False)):
            try:
                await context.bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
            except Exception:
                pass

        if delete_previous:
            ids = [x for x in previous_ids if x != int(msg.message_id)]
            if '_v98_delete_message_ids' in globals():
                await _v98_delete_message_ids(context.bot, chat_id, ids)
            else:
                for mid in ids:
                    try: await safe_delete(context.bot, chat_id, mid)
                    except Exception: pass
        return int(msg.message_id)
    except Exception:
        logger.exception('No se pudo enviar texto arriba + foto abajo V102 %s en chat %s', row.get('id'), chat_id)
        return await _old_send_recurring_message_v102(context, chat_id, row)


_old_recurring_detail_text_v102 = recurring_detail_text
def recurring_detail_text(chat_id: int, rid: int) -> str:  # type: ignore[override]
    txt = _old_recurring_detail_text_v102(chat_id, rid)
    row = recurring_find(chat_id, rid)
    media = row.get('media') if isinstance(row, dict) and isinstance(row.get('media'), dict) else None
    pos = str(row.get('media_position') or row.get('rec_media_position') or 'above').lower() if isinstance(row, dict) else 'above'
    if media and media.get('file_id') and pos == 'below':
        if media.get('type') == 'photo':
            txt += "\n\n✅ <b>Texto arriba</b>: se enviará como una sola imagen compuesta con el texto arriba y la foto abajo."
        else:
            txt += "\n\n⚠️ Telegram no permite texto arriba en un único mensaje con vídeo/GIF/documento. En esos casos el texto irá como caption debajo."
    return txt


_old_build_application_v102 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v102()
    logger.info('V102 recurrentes texto arriba + foto abajo en un solo mensaje cargado')
    return app


# =========================================================
# V103 - Recurrentes multimedia normal Telegram, sin imagen compuesta
# =========================================================
# Se elimina el experimento de V102 que creaba una foto compuesta con texto arriba,
# porque Telegram/pillow no preservaba bien emojis/fuentes y podía verse con cuadros.
# Regla final:
#   - Si hay multimedia: se envía como UN mensaje Telegram normal: media + caption + botones.
#   - Si está fijado: se fija ese mismo mensaje, por lo que arriba se ve miniatura + texto.
#   - No se crean dos mensajes y no se genera imagen compuesta.

async def send_recurring_message(context, chat_id: int, row: Dict[str, Any]) -> Optional[int]:  # type: ignore[override]
    media = row.get('media') if isinstance(row, dict) and isinstance(row.get('media'), dict) else None
    if not (media and media.get('file_id')):
        # Para recurrentes sin multimedia, usamos la lógica anterior completa.
        sent = await _old_send_recurring_message_v101(context, chat_id, row) if '_old_send_recurring_message_v101' in globals() else await _old_send_recurring_message_v102(context, chat_id, row)
        if sent:
            try:
                row['last_sent_ts'] = _v100_now_ts() if '_v100_now_ts' in globals() else int(time.time())
                save_all_states()
            except Exception:
                pass
        return sent

    text = str(row.get('text') or '').strip()
    previous_ids: List[int] = []
    try:
        if isinstance(row.get('last_message_ids'), list):
            previous_ids.extend([int(x) for x in row.get('last_message_ids') if x])
        if int(row.get('last_message_id') or 0):
            previous_ids.append(int(row.get('last_message_id')))
    except Exception:
        pass
    delete_previous = bool(row.get('delete_previous', True))

    try:
        markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
        # Formato Telegram normal. Aunque el usuario tenga "texto arriba" marcado,
        # Telegram solo permite caption debajo en el mismo mensaje; no componemos imagen.
        msg = await _v100_send_media_with_caption(context.bot, chat_id, media, text, markup=markup)
        await register_bot_message(chat_id, msg.message_id)

        link = ''
        try:
            link = _v98_message_link(chat_id, msg.message_id) if '_v98_message_link' in globals() else (_message_link_v20(chat_id, msg.message_id) if '_message_link_v20' in globals() else '')
        except Exception:
            pass

        try:
            markup2 = _v98_markup_for_rec(row, self_url=link, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, self_url=link, chat_id=chat_id)
            if markup2:
                await context.bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=markup2)
        except Exception:
            pass

        row['last_message_id'] = int(msg.message_id)
        row['last_message_ids'] = [int(msg.message_id)]
        row['last_message_link'] = link
        row['delete_previous'] = delete_previous
        row['last_sent_ts'] = _v100_now_ts() if '_v100_now_ts' in globals() else int(time.time())
        save_all_states()

        if bool(row.get('pin', False)):
            try:
                await context.bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
            except Exception:
                pass

        if delete_previous:
            ids = [x for x in previous_ids if x != int(msg.message_id)]
            if '_v98_delete_message_ids' in globals():
                await _v98_delete_message_ids(context.bot, chat_id, ids)
            else:
                for mid in ids:
                    try:
                        await safe_delete(context.bot, chat_id, mid)
                    except Exception:
                        pass
        return int(msg.message_id)
    except Exception:
        logger.exception('No se pudo enviar recurrente multimedia normal V103 %s en chat %s', row.get('id'), chat_id)
        return None


_old_recurring_detail_text_v103 = recurring_detail_text
def recurring_detail_text(chat_id: int, rid: int) -> str:  # type: ignore[override]
    txt = _old_recurring_detail_text_v103(chat_id, rid)
    row = recurring_find(chat_id, rid)
    media = row.get('media') if isinstance(row, dict) and isinstance(row.get('media'), dict) else None
    if media and media.get('file_id'):
        txt += "\n\n✅ <b>Modo normal restaurado</b>: el recurrente se enviará como multimedia + texto/caption en un solo mensaje. Así, al fijarlo, Telegram muestra miniatura + texto."
    return txt


_old_build_application_v103 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v103()
    logger.info('V103 recurrentes multimedia normal Telegram restaurado')
    return app


# =========================================================
# V104 - Recurrentes multimedia con modo visual configurable
# =========================================================
# Telegram no permite dentro de UN mensaje nativo: texto arriba + foto abajo.
# Por eso damos 5 modos claros:
#   caption      = un mensaje: multimedia + texto/caption + botones (ideal para fijado con miniatura+texto)
#   media_above  = dos mensajes: multimedia y luego texto+botones
#   text_above   = dos mensajes: texto y luego multimedia+botones
#   media_only   = solo multimedia+botones, sin texto
#   text_only    = solo texto+botones, sin multimedia

try:
    from telegram.ext import ApplicationHandlerStop as _V104Stop
except Exception:
    _V104Stop = Exception


def _v104_layout(row: Dict[str, Any]) -> str:
    layout = str(row.get('media_layout') or row.get('rec_media_layout') or '').strip().lower()
    if layout in {'caption','media_above','text_above','media_only','text_only'}:
        return layout
    # Compatibilidad con los botones antiguos de arriba/abajo.
    pos = str(row.get('media_position') or row.get('rec_media_position') or 'above').lower()
    return 'text_above' if pos == 'below' else 'media_above'


def _v104_layout_label(layout: str) -> str:
    return {
        'caption': '1 mensaje: multimedia + texto/caption',
        'media_above': '2 mensajes: multimedia arriba y texto abajo',
        'text_above': '2 mensajes: texto arriba y multimedia abajo',
        'media_only': 'solo multimedia, sin texto',
        'text_only': 'solo texto, sin multimedia',
    }.get(layout, layout)


async def _v104_send_media_caption(bot, chat_id: int, media: Dict[str, Any], text: str, markup=None):
    fid = media.get('file_id')
    mtype = media.get('type')
    caption = text or None
    if mtype == 'photo':
        return await bot.send_photo(chat_id, photo=fid, caption=caption, parse_mode=ParseMode.HTML if caption else None, reply_markup=markup)
    if mtype == 'video':
        return await bot.send_video(chat_id, video=fid, caption=caption, parse_mode=ParseMode.HTML if caption else None, reply_markup=markup)
    if mtype == 'animation':
        return await bot.send_animation(chat_id, animation=fid, caption=caption, parse_mode=ParseMode.HTML if caption else None, reply_markup=markup)
    return await bot.send_document(chat_id, document=fid, caption=caption, parse_mode=ParseMode.HTML if caption else None, reply_markup=markup)


async def _v104_send_media_only(bot, chat_id: int, media: Dict[str, Any], markup=None):
    fid = media.get('file_id')
    mtype = media.get('type')
    if mtype == 'photo':
        return await bot.send_photo(chat_id, photo=fid, reply_markup=markup)
    if mtype == 'video':
        return await bot.send_video(chat_id, video=fid, reply_markup=markup)
    if mtype == 'animation':
        return await bot.send_animation(chat_id, animation=fid, reply_markup=markup)
    return await bot.send_document(chat_id, document=fid, reply_markup=markup)


async def _v104_send_text(bot, chat_id: int, text: str, markup=None):
    return await bot.send_message(chat_id, text=text or ' ', parse_mode=ParseMode.HTML, reply_markup=markup, disable_web_page_preview=True)


async def send_recurring_message(context, chat_id: int, row: Dict[str, Any]) -> Optional[int]:  # type: ignore[override]
    media = row.get('media') if isinstance(row, dict) and isinstance(row.get('media'), dict) else None
    text = str(row.get('text') or '').strip()
    layout = _v104_layout(row)

    # Sin multimedia o modo solo texto: usa texto normal.
    if not media or not media.get('file_id') or layout == 'text_only':
        previous_ids: List[int] = []
        try:
            if isinstance(row.get('last_message_ids'), list):
                previous_ids.extend([int(x) for x in row.get('last_message_ids') if x])
            if int(row.get('last_message_id') or 0):
                previous_ids.append(int(row.get('last_message_id')))
        except Exception:
            pass
        delete_previous = bool(row.get('delete_previous', True))
        try:
            markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
            msg = await _v104_send_text(context.bot, chat_id, text or ' ', markup=markup)
            await register_bot_message(chat_id, msg.message_id)
            link = _v98_message_link(chat_id, msg.message_id) if '_v98_message_link' in globals() else ''
            try:
                markup2 = _v98_markup_for_rec(row, self_url=link, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, self_url=link, chat_id=chat_id)
                if markup2:
                    await context.bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=markup2)
            except Exception:
                pass
            row['last_message_id'] = int(msg.message_id)
            row['last_message_ids'] = [int(msg.message_id)]
            row['last_message_link'] = link
            row['last_sent_ts'] = _v100_now_ts() if '_v100_now_ts' in globals() else int(time.time())
            save_all_states()
            if bool(row.get('pin', False)):
                try: await context.bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
                except Exception: pass
            if delete_previous:
                if '_v98_delete_message_ids' in globals():
                    await _v98_delete_message_ids(context.bot, chat_id, [x for x in previous_ids if x != int(msg.message_id)])
                else:
                    for mid in previous_ids:
                        if mid != int(msg.message_id):
                            try: await safe_delete(context.bot, chat_id, mid)
                            except Exception: pass
            return int(msg.message_id)
        except Exception:
            logger.exception('No se pudo enviar recurrente texto V104 %s en chat %s', row.get('id'), chat_id)
            return None

    previous_ids: List[int] = []
    try:
        if isinstance(row.get('last_message_ids'), list):
            previous_ids.extend([int(x) for x in row.get('last_message_ids') if x])
        if int(row.get('last_message_id') or 0):
            previous_ids.append(int(row.get('last_message_id')))
    except Exception:
        pass
    delete_previous = bool(row.get('delete_previous', True))
    sent_ids: List[int] = []
    main_msg = None
    pin_id = None

    try:
        if layout == 'caption':
            # Un único mensaje. Es el único modo que Telegram muestra arriba como miniatura + texto al fijar.
            markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
            msg = await _v104_send_media_caption(context.bot, chat_id, media, text, markup=markup)
            main_msg = msg
            sent_ids.append(int(msg.message_id))
            await register_bot_message(chat_id, msg.message_id)
            link = _v98_message_link(chat_id, msg.message_id) if '_v98_message_link' in globals() else ''
            try:
                markup2 = _v98_markup_for_rec(row, self_url=link, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, self_url=link, chat_id=chat_id)
                if markup2:
                    await context.bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=markup2)
            except Exception:
                pass
            pin_id = int(msg.message_id)
        elif layout == 'media_only':
            markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
            msg = await _v104_send_media_only(context.bot, chat_id, media, markup=markup)
            main_msg = msg
            sent_ids.append(int(msg.message_id))
            await register_bot_message(chat_id, msg.message_id)
            pin_id = int(msg.message_id)
        elif layout == 'media_above':
            media_msg = await _v104_send_media_only(context.bot, chat_id, media)
            sent_ids.append(int(media_msg.message_id)); await register_bot_message(chat_id, media_msg.message_id)
            if text:
                markup = _v98_markup_for_rec(row, self_url=_v98_message_link(chat_id, media_msg.message_id) if '_v98_message_link' in globals() else None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
                txt_msg = await _v104_send_text(context.bot, chat_id, text, markup=markup)
                sent_ids.append(int(txt_msg.message_id)); await register_bot_message(chat_id, txt_msg.message_id)
                main_msg = txt_msg
                # Si se fija, fijamos el texto para que no salga solo "Foto".
                pin_id = int(txt_msg.message_id)
            else:
                main_msg = media_msg
                pin_id = int(media_msg.message_id)
                markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
                if markup:
                    try: await context.bot.edit_message_reply_markup(chat_id=chat_id, message_id=media_msg.message_id, reply_markup=markup)
                    except Exception: pass
        else:  # text_above
            if text:
                txt_msg = await _v104_send_text(context.bot, chat_id, text)
                sent_ids.append(int(txt_msg.message_id)); await register_bot_message(chat_id, txt_msg.message_id)
                markup = _v98_markup_for_rec(row, self_url=_v98_message_link(chat_id, txt_msg.message_id) if '_v98_message_link' in globals() else None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
                media_msg = await _v104_send_media_only(context.bot, chat_id, media, markup=markup)
                sent_ids.append(int(media_msg.message_id)); await register_bot_message(chat_id, media_msg.message_id)
                main_msg = media_msg
                # Si se fija, fijamos el texto para que se vea el texto y no solo "Foto".
                pin_id = int(txt_msg.message_id)
            else:
                markup = _v98_markup_for_rec(row, self_url=None, chat_id=chat_id) if '_v98_markup_for_rec' in globals() else recurring_buttons_markup(row, chat_id=chat_id)
                media_msg = await _v104_send_media_only(context.bot, chat_id, media, markup=markup)
                sent_ids.append(int(media_msg.message_id)); await register_bot_message(chat_id, media_msg.message_id)
                main_msg = media_msg
                pin_id = int(media_msg.message_id)

        if main_msg is None:
            return None
        row['last_message_id'] = int(main_msg.message_id)
        row['last_message_ids'] = sent_ids
        try:
            row['last_message_link'] = _v98_message_link(chat_id, int(main_msg.message_id)) if '_v98_message_link' in globals() else ''
        except Exception:
            row['last_message_link'] = ''
        row['last_sent_ts'] = _v100_now_ts() if '_v100_now_ts' in globals() else int(time.time())
        save_all_states()

        if bool(row.get('pin', False)) and pin_id:
            try: await context.bot.pin_chat_message(chat_id, int(pin_id), disable_notification=True)
            except Exception: pass
        if delete_previous:
            ids = [x for x in previous_ids if x not in sent_ids]
            if '_v98_delete_message_ids' in globals():
                await _v98_delete_message_ids(context.bot, chat_id, ids)
            else:
                for mid in ids:
                    try: await safe_delete(context.bot, chat_id, mid)
                    except Exception: pass
        return int(main_msg.message_id)
    except Exception:
        logger.exception('No se pudo enviar recurrente multimedia V104 %s en chat %s', row.get('id'), chat_id)
        return None


_old_recurring_detail_text_v104 = recurring_detail_text
def recurring_detail_text(chat_id: int, rid: int) -> str:  # type: ignore[override]
    txt = _old_recurring_detail_text_v104(chat_id, rid)
    row = recurring_find(chat_id, rid)
    if isinstance(row, dict) and isinstance(row.get('media'), dict) and row.get('media', {}).get('file_id'):
        layout = _v104_layout(row)
        txt += f"\n\n📐 Formato multimedia: <b>{h(_v104_layout_label(layout))}</b>"
        if layout != 'caption' and bool(row.get('pin', False)):
            txt += "\n⚠️ Si quieres que el fijado muestre miniatura + texto juntos, usa el modo <b>1 mensaje: multimedia + texto/caption</b>."
    return txt


_old_recurring_detail_markup_v104 = recurring_detail_markup
def recurring_detail_markup(chat_id: int, rid: int) -> InlineKeyboardMarkup:  # type: ignore[override]
    markup = _old_recurring_detail_markup_v104(chat_id, rid)
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', []) or []]
    row = recurring_find(chat_id, rid) or {}
    if isinstance(row.get('media'), dict) and row.get('media', {}).get('file_id'):
        insert_at = max(0, len(rows) - 1)
        layout = _v104_layout(row)
        rows.insert(insert_at, [InlineKeyboardButton('📐 Formato multimedia', callback_data=f'cfg|rec_media_layout_menu|{chat_id}|{rid}')])
        # Evita confusión con botones antiguos de arriba/abajo si siguen apareciendo.
        # Los dejamos, pero el menú nuevo manda.
    return InlineKeyboardMarkup(rows)


def _v104_layout_menu(chat_id: int, rid: int) -> InlineKeyboardMarkup:
    row = recurring_find(chat_id, rid) or {}
    current = _v104_layout(row)
    opts = [
        ('caption', '📌 1 mensaje: multimedia + texto/caption'),
        ('media_above', '🖼 Multimedia arriba + texto abajo'),
        ('text_above', '📝 Texto arriba + multimedia abajo'),
        ('media_only', '🚫 Solo multimedia, sin texto'),
        ('text_only', '📝 Solo texto, sin multimedia'),
    ]
    rows = []
    for key, label in opts:
        rows.append([InlineKeyboardButton(('✅ ' if key == current else '') + label, callback_data=f'cfg|rec_media_layout_set|{chat_id}|{rid}|{key}')])
    rows.append([InlineKeyboardButton('🔙 Volver al recurrente', callback_data=f'cfg|rec_edit|{chat_id}|{rid}|recurrentes')])
    return InlineKeyboardMarkup(rows)


async def _v104_recurrente_layout_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    parts = data.split('|')
    try:
        action = parts[1]
    except Exception:
        return
    if action not in {'rec_media_layout_menu', 'rec_media_layout_set'}:
        return
    try:
        chat_id = int(parts[2]); rid = int(parts[3])
        row = recurring_find(chat_id, rid)
        if not row:
            await q.answer('No encuentro ese recurrente.', show_alert=True)
            raise _V104Stop
        if action == 'rec_media_layout_menu':
            await q.answer('Formato multimedia')
            await q.edit_message_text(
                '<b>📐 Formato multimedia</b>\n\n'
                'Elige cómo quieres que se publique este recurrente.\n\n'
                'Para que el <b>mensaje fijado</b> muestre miniatura + texto juntos, usa el modo de 1 mensaje/caption.\n'
                'Para ver texto y multimedia separados en el chat, usa los modos de 2 mensajes.',
                parse_mode=ParseMode.HTML,
                reply_markup=_v104_layout_menu(chat_id, rid),
            )
            raise _V104Stop
        layout = parts[4]
        if layout not in {'caption','media_above','text_above','media_only','text_only'}:
            await q.answer('Formato no válido', show_alert=True)
            raise _V104Stop
        row['media_layout'] = layout
        # Compatibilidad con la marca antigua.
        if layout == 'text_above':
            row['media_position'] = 'below'
        elif layout == 'media_above':
            row['media_position'] = 'above'
        save_all_states()
        await q.answer('Formato guardado ✅')
        await q.edit_message_text(recurring_detail_text(chat_id, rid), parse_mode=ParseMode.HTML, reply_markup=recurring_detail_markup(chat_id, rid))
        raise _V104Stop
    except _V104Stop:
        raise
    except Exception:
        logger.exception('Error formato multimedia recurrente V104: %s', data)
        try: await q.answer('Error. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V104Stop


_old_build_application_v104 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v104()
    app.add_handler(CallbackQueryHandler(_v104_recurrente_layout_callback, pattern=r'^cfg\|rec_media_layout_'), group=-9000000)
    logger.info('V104 recurrentes multimedia con modos visuales configurables cargado')
    return app


# =========================================================
# V105 - DJ botones abren mesa + no borrar otros fijados/mensajes
# =========================================================
# - Repara callbacks de MODO DJ FÁCIL y MODO DJ-PRO con prioridad máxima.
# - DJ no usa limpiezas agresivas que borraban otros mensajes/pines del bot.
# - ensure_panel solo edita/crea el panel DJ, no hace limpieza global.

try:
    from telegram.ext import ApplicationHandlerStop as _V105Stop
except Exception:
    _V105Stop = Exception


def _v105_admin_cfg(chat_id: int) -> Dict[str, Any]:
    try:
        return admin_cfg(chat_id)
    except Exception:
        return get_state(chat_id).admin_config


def _v105_session_mode(chat_id: int) -> str:
    try:
        return str(_v75_session_mode(chat_id) or _v105_admin_cfg(chat_id).get('dj_session_mode') or '').lower()
    except Exception:
        return str(_v105_admin_cfg(chat_id).get('dj_session_mode') or '').lower()


def _v105_set_mode(chat_id: int, mode: str) -> None:
    try:
        _v75_set_mode(chat_id, mode)
    except Exception:
        _v105_admin_cfg(chat_id)['dj_session_mode'] = mode
    save_all_states()


def _v105_current_next(chat_id: int) -> tuple[str, str]:
    try:
        if '_v75_current_next' in globals():
            return _v75_current_next(chat_id)
    except Exception:
        pass
    state = get_state(chat_id)
    now = 'Nada sonando'
    nxt = 'Nada en cola'
    try:
        if state.now_playing:
            now = shorten_title(Track(**state.now_playing).title, 42)
        if state.queue:
            nxt = shorten_title(Track(**state.queue[0]).title, 42)
    except Exception:
        pass
    return now, nxt


