async def _v105_show_easy_panel(q, context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    try:
        await q.edit_message_text(_v105_easy_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v105_easy_markup())
    except Exception:
        msg = await context.bot.send_message(chat_id, _v105_easy_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v105_easy_markup())
        try:
            await register_bot_message(chat_id, msg.message_id)
        except Exception:
            pass


async def _v105_user_can_easy(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user) -> bool:
    if '_v72_dj_role_allowed' in globals():
        try:
            return await _v72_dj_role_allowed(context, chat_id, user, 'easy')
        except Exception:
            logger.exception('Error comprobando permiso DJ Fácil')
    try:
        return await is_controller(context, chat_id, int(user.id))
    except Exception:
        return False


async def _v105_user_can_pro(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user) -> bool:
    if '_v72_dj_role_allowed' in globals():
        try:
            return await _v72_dj_role_allowed(context, chat_id, user, 'big')
        except Exception:
            logger.exception('Error comprobando permiso DJ-PRO')
    try:
        return await is_controller(context, chat_id, int(user.id))
    except Exception:
        return False


async def _v105_modes_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'dj_easy_menu', 'menu_panel'}:
        return
    chat_id = int(update.effective_chat.id)
    user = update.effective_user
    state = get_state(chat_id)
    if data == 'dj_easy_menu':
        if not await _v105_user_can_easy(context, chat_id, user):
            await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
            raise _V105Stop
        state.dj_mode = True
        state.assigned_dj_id = int(user.id)
        state.assigned_dj_name = display_name(user)
        _v105_set_mode(chat_id, 'easy')
        # No crear mesa PRO ni hacer limpiezas agresivas.
        save_all_states()
        await q.answer('DJ Fácil abierto ✅')
        await _v105_show_easy_panel(q, context, chat_id)
        try:
            await ensure_panel(context.bot, chat_id)
        except Exception:
            logger.exception('No se pudo asegurar panel fijado DJ Fácil')
        raise _V105Stop

    if data == 'menu_panel':
        if not await _v105_user_can_pro(context, chat_id, user):
            await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
            raise _V105Stop
        state.dj_mode = True
        if state.assigned_dj_id is None:
            state.assigned_dj_id = int(user.id)
            state.assigned_dj_name = display_name(user)
        _v105_set_mode(chat_id, 'pro')
        save_all_states()
        await q.answer('Mesa DJ-PRO abierta ✅')
        try:
            # Mostrar mesa PRO completa.
            await ensure_panel(context.bot, chat_id)
            await ensure_control_panel(context.bot, chat_id)
        except Exception:
            logger.exception('No se pudo abrir mesa DJ-PRO')
            await context.bot.send_message(chat_id, '❌ No pude abrir la mesa DJ-PRO. Revisa logs.')
        raise _V105Stop


# Reforzar acciones internas DJ Fácil para no abrir mesa PRO.
async def _v105_easy_actions_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'dj_easy_start', 'dj_easy_next', 'dj_easy_close', 'dj_easy_info'} and not data.startswith('dj_timer|easy'):
        return
    chat_id = int(update.effective_chat.id)
    user = update.effective_user
    state = get_state(chat_id)
    if not await _v105_user_can_easy(context, chat_id, user):
        await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
        raise _V105Stop
    if data == 'dj_easy_info':
        await q.answer('Instrucciones')
        await q.edit_message_text(
            '<b>ℹ️ Abrir videochat manualmente</b>\n\n'
            '1. Pulsa arriba en el <b>nombre del grupo</b>.\n'
            '2. Entra en <b>Videochat / Directo</b>.\n'
            '3. Vuelve aquí y pulsa reproducir.',
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 Volver DJ Fácil', callback_data='dj_easy_menu')]])
        )
        raise _V105Stop
    if data.startswith('dj_timer|easy'):
        try:
            hours = int(data.split('|')[2])
        except Exception:
            hours = 0
        if hours <= 0:
            if '_v75_cancel_timer' in globals(): _v75_cancel_timer(chat_id)
            await q.answer('Temporizador quitado ✅', show_alert=True)
        else:
            if '_v75_set_timer' in globals(): _v75_set_timer(context.bot, chat_id, hours, 'easy')
            await q.answer(f'DJ Fácil se cerrará en {hours}h ✅', show_alert=True)
        await _v105_show_easy_panel(q, context, chat_id)
        await ensure_panel(context.bot, chat_id)
        raise _V105Stop
    if data == 'dj_easy_start':
        if not state.library:
            await q.answer('La biblioteca está vacía.', show_alert=True)
            raise _V105Stop
        items = [dict(x) for x in state.library]
        try:
            import random as _r105
            _r105.shuffle(items)
        except Exception:
            pass
        state.queue = dedupe_track_items(items)
        state.dj_mode = True
        state.assigned_dj_id = int(user.id)
        state.assigned_dj_name = display_name(user)
        state.dj_shuffle_enabled = True
        state.auto_track_enabled = True
        state.auto_sig_seconds = 0
        _v105_set_mode(chat_id, 'easy')
        _v105_admin_cfg(chat_id)['dj_announce_now_enabled'] = False
        save_all_states()
        try:
            await _dj_open_or_explain_live_v29(context, chat_id, start_call=True)
        except Exception:
            logger.exception('No se pudo abrir directo en DJ Fácil')
        try:
            if not state.now_playing:
                await simulate_panel_next(chat_id, reason='dj_easy_start')
        except Exception:
            logger.exception('No se pudo iniciar primera canción DJ Fácil')
        await q.answer('DJ Fácil iniciado ✅', show_alert=True)
        await _v105_show_easy_panel(q, context, chat_id)
        await ensure_panel(context.bot, chat_id)
        raise _V105Stop
    if data == 'dj_easy_next':
        if not state.dj_mode:
            await q.answer('DJ Fácil no está activo.', show_alert=True)
            raise _V105Stop
        await simulate_panel_next(chat_id, reason='dj_easy_next')
        await q.answer('Siguiente canción ✅')
        await _v105_show_easy_panel(q, context, chat_id)
        await ensure_panel(context.bot, chat_id)
        raise _V105Stop
    if data == 'dj_easy_close':
        await q.answer('Cerrando DJ Fácil…')
        if '_v75_cancel_timer' in globals():
            _v75_cancel_timer(chat_id)
        try:
            await close_dj_session(context.bot, chat_id)
        except Exception:
            logger.exception('Error cerrando DJ Fácil')
        try:
            await q.edit_message_text('🎧 DJ Fácil cerrado ✅')
        except Exception:
            pass
        raise _V105Stop


_old_build_application_v105 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v105()
    app.add_handler(CallbackQueryHandler(_v105_modes_router, pattern=r'^(dj_easy_menu|menu_panel)$'), group=-5000000)
    app.add_handler(CallbackQueryHandler(_v105_easy_actions_router, pattern=r'^(dj_easy_start|dj_easy_next|dj_easy_close|dj_easy_info|dj_timer\|easy\|)'), group=-5000000)
    logger.info('V105 DJ botones reparados y limpieza no agresiva de fijados cargada')
    return app



# =========================================================
# V106 - DJ definitivo estable: sin duplicados, permisos separados y privado robusto
# =========================================================
# Objetivo: dejar el modo DJ estable tanto en grupo como en privado.
# - Los botones MODO DJ FÁCIL y MODO DJ-PRO entran con prioridad máxima.
# - DJ Fácil nunca abre la mesa PRO.
# - DJ-PRO abre/edita una única mesa completa.
# - Cargar listas y añadir recientes no duplica cola.
# - Las limpiezas DJ no borran mensajes/fijados de otros módulos.
# - El panel fijado DJ se edita si existe; solo crea uno si se perdió.

try:
    from telegram.ext import ApplicationHandlerStop as _V106Stop
except Exception:
    _V106Stop = Exception


def _v106_cfg(chat_id: int) -> Dict[str, Any]:
    try:
        return admin_cfg(chat_id)
    except Exception:
        return get_state(chat_id).admin_config


def _v106_mode(chat_id: int) -> str:
    try:
        mode = str(_v75_session_mode(chat_id) or '').strip().lower()
        if mode:
            return mode
    except Exception:
        pass
    return str(_v106_cfg(chat_id).get('dj_session_mode') or '').strip().lower()


def _v106_set_mode(chat_id: int, mode: str) -> None:
    mode = 'easy' if str(mode).lower().startswith('easy') else 'pro'
    try:
        _v75_set_mode(chat_id, mode)
    except Exception:
        _v106_cfg(chat_id)['dj_session_mode'] = mode
    save_all_states()


def _v106_now_next(chat_id: int) -> tuple[str, str]:
    state = get_state(chat_id)
    now = 'Nada sonando'
    nxt = 'Nada en cola'
    try:
        if state.now_playing:
            now = shorten_title(Track(**state.now_playing).title, 42)
        if state.queue:
            nxt = shorten_title(Track(**state.queue[0]).title, 42)
    except Exception:
        pass
    return now, nxt


def _v106_timer_label(chat_id: int) -> str:
    try:
        return _v75_timer_label(chat_id)
    except Exception:
        return 'OFF'


def main_menu_markup() -> InlineKeyboardMarkup:  # type: ignore[override]
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('🎧 MODO DJ FÁCIL', callback_data='dj_easy_menu')],
        [InlineKeyboardButton('🎛 MODO DJ-PRO', callback_data='menu_panel')],
    ])


def _v106_panel_markup(chat_id: int) -> InlineKeyboardMarkup:
    if _v106_mode(chat_id) == 'easy':
        main = InlineKeyboardButton('🎧 DJ Fácil', callback_data='dj_easy_menu')
    else:
        main = InlineKeyboardButton('🎛 Mesa DJ-PRO', callback_data='menu_panel')
    return InlineKeyboardMarkup([[main, InlineKeyboardButton('❤️ Me gusta', callback_data='djlike|current')]])


async def ensure_panel(bot, chat_id: int) -> None:  # type: ignore[override]
    """Panel fijado DJ estable.

    Edita el panel existente. Si se perdió, crea uno nuevo. No borra ni desfija
    mensajes de recurrentes, impostor, frase del día u otros módulos.
    """
    async with get_chat_lock(PANEL_LOCKS, chat_id):
        state = get_state(chat_id)
        if not state.dj_mode:
            return
        text = panel_text(state)
        markup = _v106_panel_markup(chat_id)
        old_id = int(state.panel_message_id or 0)
        if old_id:
            try:
                await bot.edit_message_text(chat_id=chat_id, message_id=old_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
                return
            except BadRequest as e:
                msg = str(e).lower()
                if 'message is not modified' in msg:
                    return
                if 'message to edit not found' in msg or 'message not found' in msg:
                    state.panel_message_id = None
                    save_all_states()
                else:
                    logger.warning('Panel DJ no editado; no creo duplicado para evitar spam: %s', e)
                    return
            except Exception:
                logger.exception('Fallo temporal editando panel DJ; no creo duplicado para evitar spam')
                return
        sent = await bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
        state.panel_message_id = int(sent.message_id)
        save_all_states()
        try:
            await register_bot_message(chat_id, sent.message_id)
        except Exception:
            pass
        try:
            await bot.pin_chat_message(chat_id=chat_id, message_id=sent.message_id, disable_notification=True)
        except Exception:
            logger.warning('No se pudo fijar el panel DJ; sigo sin tocar otros fijados')


async def cleanup_all_bot_messages(bot, chat_id: int) -> None:  # type: ignore[override]
    """Limpieza DJ segura: solo temporales registrados, nunca bot_message_ids global."""
    state = get_state(chat_id)
    keep = {int(x) for x in [state.panel_message_id, state.control_message_id, state.temp_pin_message_id] if x}
    for mid in list(state.temp_message_ids):
        if int(mid) not in keep:
            try:
                await safe_delete(bot, chat_id, int(mid))
            except Exception:
                pass
    state.temp_message_ids = [int(x) for x in state.temp_message_ids if int(x) in keep]
    save_all_states()


async def cleanup_bot_messages_keep_core(bot, chat_id: int) -> None:  # type: ignore[override]
    return await cleanup_all_bot_messages(bot, chat_id)


async def enforce_single_core_messages(bot, chat_id: int) -> None:  # type: ignore[override]
    # Desactivado a propósito: versiones antiguas borraban pines/mensajes de otros módulos.
    return


async def close_dj_session(bot, chat_id: int) -> None:  # type: ignore[override]
    """Cierre DJ seguro, sin tocar fijados ajenos."""
    try:
        if '_v75_cancel_timer' in globals():
            _v75_cancel_timer(chat_id)
    except Exception:
        pass
    state = get_state(chat_id)
    try:
        await cancel_temporary_pin(chat_id)
    except Exception:
        pass
    try:
        await cancel_auto_next(chat_id)
    except Exception:
        pass
    task = SCAN_TASKS.pop(chat_id, None)
    if task and not task.done():
        task.cancel()
    panel_id = int(state.panel_message_id or 0)
    control_id = int(state.control_message_id or 0)
    state.dj_mode = False
    state.live_enabled = False
    state.now_playing = None
    state.paused = False
    state.play_started_at = None
    state.paused_remaining = None
    state.panel_message_id = None
    state.control_message_id = None
    _v106_cfg(chat_id)['dj_session_mode'] = ''
    save_all_states()
    try:
        await VOICE.leave(chat_id, end_videochat=True)
    except Exception:
        logger.exception('No se pudo salir/cerrar videochat DJ')
    # Solo paneles DJ propios. No bot_message_ids global ni otros pines.
    for mid in [control_id, panel_id]:
        if mid:
            try:
                await safe_delete(bot, chat_id, mid)
            except Exception:
                pass
    try:
        await cleanup_track_controls(bot, chat_id)
    except Exception:
        pass
    TRACK_CONTROL_REGISTRY.pop(chat_id, None)
    for key in list(PENDING_ACTIONS.keys()):
        if key.startswith(f'{chat_id}:'):
            PENDING_ACTIONS.pop(key, None)
    save_all_states()


async def _v106_user_can(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, mode: str) -> bool:
    try:
        if '_v72_dj_role_allowed' in globals():
            return await _v72_dj_role_allowed(context, chat_id, user, 'easy' if mode == 'easy' else 'big')
    except Exception:
        logger.exception('Error comprobando permisos DJ %s', mode)
    try:
        return await is_controller(context, chat_id, int(user.id))
    except Exception:
        return False


def _v106_easy_text(chat_id: int) -> str:
    state = get_state(chat_id)
    now, nxt = _v106_now_next(chat_id)
    return (
        '<b>🎧 MODO DJ FÁCIL</b>\n\n'
        f'▶️ Sonando: <b>{h(now)}</b>\n'
        f'⏭ Próxima: <b>{h(nxt)}</b>\n'
        f'📚 Biblioteca: <b>{len(state.library)}</b> canciones\n'
        f'📋 Cola: <b>{len(state.queue)}</b>\n'
        f'🎧 DJ actual: <b>{h(state.assigned_dj_name or "Sin asignar")}</b>\n'
        f'⏱ Temporizador: <b>{h(_v106_timer_label(chat_id))}</b>\n\n'
        'Pulsa <b>▶️ Reproducir biblioteca</b>.\n'
        'Si no se abre el directo, entra manualmente desde el nombre del grupo → Videochat.'
    )


def _v106_easy_markup() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('▶️ Reproducir biblioteca', callback_data='dj_easy_start')],
        [InlineKeyboardButton('⏭ Siguiente canción', callback_data='dj_easy_next'), InlineKeyboardButton('❌ Cerrar DJ Fácil', callback_data='dj_easy_close')],
        [InlineKeyboardButton('⏱ 1h', callback_data='dj_timer|easy|1'), InlineKeyboardButton('⏱ 2h', callback_data='dj_timer|easy|2'), InlineKeyboardButton('⏱ 3h', callback_data='dj_timer|easy|3'), InlineKeyboardButton('⏱ OFF', callback_data='dj_timer|easy|0')],
        [InlineKeyboardButton('ℹ️ Abrir videochat manual', callback_data='dj_easy_info')],
    ])


async def _v106_show_easy(q, context: ContextTypes.DEFAULT_TYPE, chat_id: int) -> None:
    try:
        await q.edit_message_text(_v106_easy_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v106_easy_markup())
    except BadRequest as e:
        if 'message is not modified' in str(e).lower():
            return
        sent = await context.bot.send_message(chat_id, _v106_easy_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v106_easy_markup())
        try:
            await register_temp_message(chat_id, sent.message_id)
        except Exception:
            pass
    except Exception:
        logger.exception('No se pudo mostrar DJ Fácil')


async def _v106_modes_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'dj_easy_menu', 'menu_panel'}:
        return
    chat_id = int(update.effective_chat.id)
    state = get_state(chat_id)
    user = update.effective_user
    if data == 'dj_easy_menu':
        if not await _v106_user_can(context, chat_id, user, 'easy'):
            await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
            raise _V106Stop
        state.dj_mode = True
        state.assigned_dj_id = int(user.id)
        state.assigned_dj_name = display_name(user)
        state.auto_track_enabled = True if state.auto_track_enabled else state.auto_track_enabled
        _v106_cfg(chat_id)['dj_mesa_minimized'] = True
        _v106_cfg(chat_id)['dj_mesa_visible'] = False
        _v106_cfg(chat_id)['dj_announce_now_enabled'] = False
        _v106_set_mode(chat_id, 'easy')
        save_all_states()
        await q.answer('DJ Fácil abierto ✅')
        await _v106_show_easy(q, context, chat_id)
        await ensure_panel(context.bot, chat_id)
        raise _V106Stop
    # DJ-PRO
    if not await _v106_user_can(context, chat_id, user, 'pro'):
        await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
        raise _V106Stop
    state.dj_mode = True
    if not state.assigned_dj_id:
        state.assigned_dj_id = int(user.id)
        state.assigned_dj_name = display_name(user)
    _v106_cfg(chat_id)['dj_mesa_minimized'] = False
    _v106_cfg(chat_id)['dj_mesa_visible'] = True
    _v106_set_mode(chat_id, 'pro')
    set_control_view(state, 'home', 0)
    save_all_states()
    await q.answer('Mesa DJ-PRO abierta ✅')
    await ensure_panel(context.bot, chat_id)
    await ensure_control_panel(context.bot, chat_id)
    raise _V106Stop


async def _v106_easy_actions(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'dj_easy_start','dj_easy_next','dj_easy_close','dj_easy_info'} and not data.startswith('dj_timer|easy|'):
        return
    chat_id = int(update.effective_chat.id)
    user = update.effective_user
    state = get_state(chat_id)
    if not await _v106_user_can(context, chat_id, user, 'easy'):
        await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
        raise _V106Stop
    _v106_set_mode(chat_id, 'easy')
    _v106_cfg(chat_id)['dj_mesa_minimized'] = True
    _v106_cfg(chat_id)['dj_mesa_visible'] = False
    _v106_cfg(chat_id)['dj_announce_now_enabled'] = False
    if data == 'dj_easy_info':
        await q.answer('Instrucciones')
        await q.edit_message_text(
            '<b>ℹ️ Abrir videochat manualmente</b>\n\n'
            '1. Pulsa arriba en el <b>nombre del grupo</b>.\n'
            '2. Entra en <b>Videochat / Directo</b>.\n'
            '3. Vuelve al panel de DJ Fácil.',
            parse_mode=ParseMode.HTML,
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('🔙 Volver DJ Fácil', callback_data='dj_easy_menu')]])
        )
        raise _V106Stop
    if data.startswith('dj_timer|easy|'):
        hours = 0
        try:
            hours = int(data.split('|')[2])
        except Exception:
            pass
        try:
            if hours <= 0:
                _v75_cancel_timer(chat_id)
                await q.answer('Temporizador OFF ✅', show_alert=True)
            else:
                _v75_set_timer(context.bot, chat_id, hours, 'easy')
                await q.answer(f'DJ Fácil se cerrará en {hours}h ✅', show_alert=True)
        except Exception:
            logger.exception('No se pudo gestionar temporizador easy')
        await _v106_show_easy(q, context, chat_id)
        await ensure_panel(context.bot, chat_id)
        raise _V106Stop
    if data == 'dj_easy_start':
        if not state.library:
            await q.answer('La biblioteca está vacía.', show_alert=True)
            raise _V106Stop
        items = [dict(x) for x in state.library]
        try:
            import random as _r106
            _r106.shuffle(items)
        except Exception:
            pass
        state.queue = dedupe_track_items(items)
        state.dj_mode = True
        state.assigned_dj_id = int(user.id)
        state.assigned_dj_name = display_name(user)
        state.dj_shuffle_enabled = True
        state.auto_track_enabled = True
        state.auto_sig_seconds = 0
        save_all_states()
        try:
            await _dj_open_or_explain_live_v29(context, chat_id, start_call=True)
        except Exception:
            logger.exception('No pude abrir/explicar directo easy')
        if not state.now_playing:
            try:
                await simulate_panel_next(chat_id, reason='dj_easy_start')
            except Exception:
                logger.exception('No pude iniciar primera canción easy')
        await q.answer('DJ Fácil iniciado ✅', show_alert=True)
        await _v106_show_easy(q, context, chat_id)
        await ensure_panel(context.bot, chat_id)
        raise _V106Stop
    if data == 'dj_easy_next':
        if not state.dj_mode:
            await q.answer('DJ Fácil no está activo.', show_alert=True)
            raise _V106Stop
        ok = await simulate_panel_next(chat_id, reason='dj_easy_next')
        await q.answer('Siguiente canción ✅' if ok else 'No hay canción siguiente.', show_alert=True)
        await _v106_show_easy(q, context, chat_id)
        await ensure_panel(context.bot, chat_id)
        raise _V106Stop
    if data == 'dj_easy_close':
        await q.answer('Cerrando DJ Fácil…')
        await close_dj_session(context.bot, chat_id)
        try:
            await q.edit_message_text('🎧 DJ Fácil cerrado ✅')
        except Exception:
            pass
        raise _V106Stop


