# =========================================================
# V108 - Mesa DJ-PRO fluida: botones del panel funcionando
# =========================================================
# Corrige el caso donde la mesa visible se abre, pero botones como
# Ver lista, Biblioteca, Guardar lista, Cargar lista, Volver, etc.
# no responden por choques entre routers antiguos.
#
# Estrategia:
# - Al abrir MODO DJ-PRO, el usuario autorizado pasa a ser DJ actual.
# - Un router prioritario intercepta TODOS los botones de la mesa PRO.
# - Delegamos la lógica real en callback_router original, pero paramos el resto
#   de routers para evitar duplicados, capturas parciales o callbacks perdidos.
# - Para listas/biblioteca masiva usamos los routers deduplicados V106.

try:
    from telegram.ext import ApplicationHandlerStop as _V108Stop
except Exception:
    _V108Stop = Exception


def _v108_is_dj_panel_callback(data: str) -> bool:
    if not data:
        return False
    if data.startswith(('panel_', 'q|', 'lib|', 'lst|', 'det|', 'pin|')):
        return True
    if data.startswith('dj_timer|pro|'):
        return True
    return False


async def _v108_open_pro_visible(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user) -> None:
    state = get_state(chat_id)
    state.dj_mode = True
    # Importante: quien abre MODO DJ-PRO pasa a controlar la mesa actual.
    state.assigned_dj_id = int(user.id)
    state.assigned_dj_name = display_name(user)
    try:
        cfg = admin_cfg(chat_id)
        cfg['dj_mesa_visible'] = True
        cfg['dj_mesa_minimized'] = False
        cfg['dj_session_mode'] = 'pro'
    except Exception:
        pass
    try:
        _v106_set_mode(chat_id, 'pro')
    except Exception:
        pass
    set_control_view(state, 'home', 0)
    save_all_states()
    await ensure_panel(context.bot, chat_id)
    # Forzar mesa visible como mensaje separado.
    if '_v107_send_control_panel' in globals():
        await _v107_send_control_panel(context.bot, chat_id, force_new=True)
    else:
        await ensure_control_panel(context.bot, chat_id)


async def _v108_modes_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'menu_panel', 'dj_easy_menu'}:
        return
    chat_id = int(update.effective_chat.id)
    user = update.effective_user

    if data == 'dj_easy_menu':
        # Dejar que el router fácil más reciente actúe, pero si no, fallback.
        try:
            if not await _v106_user_can(context, chat_id, user, 'easy'):
                await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
                raise _V108Stop
            state = get_state(chat_id)
            state.dj_mode = True
            state.assigned_dj_id = int(user.id)
            state.assigned_dj_name = display_name(user)
            save_all_states()
            await q.answer('DJ Fácil abierto ✅')
            if '_v107_send_easy_panel' in globals():
                await _v107_send_easy_panel(context.bot, chat_id)
            elif '_v106_show_easy' in globals():
                await _v106_show_easy(q, context, chat_id)
            await ensure_panel(context.bot, chat_id)
            raise _V108Stop
        except _V108Stop:
            raise
        except Exception:
            logger.exception('V108 no pudo abrir DJ Fácil')
            await q.answer('Error abriendo DJ Fácil. Revisa logs.', show_alert=True)
            raise _V108Stop

    # MODO DJ-PRO
    try:
        if not await _v106_user_can(context, chat_id, user, 'pro'):
            await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True)
            raise _V108Stop
        await q.answer('Abriendo mesa DJ-PRO…')
        await _v108_open_pro_visible(context, chat_id, user)
        raise _V108Stop
    except _V108Stop:
        raise
    except Exception:
        logger.exception('V108 no pudo abrir MODO DJ-PRO')
        try:
            await q.answer('Error abriendo mesa DJ-PRO. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V108Stop


async def _v108_panel_buttons_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if not _v108_is_dj_panel_callback(data):
        return
    chat_id = int(update.effective_chat.id)
    user = update.effective_user

    # Solo afecta a mesa PRO. Si estamos en easy, no dejar que botones PRO abran cosas raras.
    try:
        if data.startswith('dj_timer|pro|') or data.startswith(('panel_', 'q|', 'lib|', 'lst|', 'det|', 'pin|')):
            if not await _v106_user_can(context, chat_id, user, 'pro'):
                await q.answer('No estás autorizado para usar la mesa DJ-PRO.', show_alert=True)
                raise _V108Stop
            # Hacer al pulsador DJ actual para que los checks antiguos de is_controller no bloqueen.
            state = get_state(chat_id)
            state.dj_mode = True
            state.assigned_dj_id = int(user.id)
            state.assigned_dj_name = display_name(user)
            try:
                cfg = admin_cfg(chat_id)
                cfg['dj_session_mode'] = 'pro'
                cfg['dj_mesa_visible'] = True
                cfg['dj_mesa_minimized'] = False
            except Exception:
                pass
            try:
                _v106_set_mode(chat_id, 'pro')
            except Exception:
                pass
            save_all_states()

        # Rutas deduplicadas/modernas primero.
        if data.startswith('lst|') and '_v106_saved_list_router' in globals():
            await _v106_saved_list_router(update, context)
            raise _V108Stop
        if data.startswith('lib|'):
            parts = data.split('|')
            if len(parts) > 1 and parts[1] in {'qa', 'pa'} and '_v106_library_bulk_router' in globals():
                await _v106_library_bulk_router(update, context)
                raise _V108Stop
        if data.startswith('dj_timer|pro|') and '_v106_pro_timer' in globals():
            await _v106_pro_timer(update, context)
            raise _V108Stop

        # Delegación al router original para Ver lista, Guardar lista, Biblioteca,
        # mover cola, reproducir tema, volumen, limpiar, cerrar, etc.
        await callback_router(update, context)
        raise _V108Stop
    except _V108Stop:
        raise
    except Exception:
        logger.exception('V108 error gestionando botón mesa PRO: %s', data)
        try:
            await q.answer('Error en botón de mesa DJ-PRO. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V108Stop


# Refuerzo: ensure_control_panel siempre debe editar o crear una mesa visible en PRO.
_old_ensure_control_panel_v108 = ensure_control_panel
async def ensure_control_panel(bot, chat_id: int) -> None:  # type: ignore[override]
    try:
        if '_v106_mode' in globals() and _v106_mode(chat_id) == 'easy':
            return
        if '_v107_send_control_panel' in globals():
            await _v107_send_control_panel(bot, chat_id, force_new=False)
            return
    except Exception:
        logger.exception('V108 ensure_control_panel falló; intento fallback')
    try:
        await _old_ensure_control_panel_v108(bot, chat_id)
    except Exception:
        logger.exception('Fallback ensure_control_panel también falló')


_old_build_application_v108 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v108()
    # Más prioridad que todos los routers DJ anteriores.
    app.add_handler(CallbackQueryHandler(_v108_modes_router, pattern=r'^(dj_easy_menu|menu_panel)$'), group=-300000000)
    app.add_handler(CallbackQueryHandler(_v108_panel_buttons_router, pattern=r'^(panel_|q\||lib\||lst\||det\||pin\||dj_timer\|pro\|)'), group=-300000000)
    logger.info('V108 mesa DJ-PRO: botones reparados y flujo estabilizado')
    return app



# =========================================================
# V109 - DJ-PRO: botones de vistas reparados de verdad
# =========================================================
# Causa real del fallo:
# _v107_send_control_panel() siempre hacía set_control_view(state, 'home', 0).
# Entonces al pulsar 📋 Ver lista / 📚 Biblioteca / 📂 Cargar lista:
#   1) el callback ponía state.control_view = queue/library/saved_lists
#   2) ensure_control_panel llamaba a _v107_send_control_panel
#   3) _v107_send_control_panel volvía a poner home
# Resultado: parecía que el botón no hacía nada.
#
# Esta versión respeta la vista actual y solo fuerza home al abrir MODO DJ-PRO.

try:
    from telegram.ext import ApplicationHandlerStop as _V109Stop
except Exception:
    _V109Stop = Exception


async def _v109_delete_control_only(bot, chat_id: int) -> None:
    state = get_state(chat_id)
    mid = int(state.control_message_id or 0)
    if mid and mid != int(state.panel_message_id or 0):
        try:
            await safe_delete(bot, chat_id, mid)
        except Exception:
            pass
    state.control_message_id = None
    save_all_states()


async def _v109_send_control_panel(bot, chat_id: int, *, force_new: bool = False, reset_home: bool = False) -> int:
    """Edita/crea la mesa PRO respetando la vista actual.

    reset_home=True solo se usa al abrir MODO DJ-PRO desde cero.
    Para botones como Ver lista/Biblioteca/Cargar lista NO se resetea.
    """
    state = get_state(chat_id)
    state.dj_mode = True
    try:
        cfg = admin_cfg(chat_id)
        cfg['dj_mesa_visible'] = True
        cfg['dj_mesa_minimized'] = False
        cfg['dj_session_mode'] = 'pro'
    except Exception:
        pass
    try:
        _v106_set_mode(chat_id, 'pro')
    except Exception:
        pass
    if reset_home:
        set_control_view(state, 'home', 0)
    save_all_states()

    text, markup = current_control_view(state)

    if not force_new and state.control_message_id:
        try:
            await bot.edit_message_text(
                chat_id=chat_id,
                message_id=int(state.control_message_id),
                text=text,
                parse_mode=ParseMode.HTML,
                reply_markup=markup,
            )
            save_all_states()
            return int(state.control_message_id)
        except BadRequest as e:
            if 'message is not modified' in str(e).lower():
                return int(state.control_message_id)
            if 'message to edit not found' in str(e).lower():
                state.control_message_id = None
                save_all_states()
        except Exception:
            logger.exception('V109 no pudo editar mesa PRO; se recrea')

    if force_new or not state.control_message_id:
        await _v109_delete_control_only(bot, chat_id)

    msg = await bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
    state.control_message_id = int(msg.message_id)
    save_all_states()
    try:
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        pass
    return int(msg.message_id)


# Sustituimos la función problemática de V107/V108 por una que NO resetea vistas.
_v107_send_control_panel = _v109_send_control_panel  # type: ignore[assignment]


async def ensure_control_panel(bot, chat_id: int) -> None:  # type: ignore[override]
    try:
        if '_v106_mode' in globals() and _v106_mode(chat_id) == 'easy':
            return
    except Exception:
        pass
    await _v109_send_control_panel(bot, chat_id, force_new=False, reset_home=False)


