async def render_control_view(bot, chat_id: int, body_text: str, reply_markup: InlineKeyboardMarkup) -> None:  # type: ignore[override]
    """Vista auxiliar sin perder el mensaje de la mesa."""
    state = get_state(chat_id)
    text = control_header(state) + body_text
    if state.control_message_id:
        try:
            await bot.edit_message_text(
                chat_id=chat_id,
                message_id=int(state.control_message_id),
                text=text,
                reply_markup=reply_markup,
                parse_mode=ParseMode.HTML,
            )
            return
        except BadRequest as e:
            if 'message is not modified' in str(e).lower():
                return
            if 'message to edit not found' in str(e).lower():
                state.control_message_id = None
                save_all_states()
        except Exception:
            logger.exception('V109 no pudo editar vista auxiliar de mesa')
    msg = await bot.send_message(chat_id=chat_id, text=text, reply_markup=reply_markup, parse_mode=ParseMode.HTML)
    state.control_message_id = int(msg.message_id)
    save_all_states()
    try:
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        pass


