# =========================================================
# V110 - Impostor PRO visual/configurable + manual del bot
# =========================================================
# Enfoque: mejorar el juego del impostor sin desmontar el resto del bot.
# - Lobby se actualiza con jugadores + configuración de partida.
# - Botón Configurar partida en lobby solo admins/owner.
# - Acusar desde R1/R2/R3 o solo votación final.
# - Modo Normal 2m / Rápido 1m por partida.
# - Modo HOT por partida.
# - Mensaje fijado: "EL IMPOSTOR PARTIDA ABIERTA" + botón Unirme.
# - Mensaje superior del juego: turno actual, activos, pistas por ronda, solo Ver palabra.
# - Mensaje inferior: jugador mencionado + responder + acusar cuando toque.
# - Resultados claros + ranking + sistema de puntuación.
# - Imágenes opcionales para lobby/ganador desde ajustes.
# - Manual del bot en ajustes.

try:
    from telegram.ext import ApplicationHandlerStop as _V110Stop
except Exception:
    _V110Stop = Exception


def _v110_is_owner_or_admin_id(user_id: int) -> bool:
    try:
        return int(user_id) in ADMIN_IDS or int(user_id) in globals().get('OWNER_IDS', set())
    except Exception:
        return False


async def _v110_can_configure(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user_id: int) -> bool:
    if _v110_is_owner_or_admin_id(user_id):
        return True
    try:
        return await is_admin(context, chat_id, user_id)
    except Exception:
        return False


def _v110_cfg_defaults(chat_id: int) -> Dict[str, Any]:
    return {
        'accuse_round': int(cfg_value(chat_id, 'imp_min_accuse_round', 1) or 1),
        'final_vote_only': bool(cfg_value(chat_id, 'imp_final_vote_only', False)),
        'speed': str(cfg_value(chat_id, 'imp_match_speed', 'normal') or 'normal'),
        'hot': bool(cfg_value(chat_id, 'imp_hot_words_enabled', False)),
    }


def _v110_ensure_game_config(chat_id: int, game: Dict[str, Any]) -> Dict[str, Any]:
    cfg = game.setdefault('v110_config', {})
    if not isinstance(cfg, dict):
        cfg = {}
        game['v110_config'] = cfg
    defaults = _v110_cfg_defaults(chat_id)
    for k, v in defaults.items():
        cfg.setdefault(k, v)
    # Normal = 2m, rápido = 1m.
    if str(cfg.get('speed')) not in ('normal', 'fast'):
        cfg['speed'] = 'normal'
    if int(cfg.get('accuse_round') or 1) not in (1, 2, 3):
        cfg['accuse_round'] = 1
    return cfg


def _v110_turn_seconds(chat_id: int, game: Optional[Dict[str, Any]] = None) -> int:
    if game is not None:
        cfg = _v110_ensure_game_config(chat_id, game)
        return 60 if str(cfg.get('speed')) == 'fast' else 120
    return 60 if str(cfg_value(chat_id, 'imp_match_speed', 'normal')) == 'fast' else 120


def _v110_config_summary(chat_id: int, game: Dict[str, Any]) -> str:
    cfg = _v110_ensure_game_config(chat_id, game)
    if bool(cfg.get('final_vote_only')):
        accuse = 'sin acusación · solo votación final R3'
    else:
        accuse = f'acusar desde R{int(cfg.get("accuse_round") or 1)}'
    speed = 'Rápido 1 min' if str(cfg.get('speed')) == 'fast' else 'Normal 2 min'
    hot = 'HOT ON 🔥' if bool(cfg.get('hot')) else 'Normal'
    return f'{accuse} · {speed} · {hot}'


def _v110_word_bank(hot: bool) -> List[str]:
    if hot and '_V79_HOT_WORDS' in globals():
        return list(_V79_HOT_WORDS)
    if not hot and '_V79_NORMAL_WORDS' in globals():
        return list(_V79_NORMAL_WORDS)
    return list(globals().get('IMPOSTOR_WORDS', ['playa','cita','fiesta','secreto','música','viaje']))


def _v110_pick_word(chat_id: int, hot: bool) -> str:
    cfg = admin_cfg(chat_id)
    hist_key = 'imp_word_history_hot' if hot else 'imp_word_history_normal'
    words = [str(w).strip() for w in _v110_word_bank(hot) if str(w).strip()]
    if not words:
        words = ['secreto']
    hist = cfg.setdefault(hist_key, [])
    if not isinstance(hist, list):
        hist = []
        cfg[hist_key] = hist
    recent = {str(x).lower() for x in hist[-50:]}
    available = [w for w in words if w.lower() not in recent]
    if not available:
        available = words[:]
        hist.clear()
    word = secrets.choice(available)
    hist.append(word)
    del hist[:-100]
    save_all_states()
    return word


def _v110_players_lines(game: Dict[str, Any]) -> str:
    players = game.get('players') if isinstance(game.get('players'), list) else []
    if not players:
        return '<i>Aún no hay jugadores.</i>'
    lines = []
    for i, p in enumerate(players, 1):
        lines.append(f'{i}. {_imp_mention(p)}')
    return '\n'.join(lines)


def _v110_lobby_text(game: Dict[str, Any]) -> str:
    chat_id = int(game.get('chat_id') or 0)
    players = game.get('players') if isinstance(game.get('players'), list) else []
    return (
        '<b>🎭 EL JUEGO DEL IMPOSTOR</b>\n\n'
        'Sala abierta. Entra, espera al inicio y cuando empiece revisa tu palabra secreta.\n\n'
        f'👥 Jugadores: <b>{len(players)}</b>\n'
        f'{_v110_players_lines(game)}\n\n'
        f'⚙️ <b>Configuración:</b> {h(_v110_config_summary(chat_id, game))}\n'
        f'⏱ Auto-inicio lobby: <b>{h(_v83_lobby_timer_label(chat_id) if "_v83_lobby_timer_label" in globals() else "OFF")}</b>\n\n'
        '<i>Mínimo 3 jugadores para empezar.</i>'
    )


