def _v110_lobby_cfg_markup(chat_id: int, game: Dict[str, Any]) -> InlineKeyboardMarkup:
    gid = int(game.get('id', 0) or 0)
    cfg = _v110_ensure_game_config(chat_id, game)
    acc = int(cfg.get('accuse_round') or 1)
    final_only = bool(cfg.get('final_vote_only'))
    speed = str(cfg.get('speed') or 'normal')
    hot = bool(cfg.get('hot'))
    def chk(cond: bool, label: str) -> str:
        return ('✅ ' if cond else '') + label
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(chk(not final_only and acc == 1, 'Acusar R1'), callback_data=f'imp|cfgset|{chat_id}|{gid}|accuse|1'), InlineKeyboardButton(chk(not final_only and acc == 2, 'Acusar R2'), callback_data=f'imp|cfgset|{chat_id}|{gid}|accuse|2'), InlineKeyboardButton(chk(not final_only and acc == 3, 'Acusar R3'), callback_data=f'imp|cfgset|{chat_id}|{gid}|accuse|3')],
        [InlineKeyboardButton(chk(final_only, 'Solo votación final R3'), callback_data=f'imp|cfgset|{chat_id}|{gid}|final|1')],
        [InlineKeyboardButton(chk(speed == 'normal', 'Normal · 2 min'), callback_data=f'imp|cfgset|{chat_id}|{gid}|speed|normal'), InlineKeyboardButton(chk(speed == 'fast', 'Rápido · 1 min'), callback_data=f'imp|cfgset|{chat_id}|{gid}|speed|fast')],
        [InlineKeyboardButton(chk(not hot, 'Modo normal'), callback_data=f'imp|cfgset|{chat_id}|{gid}|hot|0'), InlineKeyboardButton(chk(hot, 'Modo HOT 🔥'), callback_data=f'imp|cfgset|{chat_id}|{gid}|hot|1')],
        [InlineKeyboardButton('🔙 Volver al lobby', callback_data=f'imp|cfgback|{chat_id}|{gid}')],
    ])


