try:
    from telegram.ext import ApplicationHandlerStop as _V111Stop
except Exception:
    _V111Stop = Exception


# -------------------------
# Impostor: /impostor no debe caer en handlers antiguos ni duplicar mensajes.
# -------------------------
async def impostor_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    if not update.effective_chat or not update.message or not update.effective_user:
        raise _V111Stop
    if update.effective_chat.type == 'private':
        await update.message.reply_text('Usa /impostor dentro del grupo.')
        raise _V111Stop
    chat_id = int(update.effective_chat.id)
    active = next((g for g in _imp_games(chat_id) if str(g.get('status')) in ('lobby','active','voting')), None)
    if active:
        # Si ya hay lobby, refrescamos el lobby en vez de crear ruido duplicado.
        if str(active.get('status')) == 'lobby':
            try:
                await _v110_refresh_lobby(context, chat_id, active)
            except Exception:
                pass
            await update.message.reply_html('🎭 Ya hay una sala de Impostor abierta. Usa el botón <b>Unirme</b> del mensaje fijado.')
        else:
            await update.message.reply_html('🎭 Ya hay una partida de Impostor en marcha. Termínala o cancélala antes de crear otra.')
        raise _V111Stop
    # Crear una única sala y detener propagación.
    gid = _imp_next_id(chat_id)
    cfg = _v110_cfg_defaults(chat_id)
    word = _v110_pick_word(chat_id, bool(cfg.get('hot')))
    creator = update.effective_user
    game = {
        'id': gid, 'status': 'lobby', 'word': word, 'creator_id': int(creator.id), 'created_ts': int(time.time()),
        'players': [{'id': int(creator.id), 'name': display_name(creator), 'username': getattr(creator, 'username', '') or ''}],
        'round': 1, 'turn_idx': 0, 'votes': {}, 'impostor_id': 0, 'message_id': 0, 'chat_id': chat_id,
        'v110_config': cfg,
        'v83_auto_start_sec': int(cfg_value(chat_id, 'imp_lobby_auto_start_sec', 0) or 0),
    }
    img = admin_cfg(chat_id).get('imp_lobby_image_file_id')
    if img:
        msg = await update.message.reply_photo(photo=img, caption=_v110_lobby_text(game)[:1024], parse_mode=ParseMode.HTML, reply_markup=_imp_lobby_markup(chat_id, game))
    else:
        msg = await update.message.reply_html(_v110_lobby_text(game), reply_markup=_imp_lobby_markup(chat_id, game))
    game['message_id'] = int(msg.message_id)
    _imp_games(chat_id).insert(0, game)
    save_all_states()
    await _v79_pin_lobby(context, chat_id, msg.message_id)
    raise _V111Stop


# -------------------------
# DJ panel fijado: emojis ON/OFF configurables y botón cerrar sesión.
# -------------------------
def _v111_dj_status_text(chat_id: int, state: ChatState) -> str:
    cfg = admin_cfg(chat_id)
    on = str(cfg.get('dj_status_on_emoji') or '🛜 ON')
    off = str(cfg.get('dj_status_off_emoji') or '🛑 OFF')
    return on if bool(state.live_enabled) else off


def panel_text(state: ChatState) -> str:  # type: ignore[override]
    # Respeta el texto personalizado si existe, pero {estado} usa emojis configurables.
    try:
        chat_id = next((cid for cid, st in STATE_CACHE.items() if st is state), None)
        if chat_id is not None:
            cfg = admin_cfg(int(chat_id))
            custom = str(cfg.get('dj_panel_custom_text_html') or '').strip()
            current = 'Nada sonando'
            nxt = 'Nada en cola'
            if state.now_playing:
                current = shorten_title(Track(**state.now_playing).title, 42)
            if state.queue:
                nxt = shorten_title(Track(**state.queue[0]).title, 42)
            status = _v111_dj_status_text(int(chat_id), state)
            if custom:
                repl = {
                    '{estado}': h(status),
                    '{cancion}': h(current),
                    '{actual}': h(current),
                    '{siguiente}': h(nxt),
                    '{dj}': h(state.assigned_dj_name or 'Sin asignar'),
                    '{cola}': str(len(state.queue)),
                    '{biblioteca}': str(len(state.library)),
                }
                for k, v in repl.items():
                    custom = custom.replace(k, v)
                return custom
            dj = state.assigned_dj_name or 'Sin asignar'
            if state.now_playing:
                song_label = '💽'; song_value = current
            elif state.queue:
                song_label = '⏭️'; song_value = nxt
            else:
                song_label = '❌'; song_value = 'Nada sonando'
            return f'🔊 <b>DIRECTO</b> {h(status)} <b>{song_label}</b> <i>{h(song_value)}</i> | 🎧 DJ: <b>{h(dj)}</b>'
    except Exception:
        logger.exception('Error panel_text V111')
    try:
        return _old_panel_text_v98(state) if '_old_panel_text_v98' in globals() else '🔊 <b>DIRECTO</b>'
    except Exception:
        return '🔊 <b>DIRECTO</b>'


def _v111_panel_markup(chat_id: int) -> InlineKeyboardMarkup:
    # Mantiene botón de mesa fácil/pro + like y añade cerrar sesión visible desde el panel superior.
    try:
        mode = _v106_mode(chat_id) if '_v106_mode' in globals() else 'pro'
    except Exception:
        mode = 'pro'
    main = InlineKeyboardButton('🎧 DJ Fácil' if mode == 'easy' else '🎛 Mesa DJ-PRO', callback_data='dj_easy_menu' if mode == 'easy' else 'menu_panel')
    return InlineKeyboardMarkup([
        [main, InlineKeyboardButton('❤️ Me gusta', callback_data='djlike|current')],
        [InlineKeyboardButton('❌ Cerrar sesión DJ', callback_data='panel_close')],
    ])

# Asegura que ensure_panel use el nuevo markup sin tocar otros fijados.
_old_ensure_panel_v111 = ensure_panel
async def ensure_panel(bot, chat_id: int) -> None:  # type: ignore[override]
    async with get_chat_lock(PANEL_LOCKS, chat_id):
        state = get_state(chat_id)
        if not state.dj_mode:
            return
        text = panel_text(state)
        markup = _v111_panel_markup(chat_id)
        old_id = int(state.panel_message_id or 0)
        if old_id:
            try:
                await bot.edit_message_text(chat_id=chat_id, message_id=old_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
                return
            except BadRequest as e:
                msg = str(e).lower()
                if 'message is not modified' in msg:
                    return
                if 'message to edit not found' in msg:
                    state.panel_message_id = None
                    save_all_states()
            except Exception:
                logger.exception('V111 no pudo editar panel fijado DJ; se recrea')
        msg = await bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
        state.panel_message_id = int(msg.message_id)
        save_all_states()
        try:
            await bot.pin_chat_message(chat_id=chat_id, message_id=msg.message_id, disable_notification=True)
        except Exception:
            pass
        try:
            await register_bot_message(chat_id, msg.message_id)
        except Exception:
            pass


# -------------------------
# DJ: minimizar y cerrar sesión de forma explícita y rápida.
# -------------------------
async def _v111_dj_fast_panel_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if data not in {'panel_minimize','panel_close','menu_panel','dj_easy_menu'}:
        return
    chat_id = int(update.effective_chat.id)
    user = update.effective_user
    try:
        if data == 'panel_minimize':
            if not await _v106_user_can(context, chat_id, user, 'pro'):
                await q.answer('No estás autorizado para minimizar la mesa.', show_alert=True); raise _V111Stop
            cfg = admin_cfg(chat_id)
            cfg['dj_mesa_minimized'] = True
            cfg['dj_mesa_visible'] = False
            state = get_state(chat_id)
            old = int(state.control_message_id or 0)
            state.control_message_id = None
            save_all_states()
            if old and old != int(state.panel_message_id or 0):
                try: await safe_delete(context.bot, chat_id, old)
                except Exception: pass
            await q.answer('Mesa minimizada. Pulsa Mesa DJ-PRO para volver a abrirla.', show_alert=True)
            raise _V111Stop
        if data == 'panel_close':
            # Delegamos en el router antiguo para hacer el cierre completo, pero evitamos duplicados.
            await callback_router(update, context)
            raise _V111Stop
        if data == 'menu_panel':
            if not await _v106_user_can(context, chat_id, user, 'pro'):
                await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True); raise _V111Stop
            cfg = admin_cfg(chat_id)
            cfg['dj_mesa_minimized'] = False
            cfg['dj_mesa_visible'] = True
            cfg['dj_session_mode'] = 'pro'
            state = get_state(chat_id)
            state.dj_mode = True
            state.assigned_dj_id = int(user.id)
            state.assigned_dj_name = display_name(user)
            set_control_view(state, 'home', 0)
            save_all_states()
            await q.answer('Abriendo mesa DJ-PRO…')
            await ensure_panel(context.bot, chat_id)
            await _v109_send_control_panel(context.bot, chat_id, force_new=False, reset_home=False)
            raise _V111Stop
        if data == 'dj_easy_menu':
            if not await _v106_user_can(context, chat_id, user, 'easy'):
                await q.answer('No estás autorizado para iniciar la música en directo.', show_alert=True); raise _V111Stop
            cfg = admin_cfg(chat_id)
            cfg['dj_mesa_minimized'] = True
            cfg['dj_mesa_visible'] = False
            cfg['dj_session_mode'] = 'easy'
            state = get_state(chat_id)
            state.dj_mode = True
            state.assigned_dj_id = int(user.id)
            state.assigned_dj_name = display_name(user)
            save_all_states()
            await q.answer('Abriendo DJ Fácil…')
            await ensure_panel(context.bot, chat_id)
            if '_v107_send_easy_panel' in globals():
                await _v107_send_easy_panel(context.bot, chat_id)
            else:
                await context.bot.send_message(chat_id, _v106_easy_text(chat_id), parse_mode=ParseMode.HTML, reply_markup=_v106_easy_markup())
            raise _V111Stop
    except _V111Stop:
        raise
    except Exception:
        logger.exception('Error router DJ rápido V111: %s', data)
        try: await q.answer('Error en DJ. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V111Stop


