# Configuración de emojis ON/OFF del panel fijado DJ.
# -------------------------
_old_admin_private_block_text_v111 = admin_private_block_text
async def _dummy_v111(): pass

def admin_private_block_text(chat_id: int, block: str, page: int = 0) -> str:  # type: ignore[override]
    txt = _old_admin_private_block_text_v111(chat_id, block, page)
    if block == 'dj_permissions':
        cfg = admin_cfg(chat_id)
        txt += (
            '\n\n<b>Emojis/estado del panel fijado DJ</b>'
            f"\nON: <code>{h(cfg.get('dj_status_on_emoji') or '🛜 ON')}</code>"
            f"\nOFF: <code>{h(cfg.get('dj_status_off_emoji') or '🛑 OFF')}</code>"
            '\nVariables del fijado: <code>{estado}</code>, <code>{actual}</code>, <code>{siguiente}</code>, <code>{dj}</code>, <code>{cola}</code>, <code>{biblioteca}</code>.'
        )
    return txt

_old_admin_private_block_markup_v111 = admin_private_block_markup

def admin_private_block_markup(chat_id: int, block: str, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    markup = _old_admin_private_block_markup_v111(chat_id, block, page)
    if block != 'dj_permissions':
        return markup
    rows = [list(r) for r in getattr(markup, 'inline_keyboard', [])]
    extra = [InlineKeyboardButton('🟢 Emoji ON', callback_data=f'cfg|djemoji|{chat_id}|on'), InlineKeyboardButton('🔴 Emoji OFF', callback_data=f'cfg|djemoji|{chat_id}|off')]
    # Insertar antes de volver si existe.
    rows.insert(max(0, len(rows)-1), extra)
    return InlineKeyboardMarkup(rows)

_old_admin_private_config_callback_v111 = admin_private_config_callback
async def admin_private_config_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    q = update.callback_query
    data = q.data if q else ''
    if q and data.startswith('cfg|djemoji|'):
        try:
            _cfg, _act, chat_s, which = data.split('|')[:4]
            chat_id = int(chat_s)
        except Exception:
            await q.answer('Config inválida', show_alert=True); raise _V111Stop
        set_config_pending(q.from_user.id, {'kind': f'djemoji_{which}_v111', 'chat_id': chat_id})
        await q.answer()
        await q.message.reply_html('Escribe el texto/emoji para el estado <b>' + ('ON' if which == 'on' else 'OFF') + '</b>.\n\nEjemplo: <code>🟢🔊</code> o <code>🔴🔇</code>')
        raise _V111Stop
    return await _old_admin_private_config_callback_v111(update, context)

_old_admin_private_config_text_v111 = admin_private_config_text
async def admin_private_config_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:  # type: ignore[override]
    if update.effective_user and update.message:
        pending = get_config_pending(update.effective_user.id)
        if pending and str(pending.get('kind','')).startswith('djemoji_'):
            chat_id = int(pending.get('chat_id') or 0)
            raw = telegram_html_from_message(update.message).strip() or plain_text_from_message(update.message).strip()
            kind = str(pending.get('kind'))
            if 'on' in kind:
                admin_cfg(chat_id)['dj_status_on_emoji'] = raw[:80]
            else:
                admin_cfg(chat_id)['dj_status_off_emoji'] = raw[:80]
            pop_config_pending(update.effective_user.id)
            save_all_states()
            await update.message.reply_html('✅ Estado guardado.\n\n' + admin_private_block_text(chat_id, 'dj_permissions'), reply_markup=admin_private_block_markup(chat_id, 'dj_permissions'))
            return True
    return await _old_admin_private_config_text_v111(update, context)


