    if r: rows.append(r)

    rows.append([InlineKeyboardButton('──── 🎲 DINÁMICAS Y CONTENIDO ────', callback_data=f'cfg|noop|{chat_id}|home')])
    r=[]
    for k,t in [('impostor_settings','🎭 Impostor'),('privadito','💌 Privadito'),('daily_phrase','🌞 Frase día')]:
        if has(k): r.append(_v111_block_button(chat_id,k,t))
    if r: rows.append(r)
    r=[]
    for k,t in [('recurrentes','🔁 Recurrentes'),('pregonero','📣 Pregonero'),('resumen_fun','🧾 Resumen')]:
        if has(k): r.append(_v111_block_button(chat_id,k,t))
    if r: rows.append(r)

    rows.append([InlineKeyboardButton('──── 🎧 DJ E IA ────', callback_data=f'cfg|noop|{chat_id}|home')])
    r=[]
    for k,t in [('dj_permissions','🎛 Permisos DJ'),('ai','🧠 Cerebrito'),('permissions','🔐 Permisos módulos')]:
        if has(k): r.append(_v111_block_button(chat_id,k,t))
    if r: rows.append(r)

    rows.append([InlineKeyboardButton('──── 🧰 CONTROL ────', callback_data=f'cfg|noop|{chat_id}|home')])
    r=[]
