_old_build_application_v111 = build_application

def build_application() -> Application:  # type: ignore[override]
    try: _v110_ensure_manual_block()
    except Exception: pass
    app = _old_build_application_v111()
    # Máxima prioridad para evitar duplicados del /impostor y para DJ rápido.
    app.add_handler(command_handler('impostor', impostor_command), group=-900000000)
    app.add_handler(CallbackQueryHandler(_v111_dj_fast_panel_router, pattern=r'^(panel_minimize|panel_close|menu_panel|dj_easy_menu)$'), group=-900000000)
    app.add_handler(CallbackQueryHandler(admin_private_config_callback, pattern=r'^cfg\|djemoji\|'), group=-900000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.PHOTO) & ~filters.COMMAND, admin_private_config_text), group=-900000000)
    logger.info('V111 estabilidad: Impostor sin duplicados, DJ fluido/minimizar, emojis ON/OFF y ajustes visuales cargado')
    return app



# =========================================================
# V112 - Comandos IA directos + botones recurrentes IA + edición clara
# =========================================================
# Corrige:
# - Comandos IA creados como "nombre | prompt" ejecutan directamente sin pedir dato.
# - Botones de recurrentes con cmd:<comando_ia> ejecutan directamente si no necesitan dato.
# - Si el prompt usa {query}/{consulta}/{texto}, entonces sí pide el dato configurado.
# - Editar comando IA muestra prompt actual completo y permite editar ask/prompt.

try:
    from telegram.ext import ApplicationHandlerStop as _V112Stop
except Exception:
    _V112Stop = Exception


def _v112_clean_cmd(cmd: str) -> str:
    try:
        return _v66_clean_cmd_name(cmd)
    except Exception:
        return str(cmd or '').lower().strip().lstrip('/').replace('cmd:', '').replace('command:', '').strip()


def _v112_ai_commands(chat_id: int) -> Dict[str, Any]:
    try:
        return _ai_custom_commands(int(chat_id))
    except Exception:
        raw = cfg_value(int(chat_id), 'ai_custom_commands', {})
        return raw if isinstance(raw, dict) else {}


def _v112_ai_command_data(chat_id: int, cmd: str) -> Optional[Dict[str, Any]]:
    data = _v112_ai_commands(int(chat_id)).get(_v112_clean_cmd(cmd))
    return data if isinstance(data, dict) else None


def _v112_prompt_text(data: Dict[str, Any]) -> str:
    return str(data.get('prompt') or data.get('instructions') or '').strip()


def _v112_prompt_needs_query(data: Dict[str, Any]) -> bool:
    """Solo pide dato si el prompt realmente lo usa.

    Esto arregla los comandos tipo: nombre | prompt
    Aunque tengan un ask por defecto de versiones anteriores, si el prompt no contiene
    {query}, {consulta} ni {texto}, se ejecutan directamente.
    """
    prompt = _v112_prompt_text(data)
    if bool(data.get('requires_query', False)):
        return True
    return any(token in prompt for token in ('{query}', '{consulta}', '{texto}'))


# Sobrescribe helpers antiguos para que todos los routers posteriores usen la lógica correcta.
def _v87_cmd_uses_query(data: Dict[str, Any]) -> bool:  # type: ignore[override]
    return _v112_prompt_needs_query(data)


def _v112_format_ai_prompt(data: Dict[str, Any], query: str = '') -> str:
    prompt = _v112_prompt_text(data)
    query = str(query or '').strip()
    if query:
        return prompt.replace('{query}', query).replace('{consulta}', query).replace('{texto}', query)
    return prompt


def _v112_ask_text(user, data: Dict[str, Any]) -> str:
    mention = _v90_user_mention(user) if '_v90_user_mention' in globals() else h(getattr(user, 'first_name', ''))
    ask = str(data.get('ask') or data.get('ask_message') or 'Escribe el dato y envía.').strip()
    return f'{mention} {h(ask)}'


def _v112_result_text(user, answer: str) -> str:
    try:
        return _v90_result_text(user, answer)
    except Exception:
        mention = h(getattr(user, 'first_name', ''))
        return f'{mention}\n\n{h(answer)}'


def _v112_command_full_summary(name: str, data: Dict[str, Any]) -> str:
    ask = str(data.get('ask') or data.get('ask_message') or '').strip()
    prompt = _v112_prompt_text(data)
    mode = 'Pide dato' if _v112_prompt_needs_query(data) else 'Directo, no pide dato'
    return (
        f'<b>/{h(name)}</b>\n'
        f'Modo: <b>{h(mode)}</b>\n\n'
        f'<b>Mensaje si falta dato:</b>\n<blockquote>{h(ask or "—")}</blockquote>\n'
        f'<b>Prompt actual:</b>\n<blockquote>{h(prompt or "—")}</blockquote>\n\n'
        'Para que pida dato, usa <code>{query}</code>, <code>{consulta}</code> o <code>{texto}</code> en el prompt.\n'
        'Si no usas esas variables, el comando se ejecuta directamente.'
    )


async def _v112_send_ai_result(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, data: Dict[str, Any], query: str = '', *, reply_to: Optional[int] = None) -> None:
    prompt = _v112_format_ai_prompt(data, query)
    if not prompt.strip():
        msg = await context.bot.send_message(chat_id=chat_id, text=f'{_v90_user_mention(user) if "_v90_user_mention" in globals() else ""}\n\n❌ Este comando IA no tiene prompt configurado.', parse_mode=ParseMode.HTML, reply_to_message_id=reply_to)
        try: _v85_schedule_delete(context, chat_id, msg.message_id, _v85_result_delete_seconds(chat_id))
        except Exception: pass
        return
    wait = await context.bot.send_message(chat_id=chat_id, text='🧠 Pensando…', reply_to_message_id=reply_to)
    try:
        ans = await _ai_openai_response(int(chat_id), prompt, max_output_tokens=int(cfg_value(int(chat_id), 'ai_custom_command_tokens', 500) or 500))
        final = _v112_result_text(user, ans)[:3900]
        try:
            await wait.edit_text(final, parse_mode=ParseMode.HTML)
        except Exception:
            try: await wait.delete()
            except Exception: pass
            wait = await context.bot.send_message(chat_id=chat_id, text=final, parse_mode=ParseMode.HTML, reply_to_message_id=reply_to)
        try:
            _v85_schedule_delete(context, chat_id, wait.message_id, _v85_result_delete_seconds(chat_id))
            _ai_usage_inc(int(chat_id), int(getattr(user, 'id', 0) or 0), 'planecito')
        except Exception:
            pass
    except Exception as e:
        logger.exception('Error comando IA V112')
        try:
            await wait.edit_text(f'{_v90_user_mention(user) if "_v90_user_mention" in globals() else ""}\n\n❌ Error IA: {type(e).__name__}\n{str(e)[:500]}', parse_mode=ParseMode.HTML)
            _v85_schedule_delete(context, chat_id, wait.message_id, _v85_result_delete_seconds(chat_id))
        except Exception:
            pass


async def _v112_ai_custom_command_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user or not update.effective_chat:
        return
    text = (update.message.text or '').strip()
    if not text.startswith('/'):
        return
    first, *rest = text.split(maxsplit=1)
    cmd = _v112_clean_cmd(first)
    reserved = {
        'start','help','ajustes','plan','djplan','ping','preguntita','retito','examen',
        'privadito','impostor','impostorstop','cerebrito','planecito','tiempo','iatest'
    }
    if cmd in reserved:
        return
    try:
        chat_id, data = _v90_find_ai_command_from_update(update, cmd) if '_v90_find_ai_command_from_update' in globals() else _v71_find_ai_command(cmd, int(update.effective_chat.id))
    except Exception:
        chat_id, data = None, None
    if not chat_id or not isinstance(data, dict):
        return
    if not bool(cfg_value(chat_id, 'ai_enabled', True)):
        msg = await update.message.reply_text('🧠 Cerebrito está desactivado en ese grupo.')
        try: _v85_schedule_delete(context, update.effective_chat.id, msg.message_id, _v85_result_delete_seconds(chat_id))
        except Exception: pass
        raise _V112Stop

    try:
        _v85_schedule_delete(context, update.effective_chat.id, update.message.message_id, _v85_cmd_delete_seconds(chat_id))
    except Exception:
        pass

    arg = rest[0].strip() if rest else ''
    needs = _v112_prompt_needs_query(data)

    if needs and not arg:
        set_config_pending(update.effective_user.id, {'kind': 'ai_custom_command_query_v112', 'chat_id': int(chat_id), 'cmd': cmd})
        msg = await update.message.reply_html(_v112_ask_text(update.effective_user, data), reply_markup=ForceReply(selective=True))
        try: _v85_schedule_delete(context, update.effective_chat.id, msg.message_id, _v85_ask_delete_seconds(chat_id))
        except Exception: pass
        raise _V112Stop

    # Si no necesita dato, se ejecuta directamente aunque no haya argumento.
    await _v112_send_ai_result(context, int(chat_id), update.effective_user, data, arg if needs else '', reply_to=None)
    raise _V112Stop


async def _v112_pending_ai_query_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user or not update.effective_chat:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'ai_custom_command_query_v112':
        return
    uid = int(update.effective_user.id)
    chat_id = int(pending.get('chat_id') or 0)
    cmd = str(pending.get('cmd') or '')
    data = _v112_ai_command_data(chat_id, cmd)
    raw = (plain_text_from_message(update.message) if 'plain_text_from_message' in globals() else (update.message.text or '')).strip()
    pop_config_pending(uid)
    try: _v85_schedule_delete(context, update.effective_chat.id, update.message.message_id, _v85_ask_delete_seconds(chat_id))
    except Exception: pass
    if not isinstance(data, dict):
        msg = await update.message.reply_html(f'{_v90_user_mention(update.effective_user) if "_v90_user_mention" in globals() else ""} No encuentro ese comando IA.')
        try: _v85_schedule_delete(context, update.effective_chat.id, msg.message_id, _v85_result_delete_seconds(chat_id))
        except Exception: pass
        raise _V112Stop
    await _v112_send_ai_result(context, int(chat_id), update.effective_user, data, raw)
    raise _V112Stop


# Botones de mensajes recurrentes: permitir comandos IA personalizados existentes aunque no estén en la lista manual.
def _v112_rec_cmd_allowed(chat_id: int, cmd: str) -> bool:
    cmd = _v112_clean_cmd(cmd)
    if _v112_ai_command_data(int(chat_id), cmd):
        return True
    try:
        return cmd in set(_v66_allowed_rec_commands(int(chat_id)))
    except Exception:
        return False


def recurring_buttons_markup(row: Dict[str, Any], self_url: Optional[str] = None, chat_id: Optional[int] = None) -> Optional[InlineKeyboardMarkup]:  # type: ignore[override]
    buttons = row.get('buttons') or []
    if not isinstance(buttons, list) or not buttons:
        return None
    rows: List[List[InlineKeyboardButton]] = []
    for b in buttons:
        if not isinstance(b, dict):
            continue
        text = str(b.get('text', '')).strip()[:64]
        if not text:
            continue
        cmd = _v112_clean_cmd(str(b.get('cmd', ''))) if b.get('cmd') else ''
        if cmd:
            if chat_id is not None and _v112_rec_cmd_allowed(int(chat_id), cmd):
                rows.append([InlineKeyboardButton(text, callback_data=f'reccmd|{int(chat_id)}|{cmd}')])
            continue
        url = str(b.get('url', '')).strip()
        try:
            if (_is_self_url_v20(url) or url == 'self') and self_url:
                rows.append([InlineKeyboardButton(text, url=self_url)])
            elif url.startswith('http://') or url.startswith('https://') or url.startswith('tg://'):
                rows.append([InlineKeyboardButton(text, url=url)])
        except Exception:
            if url:
                rows.append([InlineKeyboardButton(text, url=url)])
    return InlineKeyboardMarkup(rows) if rows else None


async def _v112_execute_ai_custom_from_recurrent(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data_raw = q.data or ''
    if not data_raw.startswith('reccmd|'):
        return
    parts = data_raw.split('|', 2)
    if len(parts) < 3:
        return
    try:
        chat_id = int(parts[1])
    except Exception:
        return
    cmd = _v112_clean_cmd(parts[2])
    data = _v112_ai_command_data(chat_id, cmd)
    if not isinstance(data, dict):
        return  # No es comando IA personalizado; que sigan los handlers de comandos normales.
    if not _v112_rec_cmd_allowed(chat_id, cmd):
        await q.answer(f'/{cmd} no está permitido en botones recurrentes.', show_alert=True)
        raise _V112Stop
    if not bool(cfg_value(chat_id, 'ai_enabled', True)):
        await q.answer('Cerebrito está desactivado en este grupo.', show_alert=True)
        raise _V112Stop
    try: await q.answer('Ejecutando IA…')
    except Exception: pass

    if _v112_prompt_needs_query(data):
        set_config_pending(q.from_user.id, {'kind': 'ai_custom_command_query_v112', 'chat_id': int(chat_id), 'cmd': cmd})
        try:
            msg = await context.bot.send_message(
                chat_id=chat_id,
                text=_v112_ask_text(q.from_user, data),
                parse_mode=ParseMode.HTML,
                reply_markup=ForceReply(selective=True),
                reply_to_message_id=q.message.message_id if q.message else None,
            )
        except Exception:
            msg = await context.bot.send_message(chat_id=chat_id, text=_v112_ask_text(q.from_user, data), parse_mode=ParseMode.HTML, reply_markup=ForceReply(selective=True))
        try: _v85_schedule_delete(context, chat_id, msg.message_id, _v85_ask_delete_seconds(chat_id))
        except Exception: pass
        raise _V112Stop

    await _v112_send_ai_result(context, chat_id, q.from_user, data, '', reply_to=None)
    raise _V112Stop


async def _v112_ai_edit_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    parts = data.split('|')
    if len(parts) < 4 or parts[1] != 'ai_cmd_edit':
        return
    try:
        chat_id = int(parts[2]); name = _v112_clean_cmd(parts[3])
    except Exception:
        return
    cmds = _v112_ai_commands(chat_id)
    cur = cmds.get(name)
    if not isinstance(cur, dict):
        await q.answer('No encuentro ese comando', show_alert=True)
        raise _V112Stop
    set_config_pending(q.from_user.id, {'kind': 'ai_custom_command_edit_v112', 'chat_id': chat_id, 'name': name})
    await q.answer()
    await q.message.reply_html(
        '✏️ <b>Editando comando IA</b>\n\n'
        + _v112_command_full_summary(name, cur)
        + '\n\n<b>Envíame el nuevo contenido:</b>\n'
          '<code>mensaje que pedirá | prompt</code>\n\n'
          'O solo el prompt si el comando es directo y no tiene que pedir nada.\n\n'
          '<b>Ejemplo directo:</b>\n<code>Genera una frase divertida para el grupo.</code>\n\n'
          '<b>Ejemplo con dato:</b>\n<code>Escribe tu ciudad y envía. | Da el tiempo actual de {query}</code>'
    )
    raise _V112Stop


async def _v112_ai_edit_pending_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'ai_custom_command_edit_v112':
        return
    uid = int(update.effective_user.id)
    chat_id = int(pending.get('chat_id') or 0)
    name = _v112_clean_cmd(str(pending.get('name') or ''))
    raw = (plain_text_from_message(update.message) if 'plain_text_from_message' in globals() else (update.message.text or '')).strip()
    cmds = _v112_ai_commands(chat_id)
    old = cmds.get(name) if isinstance(cmds.get(name), dict) else {}
    if not raw:
        await update.message.reply_html('Texto vacío. Envía un prompt o <code>mensaje | prompt</code>.')
        raise _V112Stop
    if '|' in raw:
        ask, prompt = [p.strip() for p in raw.split('|', 1)]
    else:
        ask = str(old.get('ask') or old.get('ask_message') or '').strip()
        prompt = raw
    cmds[name] = {**old, 'ask': ask[:500], 'prompt': prompt[:3000], 'edited_by': uid, 'edited_ts': int(time.time())}
    cfg_set(chat_id, 'ai_custom_commands', cmds); save_all_states(); pop_config_pending(uid)
    await update.message.reply_html('✅ Comando IA editado.\n\n' + _v112_command_full_summary(name, cmds[name]))
    raise _V112Stop


# También mejora la creación guiada: si usas "nombre | prompt", queda directo.
_old_v112_pending_text_handler = globals().get('_v71_pending_text_handler')
async def _v112_ai_create_pending_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.message or not update.effective_user:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') not in {'ai_custom_command_v71', 'ai_custom_command'}:
        return
    uid = int(update.effective_user.id)
    chat_id = int(pending.get('chat_id') or 0)
    raw = (plain_text_from_message(update.message) if 'plain_text_from_message' in globals() else (update.message.text or '')).strip()
    parts = [p.strip() for p in raw.split('|')]
    if len(parts) < 2:
        await update.message.reply_html('Formato inválido. Usa <code>comando | prompt</code> o <code>comando | mensaje que pide | prompt</code>.')
        raise _V112Stop
    if len(parts) == 2:
        name_raw, prompt = parts[0], parts[1]
        ask = ''
    else:
        name_raw, ask, prompt = parts[0], parts[1], ' | '.join(parts[2:])
    name = _v112_clean_cmd(name_raw)
    if not name:
        await update.message.reply_html('Nombre de comando inválido.')
        raise _V112Stop
    cmds = _v112_ai_commands(chat_id)
    cmds[name] = {'prompt': prompt[:3000], 'ask': ask[:500], 'created_by': uid, 'created_ts': int(time.time())}
    cfg_set(chat_id, 'ai_custom_commands', cmds); save_all_states(); pop_config_pending(uid)
    await update.message.reply_html('✅ Comando IA creado.\n\n' + _v112_command_full_summary(name, cmds[name]))
    raise _V112Stop


_old_build_application_v112 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v112()
    # Máxima prioridad para comandos IA personalizados, antes de routers antiguos.
    app.add_handler(CallbackQueryHandler(_v112_execute_ai_custom_from_recurrent, pattern=r'^reccmd\|'), group=-910000000)
    app.add_handler(MessageHandler(filters.COMMAND, _v112_ai_custom_command_handler), group=-910000000)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _v112_pending_ai_query_handler), group=-910000000)
    app.add_handler(CallbackQueryHandler(_v112_ai_edit_callback, pattern=r'^cfg\|ai_cmd_edit\|'), group=-910000000)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _v112_ai_edit_pending_handler), group=-910000000)
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, _v112_ai_create_pending_handler), group=-910000000)
    logger.info('V112 comandos IA directos, recurrentes IA y edición clara cargado')
    return app


# =========================================================
# V113 - Frase del día: imagen, botón, frases masivas y tonos
# =========================================================
# No mete frases nuevas por defecto. Mantiene las frases existentes si no añades las tuyas.

try:
    from telegram.ext import ApplicationHandlerStop as _V113Stop
except Exception:
    _V113Stop = Exception

_DAILY_TONES_V113 = [
    ('random', '🎲 Aleatorio'),
    ('motivador', '💪 Motivador'),
    ('reflexivo', '🧠 Reflexivo'),
    ('familiar', '💛 Familiar'),
    ('divertido', '😄 Divertido'),
]


def _v113_tone_label(tone: str) -> str:
    return dict(_DAILY_TONES_V113).get(str(tone or 'random'), str(tone or 'random'))


def _v113_daily_custom_rows(chat_id: int) -> List[Dict[str, Any]]:
    cfg = admin_cfg(chat_id)
    rows = cfg.setdefault('daily_phrase_custom_rows', [])
    if not isinstance(rows, list):
        rows = []
        cfg['daily_phrase_custom_rows'] = rows
    # Migración suave si existiese lista antigua solo texto.
    old = cfg.get('daily_phrase_custom_phrases')
    if old and isinstance(old, list) and not rows:
        for item in old:
            txt = str(item or '').strip()
            if txt:
                rows.append({'text': txt, 'tone': 'motivador'})
    return rows


def _v113_daily_available_rows(chat_id: int) -> List[Dict[str, Any]]:
    rows = _v113_daily_custom_rows(chat_id)
    tone = str(cfg_value(chat_id, 'daily_phrase_tone', 'random') or 'random')
    if tone and tone != 'random':
        filtered = [r for r in rows if str(r.get('tone', 'motivador')) == tone]
        if filtered:
            return filtered
    return rows


_old_v113_daily_phrase_for_chat = globals().get('daily_phrase_for_chat_v30') or globals().get('daily_phrase_for_date_v15')
def daily_phrase_for_chat_v30(chat_id: int, now_ts: Optional[int] = None) -> str:  # type: ignore[override]
    rows = _v113_daily_available_rows(chat_id)
    if rows:
        offset = int(cfg_value(chat_id, 'daily_phrase_offset', 0) or 0)
        try:
            day_index = int((_local_dt_v15(now_ts).strftime('%j') if now_ts else _local_dt_v15(int(time.time())).strftime('%j')))
        except Exception:
            day_index = int(time.time() // 86400)
        idx = (day_index + offset) % len(rows)
        return str(rows[idx].get('text') or '').strip() or 'Hoy es un buen día para tener un gran día.'
    if callable(_old_v113_daily_phrase_for_chat):
        try:
            return _old_v113_daily_phrase_for_chat(chat_id, now_ts)  # type: ignore[misc]
        except TypeError:
            return _old_v113_daily_phrase_for_chat(now_ts)  # type: ignore[misc]
    return 'Hoy es un buen día para tener un gran día.'


def _v113_phrase_button_markup(chat_id: int) -> Optional[InlineKeyboardMarkup]:
    text = str(cfg_value(chat_id, 'daily_phrase_button_text', '') or '').strip()
    target = str(cfg_value(chat_id, 'daily_phrase_button_target', '') or '').strip()
    if not text or not target:
        return None
    if target.lower().startswith('cmd:') or target.startswith('/'):
        cmd = target[4:] if target.lower().startswith('cmd:') else target
        cmd = cmd.strip().lstrip('/').split()[0].lower()
        if cmd:
            return InlineKeyboardMarkup([[InlineKeyboardButton(text[:64], callback_data=f'reccmd|{int(chat_id)}|{cmd}')]])
    if target.startswith('t.me/'):
        target = 'https://' + target
    if target.startswith(('http://', 'https://', 'tg://')):
        return InlineKeyboardMarkup([[InlineKeyboardButton(text[:64], url=target)]])
    return None


def _v113_phrase_text(chat_id: int, now_ts: Optional[int] = None) -> str:
    title = str(cfg_value(chat_id, 'daily_phrase_title', '🌞 Frase del día') or '🌞 Frase del día')
    phrase = daily_phrase_for_chat_v30(chat_id, now_ts)
    tone = _v113_tone_label(str(cfg_value(chat_id, 'daily_phrase_tone', 'random') or 'random'))
    show_tone = bool(cfg_value(chat_id, 'daily_phrase_show_tone', False))
    extra = f"\n<code>{h(tone)}</code>" if show_tone else ''
    return f"<b>{h(title)}</b>{extra}\n\n<i>{h(phrase)}</i>"


async def _v113_send_daily_phrase(application_or_bot, chat_id: int, *, now_ts: Optional[int] = None, force: bool = False) -> List[int]:
    bot = getattr(application_or_bot, 'bot', application_or_bot)
    sent_ids: List[int] = []
    cfg = admin_cfg(chat_id)
    image = cfg.get('daily_phrase_image') if isinstance(cfg.get('daily_phrase_image'), dict) else None
    markup = _v113_phrase_button_markup(chat_id)
    text = _v113_phrase_text(chat_id, now_ts)
    # Imagen encima del mensaje: se manda como foto separada antes del texto. El botón queda en el mensaje de frase.
    try:
        if image and image.get('file_id') and bool(cfg_value(chat_id, 'daily_phrase_image_enabled', True)):
            msg_img = await bot.send_photo(chat_id, photo=image.get('file_id'))
            await register_bot_message(chat_id, msg_img.message_id)
            sent_ids.append(int(msg_img.message_id))
        msg = await bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=markup)
        await register_bot_message(chat_id, msg.message_id)
        sent_ids.append(int(msg.message_id))
        if bool(cfg_value(chat_id, 'daily_phrase_pin', False)):
            try:
                await bot.pin_chat_message(chat_id, msg.message_id, disable_notification=True)
            except Exception:
                pass
    except Exception:
        logger.exception('No se pudo enviar frase del día V113')
        raise
    return sent_ids


_old_v113_daily_phrase_maybe_send = daily_phrase_maybe_send
async def daily_phrase_maybe_send(application: Application, chat_id: int, now_ts: int) -> None:  # type: ignore[override]
    cfg = admin_cfg(chat_id)
    if not bool(cfg.get('daily_phrase_enabled', False)):
        return
    # Mantenemos lógica de repetición de versiones anteriores, pero sustituimos el envío.
    now_dt = _local_dt_v15(now_ts) if '_local_dt_v15' in globals() else datetime.datetime.fromtimestamp(now_ts)
    day = now_dt.strftime('%Y-%m-%d')
    start = str(cfg.get('daily_phrase_time', '10:00') or '10:00')
    repeat = bool(cfg.get('daily_phrase_repeat_enabled', False))
    every = max(15, int(cfg.get('daily_phrase_repeat_every_minutes', 60) or 60))
    until = str(cfg.get('daily_phrase_repeat_until', start) or start)
    def _mins(v: str) -> int:
        try:
            h0,m0 = [int(x) for x in str(v).split(':',1)]
            return h0*60+m0
        except Exception:
            return 0
    now_min = now_dt.hour*60 + now_dt.minute
    start_min = _mins(start)
    until_min = _mins(until)
    if not repeat:
        slot = f'{day}:{start}'
        if cfg.get('daily_phrase_last_key') == slot or now_min < start_min:
            return
    else:
        if now_min < start_min or now_min > until_min:
            return
        slot_index = (now_min - start_min) // every
        slot_min = start_min + slot_index * every
        slot = f'{day}:{slot_min}'
        if cfg.get('daily_phrase_last_key') == slot:
            return
    if cfg.get('daily_phrase_sending_key') == slot:
        return
    cfg['daily_phrase_sending_key'] = slot
    cfg['daily_phrase_last_key'] = slot
    cfg['daily_phrase_last_sent_ts'] = int(now_ts)
    save_all_states()
    try:
        await _v113_send_daily_phrase(application, chat_id, now_ts=now_ts)
    except Exception:
        cfg['daily_phrase_last_key'] = ''
        save_all_states()
        raise
    finally:
        cfg['daily_phrase_sending_key'] = ''
        save_all_states()


async def daily_phrase_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    if not update.effective_chat:
        return
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == 'private':
        await update.message.reply_html('Usa <code>/frasedia</code> dentro del grupo o configúralo desde <code>/ajustes</code>.')
        return
    await _v113_send_daily_phrase(context.bot, chat_id, force=True)


