def queue_markup(state: ChatState, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    total = len(state.queue)
    page = clamp_page(page, total)
    _, start, end, chunk = page_slice(state.queue, page)
    rows: List[List[InlineKeyboardButton]] = []
    for rel_idx, item in enumerate(chunk):
        idx = start + rel_idx
        track = Track(**item)
        rows.append([
            InlineKeyboardButton(truncated_button_title(track.title, 42), callback_data=f'q|noop|{idx}|{page}'),
            InlineKeyboardButton('▶️', callback_data=f'q|p|{idx}|{page}'),
            InlineKeyboardButton('+1', callback_data=f'q|f|{idx}|{page}'),
            InlineKeyboardButton('🗑️', callback_data=f'q|x|{idx}|{page}'),
        ])
    nav: List[InlineKeyboardButton] = []
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'q|pg|{page-1}|0'))
    if end < len(state.queue):
        nav.append(InlineKeyboardButton('➡️', callback_data=f'q|pg|{page+1}|0'))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton('🧹 Vaciar cola', callback_data=f'q|c|0|{page}'), InlineKeyboardButton('🔙 Volver', callback_data='q|r|0|0')])
    return InlineKeyboardMarkup(rows)


def library_markup(state: ChatState, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    total = len(state.library)
    page = clamp_page(page, total)
    _, start, end, chunk = page_slice(state.library, page)
    rows: List[List[InlineKeyboardButton]] = []
    for rel_idx, item in enumerate(chunk):
        idx = start + rel_idx
        track = Track(**item)
        rows.append([
            InlineKeyboardButton(truncated_button_title(track.title, 42), callback_data=f'lib|noop|{idx}|{page}'),
            InlineKeyboardButton('➕', callback_data=f'lib|q|{idx}|{page}'),
            InlineKeyboardButton('+1', callback_data=f'lib|f|{idx}|{page}'),
            InlineKeyboardButton('🗑️', callback_data=f'lib|x|{idx}|{page}'),
        ])
    nav: List[InlineKeyboardButton] = []
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'lib|pg|{page-1}|0'))
    if end < len(state.library):
        nav.append(InlineKeyboardButton('➡️', callback_data=f'lib|pg|{page+1}|0'))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton('▶️ Reproducir todas', callback_data=f'lib|pa|0|{page}'), InlineKeyboardButton('➕ Cola todas', callback_data=f'lib|qa|0|{page}')])
    rows.append([InlineKeyboardButton('🔙 Volver', callback_data='lib|r|0|0')])
    return InlineKeyboardMarkup(rows)


async def _v122_edit_control(bot, chat_id: int, text: str, markup: InlineKeyboardMarkup, *, prefer_mid: int = 0) -> int:
    """Edita SIEMPRE la mesa canónica. Solo crea una vez si no existe.

    No borra ni crea otra mesa al minimizar/mostrar. Si prefer_mid es la mesa
    desde la que se pulsa, se adopta como canónica.
    """
    st = get_state(chat_id)
    if prefer_mid and prefer_mid != int(st.panel_message_id or 0):
        # Solo adoptamos el mensaje si parece ser la mesa/control, no el fijado.
        st.control_message_id = int(prefer_mid)
    mid = int(st.control_message_id or 0)
    if mid:
        try:
            await bot.edit_message_text(chat_id=chat_id, message_id=mid, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
            save_all_states()
            return mid
        except BadRequest as e:
            low = str(e).lower()
            if 'message is not modified' in low:
                return mid
            if 'message to edit not found' in low or 'message identifier is not specified' in low:
                st.control_message_id = None
                save_all_states()
            else:
                logger.warning('V122 no pudo editar mesa %s chat %s: %s', mid, chat_id, e)
                return mid
        except Exception:
            logger.exception('V122 fallo editando mesa %s en chat %s; no se crea duplicado salvo que no exista.', mid, chat_id)
            return mid
    # Crear solo cuando no hay mesa registrada.
    msg = await bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML, reply_markup=markup)
    st.control_message_id = int(msg.message_id)
    save_all_states()
    try:
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        pass
    return int(msg.message_id)


async def _v122_render_pro(context: ContextTypes.DEFAULT_TYPE, chat_id: int, *, prefer_mid: int = 0, reset_home: bool = False) -> int:
    st = get_state(chat_id)
    cfg = _v122_cfg(chat_id)
    cfg['dj_session_mode'] = 'pro'
    cfg['dj_mesa_visible'] = True
    cfg['dj_mesa_minimized'] = False
    _v122_set_mode(chat_id, 'pro')
    if reset_home:
        set_control_view(st, 'home', 0)
    save_all_states()
    text, markup = current_control_view(st)
    return await _v122_edit_control(context.bot, chat_id, text, markup, prefer_mid=prefer_mid)


async def ensure_control_panel(bot, chat_id: int) -> None:  # type: ignore[override]
    # Refrescos automáticos NO deben recrear ni mostrar si está minimizada.
    cfg = _v122_cfg(chat_id)
    if bool(cfg.get('dj_mesa_minimized', False)):
        return
    try:
        if _v122_mode(chat_id) == 'easy':
            return
    except Exception:
        pass
    st = get_state(chat_id)
    text, markup = current_control_view(st)
    await _v122_edit_control(bot, chat_id, text, markup)


async def render_control_view(bot, chat_id: int, body_text: str, reply_markup: InlineKeyboardMarkup) -> None:  # type: ignore[override]
    st = get_state(chat_id)
    text = control_header(st) + body_text
    await _v122_edit_control(bot, chat_id, text, reply_markup)


async def render_control_home(bot, chat_id: int) -> None:  # type: ignore[override]
    st = get_state(chat_id)
    set_control_view(st, 'home', 0)
    save_all_states()
    await ensure_control_panel(bot, chat_id)


async def _v122_render_minimized(context: ContextTypes.DEFAULT_TYPE, chat_id: int, *, prefer_mid: int = 0) -> int:
    st = get_state(chat_id)
    cfg = _v122_cfg(chat_id)
    cfg['dj_session_mode'] = 'pro'
    cfg['dj_mesa_visible'] = False
    cfg['dj_mesa_minimized'] = True
    _v122_set_mode(chat_id, 'pro')
    text = '<b>🎛 MESA DJ-PRO MINIMIZADA</b>\n\nLa sesión sigue activa. Pulsa abrir para desplegar esta misma mesa.'
    markup = InlineKeyboardMarkup([
        [InlineKeyboardButton('🎛 Abrir mesa minimizada', callback_data='menu_panel')],
        [InlineKeyboardButton('❌ Cerrar sesión DJ', callback_data='panel_close')],
    ])
    return await _v122_edit_control(context.bot, chat_id, text, markup, prefer_mid=prefer_mid or int(st.control_message_id or 0))


def _v122_is_dj_callback(data: str) -> bool:
    return (
        data in {'menu_panel','panel_home','panel_refresh','panel_queue','panel_library','panel_load_lists','panel_save_list','panel_next','panel_auto_track','panel_shuffle','panel_auto_sig','panel_join_live','panel_voice_info','panel_live_toggle','panel_pause_resume','panel_close','panel_minimize','panel_likes','panel_announce_now'}
        or data.startswith('panel_vol_set|')
        or data in {'panel_vol_up','panel_vol_down'}
        or data.startswith('q|')
        or data.startswith('lib|')
        or data.startswith('lst|')
        or data.startswith('dj_timer|pro|')
    )


async def _v122_dj_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not update.effective_user:
        return
    data = q.data or ''
    if not _v122_is_dj_callback(data):
        return
    chat_id = int(update.effective_chat.id)
    st = get_state(chat_id)
    # Si el botón viene de la propia mesa, úsalo como ID canónico. Si viene del fijado, no.
    prefer_mid = 0
    if q.message and int(q.message.chat_id) == chat_id and int(q.message.message_id) != int(st.panel_message_id or 0):
        prefer_mid = int(q.message.message_id)
        st.control_message_id = prefer_mid
    try:
        if not await _v122_can_pro(context, chat_id, update.effective_user):
            await q.answer('No estás autorizado para usar la mesa DJ-PRO.', show_alert=True)
            raise _V122Stop
        st.dj_mode = True
        st.assigned_dj_id = int(update.effective_user.id)
        st.assigned_dj_name = display_name(update.effective_user)
        save_all_states()
        await q.answer()

        if data == 'menu_panel':
            await _v122_render_pro(context, chat_id, prefer_mid=prefer_mid, reset_home=False)
            raise _V122Stop
        if data == 'panel_minimize':
            await _v122_render_minimized(context, chat_id, prefer_mid=prefer_mid)
            raise _V122Stop
        if data == 'panel_home':
            set_control_view(st, 'home', 0)
        elif data == 'panel_queue':
            set_control_view(st, 'queue', 0)
        elif data == 'panel_library':
            set_control_view(st, 'library', 0)
        elif data == 'panel_load_lists':
            set_control_view(st, 'saved_lists', 0)
        elif data == 'panel_refresh':
            pass
        elif data in ('panel_join_live','panel_voice_info'):
            url = await build_live_join_url(context.bot, chat_id)
            if url:
                try: await q.answer(url=url)
                except Exception: pass
            else:
                await q.answer('Pulsa el nombre del grupo y abre el videochat manualmente.', show_alert=True)
            raise _V122Stop
        elif data in ('panel_live_toggle','panel_pause_resume'):
            try:
                st.live_enabled = not bool(st.live_enabled)
                try:
                    live_result = await VOICE.toggle_live(chat_id)
                    st.live_enabled = bool(live_result)
                except Exception:
                    pass
            except Exception:
                logger.exception('V122 LIVE toggle')
        elif data == 'panel_next':
            if not st.queue:
                await q.answer('No hay canciones en cola.', show_alert=True)
                raise _V122Stop
            ok = await simulate_panel_next(chat_id, reason='manual_button')
            if not ok:
                await q.answer('No se pudo reproducir.', show_alert=True)
        elif data == 'panel_auto_track':
            st.auto_track_enabled = not bool(st.auto_track_enabled)
        elif data == 'panel_shuffle':
            st.dj_shuffle_enabled = not bool(getattr(st, 'dj_shuffle_enabled', False))
        elif data in ('panel_auto_sig','panel_auto_next','panel_autoplay'):
            current_idx = AUTO_SIG_OPTIONS.index(st.auto_sig_seconds) if st.auto_sig_seconds in AUTO_SIG_OPTIONS else 0
            st.auto_sig_seconds = AUTO_SIG_OPTIONS[(current_idx + 1) % len(AUTO_SIG_OPTIONS)]
        elif data == 'panel_likes':
            await _show_dj_likes_v20(context, chat_id)
            raise _V122Stop
        elif data == 'panel_announce_now':
            cfg = _v122_cfg(chat_id)
            cfg['dj_announce_now_enabled'] = not bool(cfg.get('dj_announce_now_enabled', False))
            await q.answer('Aviso canción ' + ('ON' if cfg['dj_announce_now_enabled'] else 'OFF'), show_alert=True)
        elif data == 'panel_save_list':
            prompt = await context.bot.send_message(chat_id=chat_id, text='Escribe el nombre de la lista que quieres guardar:', reply_markup=ForceReply(selective=True))
            await register_temp_message(chat_id, prompt.message_id)
            PENDING_ACTIONS[f'{chat_id}:{int(update.effective_user.id)}'] = {'kind': 'save_list', 'prompt_id': prompt.message_id}
            raise _V122Stop
        elif data == 'panel_close':
            await close_dj_session(context.bot, chat_id)
            raise _V122Stop
        elif data.startswith('panel_vol_set|'):
            try: vol = max(0, min(100, int(data.split('|',1)[1])))
            except Exception: vol = 100
            st.volume = vol
            await VOICE.set_volume(chat_id, vol)
        elif data == 'panel_vol_up':
            st.volume = max(0, min(100, int(getattr(st, 'volume', 100) or 100) + 5))
            await VOICE.set_volume(chat_id, st.volume)
        elif data == 'panel_vol_down':
            st.volume = max(0, min(100, int(getattr(st, 'volume', 100) or 100) - 5))
            await VOICE.set_volume(chat_id, st.volume)
        elif data.startswith('q|'):
            parts = data.split('|'); action = parts[1]; idx = int(parts[2]) if len(parts)>2 else 0; page = int(parts[3]) if len(parts)>3 else 0
            if action == 'noop': raise _V122Stop
            if action == 'r': set_control_view(st, 'home', 0)
            elif action == 'pg': set_control_view(st, 'queue', idx)
            elif action == 'c': st.queue = []; set_control_view(st, 'queue', 0)
            elif 0 <= idx < len(st.queue):
                if action == 'f' and idx > 0:
                    item = st.queue.pop(idx); st.queue.insert(0, item)
                elif action == 'x':
                    st.queue.pop(idx)
                elif action == 'p':
                    chosen = Track(**st.queue.pop(idx)); save_all_states(); await play_selected_track(context, chat_id, chosen)
                set_control_view(st, 'queue', clamp_page(page, len(st.queue)))
        elif data.startswith('lib|'):
            parts = data.split('|'); action = parts[1]; idx = int(parts[2]) if len(parts)>2 else 0; page = int(parts[3]) if len(parts)>3 else 0
            if action == 'noop': raise _V122Stop
            if action == 'r': set_control_view(st, 'home', 0)
            elif action == 'pg': set_control_view(st, 'library', idx)
            elif action == 'qa':
                st.queue = dedupe_track_items(list(st.queue) + [dict(x) for x in st.library]); set_control_view(st, 'library', page)
            elif action == 'pa':
                if st.library:
                    first = Track(**st.library[0])
                    st.queue = dedupe_track_items([dict(x) for x in st.library[1:]] + list(st.queue))
                    save_all_states(); await play_selected_track(context, chat_id, first)
                set_control_view(st, 'library', page)
            elif 0 <= idx < len(st.library):
                chosen = Track(**st.library[idx])
                if action == 'q': st.queue = dedupe_track_items(list(st.queue) + [asdict(chosen)])
                elif action == 'f': st.queue = dedupe_track_items([asdict(chosen)] + list(st.queue))
                elif action == 'x': st.library.pop(idx)
                set_control_view(st, 'library', clamp_page(page, len(st.library)))
        elif data.startswith('lst|'):
            parts = data.split('|'); action = parts[1]; idx = int(parts[2]) if len(parts)>2 and parts[2].lstrip('-').isdigit() else 0
            names = sorted(st.saved_lists.keys())
            if action == 'r': set_control_view(st, 'home', 0)
            elif 0 <= idx < len(names):
                name = names[idx]; items = [dict(x) for x in st.saved_lists.get(name, [])]
                if action == 'a': st.queue = dedupe_track_items(list(st.queue) + items)
                elif action == 'p':
                    st.queue = dedupe_track_items(items + list(st.queue));
                    if st.queue:
                        chosen = Track(**st.queue.pop(0)); save_all_states(); await play_selected_track(context, chat_id, chosen)
                elif action == 'x': st.saved_lists.pop(name, None)
                set_control_view(st, 'saved_lists', 0)
        elif data.startswith('dj_timer|pro|'):
            try:
                # Deja que el temporizador moderno si existe lo gestione, pero sin continuar a routers viejos.
                if '_v106_pro_timer' in globals():
                    await _v106_pro_timer(update, context)
                    raise _V122Stop
            except _V122Stop:
                raise
            except Exception:
                logger.exception('V122 timer pro')
        save_all_states()
        if not bool(_v122_cfg(chat_id).get('dj_mesa_minimized', False)):
            await _v122_render_pro(context, chat_id, prefer_mid=int(st.control_message_id or prefer_mid or 0), reset_home=False)
        raise _V122Stop
    except _V122Stop:
        raise
    except Exception:
        logger.exception('Error DJ V122 callback %s', data)
        try:
            await q.answer('Error en mesa DJ. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V122Stop


_old_v122_build_application = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_v122_build_application()
    # Máxima prioridad: evita que routers viejos creen/editen otra mesa.
    app.add_handler(CallbackQueryHandler(_v122_dj_router, pattern=r'^(menu_panel|panel_|q\||lib\||lst\||dj_timer\|pro\|)'), group=-4000000000)
    logger.info('V122 DJ-PRO mesa única/minimizar mismo mensaje/botonera compacta cargado')
    return app


# =========================================================
# V123 - Validación blindada + salidas visibles
# =========================================================
# Objetivo: cualquier entrada detectada queda obligada a presentación/preguntas,
# y las salidas/expulsiones se ven claramente sin depender de mensajes de servicio.

try:
    from telegram.ext import ApplicationHandlerStop as _V123Stop
except Exception:
    _V123Stop = Exception

_V123_EVENT_CACHE: Dict[str, int] = {}


def _v123_now() -> int:
    return int(time.time())


def _v123_seen(key: str, ttl: int = 20) -> bool:
    now = _v123_now()
    # Limpieza ligera.
    if len(_V123_EVENT_CACHE) > 1000:
        for k, ts in list(_V123_EVENT_CACHE.items()):
            if now - int(ts or 0) > 300:
                _V123_EVENT_CACHE.pop(k, None)
    last = int(_V123_EVENT_CACHE.get(key, 0) or 0)
    if last and now - last < ttl:
        return True
    _V123_EVENT_CACHE[key] = now
    return False


def _v123_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(chat_id)
    cfg.setdefault('validation_lock_entries', True)
    cfg.setdefault('validation_public_left_enabled', True)
    cfg.setdefault('validation_public_kicked_enabled', True)
    cfg.setdefault('validation_left_message', '🚪 {mention} ha salido del grupo.')
    cfg.setdefault('validation_kicked_message', '⛔ {mention} ha sido expulsado del grupo.')
    return cfg


def _v123_user_mention(user) -> str:
    try:
        return user.mention_html()
    except Exception:
        return h(display_name(user))


async def _v123_send_template(context: ContextTypes.DEFAULT_TYPE, chat_id: int, template: str, user) -> Optional[int]:
    try:
        text = validation_format_template(str(template or ''), user)
        msg = await context.bot.send_message(chat_id=chat_id, text=text, parse_mode=ParseMode.HTML)
        try:
            await register_bot_message(chat_id, msg.message_id)
        except Exception:
            pass
        return int(msg.message_id)
    except Exception:
        logger.exception('V123 no pudo enviar plantilla en %s', chat_id)
        return None


async def _v123_start_validation(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, *, source: str, public: bool = True) -> bool:
    if not user or getattr(user, 'is_bot', False):
        return False
    if not chat_is_allowed(chat_id) or not validation_is_active_for_chat(chat_id):
        return False
    cfg = _v123_cfg(chat_id)
    if not bool(cfg.get('validation_lock_entries', True)):
        return False
    key = f'join:{chat_id}:{int(user.id)}:{source}'
    if _v123_seen(key, ttl=20):
        # Ya procesado por otra vía: evita que un segundo handler mande duplicados.
        return True
    try:
        # Siempre forzamos en una entrada nueva. Así también revalida al que sale y vuelve.
        started = await start_validation_for_user(
            context,
            context,
            int(chat_id),
            user,
            reply_to_message_id=None,
            source=source,
            force=True,
        )
    except Exception:
        logger.exception('V123 no pudo iniciar validación para %s en %s', getattr(user, 'id', None), chat_id)
        started = False
    if started and public:
        try:
            mid = await send_configured_public_join(context.bot, int(chat_id), user, reply_to_message_id=None)
            rec = validation_get_record(chat_id, user.id) or {}
            if mid:
                rec['public_message_id'] = mid
            rec['v123_locked_entry'] = True
            rec['source'] = source
            validation_set_record(chat_id, user.id, rec)
        except Exception:
            logger.exception('V123 no pudo enviar mensaje público de entrada')
    return bool(started)


async def _v123_join_request(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    req = getattr(update, 'chat_join_request', None)
    if not req:
        return
    chat_id = int(req.chat.id)
    user = req.from_user
    if not validation_is_active_for_chat(chat_id):
        return
    remember_chat_title(chat_id, getattr(req.chat, 'title', '') or '')
    cfg = _v123_cfg(chat_id)
    if bool(cfg_value(chat_id, 'validation_auto_approve_join_requests', True)):
        key = f'joinreq:{chat_id}:{int(user.id)}'
        if _v123_seen(key, ttl=30):
            raise _V123Stop
        try:
            await context.bot.approve_chat_join_request(chat_id=chat_id, user_id=int(user.id))
        except Exception:
            logger.exception('V123 no pudo aprobar solicitud; revisa permisos del bot')
            # Si no puede aprobar, no dejamos que otro handler haga algo raro.
            raise _V123Stop
        await _v123_start_validation(context, chat_id, user, source='join_request_v123', public=True)
        raise _V123Stop
    # Si no autoaprueba, dejamos el flujo antiguo de solicitud pendiente a admins.


async def _v123_new_member(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if not validation_is_active_for_chat(chat_id):
        return
    remember_chat_title(chat_id, getattr(update.effective_chat, 'title', '') or '')
    users = list(getattr(update.message, 'new_chat_members', []) or [])
    handled = False
    for user in users:
        ok = await _v123_start_validation(context, chat_id, user, source='service_new_member_v123', public=True)
        handled = handled or ok
    if handled:
        raise _V123Stop


async def _v123_chat_member(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    cmu = getattr(update, 'chat_member', None)
    if not cmu or not getattr(cmu, 'chat', None):
        return
    chat_id = int(cmu.chat.id)
    remember_chat_title(chat_id, getattr(cmu.chat, 'title', '') or '')
    old = getattr(cmu, 'old_chat_member', None)
    new = getattr(cmu, 'new_chat_member', None)
    user = getattr(new, 'user', None) or getattr(old, 'user', None)
    if not user or getattr(user, 'is_bot', False):
        return
    old_status = str(getattr(old, 'status', '') or '')
    new_status = str(getattr(new, 'status', '') or '')

    # Entrada/reentrada: left/kicked -> member/restricted/admin.
    if validation_is_active_for_chat(chat_id) and old_status in ('left', 'kicked', '') and new_status in ('member', 'restricted', 'administrator', 'creator'):
        ok = await _v123_start_validation(context, chat_id, user, source='chat_member_join_v123', public=True)
        if ok:
            raise _V123Stop
        return

    # Salidas/expulsiones visibles y deduplicadas.
    if old_status not in ('left', 'kicked', '') and new_status in ('left', 'kicked'):
        await _v123_handle_exit(context, chat_id, user, kicked=(new_status == 'kicked'), source='chat_member_v123')
        raise _V123Stop


async def _v123_left_service(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.message or not getattr(update.message, 'left_chat_member', None):
        return
    chat_id = int(update.effective_chat.id)
    user = update.message.left_chat_member
    await _v123_handle_exit(context, chat_id, user, kicked=False, source='service_left_v123')
    raise _V123Stop


async def _v123_handle_exit(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, *, kicked: bool, source: str) -> None:
    if not user or getattr(user, 'is_bot', False):
        return
    key = f'exit:{chat_id}:{int(user.id)}:{"kick" if kicked else "left"}'
    if _v123_seen(key, ttl=45):
        return
    cfg = _v123_cfg(chat_id)
    try:
        if kicked:
            if not bool(cfg.get('validation_public_kicked_enabled', True)):
                return
            template = str(cfg.get('validation_kicked_message') or '⛔ {mention} ha sido expulsado del grupo.')
            src = 'kicked_v123'
        else:
            if not bool(cfg.get('validation_public_left_enabled', True)):
                return
            template = str(cfg.get('validation_left_message') or '🚪 {mention} ha salido del grupo.')
            src = 'left_v123'
        _v31_record_left_user(chat_id, user, source=src) if '_v31_record_left_user' in globals() and not kicked else None
        remember_member_activity(chat_id, user, kind='left' if not kicked else 'kicked', source=source)
        await _v123_send_template(context, chat_id, template, user)
    except Exception:
        logger.exception('V123 error registrando salida/expulsión')


async def _v123_pending_guard(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Evita que usuarios pendientes usen comandos/media antes de validar.

    Las respuestas de texto normales se dejan pasar para que validation_handle_text las procese.
    """
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == 'private' or not validation_is_active_for_chat(chat_id):
        return
    record = validation_get_record(chat_id, int(update.effective_user.id))
    if not record:
        return
    status = str(record.get('status') or '')
    if status in ('validated', 'approved'):
        return
    # Si está respondiendo y manda texto normal, se procesa como respuesta por validation_handle_text.
    if status == 'answering' and update.message.text and not update.message.text.startswith('/'):
        return
    # Todo lo demás: comandos, fotos, audios, stickers, etc., fuera.
    try:
        await safe_delete(context.bot, chat_id, update.message.message_id)
    except Exception:
        pass
    try:
        await validation_restrict_answering(context, chat_id, update.effective_user.id)
    except Exception:
        pass
    # Aviso corto, autodestruible si existe send_temp_message.
    try:
        await send_temp_message(context.bot, chat_id, f'🛡 {_v123_user_mention(update.effective_user)}, completa primero la presentación y preguntas.', ttl=20)
    except Exception:
        pass
    raise _V123Stop


