async def _v126_ai_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    parts = data.split('|')
    if len(parts) < 3:
        return
    action = parts[1]
    if action not in {'ai_builtin', 'ai_summary700'}:
        return
    chat_id = int(parts[2])
    if action == 'ai_builtin':
        _v126_ensure_builtin_ai_commands(chat_id)
        await q.answer('Comandos base creados/actualizados ✅', show_alert=True)
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, 'ai'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'ai'))
        except Exception:
            pass
        raise _V126Stop
    if action == 'ai_summary700':
        await q.answer('Enviando resumen IA al grupo…')
        await _v126_send_summary_to_chat(context, chat_id, q.from_user)
        raise _V126Stop


# DJ emoji premium: captura cualquier mensaje privado con pendiente djemoji_* en grupo todavía más prioritario.
async def _v126_djemoji_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or not str(pending.get('kind','')).startswith('djemoji_'):
        return
    chat_id = int(pending.get('chat_id') or 0)
