try:
    from telegram.ext import ApplicationHandlerStop as _V128Stop
except Exception:
    _V128Stop = Exception


def queue_markup(state: ChatState, page: int = 0) -> InlineKeyboardMarkup:  # type: ignore[override]
    """Lista actual más legible: sin columna de reproducir ahora.

    Por fila: título largo | +1 siguiente | basura.
    """
    total = len(state.queue)
    page = clamp_page(page, total)
    _, start, end, chunk = page_slice(state.queue, page)
    rows: List[List[InlineKeyboardButton]] = []
    for rel_idx, item in enumerate(chunk):
        idx = start + rel_idx
        track = Track(**item)
        rows.append([
            InlineKeyboardButton(truncated_button_title(track.title, 55), callback_data=f'q|noop|{idx}|{page}'),
            InlineKeyboardButton('+1', callback_data=f'q|f|{idx}|{page}'),
            InlineKeyboardButton('🗑️', callback_data=f'q|x|{idx}|{page}'),
        ])
    nav: List[InlineKeyboardButton] = []
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'q|pg|{page-1}|0'))
    if end < len(state.queue):
        nav.append(InlineKeyboardButton('➡️', callback_data=f'q|pg|{page+1}|0'))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton('🧹 Vaciar cola', callback_data=f'q|c|0|{page}'), InlineKeyboardButton('🔙 Volver', callback_data='q|r|0|0')])
    return InlineKeyboardMarkup(rows)


def _v128_song_html(chat_id: int, text: str) -> str:
    safe = h(text)
    if bool(cfg_value(chat_id, 'dj_current_bold_italic', False)):
        return f'<b><i>{safe}</i></b>'
    return safe


# Refuerzo del texto fijado DJ: aplica negrita+cursiva a {actual}, {cancion} y, si no hay actual, también a la siguiente.
def panel_text(state: ChatState) -> str:  # type: ignore[override]
    try:
        chat_id = next((cid for cid, st in STATE_CACHE.items() if st is state), None)
        if chat_id is None:
            raise RuntimeError('chat no localizado')
        chat_id = int(chat_id)
        cfg = admin_cfg(chat_id)
        custom = str(cfg.get('dj_panel_custom_text_html') or '').strip()
        current = 'Nada sonando'
        nxt = 'Nada en cola'
        if state.now_playing:
            current = shorten_title(Track(**state.now_playing).title, 42)
        if state.queue:
            nxt = shorten_title(Track(**state.queue[0]).title, 42)
        status = _v127_dj_status_html(chat_id, state) if '_v127_dj_status_html' in globals() else ('🛜 ON' if state.live_enabled else '🛑 OFF')
        current_html = _v128_song_html(chat_id, current)
        next_html = _v128_song_html(chat_id, nxt) if (not state.now_playing and state.queue) else h(nxt)
        if custom:
            repl = {
                '{estado}': status,
                '{cancion}': current_html,
                '{actual}': current_html,
                '{siguiente}': next_html,
                '{dj}': h(state.assigned_dj_name or 'Sin asignar'),
                '{cola}': str(len(state.queue)),
                '{biblioteca}': str(len(state.library)),
            }
            for k, v in repl.items():
                custom = custom.replace(k, v)
            return custom
        dj = h(state.assigned_dj_name or 'Sin asignar')
        if state.now_playing:
            song_label = '💽'; song_value = current_html
        elif state.queue:
            song_label = '⏭️'; song_value = next_html
        else:
            song_label = '❌'; song_value = h('Nada sonando')
        return f'🔊 <b>DIRECTO</b> {status} <b>{song_label}</b> {song_value} | 🎧 DJ: <b>{dj}</b>'
    except Exception:
        try:
            return _old_v127_panel_text(state) if '_old_v127_panel_text' in globals() else '🔊 <b>DIRECTO</b>'
        except Exception:
            return '🔊 <b>DIRECTO</b>'


# Permitir botones recurrentes hacia /Djplan.
_old_v128_rec_cmd_allowed = _v112_rec_cmd_allowed if '_v112_rec_cmd_allowed' in globals() else None
def _v112_rec_cmd_allowed(chat_id: int, cmd: str) -> bool:  # type: ignore[override]
    c = _v112_clean_cmd(cmd) if '_v112_clean_cmd' in globals() else str(cmd or '').lower().strip().lstrip('/')
    if c in {'djplan', 'dj', 'musica', 'música'}:
        return True
    if callable(_old_v128_rec_cmd_allowed):
        return _old_v128_rec_cmd_allowed(chat_id, cmd)
    return False


async def _v128_reccmd_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('reccmd|'):
        return
    parts = (q.data or '').split('|', 2)
    if len(parts) < 3:
        return
    try:
        chat_id = int(parts[1])
    except Exception:
        return
    cmd = _v112_clean_cmd(parts[2]) if '_v112_clean_cmd' in globals() else str(parts[2]).strip().lower().lstrip('/')

    # Abrir menú DJPLAN del grupo donde está el botón.
    if cmd in {'djplan', 'dj', 'musica', 'música'}:
        await q.answer('Abriendo DJ-PLAN…')
        try:
            msg = await context.bot.send_message(
                chat_id=chat_id,
                text='🎧 <b>DJ-PLAN</b>\n\nElige modo:',
                parse_mode=ParseMode.HTML,
                reply_markup=main_menu_markup(),
            )
            try:
                await register_bot_message(chat_id, msg.message_id)
            except Exception:
                pass
        except Exception:
            logger.exception('No se pudo abrir DJPLAN desde botón recurrente')
            await q.answer('No pude abrir DJ-PLAN. Mira logs.', show_alert=True)
        raise _V128Stop

    # Comandos IA personalizados: ejecuta SIEMPRE en el chat_id del botón, no en otro grupo.
    data = _v112_ai_command_data(chat_id, cmd) if '_v112_ai_command_data' in globals() else None
    if isinstance(data, dict):
        if '_v112_rec_cmd_allowed' in globals() and not _v112_rec_cmd_allowed(chat_id, cmd):
            await q.answer(f'/{cmd} no está permitido en botones.', show_alert=True)
            raise _V128Stop
        try:
            needs = _v112_prompt_needs_query(data) if '_v112_prompt_needs_query' in globals() else any(x in str(data.get('prompt','')) for x in ('{query}','{consulta}','{texto}'))
            if needs:
                await q.answer('Responde al mensaje 👇')
                ask = _v112_ask_text(q.from_user, data) if '_v112_ask_text' in globals() else f'{q.from_user.mention_html()} {h(data.get("ask") or "Escribe el dato y envía.")}'
                set_config_pending(q.from_user.id, {'kind': 'ai_custom_command_query_v112', 'chat_id': int(chat_id), 'cmd': cmd})
                msg = await context.bot.send_message(chat_id=chat_id, text=ask, parse_mode=ParseMode.HTML, reply_markup=ForceReply(selective=True), reply_to_message_id=q.message.message_id if q.message else None)
                try:
                    _v85_schedule_delete(context, chat_id, msg.message_id, _v85_ask_delete_seconds(chat_id))
                except Exception:
                    pass
            else:
                await q.answer('Ejecutando IA…')
                await _v112_send_ai_result(context, int(chat_id), q.from_user, data, '', reply_to=None)
        except Exception:
            logger.exception('Error ejecutando IA recurrente V128 /%s chat %s', cmd, chat_id)
            await q.answer('Error ejecutando IA. Mira logs.', show_alert=True)
        raise _V128Stop

    # Deja pasar otros comandos permitidos (impostor, etc.) al router anterior.
    return


async def _v128_phrase_send_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('cfg|phrase_send|'):
        return
    parts = (q.data or '').split('|')
    try:
        chat_id = int(parts[2])
    except Exception:
        await q.answer('Grupo inválido', show_alert=True); raise _V128Stop
    try:
        await _v113_send_daily_phrase(context.bot, chat_id, now_ts=int(time.time()), force=True)
        cfg = admin_cfg(chat_id)
        cfg['daily_phrase_last_sent_ts'] = int(time.time())
        save_all_states()
        await q.answer('Frase enviada ✅', show_alert=True)
        try:
            await q.edit_message_text(admin_private_block_text(chat_id, 'daily_phrase'), parse_mode=ParseMode.HTML, reply_markup=admin_private_block_markup(chat_id, 'daily_phrase'))
        except Exception:
            pass
    except Exception as e:
        logger.exception('V128 error enviando frase del día ahora')
        await q.answer(f'Error enviando frase: {type(e).__name__}', show_alert=True)
    raise _V128Stop


_old_build_application_v128 = build_application
def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v128()
    app.add_handler(CallbackQueryHandler(_v128_reccmd_router, pattern=r'^reccmd\|'), group=-6400000000)
    app.add_handler(CallbackQueryHandler(_v128_phrase_send_router, pattern=r'^cfg\|phrase_send\|'), group=-6400000000)
    logger.info('V128 DJ cola, djplan en recurrentes, IA grupo correcto y frase send fix cargado')
    return app


