def _v129_ensure_tarot_block() -> None:
    try:
        global ADMIN_PRIVATE_BLOCKS, ADMIN_PRIVATE_BLOCK_IDS
        if ('tarot', '🔮 Tarot del Plan') not in ADMIN_PRIVATE_BLOCKS:
            insert_at = next((i for i,(k,_l) in enumerate(ADMIN_PRIVATE_BLOCKS) if k in ('manual','lists')), len(ADMIN_PRIVATE_BLOCKS))
            ADMIN_PRIVATE_BLOCKS.insert(insert_at, ('tarot', '🔮 Tarot del Plan'))
        ADMIN_PRIVATE_BLOCK_IDS.add('tarot')
    except Exception:
        logger.exception('No se pudo añadir bloque Tarot')


def _v129_today_key() -> str:
    return _dt_v129.datetime.now().strftime('%Y-%m-%d')


def _v129_tarot_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = admin_cfg(chat_id)
    cfg.setdefault('tarot_enabled', True)
    cfg.setdefault('tarot_ppf_enabled', True)
    cfg.setdefault('tarot_day_enabled', True)
    cfg.setdefault('tarot_ppf_limit', 2)
    cfg.setdefault('tarot_day_limit', 3)
    cfg.setdefault('tarot_likes', {})
    cfg.setdefault('tarot_usage', {})
    return cfg


def _v129_usage(chat_id: int, user_id: int, mode: str) -> int:
    cfg = _v129_tarot_cfg(chat_id)
    usage = cfg.setdefault('tarot_usage', {})
    day = usage.setdefault(_v129_today_key(), {})
    row = day.setdefault(str(int(user_id)), {'ppf': 0, 'day': 0})
    return int(row.get(mode, 0) or 0)


def _v129_inc_usage(chat_id: int, user_id: int, mode: str) -> None:
    cfg = _v129_tarot_cfg(chat_id)
    usage = cfg.setdefault('tarot_usage', {})
    day = usage.setdefault(_v129_today_key(), {})
    row = day.setdefault(str(int(user_id)), {'ppf': 0, 'day': 0})
    row[mode] = int(row.get(mode, 0) or 0) + 1
    save_all_states()


def _v129_can_play(chat_id: int, user_id: int, mode: str) -> tuple[bool, str]:
    cfg = _v129_tarot_cfg(chat_id)
    if not bool(cfg.get('tarot_enabled', True)):
        return False, '🔮 El Tarot está desactivado.'
    if mode == 'ppf':
        if not bool(cfg.get('tarot_ppf_enabled', True)):
            return False, '🔮 La tirada pasado/presente/futuro está desactivada.'
        limit = int(cfg.get('tarot_ppf_limit', 2) or 0)
    else:
        if not bool(cfg.get('tarot_day_enabled', True)):
            return False, '🔮 La carta del día está desactivada.'
        limit = int(cfg.get('tarot_day_limit', 3) or 0)
    if limit > 0 and _v129_usage(chat_id, user_id, mode) >= limit:
        return False, f'Has llegado al límite diario de esta tirada ({limit}).'
    return True, ''


def _v129_session_key(chat_id: int, user_id: int) -> str:
    return f'{int(chat_id)}:{int(user_id)}'


def _v129_pick_deck(session: Dict[str, Any], pick: str) -> Dict[str, str]:
    deck_ids = session.setdefault('deck', [c['id'] for c in TAROT_CARDS_V129])
    if not deck_ids:
        deck_ids = [c['id'] for c in TAROT_CARDS_V129]
        session['deck'] = deck_ids
    rng = secrets.SystemRandom()
    if pick == 'top':
        cid = deck_ids.pop(0)
    elif pick == 'bottom':
        cid = deck_ids.pop(-1)
    else:
        idx = rng.randrange(len(deck_ids))
        cid = deck_ids.pop(idx)
    card = next((c for c in TAROT_CARDS_V129 if c['id'] == cid), TAROT_CARDS_V129[0])
    return card


def _v129_card_image(card: Dict[str, str], subtitle: str = ''):
    try:
        from PIL import Image, ImageDraw, ImageFont
        W, H = 900, 1300
        img = Image.new('RGB', (W, H), (26, 18, 46))
        draw = ImageDraw.Draw(img)
        try:
            font_big = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 64)
            font_mid = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 44)
            font_small = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf', 34)
            font_emoji = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf', 180)
        except Exception:
            font_big = font_mid = font_small = font_emoji = None
        # borde
        for i in range(18):
            draw.rounded_rectangle((40+i, 40+i, W-40-i, H-40-i), radius=38, outline=(222, 190, 110), width=2)
        draw.rounded_rectangle((95, 105, W-95, H-105), radius=30, outline=(120, 92, 190), width=5)
        title = card.get('name','Carta')
        emoji = card.get('emoji','🔮')
        # centrar título
        bbox = draw.textbbox((0,0), title, font=font_big)
        draw.text(((W-(bbox[2]-bbox[0]))/2, 150), title, fill=(255, 235, 170), font=font_big)
        bboxe = draw.textbbox((0,0), emoji, font=font_emoji)
        draw.text(((W-(bboxe[2]-bboxe[0]))/2, 335), emoji, fill=(255,255,255), font=font_emoji)
        if subtitle:
            bbox2 = draw.textbbox((0,0), subtitle, font=font_mid)
            draw.text(((W-(bbox2[2]-bbox2[0]))/2, 620), subtitle, fill=(210, 190, 255), font=font_mid)
        short = card.get('short','')
        y = 760
        for line in _textwrap_v129.wrap(short, 28)[:4]:
            bboxl = draw.textbbox((0,0), line, font=font_small)
            draw.text(((W-(bboxl[2]-bboxl[0]))/2, y), line, fill=(240, 240, 245), font=font_small)
            y += 52
        draw.text((W/2-90, H-210), 'EL PLAN', fill=(222,190,110), font=font_mid)
        bio = _io_v129.BytesIO()
        img.save(bio, format='PNG')
        bio.seek(0)
        bio.name = f"tarot_{card.get('id','card')}.png"
        return bio
    except Exception:
        logger.exception('No se pudo generar imagen tarot')
        return None


def _v129_lobby_text(chat_id: int, user=None) -> str:
    cfg = _v129_tarot_cfg(chat_id)
    lines = [
        '<b>🔮 TAROT DEL PLAN</b>',
        '',
        'Elige una tirada y deja que los arcanos hagan el resto.',
        '',
        '<b>Opciones disponibles</b>',
        f"🕰 Pasado / Presente / Futuro: <b>{'ON' if cfg.get('tarot_ppf_enabled', True) else 'OFF'}</b> · límite diario <b>{int(cfg.get('tarot_ppf_limit',2) or 0)}</b>",
        f"☀️ Carta del día: <b>{'ON' if cfg.get('tarot_day_enabled', True) else 'OFF'}</b> · límite diario <b>{int(cfg.get('tarot_day_limit',3) or 0)}</b>",
        '',
        '<b>Cómo va</b>',
        '1. El bot baraja las cartas.',
        '2. Eliges carta de arriba, abajo o cualquiera.',
        '3. Sale la carta con imagen e interpretación.',
        '',
        'Esto es un juego de entretenimiento. No sustituye decisiones reales, pero puede dar conversación.',
    ]
    return '\n'.join(lines)


def _v129_lobby_markup() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('🕰 Pasado · Presente · Futuro', callback_data='tar|start|ppf')],
        [InlineKeyboardButton('☀️ Tirada rápida del día', callback_data='tar|start|day')],
        [InlineKeyboardButton('📖 Ver arcanos', callback_data='tar|cards|0')],
    ])


async def tarot_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_chat or not update.effective_user:
        return
    chat_id = int(update.effective_chat.id)
    if update.effective_chat.type == 'private':
        await update.message.reply_html('🔮 Usa <code>/tarot</code> dentro del grupo para jugar al Tarot del Plan.')
        return
    msg = await update.message.reply_html(_v129_lobby_text(chat_id, update.effective_user), reply_markup=_v129_lobby_markup())
    try:
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        pass


def _v129_cards_text(page: int = 0) -> str:
    page_size = 6
    total = len(TAROT_CARDS_V129)
    page = max(0, min(page, (total-1)//page_size))
    items = TAROT_CARDS_V129[page*page_size:(page+1)*page_size]
    lines = ['<b>📖 Arcanos mayores</b>', '']
    for c in items:
        lines.append(f"{c['emoji']} <b>{h(c['name'])}</b> — {h(c['short'])}")
    lines.append('')
    lines.append(f'Página {page+1}/{((total-1)//page_size)+1}')
    return '\n'.join(lines)


def _v129_cards_markup(page: int = 0) -> InlineKeyboardMarkup:
    total_pages = ((len(TAROT_CARDS_V129)-1)//6)+1
    rows = []
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f'tar|cards|{page-1}'))
    if page < total_pages-1:
        nav.append(InlineKeyboardButton('➡️', callback_data=f'tar|cards|{page+1}'))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton('🔙 Tarot', callback_data='tar|home')])
    return InlineKeyboardMarkup(rows)


def _v129_draws_text(session: Dict[str, Any]) -> str:
    mode = session.get('mode')
    title = '<b>🔮 TIRADA DEL TAROT</b>' if mode == 'day' else '<b>🔮 PASADO · PRESENTE · FUTURO</b>'
    lines = [title, '']
    draws = session.get('draws', [])
    if mode == 'ppf':
        names = ['PASADO', 'PRESENTE', 'FUTURO']
        for idx, name in enumerate(names):
            if idx < len(draws):
                c = draws[idx]
                lines.append(f"<b>{name}</b>")
                lines.append(f"{c['emoji']} <b>{h(c['name'])}</b> — {h(c['short'])}")
                lines.append('')
            else:
                lines.append(f"<b>{name}</b>")
                lines.append('Pendiente de elegir carta.')
                lines.append('')
    else:
        if draws:
            c = draws[0]
            lines.append(f"☀️ <b>CARTA DEL DÍA</b>")
            lines.append(f"{c['emoji']} <b>{h(c['name'])}</b> — {h(c['short'])}")
        else:
            lines.append('Carta pendiente de elegir.')
    return '\n'.join(lines)


def _v129_stage_name(session: Dict[str, Any]) -> str:
    if session.get('mode') == 'day':
        return 'Carta del día'
    return ['Pasado', 'Presente', 'Futuro'][min(int(session.get('stage', 0) or 0), 2)]


def _v129_choice_text(session: Dict[str, Any], user) -> str:
    return (
        f"🔮 {user.mention_html()}, elige tu carta.\n"
        f"<b>{h(_v129_stage_name(session))}</b>\n\n"
        "Las cartas están barajadas. Elige por intuición."
    )


def _v129_choice_markup() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('⬆️ Carta de arriba', callback_data='tar|pick|top'), InlineKeyboardButton('⬇️ Carta de abajo', callback_data='tar|pick|bottom')],
        [InlineKeyboardButton('🌀 Cualquier carta', callback_data='tar|pick|any')],
    ])


async def _v129_delete_msg(bot, chat_id: int, mid: Optional[int]) -> None:
    if not mid:
        return
    try:
        await bot.delete_message(chat_id, int(mid))
    except Exception:
        pass


async def _v129_send_pair(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any], *, new_pair: bool = True) -> None:
    # Borra par anterior cuando avanza la tirada, estilo Impostor.
    if new_pair:
        await _v129_delete_msg(context.bot, chat_id, session.get('draws_msg_id'))
        await _v129_delete_msg(context.bot, chat_id, session.get('choice_msg_id'))
        session['draws_msg_id'] = 0
        session['choice_msg_id'] = 0
    draws_msg = await context.bot.send_message(chat_id, _v129_draws_text(session), parse_mode=ParseMode.HTML)
    session['draws_msg_id'] = int(draws_msg.message_id)
    try:
        await register_bot_message(chat_id, draws_msg.message_id)
    except Exception:
        pass
    choice_msg = await context.bot.send_message(chat_id, _v129_choice_text(session, user), parse_mode=ParseMode.HTML, reply_markup=_v129_choice_markup())
    session['choice_msg_id'] = int(choice_msg.message_id)
    try:
        await register_bot_message(chat_id, choice_msg.message_id)
    except Exception:
        pass


async def _v129_show_card_result(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any], card: Dict[str, str]) -> None:
    stage = _v129_stage_name(session)
    caption = (
        f"🔮 <b>{h(stage)}</b>\n"
        f"{card['emoji']} <b>{h(card['name'])}</b>\n\n"
        f"{h(card['meaning'])}"
    )
    photo = _v129_card_image(card, stage)
    markup = None
    if session.get('mode') == 'ppf' and int(session.get('stage', 0) or 0) < 2:
        markup = InlineKeyboardMarkup([[InlineKeyboardButton('➡️ Siguiente tirada', callback_data='tar|next')]])
    else:
        markup = InlineKeyboardMarkup([[InlineKeyboardButton('🏁 Ver resultado final', callback_data='tar|final')]])
    try:
        if photo:
            await context.bot.edit_message_media(
                chat_id=chat_id,
                message_id=int(session.get('choice_msg_id')),
                media=__import__('telegram').InputMediaPhoto(media=photo, caption=caption, parse_mode=ParseMode.HTML),
                reply_markup=markup,
            )
        else:
            await context.bot.edit_message_text(chat_id=chat_id, message_id=int(session.get('choice_msg_id')), text=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        # si no se puede convertir texto a media, manda resultado nuevo y guarda id
        await _v129_delete_msg(context.bot, chat_id, session.get('choice_msg_id'))
        if photo:
            msg = await context.bot.send_photo(chat_id, photo=photo, caption=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=markup)
        session['choice_msg_id'] = int(msg.message_id)


async def _v129_show_final(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any]) -> None:
    draws = session.get('draws', [])
    if not draws:
        return
    result_id = secrets.token_hex(4)
    session['result_id'] = result_id
    cfg = _v129_tarot_cfg(chat_id)
    cfg.setdefault('tarot_results', {})[result_id] = {'user_id': int(user.id), 'user_name': display_name(user), 'cards': [c['id'] for c in draws], 'likes': [], 'ts': int(time.time())}
    save_all_states()
    title = '☀️ <b>RESULTADO DE TU CARTA DEL DÍA</b>' if session.get('mode') == 'day' else '🔮 <b>RESULTADO FINAL DE LA TIRADA</b>'
    lines = [title, f"Para {user.mention_html()}", '']
    if session.get('mode') == 'ppf':
        for label, c in zip(['🕰 Pasado','🔥 Presente','✨ Futuro'], draws):
            lines.append(f"{label}: {c['emoji']} <b>{h(c['name'])}</b>")
            lines.append(f"{h(c['short'])}")
            lines.append('')
    else:
        c = draws[0]
        lines.append(f"{c['emoji']} <b>{h(c['name'])}</b>")
        lines.append(h(c['meaning']))
        lines.append('')
    lines.append('Comentad qué os transmite la tirada. A veces el grupo interpreta mejor que los arcanos 😄')
    markup = InlineKeyboardMarkup([
        [InlineKeyboardButton('❤️ Me gusta · 0', callback_data=f'tar|like|{result_id}'), InlineKeyboardButton('📖 Ver arcanos', callback_data='tar|cards|0')],
        [InlineKeyboardButton('🔮 Nueva tirada', callback_data='tar|home')],
    ])
    await _v129_delete_msg(context.bot, chat_id, session.get('draws_msg_id'))
    await _v129_delete_msg(context.bot, chat_id, session.get('choice_msg_id'))
    msg = await context.bot.send_message(chat_id, '\n'.join(lines), parse_mode=ParseMode.HTML, reply_markup=markup)
    session['final_msg_id'] = int(msg.message_id)
    _v129_inc_usage(chat_id, int(user.id), session.get('mode','day'))


async def _v129_tarot_callback(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not q.from_user:
        return
    data = q.data or ''
    if not data.startswith('tar|'):
        return
    parts = data.split('|')
    chat_id = int(update.effective_chat.id)
    user = q.from_user
    skey = _v129_session_key(chat_id, int(user.id))
    action = parts[1] if len(parts) > 1 else ''
    try:
        if action == 'home':
            await q.answer()
            await q.edit_message_text(_v129_lobby_text(chat_id, user), parse_mode=ParseMode.HTML, reply_markup=_v129_lobby_markup())
            raise _V129Stop
        if action == 'cards':
            page = int(parts[2]) if len(parts) > 2 else 0
            await q.answer()
            try:
                await q.edit_message_text(_v129_cards_text(page), parse_mode=ParseMode.HTML, reply_markup=_v129_cards_markup(page))
            except Exception:
                await context.bot.send_message(chat_id, _v129_cards_text(page), parse_mode=ParseMode.HTML, reply_markup=_v129_cards_markup(page))
            raise _V129Stop
        if action == 'start':
            mode = parts[2] if len(parts) > 2 else 'day'
            if mode not in ('ppf','day'):
                mode = 'day'
            ok, reason = _v129_can_play(chat_id, int(user.id), mode)
            if not ok:
                await q.answer(reason, show_alert=True); raise _V129Stop
            rng = secrets.SystemRandom()
            deck = [c['id'] for c in TAROT_CARDS_V129]
            rng.shuffle(deck)
            session = {'chat_id': chat_id, 'user_id': int(user.id), 'mode': mode, 'stage': 0, 'draws': [], 'deck': deck, 'started_ts': int(time.time())}
            TAROT_SESSIONS_V129[skey] = session
            await q.answer('Barajando cartas…')
            # Primer mensaje tipo barajeo
            try:
                await q.edit_message_text(f'🔮 {user.mention_html()} está barajando las cartas…', parse_mode=ParseMode.HTML)
            except Exception:
                pass
            await asyncio.sleep(1.0)
            await _v129_send_pair(context, chat_id, user, session, new_pair=True)
            raise _V129Stop
        if action == 'pick':
            session = TAROT_SESSIONS_V129.get(skey)
            if not session:
                await q.answer('No tienes una tirada activa. Pulsa /tarot.', show_alert=True); raise _V129Stop
            pick = parts[2] if len(parts) > 2 else 'any'
            await q.answer('Carta elegida 🔮')
            card = _v129_pick_deck(session, pick)
            session.setdefault('draws', []).append(card)
            await _v129_show_card_result(context, chat_id, user, session, card)
            raise _V129Stop
        if action == 'next':
            session = TAROT_SESSIONS_V129.get(skey)
            if not session:
                await q.answer('No tienes una tirada activa.', show_alert=True); raise _V129Stop
            session['stage'] = int(session.get('stage', 0) or 0) + 1
            await q.answer('Siguiente tirada…')
            await _v129_send_pair(context, chat_id, user, session, new_pair=True)
            raise _V129Stop
        if action == 'final':
            session = TAROT_SESSIONS_V129.get(skey)
            if not session:
                await q.answer('No tienes una tirada activa.', show_alert=True); raise _V129Stop
            await q.answer('Mostrando resultado…')
            await _v129_show_final(context, chat_id, user, session)
            TAROT_SESSIONS_V129.pop(skey, None)
            raise _V129Stop
        if action == 'like':
            rid = parts[2] if len(parts) > 2 else ''
            cfg = _v129_tarot_cfg(chat_id)
            res = cfg.setdefault('tarot_results', {}).get(rid)
            if not res:
                await q.answer('No encuentro esta tirada.', show_alert=True); raise _V129Stop
            likes = res.setdefault('likes', [])
            uid = int(user.id)
            if uid in likes:
                await q.answer('Ya le diste me gusta.')
            else:
                likes.append(uid); save_all_states(); await q.answer('❤️ Sumado')
            count = len(likes)
            try:
                markup = q.message.reply_markup
                rows = [list(r) for r in markup.inline_keyboard]
                rows[0][0] = InlineKeyboardButton(f'❤️ Me gusta · {count}', callback_data=f'tar|like|{rid}')
                await q.edit_message_reply_markup(reply_markup=InlineKeyboardMarkup(rows))
            except Exception:
                pass
            raise _V129Stop
    except _V129Stop:
        raise
    except Exception:
        logger.exception('Error callback Tarot V129: %s', data)
        try:
            await q.answer('Error en Tarot. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V129Stop


