# =========================================================
# V132 - Tarot accesible, callbacks cortos, PNG/redimensionado y limpieza
# =========================================================
# - El bloque Tarot abre siempre desde /ajustes.
# - Se sustituyen callbacks largos por callbacks cortos t32|...
# - Permite subir PNG/JPG como foto o documento; si es documento intenta redimensionarlo y guardarlo como foto.
# - Añade opciones de limpieza/borrado de mensajes del Tarot.

try:
    from telegram.ext import ApplicationHandlerStop as _V132Stop
except Exception:
    _V132Stop = Exception


def _v132_bool(v: bool) -> str:
    return 'ON ✅' if bool(v) else 'OFF ❌'


def _v132_sec_label(sec: int) -> str:
    try:
        sec = int(sec)
    except Exception:
        sec = 0
    if sec <= 0:
        return 'No borrar'
    if sec < 60:
        return f'{sec}s'
    if sec % 60 == 0:
        return f'{sec//60}m'
    return f'{sec}s'


def _v132_cleanup_get(chat_id: int, key: str, default: int) -> int:
    cfg = _v129_tarot_cfg(chat_id)
    try:
        return int(cfg.get(key, default) or 0)
    except Exception:
        return default


