def _v132_cards_markup(chat_id: int, page: int = 0) -> InlineKeyboardMarkup:
    page_size = 6
    total_pages = ((len(TAROT_CARDS_V129)-1)//page_size)+1
    page = max(0, min(int(page), total_pages-1))
    rows = []
    for c in TAROT_CARDS_V129[page*page_size:(page+1)*page_size]:
        rows.append([InlineKeyboardButton(f"{'✅' if _v130_card_file_id(chat_id,c['id']) else '❌'} {_v130_card_number(c['id'])} · {c['name']}", callback_data=f't32|upc|{chat_id}|{c["id"]}')])
    nav=[]
    if page>0:
        nav.append(InlineKeyboardButton('⬅️', callback_data=f't32|cards|{chat_id}|{page-1}'))
    if page<total_pages-1:
        nav.append(InlineKeyboardButton('➡️', callback_data=f't32|cards|{chat_id}|{page+1}'))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton('🔙 Imágenes Tarot', callback_data=f't32|assets|{chat_id}')])
    return InlineKeyboardMarkup(rows)


