async def _v132_edit(q, text: str, markup: InlineKeyboardMarkup) -> None:
    try:
        await q.edit_message_text(text, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        await q.message.reply_html(text, reply_markup=markup)


async def _v132_tarot_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    # Abre desde el menú visual antiguo.
    if data.startswith('cfg|block|'):
        parts = data.split('|')
        if len(parts) < 4 or parts[3] != 'tarot':
            return
        try:
            chat_id = int(parts[2])
            await q.answer()
            await _v132_edit(q, _v132_tarot_settings_text(chat_id), _v132_tarot_settings_markup(chat_id))
        except Exception:
            logger.exception('Error abriendo Tarot V132')
            try: await q.answer('Error Tarot. Revisa logs.', show_alert=True)
            except Exception: pass
        raise _V132Stop
    if not data.startswith('t32|'):
        return
    parts = data.split('|')
    action = parts[1] if len(parts)>1 else ''
    try:
        chat_id = int(parts[2]) if len(parts)>2 else 0
        cfg = _v129_tarot_cfg(chat_id)
        if action == 'noop':
            await q.answer(); raise _V132Stop
        if action == 'main':
            await q.answer(); await _v132_edit(q, _v132_tarot_settings_text(chat_id), _v132_tarot_settings_markup(chat_id)); raise _V132Stop
        if action == 'tg':
            keymap={'all':'tarot_enabled','ppf':'tarot_ppf_enabled','day':'tarot_day_enabled'}
            key=keymap.get(parts[3])
            if key:
                cfg[key]=not bool(cfg.get(key, True)); save_all_states()
            await q.answer('Actualizado ✅')
            await _v132_edit(q, _v132_tarot_settings_text(chat_id), _v132_tarot_settings_markup(chat_id)); raise _V132Stop
        if action == 'lim':
            mode=parts[3]; delta=int(parts[4])
            key='tarot_ppf_limit' if mode=='ppf' else 'tarot_day_limit'
            cfg[key]=max(0, min(50, int(cfg.get(key,2 if mode=='ppf' else 3) or 0)+delta)); save_all_states()
            await q.answer('Límite actualizado ✅')
            await _v132_edit(q, _v132_tarot_settings_text(chat_id), _v132_tarot_settings_markup(chat_id)); raise _V132Stop
        if action == 'assets':
            await q.answer(); await _v132_edit(q, _v132_assets_text(chat_id), _v132_assets_markup(chat_id)); raise _V132Stop
        if action == 'cards':
            page=int(parts[3]) if len(parts)>3 else 0
            await q.answer(); await _v132_edit(q, _v130_cards_upload_text(chat_id,page), _v132_cards_markup(chat_id,page)); raise _V132Stop
        if action == 'up':
            target=parts[3]
            set_config_pending(q.from_user.id, {'kind':'tarot_image_upload_v132','chat_id':chat_id,'target':target})
            await q.answer()
            await q.message.reply_html('📸 Envíame ahora la imagen PNG/JPG para <b>{}</b>.\n\nPuedes enviarla como foto o como documento PNG.'.format('inicio/lobby' if target=='start' else 'reverso/barajeo'))
            raise _V132Stop
        if action == 'upc':
            cid=parts[3]
            card=next((c for c in TAROT_CARDS_V129 if c['id']==cid), None)
            if not card:
                await q.answer('Carta inválida', show_alert=True); raise _V132Stop
            set_config_pending(q.from_user.id, {'kind':'tarot_image_upload_v132','chat_id':chat_id,'target':'card','card_id':cid})
            await q.answer()
            await q.message.reply_html(f"📸 Envíame la imagen PNG/JPG de <b>{_v130_card_number(cid)} · {h(card['name'])}</b>.")
            raise _V132Stop
        if action == 'del':
            target=parts[3]
            imgs=_v130_tarot_images(chat_id)
            if target in ('start','back'):
                imgs[target]=''; save_all_states()
            await q.answer('Quitado ✅')
            await _v132_edit(q, _v132_assets_text(chat_id), _v132_assets_markup(chat_id)); raise _V132Stop
        if action == 'clean':
            await q.answer(); await _v132_edit(q, _v132_clean_text(chat_id), _v132_clean_markup(chat_id)); raise _V132Stop
        if action == 'cln':
            target=parts[3]; sec=int(parts[4])
            cfg['tarot_cleanup_choice_sec' if target=='choice' else 'tarot_cleanup_result_sec']=sec; save_all_states()
            await q.answer('Borrado actualizado ✅')
            await _v132_edit(q, _v132_clean_text(chat_id), _v132_clean_markup(chat_id)); raise _V132Stop
        if action == 'rank':
            await q.answer()
            await _v132_edit(q, _v129_tarot_ranking_text(chat_id), InlineKeyboardMarkup([[InlineKeyboardButton('🔙 Tarot', callback_data=f't32|main|{chat_id}')]])); raise _V132Stop
    except _V132Stop:
        raise
    except Exception:
        logger.exception('Error router Tarot V132: %s', data)
        try: await q.answer('Error Tarot. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V132Stop


async def _v132_resize_document_to_photo(context: ContextTypes.DEFAULT_TYPE, update: Update) -> Optional[str]:
    doc = update.message.document
    if not doc:
        return None
    mime = (doc.mime_type or '').lower()
    if not (mime.startswith('image/') or doc.file_name.lower().endswith(('.png','.jpg','.jpeg','.webp'))):
        return None
    try:
        from PIL import Image
        from io import BytesIO
        tgfile = await context.bot.get_file(doc.file_id)
        raw = BytesIO()
        await tgfile.download_to_memory(raw)
        raw.seek(0)
        img = Image.open(raw).convert('RGB')
        img.thumbnail((900, 1200))
        out = BytesIO()
        img.save(out, format='JPEG', quality=88, optimize=True)
        out.seek(0)
        out.name = 'tarot_card.jpg'
        # Enviar una previsualización comprimida al privado para obtener file_id de photo utilizable en send_photo.
        sent = await context.bot.send_photo(update.effective_chat.id, photo=out, caption='✅ Imagen recibida y reducida para Tarot.')
        try:
            await asyncio.sleep(2)
            await context.bot.delete_message(update.effective_chat.id, sent.message_id)
        except Exception:
            pass
        return sent.photo[-1].file_id if sent.photo else None
    except Exception:
        logger.exception('No pude redimensionar PNG/JPG de Tarot')
        return doc.file_id


async def _v132_tarot_upload_image(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'tarot_image_upload_v132':
        return
    chat_id=int(pending.get('chat_id') or 0)
    file_id=''
    if update.message.photo:
        file_id=update.message.photo[-1].file_id
    elif update.message.document:
        file_id=await _v132_resize_document_to_photo(context, update) or ''
    if not file_id:
        await update.message.reply_html('Necesito que envíes una imagen PNG/JPG como foto o documento.')
        raise _V132Stop
    target=str(pending.get('target'))
    imgs=_v130_tarot_images(chat_id)
    if target in ('start','back'):
        imgs[target]=file_id
        label='inicio/lobby' if target=='start' else 'reverso/barajeo'
    elif target=='card':
        cid=str(pending.get('card_id'))
        imgs.setdefault('cards', {})[cid]=file_id
        card=next((c for c in TAROT_CARDS_V129 if c['id']==cid), {'name':cid})
        label=f"{_v130_card_number(cid)} · {card['name']}"
    else:
        await update.message.reply_html('Destino de imagen no válido.')
        pop_config_pending(update.effective_user.id)
        raise _V132Stop
    save_all_states(); pop_config_pending(update.effective_user.id)
    await update.message.reply_html(f'✅ Guardada imagen de <b>{h(label)}</b>.')
    raise _V132Stop


# Limpieza opcional de mensajes de elección/resultado.
async def _v132_auto_delete(bot, chat_id: int, message_id: int, seconds: int) -> None:
    try:
        seconds=int(seconds)
    except Exception:
        seconds=0
    if seconds <= 0 or not message_id:
        return
    await asyncio.sleep(seconds)
    try:
        await bot.delete_message(chat_id, message_id)
    except Exception:
        pass


