# =========================================================
# V133 - Tarot: bloqueo/cooldown por grupo y tamaño de imágenes
# =========================================================
# Añade en /ajustes -> Tarot:
# - tiempo máximo de tarot abierto para bloquear nuevas tiradas;
# - espera/cooldown entre tiradas;
# - tamaño de cartas pequeño/mediano/grande.

try:
    from telegram.ext import ApplicationHandlerStop as _V133Stop
except Exception:
    _V133Stop = Exception


def _v133_tarot_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = _v129_tarot_cfg(chat_id)
    cfg.setdefault('tarot_active_lock_sec', 300)      # 5 min por defecto para que no se quede bloqueado infinito
    cfg.setdefault('tarot_cooldown_sec', 60)          # 1 min por defecto entre una y otra
    cfg.setdefault('tarot_image_size', 'medium')      # small / medium / large
    cfg.setdefault('tarot_active_until_ts', 0)
    cfg.setdefault('tarot_active_user_id', 0)
    cfg.setdefault('tarot_last_end_ts', 0)
    return cfg


def _v133_sec_label(seconds: int) -> str:
    try:
        seconds = int(seconds)
    except Exception:
        seconds = 0
    if seconds <= 0:
        return 'OFF'
    if seconds % 60 == 0:
        m = seconds // 60
        return f'{m} min'
    return f'{seconds}s'


def _v133_size_label(size: str) -> str:
    return {'small':'Pequeña', 'medium':'Mediana', 'large':'Grande'}.get(str(size), 'Mediana')


def _v133_size_dims(chat_id: int) -> tuple[int, int]:
    size = str(_v133_tarot_cfg(chat_id).get('tarot_image_size', 'medium'))
    if size == 'small':
        return (420, 620)
    if size == 'large':
        return (900, 1280)
    return (650, 920)


def _v133_is_chat_locked(chat_id: int, user_id: int) -> tuple[bool, str]:
    cfg = _v133_tarot_cfg(chat_id)
    now = int(time.time())
    active_until = int(cfg.get('tarot_active_until_ts', 0) or 0)
    active_user = int(cfg.get('tarot_active_user_id', 0) or 0)
    if active_until > now and active_user and active_user != int(user_id):
        remain = active_until - now
        return True, f'🔮 Ya hay una tirada de Tarot abierta. Espera {_v133_sec_label(remain)} o a que termine.'
    cooldown = int(cfg.get('tarot_cooldown_sec', 0) or 0)
    last_end = int(cfg.get('tarot_last_end_ts', 0) or 0)
    if cooldown > 0 and last_end > 0 and now - last_end < cooldown:
        return True, f'🔮 Espera {_v133_sec_label(cooldown - (now - last_end))} antes de abrir otra tirada.'
    return False, ''


def _v133_mark_tarot_started(chat_id: int, user_id: int) -> None:
    cfg = _v133_tarot_cfg(chat_id)
    sec = int(cfg.get('tarot_active_lock_sec', 0) or 0)
    if sec > 0:
        cfg['tarot_active_until_ts'] = int(time.time()) + sec
        cfg['tarot_active_user_id'] = int(user_id)
    else:
        cfg['tarot_active_until_ts'] = 0
        cfg['tarot_active_user_id'] = 0
    save_all_states()


def _v133_mark_tarot_finished(chat_id: int) -> None:
    cfg = _v133_tarot_cfg(chat_id)
    cfg['tarot_active_until_ts'] = 0
    cfg['tarot_active_user_id'] = 0
    cfg['tarot_last_end_ts'] = int(time.time())
    save_all_states()


# Texto/markup de ajustes Tarot con las opciones nuevas.
_old_v133_tarot_settings_text = _v132_tarot_settings_text

def _v132_tarot_settings_text(chat_id: int) -> str:  # type: ignore[override]
    base = _old_v133_tarot_settings_text(chat_id)
    cfg = _v133_tarot_cfg(chat_id)
    now = int(time.time())
    active_until = int(cfg.get('tarot_active_until_ts', 0) or 0)
    active_text = 'libre'
    if active_until > now:
        active_text = f'bloqueado {_v133_sec_label(active_until-now)}'
    return base + (
        '\n\n<b>Control de partidas</b>\n'
        f"Tarot abierto bloquea nuevas tiradas: <b>{_v133_sec_label(int(cfg.get('tarot_active_lock_sec', 0) or 0))}</b>\n"
        f"Espera entre tiradas: <b>{_v133_sec_label(int(cfg.get('tarot_cooldown_sec', 0) or 0))}</b>\n"
        f"Estado actual: <b>{h(active_text)}</b>\n\n"
        '<b>Tamaño de imágenes</b>\n'
        f"Cartas: <b>{h(_v133_size_label(str(cfg.get('tarot_image_size', 'medium'))))}</b>"
    )

_old_v133_tarot_settings_markup = _v132_tarot_settings_markup

def _v132_tarot_settings_markup(chat_id: int) -> InlineKeyboardMarkup:  # type: ignore[override]
    old = _old_v133_tarot_settings_markup(chat_id)
    rows = [list(r) for r in getattr(old, 'inline_keyboard', [])]
    # Insertamos antes del ranking/volver si están al final.
    insert_at = max(0, len(rows)-2)
    extra = [
        [InlineKeyboardButton('⏳ Bloqueo partida', callback_data=f't33|lock|{chat_id}')],
        [InlineKeyboardButton('⌛ Espera entre tiradas', callback_data=f't33|cool|{chat_id}')],
        [InlineKeyboardButton('🖼 Tamaño cartas', callback_data=f't33|size|{chat_id}')],
    ]
    rows = rows[:insert_at] + extra + rows[insert_at:]
    return InlineKeyboardMarkup(rows)


def _v133_lock_markup(chat_id: int) -> InlineKeyboardMarkup:
    vals = [('OFF',0),('1m',60),('2m',120),('5m',300),('10m',600),('15m',900)]
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(label, callback_data=f't33|setlock|{chat_id}|{sec}') for label,sec in vals[:3]],
        [InlineKeyboardButton(label, callback_data=f't33|setlock|{chat_id}|{sec}') for label,sec in vals[3:]],
        [InlineKeyboardButton('🔓 Liberar bloqueo actual', callback_data=f't33|free|{chat_id}')],
        [InlineKeyboardButton('🔙 Tarot', callback_data=f't32|main|{chat_id}')],
    ])


def _v133_cool_markup(chat_id: int) -> InlineKeyboardMarkup:
    vals = [('OFF',0),('30s',30),('1m',60),('2m',120),('5m',300),('10m',600)]
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(label, callback_data=f't33|setcool|{chat_id}|{sec}') for label,sec in vals[:3]],
        [InlineKeyboardButton(label, callback_data=f't33|setcool|{chat_id}|{sec}') for label,sec in vals[3:]],
        [InlineKeyboardButton('🔙 Tarot', callback_data=f't32|main|{chat_id}')],
    ])


def _v133_size_markup(chat_id: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton('Pequeñas', callback_data=f't33|setsize|{chat_id}|small'), InlineKeyboardButton('Medianas', callback_data=f't33|setsize|{chat_id}|medium'), InlineKeyboardButton('Grandes', callback_data=f't33|setsize|{chat_id}|large')],
        [InlineKeyboardButton('🔙 Tarot', callback_data=f't32|main|{chat_id}')],
    ])


def _v133_lock_text(chat_id: int) -> str:
    cfg = _v133_tarot_cfg(chat_id)
    return (
        '<b>⏳ Bloqueo de partida Tarot</b>\n\n'
        'Mientras alguien tenga una tirada abierta, puedes bloquear que otra persona abra otra.\n'
        'El tiempo sirve también para desbloquear automáticamente si alguien deja el juego a medias.\n\n'
        f"Actual: <b>{_v133_sec_label(int(cfg.get('tarot_active_lock_sec', 0) or 0))}</b>"
    )


def _v133_cool_text(chat_id: int) -> str:
    cfg = _v133_tarot_cfg(chat_id)
    return (
        '<b>⌛ Espera entre tiradas Tarot</b>\n\n'
        'Tiempo mínimo entre una tirada terminada y la siguiente.\n\n'
        f"Actual: <b>{_v133_sec_label(int(cfg.get('tarot_cooldown_sec', 0) or 0))}</b>"
    )


def _v133_size_text(chat_id: int) -> str:
    cfg = _v133_tarot_cfg(chat_id)
    w,h = _v133_size_dims(chat_id)
    return (
        '<b>🖼 Tamaño de imágenes Tarot</b>\n\n'
        'Afecta a las imágenes que subas como PNG/JPG, sobre todo si las mandas como documento.\n'
        'Si ya tenías cartas subidas, vuelve a subirlas para que se reduzcan con el nuevo tamaño.\n\n'
        f"Actual: <b>{h(_v133_size_label(str(cfg.get('tarot_image_size', 'medium'))))}</b> · aprox. <b>{w}x{h}px</b>"
    )


async def _v133_settings_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('t33|'):
        return
    parts = (q.data or '').split('|')
    action = parts[1] if len(parts)>1 else ''
    try:
        chat_id = int(parts[2])
        cfg = _v133_tarot_cfg(chat_id)
        if action == 'lock':
            await q.answer(); await _v132_edit(q, _v133_lock_text(chat_id), _v133_lock_markup(chat_id)); raise _V133Stop
        if action == 'cool':
            await q.answer(); await _v132_edit(q, _v133_cool_text(chat_id), _v133_cool_markup(chat_id)); raise _V133Stop
        if action == 'size':
            await q.answer(); await _v132_edit(q, _v133_size_text(chat_id), _v133_size_markup(chat_id)); raise _V133Stop
        if action == 'setlock':
            cfg['tarot_active_lock_sec'] = int(parts[3]); save_all_states()
            await q.answer('Bloqueo actualizado ✅')
            await _v132_edit(q, _v133_lock_text(chat_id), _v133_lock_markup(chat_id)); raise _V133Stop
        if action == 'setcool':
            cfg['tarot_cooldown_sec'] = int(parts[3]); save_all_states()
            await q.answer('Espera actualizada ✅')
            await _v132_edit(q, _v133_cool_text(chat_id), _v133_cool_markup(chat_id)); raise _V133Stop
        if action == 'setsize':
            size = parts[3]
            if size not in ('small','medium','large'):
                size = 'medium'
            cfg['tarot_image_size'] = size; save_all_states()
            await q.answer('Tamaño actualizado ✅')
            await _v132_edit(q, _v133_size_text(chat_id), _v133_size_markup(chat_id)); raise _V133Stop
        if action == 'free':
            cfg['tarot_active_until_ts'] = 0
            cfg['tarot_active_user_id'] = 0
            save_all_states()
            await q.answer('Bloqueo liberado ✅')
            await _v132_edit(q, _v133_lock_text(chat_id), _v133_lock_markup(chat_id)); raise _V133Stop
    except _V133Stop:
        raise
    except Exception:
        logger.exception('Error router Tarot V133: %s', q.data)
        try: await q.answer('Error Tarot. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V133Stop


# Redimensionado configurable. También intenta reducir fotos normales para que las cartas no sean enormes.
async def _v133_resize_to_photo_id(context: ContextTypes.DEFAULT_TYPE, update: Update, src_file_id: str, chat_id: int, *, caption: str = '✅ Imagen recibida y ajustada para Tarot.') -> Optional[str]:
    try:
        from PIL import Image
        from io import BytesIO
        tgfile = await context.bot.get_file(src_file_id)
        raw = BytesIO()
        await tgfile.download_to_memory(raw)
        raw.seek(0)
        img = Image.open(raw).convert('RGB')
        img.thumbnail(_v133_size_dims(chat_id))
        out = BytesIO()
        out.name = 'tarot_card.jpg'
        img.save(out, format='JPEG', quality=88, optimize=True)
        out.seek(0)
        sent = await context.bot.send_photo(update.effective_chat.id, photo=out, caption=caption)
        try:
            await asyncio.sleep(2)
            await context.bot.delete_message(update.effective_chat.id, sent.message_id)
        except Exception:
            pass
        return sent.photo[-1].file_id if sent.photo else None
    except Exception:
        logger.exception('No pude redimensionar imagen de Tarot V133')
        return None


async def _v132_resize_document_to_photo(context: ContextTypes.DEFAULT_TYPE, update: Update) -> Optional[str]:  # type: ignore[override]
    doc = update.message.document
    if not doc:
        return None
    mime = (doc.mime_type or '').lower()
    fname = (doc.file_name or '').lower()
    if not (mime.startswith('image/') or fname.endswith(('.png','.jpg','.jpeg','.webp'))):
        return None
    pending = get_config_pending(update.effective_user.id) if update.effective_user else None
    chat_id = int((pending or {}).get('chat_id') or 0)
    return await _v133_resize_to_photo_id(context, update, doc.file_id, chat_id) or doc.file_id


_old_v133_upload_image = _v132_tarot_upload_image
async def _v132_tarot_upload_image(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    # Override para que las fotos normales también se reduzcan según pequeño/mediano/grande.
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'tarot_image_upload_v132':
        return
    chat_id = int(pending.get('chat_id') or 0)
    if update.message.photo:
        resized = await _v133_resize_to_photo_id(context, update, update.message.photo[-1].file_id, chat_id)
        if resized:
            # Simulamos el guardado directamente para evitar que el handler viejo use la foto grande.
            target=str(pending.get('target'))
            imgs=_v130_tarot_images(chat_id)
            if target in ('start','back'):
                imgs[target]=resized
                label='inicio/lobby' if target=='start' else 'reverso/barajeo'
            elif target=='card':
                cid=str(pending.get('card_id'))
                imgs.setdefault('cards', {})[cid]=resized
                card=next((c for c in TAROT_CARDS_V129 if c['id']==cid), {'name':cid})
                label=f"{_v130_card_number(cid)} · {card['name']}"
            else:
                await update.message.reply_html('Destino de imagen no válido.')
                pop_config_pending(update.effective_user.id)
                raise _V133Stop
            save_all_states(); pop_config_pending(update.effective_user.id)
            await update.message.reply_html(f'✅ Guardada imagen de <b>{h(label)}</b> en tamaño <b>{h(_v133_size_label(str(_v133_tarot_cfg(chat_id).get("tarot_image_size", "medium"))))}</b>.')
            raise _V133Stop
    return await _old_v133_upload_image(update, context)


# Intercepta el inicio/final del juego para aplicar bloqueo y espera.
_old_v133_tarot_callback = _v129_tarot_callback
async def _v133_tarot_start_finish_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not q.from_user:
        return
    data = q.data or ''
    if not data.startswith('tar|'):
        return
    parts = data.split('|')
    action = parts[1] if len(parts)>1 else ''
    chat_id = int(update.effective_chat.id)
    user = q.from_user
    if action == 'start':
        locked, reason = _v133_is_chat_locked(chat_id, int(user.id))
        if locked:
            await q.answer(reason, show_alert=True)
            raise _V133Stop
        # Aplicamos marca antes de delegar al start original para evitar doble click simultáneo.
        _v133_mark_tarot_started(chat_id, int(user.id))
        try:
            await _old_v133_tarot_callback(update, context)
        except Exception as e:
            # Si no era Stop, libera bloqueo por error real.
            if not isinstance(e, _V133Stop):
                cfg = _v133_tarot_cfg(chat_id); cfg['tarot_active_until_ts']=0; cfg['tarot_active_user_id']=0; save_all_states()
            raise
        raise _V133Stop
    if action == 'final':
        try:
            await _old_v133_tarot_callback(update, context)
        finally:
            _v133_mark_tarot_finished(chat_id)
        raise _V133Stop


_old_build_application_v133 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v133()
    app.add_handler(CallbackQueryHandler(_v133_settings_router, pattern=r'^t33\|'), group=-7400000000)
    app.add_handler(CallbackQueryHandler(_v133_tarot_start_finish_router, pattern=r'^tar\|(start|final)\|?'), group=-7400000000)
    # Re-registra el upload con la versión que reduce fotos normales y docs.
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.PHOTO | filters.Document.IMAGE), _v132_tarot_upload_image), group=-7400000001)
    logger.info('V133 Tarot bloqueo/cooldown e imágenes pequeñas/medianas/grandes cargado')
    return app



# =========================================================
# V134 - Tarot: tamaño visible real, menú tamaño corregido y fotos compactas
# =========================================================
# Cambios:
# - Corrige el botón "Tamaño cartas" que fallaba por sombrear h() con variable h.
# - Añade tamaño "Compacta": se ve mucho más baja en el chat y se puede ampliar tocando la imagen.
# - Procesa imágenes ya guardadas al mostrarlas, no solo al subirlas.
# - PNG/JPG enviados como foto o documento se guardan usando el tamaño elegido.

try:
    from telegram.ext import ApplicationHandlerStop as _V134Stop
except Exception:
    _V134Stop = Exception


def _v134_size_options() -> list[tuple[str, str]]:
    return [
        ('compact', 'Compacta'),
        ('small', 'Pequeña'),
        ('medium', 'Mediana'),
        ('large', 'Grande'),
    ]


def _v133_size_label(size: str) -> str:  # type: ignore[override]
    return dict(_v134_size_options()).get(str(size or 'compact'), 'Compacta')


def _v133_size_dims(chat_id: int) -> tuple[int, int]:  # type: ignore[override]
    cfg = _v133_tarot_cfg(chat_id)
    size = str(cfg.get('tarot_image_size', 'compact') or 'compact')
    # Compacta es paisaje: Telegram la muestra más bajita; dentro se ve la carta reducida.
    if size == 'compact':
        return (900, 520)
    if size == 'small':
        return (420, 620)
    if size == 'large':
        return (700, 1000)
    return (520, 760)


def _v134_is_compact(chat_id: int) -> bool:
    return str(_v133_tarot_cfg(chat_id).get('tarot_image_size', 'compact') or 'compact') == 'compact'


def _v133_size_text(chat_id: int) -> str:  # type: ignore[override]
    cfg = _v133_tarot_cfg(chat_id)
    w, hh = _v133_size_dims(chat_id)
    return (
        '<b>🖼 Tamaño de imágenes Tarot</b>\n\n'
        'El tamaño <b>Compacta</b> crea una imagen más baja en el chat, con la carta reducida dentro. '
        'Al tocarla, Telegram la abre ampliada.\n\n'
        'Esto afecta al lobby, reverso/barajeo y cartas. También funciona con imágenes ya subidas porque el bot las procesa al mostrarlas.\n\n'
        f"Actual: <b>{h(_v133_size_label(str(cfg.get('tarot_image_size', 'compact'))))}</b> · aprox. <b>{w}x{hh}px</b>"
    )


def _v133_size_markup(chat_id: int) -> InlineKeyboardMarkup:  # type: ignore[override]
    cfg = _v133_tarot_cfg(chat_id)
    current = str(cfg.get('tarot_image_size', 'compact') or 'compact')
    rows = []
    opts = _v134_size_options()
    rows.append([
        InlineKeyboardButton(('✅ ' if current == 'compact' else '') + 'Compacta', callback_data=f't34|setsize|{chat_id}|compact'),
        InlineKeyboardButton(('✅ ' if current == 'small' else '') + 'Pequeña', callback_data=f't34|setsize|{chat_id}|small'),
    ])
    rows.append([
        InlineKeyboardButton(('✅ ' if current == 'medium' else '') + 'Mediana', callback_data=f't34|setsize|{chat_id}|medium'),
        InlineKeyboardButton(('✅ ' if current == 'large' else '') + 'Grande', callback_data=f't34|setsize|{chat_id}|large'),
    ])
    rows.append([InlineKeyboardButton('🔙 Tarot', callback_data=f't32|main|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v134_processed_image_from_file_id(context: ContextTypes.DEFAULT_TYPE, chat_id: int, file_id: str):
    """Devuelve BytesIO con el formato elegido. En compacta: carta pequeña centrada en lienzo paisaje."""
    if not file_id:
        return None
    try:
        from PIL import Image, ImageFilter
        from io import BytesIO
        tgfile = await context.bot.get_file(file_id)
        raw = BytesIO()
        await tgfile.download_to_memory(raw)
        raw.seek(0)
        img = Image.open(raw).convert('RGB')
        target_w, target_h = _v133_size_dims(chat_id)

        if _v134_is_compact(chat_id):
            # Lienzo horizontal para que en Telegram no ocupe media pantalla de alto.
            canvas = Image.new('RGB', (target_w, target_h), (18, 12, 32))
            # Fondo suave con la propia imagen desenfocada.
            bg = img.copy()
            bg.thumbnail((target_w, target_h))
            bg2 = Image.new('RGB', (target_w, target_h), (18, 12, 32))
            xbg = (target_w - bg.width) // 2
            ybg = (target_h - bg.height) // 2
            bg2.paste(bg, (xbg, ybg))
            try:
                bg2 = bg2.filter(ImageFilter.GaussianBlur(12))
                canvas = Image.blend(canvas, bg2, 0.35)
            except Exception:
                pass
            card = img.copy()
            # La carta ocupa aprox la mitad/largo cómodo, similar a lo que pedías.
            card.thumbnail((int(target_w * 0.52), int(target_h * 0.92)))
            x = (target_w - card.width) // 2
            y = (target_h - card.height) // 2
            canvas.paste(card, (x, y))
            out_img = canvas
        else:
            img.thumbnail((target_w, target_h))
            out_img = img

        out = BytesIO()
        out.name = 'tarot_elplan.jpg'
        out_img.save(out, format='JPEG', quality=88, optimize=True)
        out.seek(0)
        return out
    except Exception:
        logger.exception('No pude procesar imagen Tarot V134')
        return file_id


async def _v134_send_photo_or_text(bot, chat_id: int, photo, caption: str, markup=None):
    if photo:
        return await bot.send_photo(chat_id, photo=photo, caption=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
    return await bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=markup)


async def _v130_send_lobby(bot, chat_id: int, user=None):  # type: ignore[override]
    imgs = _v130_tarot_images(chat_id)
    start = str(imgs.get('start') or '')
    if start:
        try:
            # No siempre tenemos context aquí; usamos bot directamente con get_file igual.
            class _Ctx: pass
            ctx = _Ctx(); ctx.bot = bot
            photo = await _v134_processed_image_from_file_id(ctx, chat_id, start)
            return await bot.send_photo(chat_id, photo=photo or start, caption=_v130_lobby_caption(chat_id, user), parse_mode=ParseMode.HTML, reply_markup=_v129_lobby_markup())
        except Exception:
            logger.exception('No se pudo enviar lobby Tarot compacto; uso texto')
    return await bot.send_message(chat_id, _v130_lobby_caption(chat_id, user), parse_mode=ParseMode.HTML, reply_markup=_v129_lobby_markup())


async def _v129_send_pair(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any], *, new_pair: bool = True) -> None:  # type: ignore[override]
    if new_pair:
        await _v129_delete_msg(context.bot, chat_id, session.get('draws_msg_id'))
        await _v129_delete_msg(context.bot, chat_id, session.get('choice_msg_id'))
        session['draws_msg_id'] = 0
        session['choice_msg_id'] = 0
    draws_msg = await context.bot.send_message(chat_id, _v129_draws_text(session), parse_mode=ParseMode.HTML)
    session['draws_msg_id'] = int(draws_msg.message_id)
    try: await register_bot_message(chat_id, draws_msg.message_id)
    except Exception: pass
    imgs = _v130_tarot_images(chat_id)
    back = str(imgs.get('back') or '')
    caption = _v129_choice_text(session, user)
    if back:
        try:
            photo = await _v134_processed_image_from_file_id(context, chat_id, back)
            choice_msg = await context.bot.send_photo(chat_id, photo=photo or back, caption=caption, parse_mode=ParseMode.HTML, reply_markup=_v129_choice_markup())
        except Exception:
            logger.exception('No se pudo enviar reverso Tarot compacto; uso texto')
            choice_msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=_v129_choice_markup())
    else:
        choice_msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=_v129_choice_markup())
    session['choice_msg_id'] = int(choice_msg.message_id)
    try: await register_bot_message(chat_id, choice_msg.message_id)
    except Exception: pass


async def _v129_show_card_result(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any], card: Dict[str, str]) -> None:  # type: ignore[override]
    stage = _v129_stage_name(session)
    caption = (
        f"🔮 <b>{h(stage)}</b>\n"
        f"<b>{_v130_card_number(card.get('id',''))} · {h(card['name'])}</b> {card.get('emoji','')}\n\n"
        f"{h(card['meaning'])}"
    )
    fid = _v130_card_file_id(chat_id, card.get('id',''))
    photo = await _v134_processed_image_from_file_id(context, chat_id, fid) if fid else _v129_card_image(card, stage)
    if session.get('mode') == 'ppf' and int(session.get('stage', 0) or 0) < 2:
        markup = InlineKeyboardMarkup([[InlineKeyboardButton('➡️ Siguiente tirada', callback_data='tar|next')]])
    else:
        markup = InlineKeyboardMarkup([[InlineKeyboardButton('🏁 Ver resultado final', callback_data='tar|final')]])
    try:
        if photo:
            from telegram import InputMediaPhoto
            await context.bot.edit_message_media(
                chat_id=chat_id,
                message_id=int(session.get('choice_msg_id')),
                media=InputMediaPhoto(media=photo, caption=caption, parse_mode=ParseMode.HTML),
                reply_markup=markup,
            )
        else:
            await context.bot.edit_message_text(chat_id=chat_id, message_id=int(session.get('choice_msg_id')), text=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        await _v129_delete_msg(context.bot, chat_id, session.get('choice_msg_id'))
        if photo:
            msg = await context.bot.send_photo(chat_id, photo=photo, caption=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=markup)
        session['choice_msg_id'] = int(msg.message_id)


# Guardado de imágenes: siempre almacena una versión procesada con el tamaño elegido, pero el juego vuelve a ajustar al mostrar si cambias tamaño.
async def _v134_store_uploaded_tarot_image(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'tarot_image_upload_v132':
        return
    chat_id = int(pending.get('chat_id') or 0)
    src_file_id = ''
    if update.message.photo:
        src_file_id = update.message.photo[-1].file_id
    elif update.message.document:
        doc = update.message.document
        mime = (doc.mime_type or '').lower()
        fname = (doc.file_name or '').lower()
        if mime.startswith('image/') or fname.endswith(('.png','.jpg','.jpeg','.webp')):
            src_file_id = doc.file_id
    if not src_file_id:
        await update.message.reply_html('❌ Envíame una imagen PNG/JPG como foto o documento.')
        raise _V134Stop
    try:
        processed = await _v134_processed_image_from_file_id(context, chat_id, src_file_id)
        # Para convertir BytesIO en file_id estable, lo enviamos temporalmente al privado y guardamos el file_id resultante.
        if hasattr(processed, 'read'):
            sent = await context.bot.send_photo(update.effective_chat.id, photo=processed, caption='✅ Imagen recibida y ajustada para Tarot.')
            stored_id = sent.photo[-1].file_id if sent.photo else src_file_id
            try:
                await asyncio.sleep(1)
                await context.bot.delete_message(update.effective_chat.id, sent.message_id)
            except Exception:
                pass
        else:
            stored_id = str(processed or src_file_id)
    except Exception:
        logger.exception('No pude guardar imagen Tarot V134; uso original')
        stored_id = src_file_id

    imgs = _v130_tarot_images(chat_id)
    target = str(pending.get('target'))
    if target in ('start','back'):
        imgs[target] = stored_id
        label = 'inicio/lobby' if target == 'start' else 'reverso/barajeo'
    elif target == 'card':
        cid = str(pending.get('card_id'))
        imgs.setdefault('cards', {})[cid] = stored_id
        card = next((c for c in TAROT_CARDS_V129 if c['id'] == cid), {'name': cid})
        label = f"{_v130_card_number(cid)} · {card['name']}"
    else:
        await update.message.reply_html('Destino de imagen no válido.')
        pop_config_pending(update.effective_user.id)
        raise _V134Stop
    save_all_states(); pop_config_pending(update.effective_user.id)
    await update.message.reply_html(
        f'✅ Guardada imagen de <b>{h(label)}</b>.\n'
        f'Tamaño actual: <b>{h(_v133_size_label(str(_v133_tarot_cfg(chat_id).get("tarot_image_size", "compact"))))}</b>.\n\n'
        'Recuerda: si eliges <b>Compacta</b>, se ve más pequeña en el chat y se puede ampliar tocando la imagen.'
    )
    raise _V134Stop


async def _v134_settings_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith(('t33|','t34|')):
        return
    parts = (q.data or '').split('|')
    prefix = parts[0]
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
        cfg = _v133_tarot_cfg(chat_id)
        if action == 'size':
            await q.answer(); await _v132_edit(q, _v133_size_text(chat_id), _v133_size_markup(chat_id)); raise _V134Stop
        if action == 'setsize':
            size = parts[3] if len(parts) > 3 else 'compact'
            if size not in ('compact','small','medium','large'):
                size = 'compact'
            cfg['tarot_image_size'] = size; save_all_states()
            await q.answer('Tamaño actualizado ✅', show_alert=False)
            await _v132_edit(q, _v133_size_text(chat_id), _v133_size_markup(chat_id)); raise _V134Stop
        # El resto se lo dejamos al router V133, pero como este va antes, reimplementamos básico para no chocar con el bug.
        if action == 'lock':
            await q.answer(); await _v132_edit(q, _v133_lock_text(chat_id), _v133_lock_markup(chat_id)); raise _V134Stop
        if action == 'cool':
            await q.answer(); await _v132_edit(q, _v133_cool_text(chat_id), _v133_cool_markup(chat_id)); raise _V134Stop
        if action == 'setlock':
            cfg['tarot_active_lock_sec'] = int(parts[3]); save_all_states(); await q.answer('Bloqueo actualizado ✅'); await _v132_edit(q, _v133_lock_text(chat_id), _v133_lock_markup(chat_id)); raise _V134Stop
        if action == 'setcool':
            cfg['tarot_cooldown_sec'] = int(parts[3]); save_all_states(); await q.answer('Espera actualizada ✅'); await _v132_edit(q, _v133_cool_text(chat_id), _v133_cool_markup(chat_id)); raise _V134Stop
        if action == 'free':
            cfg['tarot_active_until_ts'] = 0; cfg['tarot_active_user_id'] = 0; save_all_states(); await q.answer('Bloqueo liberado ✅'); await _v132_edit(q, _v133_lock_text(chat_id), _v133_lock_markup(chat_id)); raise _V134Stop
    except _V134Stop:
        raise
    except Exception:
        logger.exception('Error router Tarot V134: %s', q.data)
        try: await q.answer('Error Tarot. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V134Stop


_old_build_application_v134 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v134()
    # Prioridad mayor que V133 para corregir tamaño y upload.
    app.add_handler(CallbackQueryHandler(_v134_settings_router, pattern=r'^(t33|t34)\|'), group=-7500000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.PHOTO | filters.Document.IMAGE), _v134_store_uploaded_tarot_image), group=-7500000001)
    logger.info('V134 Tarot tamaño compacto real y ajuste de imágenes cargado')
    return app



# =========================================================
# V135 - Tarot: elimina doble apertura /tarot y mejora taco-aleatoriedad
# =========================================================
# El problema era que existían varios CommandHandler('/tarot') acumulados de versiones
# anteriores. Este handler va el primero y corta la propagación con ApplicationHandlerStop.

try:
    from telegram.ext import ApplicationHandlerStop as _V135Stop
except Exception:
    _V135Stop = Exception


def _v135_mystic_shuffle_deck(chat_id: int, user_id: int) -> list[str]:
    """Barajado fuerte y no determinista para los 22 arcanos.

    No es predictivo: mezcla secrets.SystemRandom varias veces con ruido de tiempo,
    usuario y grupo. Lo de las fuerzas/almas es el tono del juego; técnicamente usa
    aleatoriedad segura del sistema.
    """
    deck = [c['id'] for c in TAROT_CARDS_V129]
    rng = secrets.SystemRandom()
    # Varias pasadas para evitar cualquier orden residual.
    for _ in range(7):
        rng.shuffle(deck)
    # Corte místico: mueve una parte aleatoria arriba/abajo.
    if deck:
        cut = rng.randrange(len(deck))
        deck = deck[cut:] + deck[:cut]
        if rng.choice([True, False]):
            deck.reverse()
        for _ in range(rng.randrange(3, 9)):
            a = rng.randrange(len(deck)); b = rng.randrange(len(deck))
            deck[a], deck[b] = deck[b], deck[a]
    return deck


_old_v135_tarot_lobby_text = _v129_lobby_text

def _v129_lobby_text(chat_id: int, user=None) -> str:  # type: ignore[override]
    base = _old_v135_tarot_lobby_text(chat_id, user)
    add = (
        "\n\n🃏 <b>El reverso configurado se usa como taco de cartas</b> durante el barajeo."
        "\n✨ Las cartas se eligen con barajado aleatorio real: arcanos, intuición, almas y amores del recuerdo."        
    )
    if 'taco de cartas' in base:
        return base
    return base + add


_old_v135_assets_text = _v130_tarot_assets_text

def _v130_tarot_assets_text(chat_id: int) -> str:  # type: ignore[override]
    txt = _old_v135_assets_text(chat_id)
    txt = txt.replace('Reverso/barajeo', 'Taco/reverso/barajeo')
    txt = txt.replace('Reverso', 'Taco/reverso')
    if 'taco de cartas' not in txt.lower():
        txt += '\n\n🂠 <b>Taco/reverso/barajeo</b>: es la imagen que se muestra cuando el usuario elige carta de arriba, abajo o cualquiera.'
    return txt


async def tarot_command(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:  # type: ignore[override]
    """Handler único y prioritario de /tarot para evitar doble lobby."""
    if not update.effective_chat or not update.message:
        return
    if update.effective_chat.type == 'private':
        await update.message.reply_html('🔮 Usa <code>/tarot</code> dentro del grupo para jugar al Tarot del Plan.')
        raise _V135Stop
    chat_id = int(update.effective_chat.id)
    if not bool(_v129_tarot_cfg(chat_id).get('tarot_enabled', True)):
        await update.message.reply_text('🔮 El Tarot del Plan está desactivado en este grupo.')
        raise _V135Stop
    # Si hay una sesión abierta y el bloqueo está activo, respeta la config.
    try:
        locked, reason = _v133_is_chat_locked(chat_id, int(update.effective_user.id))
        if locked:
            await update.message.reply_text(reason)
            raise _V135Stop
    except Exception:
        pass
    await _v130_send_lobby(context.bot, chat_id, update.effective_user)
    raise _V135Stop


_old_v135_tarot_callback = _v129_tarot_callback

async def _v135_tarot_callback_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Start del tarot con barajado V135 y corte de propagación.

    Para el resto de acciones delega al router vigente, pero corta siempre para que no
    entren routers antiguos acumulados.
    """
    q = update.callback_query
    if not q or not update.effective_chat:
        return
    data = q.data or ''
    if not data.startswith('tar|'):
        return
    parts = data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    chat_id = int(update.effective_chat.id)
    user = q.from_user
    try:
        if action == 'start':
            mode = parts[2] if len(parts) > 2 else 'day'
            if mode not in ('ppf','day'):
                mode = 'day'
            try:
                locked, reason = _v133_is_chat_locked(chat_id, int(user.id))
                if locked:
                    await q.answer(reason, show_alert=True)
                    raise _V135Stop
                _v133_mark_tarot_started(chat_id, int(user.id))
            except _V135Stop:
                raise
            except Exception:
                pass
            ok, reason = _v129_can_play(chat_id, int(user.id), mode)
            if not ok:
                await q.answer(reason, show_alert=True)
                raise _V135Stop
            skey = _v129_session_key(chat_id, int(user.id))
            session = {
                'chat_id': chat_id,
                'user_id': int(user.id),
                'mode': mode,
                'stage': 0,
                'draws': [],
                'deck': _v135_mystic_shuffle_deck(chat_id, int(user.id)),
                'started_ts': int(time.time()),
            }
            TAROT_SESSIONS_V129[skey] = session
            await q.answer('Barajando el taco…')
            try:
                await q.edit_message_caption(
                    caption=f'🔮 {user.mention_html()} está barajando el taco de cartas…\n✨ Que hablen los arcanos.',
                    parse_mode=ParseMode.HTML,
                    reply_markup=None,
                )
            except Exception:
                try:
                    await q.edit_message_text(f'🔮 {user.mention_html()} está barajando el taco de cartas…\n✨ Que hablen los arcanos.', parse_mode=ParseMode.HTML)
                except Exception:
                    pass
            await asyncio.sleep(0.8)
            await _v129_send_pair(context, chat_id, user, session, new_pair=True)
            raise _V135Stop
        # Delegamos el resto pero cortamos propagación.
        await _old_v135_tarot_callback(update, context)
        raise _V135Stop
    except _V135Stop:
        raise
    except Exception:
        logger.exception('Error Tarot V135 callback: %s', data)
        try:
            await q.answer('Error en Tarot. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V135Stop


_old_build_application_v135 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v135()
    # Prioridad máxima: evita que /tarot y tar|start pasen a handlers antiguos duplicados.
    app.add_handler(CommandHandler(['tarot','tarotplan'], tarot_command), group=-7600000000)
    app.add_handler(CallbackQueryHandler(_v135_tarot_callback_router, pattern=r'^tar\|'), group=-7600000000)
    logger.info('V135 Tarot sin doble apertura y taco/reverso mejorado cargado')
    return app


# =========================================================
# V136 - Tarot: taco ancho para elegir + imagen de barajeo separada
# =========================================================
# - Separa imagen de inicio/lobby, imagen de barajeo y taco/reverso de elección.
# - El taco/reverso se muestra en formato ancho completo, sin meterlo en lienzo pequeño.
# - /tarot sigue sin duplicarse.

try:
    from telegram.ext import ApplicationHandlerStop as _V136Stop
except Exception:
    _V136Stop = Exception


def _v136_tarot_images(chat_id: int) -> Dict[str, Any]:
    imgs = _v130_tarot_images(chat_id)
    imgs.setdefault('start', '')    # lobby / portada
    imgs.setdefault('shuffle', '')  # barajeo animado/visual
    imgs.setdefault('back', '')     # taco/reverso para elegir carta
    imgs.setdefault('cards', {})
    return imgs


def _v136_img_status(chat_id: int) -> str:
    imgs = _v136_tarot_images(chat_id)
