        [InlineKeyboardButton('🧹 Quitar inicio', callback_data=f't32|del|{chat_id}|start'), InlineKeyboardButton('🧹 Quitar barajeo', callback_data=f't32|del|{chat_id}|shuffle')],
        [InlineKeyboardButton('🧹 Quitar taco/reverso', callback_data=f't32|del|{chat_id}|back')],
