async def _v143_save_image_target(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Handler único para subida de imágenes Tarot: evita duplicados de handlers antiguos."""
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') not in ('tarot_image_upload_v132', 'tarot_image_upload_v130'):
        return
    chat_id = int(pending.get('chat_id') or 0)
    target = str(pending.get('target') or '')
    src = ''
    if update.message.photo:
        src = update.message.photo[-1].file_id
    elif update.message.document:
        src = update.message.document.file_id
    if not src:
        await update.message.reply_html('Necesito una imagen PNG/JPG como foto o documento.')
        raise _V143Stop
    imgs = _v143_tarot_images(chat_id)
    if target in ('start','shuffle','back','result','ai'):
        role = 'choice' if target == 'back' else ('shuffle' if target == 'shuffle' else 'lobby')
        if target in ('result','ai'):
            role = 'card'
        processed = await _v136_processed_tarot_image(context, chat_id, src, role=role) if '_v136_processed_tarot_image' in globals() else src
        try:
            preview = await context.bot.send_photo(update.effective_chat.id, photo=processed or src, caption='✅ Imagen recibida para Tarot.')
            fid = preview.photo[-1].file_id if preview.photo else src
            try:
                await asyncio.sleep(1.2)
                await context.bot.delete_message(update.effective_chat.id, preview.message_id)
            except Exception:
                pass
        except Exception:
            fid = src
        imgs[target] = fid
        label = {'start':'inicio/lobby','shuffle':'barajeo','back':'taco/reverso','result':'resultado final','ai':'opinión IA'}.get(target, target)
    elif target == 'card':
        cid = str(pending.get('card_id'))
        processed = await _v136_processed_tarot_image(context, chat_id, src, role='card') if '_v136_processed_tarot_image' in globals() else src
        try:
            preview = await context.bot.send_photo(update.effective_chat.id, photo=processed or src, caption='✅ Carta recibida para Tarot.')
            fid = preview.photo[-1].file_id if preview.photo else src
            try:
                await asyncio.sleep(1.2)
                await context.bot.delete_message(update.effective_chat.id, preview.message_id)
            except Exception:
                pass
        except Exception:
            fid = src
        imgs.setdefault('cards', {})[cid] = fid
        card = next((c for c in TAROT_CARDS_V129 if c['id'] == cid), {'name': cid})
        label = f"{_v130_card_number(cid)} · {card['name']}"
    else:
        pop_config_pending(update.effective_user.id)
        await update.message.reply_html('Destino de imagen Tarot no válido.')
        raise _V143Stop
    save_all_states(); pop_config_pending(update.effective_user.id)
    await update.message.reply_html(f'✅ Guardada imagen de <b>{h(label)}</b>.')
    raise _V143Stop


async def _v143_tarot_settings_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Router prioritario para Tarot en ajustes. Maneja t32 principales y corta duplicados."""
    q = update.callback_query
    if not q:
        return
    data = q.data or ''
    try:
        # Abrir bloque Tarot desde menú visual.
        if data.startswith('cfg|block|'):
            parts = data.split('|')
            if len(parts) < 4 or parts[3] != 'tarot':
                return
            chat_id = int(parts[2])
            await q.answer()
            await _v132_edit(q, _v132_tarot_settings_text(chat_id), _v132_tarot_settings_markup(chat_id))
            raise _V143Stop
        if not data.startswith('t32|'):
            return
        parts = data.split('|')
        action = parts[1]
        chat_id = int(parts[2]) if len(parts) > 2 else 0
        if action == 'main':
            await q.answer()
            await _v132_edit(q, _v132_tarot_settings_text(chat_id), _v132_tarot_settings_markup(chat_id))
            raise _V143Stop
        if action == 'assets':
            await q.answer()
            await _v132_edit(q, _v132_assets_text(chat_id), _v132_assets_markup(chat_id))
            raise _V143Stop
        if action == 'up':
            target = parts[3]
            set_config_pending(q.from_user.id, {'kind':'tarot_image_upload_v132','chat_id':chat_id,'target':target})
            await q.answer()
            labels = {'start':'inicio/lobby','shuffle':'barajeo','back':'taco/reverso','result':'resultado final','ai':'opinión IA'}
            await q.message.reply_html(f'📸 Envíame ahora la imagen PNG/JPG para <b>{h(labels.get(target, target))}</b>.')
            raise _V143Stop
        if action == 'del':
            target = parts[3]
            if target in ('start','shuffle','back','result','ai'):
                _v143_tarot_images(chat_id)[target] = ''
                save_all_states()
            await q.answer('Imagen quitada ✅')
            await _v132_edit(q, _v132_assets_text(chat_id), _v132_assets_markup(chat_id))
            raise _V143Stop
        if action == 'cards':
            page = int(parts[3]) if len(parts) > 3 else 0
            await q.answer()
            await _v132_edit(q, _v130_cards_upload_text(chat_id, page), _v132_cards_markup(chat_id, page))
            raise _V143Stop
        if action == 'upc':
            cid = parts[3]
            card = next((c for c in TAROT_CARDS_V129 if c['id'] == cid), None)
            if not card:
                await q.answer('Carta inválida', show_alert=True); raise _V143Stop
            set_config_pending(q.from_user.id, {'kind':'tarot_image_upload_v132','chat_id':chat_id,'target':'card','card_id':cid})
            await q.answer()
            await q.message.reply_html(f"📸 Envíame la imagen PNG/JPG de <b>{_v130_card_number(cid)} · {h(card['name'])}</b>.")
            raise _V143Stop
        # resto t32 lo dejamos a routers existentes, pero no duplicamos aquí
    except _V143Stop:
        raise
    except Exception:
        logger.exception('Error router Tarot V143: %s', data)
        try: await q.answer('Error Tarot. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V143Stop


# Resultado final con imagen decorativa si está configurada.
async def _v129_show_final(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any]) -> None:  # type: ignore[override]
    draws = session.get('draws', [])
    if not draws:
        return
    if bool(_v137_tarot_cfg(chat_id).get('tarot_keep_only_final', True)):
        try:
            await _v137_delete_intermediate(context, chat_id, session, include_result=False)
        except Exception:
            pass
    for mid in list(session.get('extra_msg_ids', []) or []):
        try: await _v129_delete_msg(context.bot, chat_id, mid)
        except Exception: pass
    result_id = secrets.token_hex(4)
    session['result_id'] = result_id
    cfg = _v129_tarot_cfg(chat_id)
    cfg.setdefault('tarot_results', {})[result_id] = {
        'user_id': int(user.id), 'user_name': display_name(user), 'mode': session.get('mode','day'),
        'cards': [c['id'] for c in draws], 'likes': [], 'ts': int(time.time()),
    }
    save_all_states()
    text = _v138_result_text(user, session, draws) if '_v138_result_text' in globals() else _v129_result_text(user, session, draws)
    rows = [[InlineKeyboardButton('🃏 Ver cartas', callback_data=f'tar|showdraw|{result_id}'), InlineKeyboardButton('💾 Guardar resumen', callback_data=f'tar|save|{result_id}')]]
    if bool(_v139_tarot_cfg(chat_id).get('tarot_ai_enabled', True)):
        rows.insert(0, [InlineKeyboardButton('🔮 Opinión de tarotista IA', callback_data=f'tar|ai|{result_id}')])
    img = str(_v143_tarot_images(chat_id).get('result') or '')
    if img:
        try:
            msg = await context.bot.send_photo(chat_id, photo=img, caption=text[:1000], parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(rows))
        except Exception:
            logger.exception('No pude enviar resultado Tarot con imagen; uso texto')
            msg = await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(rows))
    else:
        msg = await context.bot.send_message(chat_id, text, parse_mode=ParseMode.HTML, reply_markup=InlineKeyboardMarkup(rows))
    session['final_msg_id'] = int(msg.message_id)
    try: _v129_inc_usage(chat_id, int(user.id), session.get('mode','day'))
    except Exception: pass
    try: _v133_mark_tarot_finished(chat_id)
    except Exception: pass
    sec = _v132_cleanup_get(chat_id, 'tarot_cleanup_result_sec', 0) if '_v132_cleanup_get' in globals() else 0
    if sec:
        asyncio.create_task(_v132_auto_delete(context.bot, chat_id, int(session.get('final_msg_id')), sec))


async def _v143_tarot_ai_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|ai|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = q.data.split('|', 2)[2]
    cfg = _v139_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid)
    if not isinstance(res, dict):
        await q.answer('No encuentro esa tirada.', show_alert=True); raise _V143Stop
    ok, reason = _v139_can_use_ai(chat_id, int(q.from_user.id)) if '_v139_can_use_ai' in globals() else (True, '')
    if not ok:
        await q.answer(reason, show_alert=True); raise _V143Stop
    cards = []
    for cid in res.get('cards', []) or []:
        c = _v138_card_by_id(cid) if '_v138_card_by_id' in globals() else next((x for x in TAROT_CARDS_V129 if x['id'] == cid), None)
        if c: cards.append(c)
    if not cards:
        await q.answer('Esta tirada no tiene cartas guardadas.', show_alert=True); raise _V143Stop
    user_name = str(res.get('user_name') or 'la persona que hizo la tirada')
    await q.answer('Consultando al tarotista IA…')
    labels = ['Pasado','Presente','Futuro'] if len(cards) == 3 else ['Carta del día']
    card_lines = []
    for label, c in zip(labels, cards):
        card_lines.append(f"{label}: {c.get('name')} ({c.get('short')}). Significado base: {c.get('meaning')}")
    prompt = (
        'Actúa como un tarotista profesional, cercano, elegante y claro. '
        f'La persona consultante es {user_name}; si no encaja mencionar el nombre, habla de forma neutra como “la persona consultante”. '
        'No digas que EL PLAN consulta ni que el bot consulta. '
        'Interpreta esta tirada de forma simbólica, sin afirmar certezas absolutas ni hacer predicciones médicas, legales o peligrosas. '
        'Explica cómo se relacionan las cartas, qué energía trae cada una y qué consejo práctico puede extraer. '
        'Tono místico, humano y fácil de entender.\n\n' + '\n'.join(card_lines)
    )
    wait = None
    try:
        wait = await q.message.reply_html(f'🔮 Consultando al tarotista IA para <b>{h(user_name)}</b>…')
        ans = await (_v57_cerebrito_answer(chat_id, prompt, max_output_tokens=900) if '_v57_cerebrito_answer' in globals() else _ai_openai_response(chat_id, prompt, max_output_tokens=900))
        text = '🔮 <b>Opinión del tarotista IA</b>\n\n' + h(ans[:3500])
        img = str(_v143_tarot_images(chat_id).get('ai') or '')
        if img:
            try:
                await wait.delete()
            except Exception:
                pass
            sent = await context.bot.send_photo(chat_id, photo=img, caption=text[:1000], parse_mode=ParseMode.HTML)
        else:
            await wait.edit_text(text, parse_mode=ParseMode.HTML)
            sent = wait
        try: _v139_ai_inc(chat_id, int(q.from_user.id))
        except Exception: pass
        sec = int(cfg.get('tarot_cleanup_ai_sec', 0) or 0)
        if sec and getattr(sent, 'message_id', None):
            asyncio.create_task(_v139_auto_delete(context.bot, chat_id, int(sent.message_id), sec))
    except Exception as e:
        logger.exception('Error Opinión tarotista IA V143')
        if wait:
            try: await wait.edit_text(f'❌ Error IA: {type(e).__name__}')
            except Exception: pass
        else:
            await q.answer('Error IA. Revisa logs.', show_alert=True)
    raise _V143Stop


_old_build_application_v143 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v143()
    app.add_handler(CallbackQueryHandler(_v143_tarot_settings_router, pattern=r'^(cfg\|block\|-?\d+\|tarot$|t32\|)'), group=-8400000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.PHOTO | filters.Document.IMAGE), _v143_save_image_target), group=-8400000001)
    app.add_handler(CallbackQueryHandler(_v143_tarot_ai_router, pattern=r'^tar\|ai\|'), group=-8400000000)
    logger.info('V143 Tarot lobby corto, imágenes resultado/IA y router sin duplicados cargado')
    return app


