def _v144_tarot_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = _v141_tarot_cfg(chat_id) if '_v141_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)
    cfg.setdefault('tarot_shuffle_magic_emojis_html', '')
    return cfg


def _v144_magic_emojis(chat_id: int) -> str:
    raw = str(_v144_tarot_cfg(chat_id).get('tarot_shuffle_magic_emojis_html') or '').strip()
    return raw[:500]


def _v129_choice_markup() -> InlineKeyboardMarkup:  # type: ignore[override]
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton('🌙 PRIMERA', callback_data='tar|pick|top'),
            InlineKeyboardButton('👁 ALEATORIO', callback_data='tar|pick|any'),
            InlineKeyboardButton('🕯 ÚLTIMA', callback_data='tar|pick|bottom'),
        ]
    ])


def _v144_next_stage_label(session: Dict[str, Any]) -> str:
    # El botón aparece después de mostrar la carta de la etapa actual.
    # stage 0 mostrado = Pasado, siguiente = Presente. stage 1 mostrado = Presente, siguiente = Futuro.
    stage = int(session.get('stage', 0) or 0)
    if stage <= 0:
        return '🔥 PRESENTE'
    if stage == 1:
        return '✨ FUTURO'
    return '🔮 CONTINUAR'


def _v144_card_extra(card: Dict[str, str], stage: str) -> str:
    name = str(card.get('name') or 'La carta')
    meaning = str(card.get('meaning') or card.get('short') or '')
    if stage.lower().startswith('pasado'):
        return f"Esta carta habla de una energía que viene de atrás. {name} señala aquello que todavía influye en el presente: aprendizajes, heridas, decisiones o deseos que no se han apagado del todo. No aparece para quedarse en el pasado, sino para mostrar qué parte de esa historia sigue empujando la tirada."
    if stage.lower().startswith('presente'):
        return f"En el presente, {name} marca el clima real de este momento. Puede señalar una actitud, una tensión, una oportunidad o una señal que conviene mirar sin prisas. La carta invita a observar qué está pasando ahora y qué papel está tomando la persona consultante dentro de esa energía."
    if stage.lower().startswith('futuro'):
        return f"Mirando hacia el futuro, {name} no dicta una sentencia cerrada: muestra una tendencia. Habla de hacia dónde puede moverse la situación si se mantiene la energía actual. Es una advertencia suave, una pista o una puerta abierta para actuar con más conciencia."
    return f"{name} trae una energía clara para hoy. {meaning} Su mensaje no busca dar una respuesta absoluta, sino abrir una intuición: qué conviene mirar, qué se está moviendo por dentro y qué pequeño gesto puede ayudar a vivir el día con más claridad."


async def _v129_show_card_result(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any], card: Dict[str, str]) -> None:  # type: ignore[override]
    stage = _v129_stage_name(session)
    extra = _v144_card_extra(card, stage)
    caption = (
        f"🔮 <b>{h(stage)}</b>\n"
        f"<b>{_v130_card_number(card.get('id','')) if '_v130_card_number' in globals() else h(card.get('id',''))} · {h(card['name'])}</b> {card.get('emoji','')}\n\n"
        f"{h(card['meaning'])}\n\n"
        f"{h(extra)}"
    )
    if session.get('mode') == 'ppf' and int(session.get('stage', 0) or 0) < 2:
        markup = InlineKeyboardMarkup([[InlineKeyboardButton(_v144_next_stage_label(session), callback_data='tar|next')]])
    else:
        markup = InlineKeyboardMarkup([[InlineKeyboardButton('🏁 VER RESULTADO FINAL', callback_data='tar|final')]])
    photo = _v130_card_photo(chat_id, card, stage) if '_v130_card_photo' in globals() else None
    try:
        if photo:
            from telegram import InputMediaPhoto
            await context.bot.edit_message_media(
                chat_id=chat_id,
                message_id=int(session.get('choice_msg_id')),
                media=InputMediaPhoto(media=photo, caption=caption[:1000], parse_mode=ParseMode.HTML),
                reply_markup=markup,
            )
        else:
            await context.bot.edit_message_text(chat_id=chat_id, message_id=int(session.get('choice_msg_id')), text=caption, parse_mode=ParseMode.HTML, reply_markup=markup)
    except Exception:
        try:
            await _v129_delete_msg(context.bot, chat_id, session.get('choice_msg_id'))
        except Exception:
            pass
        if photo:
            msg = await context.bot.send_photo(chat_id, photo=photo, caption=caption[:1000], parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=markup)
        session['choice_msg_id'] = int(msg.message_id)


def _v141_shuffle_caption(user, session: Dict[str, Any], seconds: int) -> str:  # type: ignore[override]
    chat_id = int(session.get('chat_id') or 0)
    stage = _v141_stage_for_shuffle(session) if '_v141_stage_for_shuffle' in globals() else _v129_stage_name(session)
    magic = _v144_magic_emojis(chat_id)
    sparkle = f"✨ {magic}" if magic else '✨'
    return (
        f'🔮 <b>Barajando…</b> {sparkle}\n\n'
        f'{user.mention_html()}, las cartas se están mezclando para <b>{h(stage)}</b>.\n\n'
        '🌙 Respira despacio.\n'
        '🕯 Concéntrate en lo que quieres entender.\n'
        '🃏 El taco se mueve, los arcanos se cruzan y algo empieza a colocarse.\n\n'
        f'⏳ En unos <b>{seconds} segundos</b> podrás elegir.\n'
        '👁 No busques la carta perfecta. Deja que ella te encuentre.'
    )


