def _v132_tarot_settings_markup(chat_id: int) -> InlineKeyboardMarkup:  # type: ignore[override]
    rows = [list(r) for r in _old_v144_tarot_settings_markup(chat_id).inline_keyboard]
    insert_at = max(0, len(rows)-1)
    rows.insert(insert_at, [InlineKeyboardButton('✨ Emojis barajeo', callback_data=f't44|emojis|{chat_id}')])
    return InlineKeyboardMarkup(rows)


async def _v144_settings_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('t44|'):
        return
    parts = q.data.split('|')
    action = parts[1] if len(parts) > 1 else ''
    try:
        chat_id = int(parts[2])
        if action == 'emojis':
            set_config_pending(q.from_user.id, {'kind': 'tarot_shuffle_emojis_v144', 'chat_id': chat_id})
            await q.answer()
            await q.message.reply_html(
                '✨ Envíame ahora <b>uno o dos emojis</b> para mostrar junto a ✨ en el barajeo.\n\n'
                'Puedes enviar emojis normales o emojis premium de Telegram.'
            )
            raise _V144Stop
    except _V144Stop:
        raise
    except Exception:
        logger.exception('Error ajustes Tarot V144')
        try:
            await q.answer('Error Tarot. Revisa logs.', show_alert=True)
        except Exception:
            pass
        raise _V144Stop


async def _v144_shuffle_emojis_text_handler(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    if not update.effective_user or not update.message:
        return
    pending = get_config_pending(update.effective_user.id)
    if not pending or pending.get('kind') != 'tarot_shuffle_emojis_v144':
        return
    chat_id = int(pending.get('chat_id') or 0)
    raw = ''
    try:
        raw = telegram_html_from_message(update.message).strip()
    except Exception:
        raw = ''
    if not raw:
        try:
            raw = plain_text_from_message(update.message).strip()
        except Exception:
            raw = (update.message.text or '').strip()
    if not raw:
        await update.message.reply_html('No he detectado emojis. Envíame 1 o 2 emojis.')
        raise _V144Stop
    _v144_tarot_cfg(chat_id)['tarot_shuffle_magic_emojis_html'] = raw[:500]
    save_all_states()
    pop_config_pending(update.effective_user.id)
    await update.message.reply_html('✅ Emojis de barajeo guardados.\n\n' + _v132_tarot_settings_text(chat_id), reply_markup=_v132_tarot_settings_markup(chat_id))
    raise _V144Stop


_old_build_application_v144 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v144()
    app.add_handler(CallbackQueryHandler(_v144_settings_router, pattern=r'^t44\|'), group=-8500000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.TEXT | filters.Caption()) & ~filters.COMMAND, _v144_shuffle_emojis_text_handler), group=-8500000000)
    logger.info('V144 Tarot botones elección, emojis premium barajeo y etapas PASADO/PRESENTE/FUTURO cargado')
    return app


# =========================================================
# V145 - Tarot: textos de carta y resultado más cortos
# =========================================================
# - Carta individual: resumen muy breve, prácticamente lo de la carta + pincelada.
# - Resultado PPF: 3 párrafos, uno por carta, y una interpretación conjunta corta.

try:
    from telegram.ext import ApplicationHandlerStop as _V145Stop
except Exception:
    _V145Stop = Exception


def _v145_stage_plain(stage: str) -> str:
    s = str(stage or '').lower()
    if 'pasado' in s:
        return 'pasado'
    if 'presente' in s:
        return 'presente'
    if 'futuro' in s:
        return 'futuro'
    return 'hoy'


def _v145_card_line(card: Dict[str, str], stage: str = '') -> str:
    name = str(card.get('name') or 'La carta')
    short = str(card.get('short') or card.get('meaning') or '').strip()
    if len(short) > 125:
        short = short[:122].rstrip() + '…'
    st = _v145_stage_plain(stage)
    if st == 'pasado':
        tail = 'Aún deja eco, pero también aprendizaje.'
    elif st == 'presente':
        tail = 'Marca la energía que conviene mirar ahora.'
    elif st == 'futuro':
        tail = 'Señala una tendencia, no una sentencia.'
    else:
        tail = 'Quédate con la señal y actúa con calma.'
    return f'{short} {tail}'.strip()


def _v144_card_extra(card: Dict[str, str], stage: str) -> str:  # type: ignore[override]
    # Mucho más corto que V144: una pincelada, no párrafo largo.
    return _v145_card_line(card, stage)


def _v138_card_full_text(card: Dict[str, str], stage: str = '') -> str:  # type: ignore[override]
    # Si alguna ruta antigua usa este texto, también queda corto.
    meaning = str(card.get('meaning') or card.get('short') or '').strip()
    if len(meaning) > 145:
        meaning = meaning[:142].rstrip() + '…'
    pinch = _v145_card_line(card, stage)
    # Evita repetir casi lo mismo dos veces.
    if pinch.startswith(meaning[:40]):
        return pinch
    return f'{meaning}\n\n{pinch}'.strip()


def _v145_result_paragraph(card: Dict[str, str], label: str, stage: str) -> str:
    name = str(card.get('name') or 'La carta')
    num = _v130_card_number(card.get('id','')) if '_v130_card_number' in globals() else str(card.get('id',''))
    emoji = str(card.get('emoji') or '')
    short = str(card.get('short') or card.get('meaning') or '').strip()
    if len(short) > 135:
        short = short[:132].rstrip() + '…'
    st = _v145_stage_plain(stage)
    if st == 'pasado':
        interp = 'habla de una huella que viene de atrás y que todavía influye en la tirada.'
    elif st == 'presente':
        interp = 'muestra la energía principal del momento y lo que conviene observar ahora.'
    elif st == 'futuro':
        interp = 'marca hacia dónde puede moverse la situación si se mantiene esta energía.'
    else:
        interp = 'deja una señal sencilla para mirar el día con más intuición.'
    return f'{label}: <b>{h(num)} · {h(name)}</b> {emoji}\n{h(short)} {h(interp)}'


def _v138_result_text(user, session: Dict[str, Any], draws: List[Dict[str, str]]) -> str:  # type: ignore[override]
    title = '☀️ <b>CARTA DEL DÍA</b>' if session.get('mode') == 'day' else '🔮 <b>RESULTADO DE LA TIRADA</b>'
    lines = [title, f'Para {user.mention_html()}', '']
    if session.get('mode') == 'ppf':
        labels = [('🕰 Pasado', 'pasado'), ('🔥 Presente', 'presente'), ('✨ Futuro', 'futuro')]
        for (label, stage), c in zip(labels, draws):
            lines.append(_v145_result_paragraph(c, label, stage))
            lines.append('')
        if len(draws) == 3:
            lines.append('<b>Lectura conjunta:</b>')
            lines.append('Los arcanos dibujan un camino: lo que arrastras, lo que vibra ahora y la dirección que se abre. No es sentencia; es una pista para mirar mejor y decidir con más calma.')
    else:
        c = draws[0]
        lines.append(_v145_result_paragraph(c, '☀️ Hoy', 'día'))
        lines.append('')
        lines.append('Tómalo como una señal breve para el día: observa, respira y quédate con lo que te encaje.')
    return '\n'.join(lines)[:2200]


_old_build_application_v145 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v145()
    logger.info('V145 Tarot textos cortos de carta y resultado cargado')
    return app

