# V146 - Tarot: botones elección 2+1 y reacciones a Opinión IA
# =========================================================
try:
    from telegram.ext import ApplicationHandlerStop as _V146Stop
except Exception:
    _V146Stop = Exception


def _v129_choice_markup() -> InlineKeyboardMarkup:  # type: ignore[override]
    """PRIMERA y ÚLTIMA arriba; ALEATORIO ancho debajo."""
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton('🌙 PRIMERA', callback_data='tar|pick|top'),
            InlineKeyboardButton('🕯 ÚLTIMA', callback_data='tar|pick|bottom'),
        ],
        [InlineKeyboardButton('👁 ALEATORIO', callback_data='tar|pick|any')],
    ])


def _v146_ai_store(chat_id: int) -> Dict[str, Any]:
    cfg = _v139_tarot_cfg(chat_id) if '_v139_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)
    store = cfg.setdefault('tarot_ai_opinions', {})
    if not isinstance(store, dict):
        store = {}
        cfg['tarot_ai_opinions'] = store
    return store


def _v146_ai_counts_line(op: Dict[str, Any]) -> str:
    likes = len(op.get('likes') or [])
    flips = len(op.get('flips') or [])
    return f'\n\n❤️ Me gusta: <b>{likes}</b>\n🤯 Flipando estoy: <b>{flips}</b>'


def _v146_ai_base_text(op: Dict[str, Any]) -> str:
    ans = str(op.get('answer') or '').strip()
    if not ans:
        ans = 'La lectura todavía no está disponible.'
    return '🔮 <b>Opinión del tarotista IA</b>\n\n' + h(ans[:3200])


def _v146_ai_full_text(op: Dict[str, Any], *, max_len: int = 3900) -> str:
    text = _v146_ai_base_text(op) + _v146_ai_counts_line(op)
    return text[:max_len]


def _v146_ai_markup(rid: str) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton('❤️ Me gusta', callback_data=f'tar|air|{rid}|like'),
            InlineKeyboardButton('🤯 Flipando estoy', callback_data=f'tar|air|{rid}|flip'),
        ]
    ])


async def _v146_send_or_update_ai_message(context: ContextTypes.DEFAULT_TYPE, chat_id: int, rid: str, op: Dict[str, Any], *, reply_to=None, image_id: str = ''):
    markup = _v146_ai_markup(rid)
    msg_id = int(op.get('message_id') or 0)
    has_photo = bool(op.get('has_photo'))
    if msg_id:
        try:
            if has_photo:
                await context.bot.edit_message_caption(chat_id=chat_id, message_id=msg_id, caption=_v146_ai_full_text(op, max_len=980), parse_mode=ParseMode.HTML, reply_markup=markup)
            else:
                await context.bot.edit_message_text(chat_id=chat_id, message_id=msg_id, text=_v146_ai_full_text(op), parse_mode=ParseMode.HTML, reply_markup=markup)
            return msg_id
        except Exception:
            pass
    if image_id:
        sent = await context.bot.send_photo(chat_id, photo=image_id, caption=_v146_ai_full_text(op, max_len=980), parse_mode=ParseMode.HTML, reply_markup=markup, reply_to_message_id=reply_to)
        op['has_photo'] = True
    else:
        sent = await context.bot.send_message(chat_id, _v146_ai_full_text(op), parse_mode=ParseMode.HTML, reply_markup=markup, reply_to_message_id=reply_to)
        op['has_photo'] = False
    op['message_id'] = int(sent.message_id)
    save_all_states()
    return int(sent.message_id)


async def _v146_tarot_ai_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not q.from_user:
        return
    data = q.data or ''
    if not data.startswith('tar|ai|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = data.split('|', 2)[2]
    cfg = _v139_tarot_cfg(chat_id) if '_v139_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid)
    if not isinstance(res, dict):
        await q.answer('No encuentro esa tirada.', show_alert=True)
        raise _V146Stop
    ok, reason = _v139_can_use_ai(chat_id, int(q.from_user.id)) if '_v139_can_use_ai' in globals() else (True, '')
    store = _v146_ai_store(chat_id)
    cached = store.get(rid)
    # Si ya existe opinión, no gasta otra consulta: muestra/actualiza la existente.
    if isinstance(cached, dict) and cached.get('answer'):
        await q.answer('Opinión ya generada ✅')
        img = str((_v143_tarot_images(chat_id).get('ai') if '_v143_tarot_images' in globals() else '') or '')
        await _v146_send_or_update_ai_message(context, chat_id, rid, cached, reply_to=q.message.message_id if q.message else None, image_id=img)
        raise _V146Stop
    if not ok:
        await q.answer(reason, show_alert=True)
        raise _V146Stop
    cards = []
    for cid in res.get('cards', []) or []:
        c = _v138_card_by_id(cid) if '_v138_card_by_id' in globals() else next((x for x in TAROT_CARDS_V129 if x['id'] == cid), None)
        if c:
            cards.append(c)
    if not cards:
        await q.answer('Esta tirada no tiene cartas guardadas.', show_alert=True)
        raise _V146Stop
    user_name = str(res.get('user_name') or 'la persona que hizo la tirada')
    await q.answer('Consultando al tarotista IA…')
    labels = ['Pasado','Presente','Futuro'] if len(cards) == 3 else ['Carta del día']
    card_lines = []
    for label, c in zip(labels, cards):
        card_lines.append(f"{label}: {c.get('name')} ({c.get('short')}). Significado base: {c.get('meaning')}")
    prompt = (
        'Actúa como un tarotista profesional, cercano, elegante y claro. '
        f'La persona consultante es {user_name}; si no encaja mencionar el nombre, habla de forma neutra como “la persona consultante”. '
        'No digas que EL PLAN consulta ni que el bot consulta. '
        'Interpreta esta tirada de forma simbólica, sin afirmar certezas absolutas ni hacer predicciones médicas, legales o peligrosas. '
        'Explica cómo se relacionan las cartas, qué energía trae cada una y qué consejo práctico puede extraer. '
        'Tono místico, humano y fácil de entender. Sé claro, con una lectura bonita pero no larguísima.\n\n' + '\n'.join(card_lines)
    )
    wait = None
    try:
        wait = await q.message.reply_html(f'🔮 Consultando al tarotista IA para <b>{h(user_name)}</b>…')
        ans = await (_v57_cerebrito_answer(chat_id, prompt, max_output_tokens=900) if '_v57_cerebrito_answer' in globals() else _ai_openai_response(chat_id, prompt, max_output_tokens=900))
        op = {
            'answer': str(ans or '').strip(),
            'likes': [],
            'flips': [],
            'created_ts': int(time.time()),
            'result_id': rid,
            'user_name': user_name,
        }
        store[rid] = op
        try:
            await wait.delete()
        except Exception:
            pass
        img = str((_v143_tarot_images(chat_id).get('ai') if '_v143_tarot_images' in globals() else '') or '')
        mid = await _v146_send_or_update_ai_message(context, chat_id, rid, op, reply_to=q.message.message_id if q.message else None, image_id=img)
        try:
            _v139_ai_inc(chat_id, int(q.from_user.id))
        except Exception:
            pass
        sec = int(cfg.get('tarot_cleanup_ai_sec', 0) or 0)
        if sec and mid:
            asyncio.create_task(_v139_auto_delete(context.bot, chat_id, int(mid), sec))
        save_all_states()
    except Exception as e:
        logger.exception('Error Opinión tarotista IA V146')
        if wait:
            try:
                await wait.edit_text(f'❌ Error IA: {type(e).__name__}')
            except Exception:
                pass
        else:
            await q.answer('Error IA. Revisa logs.', show_alert=True)
    raise _V146Stop


async def _v146_ai_reaction_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not q.from_user:
        return
    data = q.data or ''
    if not data.startswith('tar|air|'):
        return
    parts = data.split('|')
    if len(parts) < 4:
        return
    chat_id = int(update.effective_chat.id)
    rid = parts[2]
    kind = parts[3]
    store = _v146_ai_store(chat_id)
    op = store.get(rid)
    if not isinstance(op, dict):
        await q.answer('No encuentro esta opinión IA.', show_alert=True)
        raise _V146Stop
    uid = str(int(q.from_user.id))
    key = 'likes' if kind == 'like' else 'flips'
    arr = op.setdefault(key, [])
    if uid in arr:
        await q.answer('Ya habías pulsado aquí ✅')
    else:
        arr.append(uid)
        save_all_states()
        await q.answer('Guardado ✨')
    await _v146_send_or_update_ai_message(context, chat_id, rid, op)
    raise _V146Stop


_old_build_application_v146 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v146()
    app.add_handler(CallbackQueryHandler(_v146_tarot_ai_router, pattern=r'^tar\|ai\|'), group=-7900000000)
    app.add_handler(CallbackQueryHandler(_v146_ai_reaction_router, pattern=r'^tar\|air\|'), group=-7900000000)
    logger.info('V146 Tarot elección 2+1 y reacciones IA cargado')
    return app


# =========================================================
# V147 - Definitiva fixes: Tarot guardar/IA sin borrar, comandos por grupo,
#        DJ ON abre directo+play, likes canciones con recuento, imagen lectura,
#        texto barajeo corto
# =========================================================
try:
    from telegram.ext import ApplicationHandlerStop as _V147Stop
except Exception:
    _V147Stop = Exception


def _v147_tarot_cfg(chat_id: int) -> Dict[str, Any]:
    cfg = _v139_tarot_cfg(chat_id) if '_v139_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)
    cfg.setdefault('tarot_result_reactions', {})
    return cfg


def _v147_result_store(chat_id: int) -> Dict[str, Any]:
    cfg = _v147_tarot_cfg(chat_id)
    store = cfg.setdefault('tarot_result_reactions', {})
    if not isinstance(store, dict):
        store = {}; cfg['tarot_result_reactions'] = store
    return store


def _v147_result_op(chat_id: int, rid: str) -> Dict[str, Any]:
    store = _v147_result_store(chat_id)
    op = store.setdefault(rid, {'likes': [], 'flips': []})
    op.setdefault('likes', [])
    op.setdefault('flips', [])
    return op


def _v147_result_counts_text(chat_id: int, rid: str) -> str:
    op = _v147_result_op(chat_id, rid)
    return f"\n\n❤️ Me gusta: <b>{len(op.get('likes') or [])}</b>\n🤯 Flipando estoy: <b>{len(op.get('flips') or [])}</b>"


def _v147_final_markup(chat_id: int, rid: str) -> InlineKeyboardMarkup:
    rows = []
    if bool(_v139_tarot_cfg(chat_id).get('tarot_ai_enabled', True)) if '_v139_tarot_cfg' in globals() else True:
        rows.append([InlineKeyboardButton('🔮 Opinión de tarotista IA', callback_data=f'tar|ai|{rid}')])
    rows.append([
        InlineKeyboardButton('❤️ Me gusta', callback_data=f'tar|rr|{rid}|like'),
        InlineKeyboardButton('🤯 Flipando estoy', callback_data=f'tar|rr|{rid}|flip'),
    ])
    rows.append([
        InlineKeyboardButton('🃏 Ver cartas', callback_data=f'tar|showdraw|{rid}'),
        InlineKeyboardButton('💾 Guardar resumen', callback_data=f'tar|save|{rid}'),
    ])
    return InlineKeyboardMarkup(rows)


def _v147_result_caption_or_text(base: str, chat_id: int, rid: str, *, max_len: int = 3900) -> str:
    full = (base or '') + _v147_result_counts_text(chat_id, rid)
    return full[:max_len]


async def _v147_update_result_message(context: ContextTypes.DEFAULT_TYPE, chat_id: int, rid: str) -> None:
    cfg = _v129_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid)
    if not isinstance(res, dict):
        return
    mid = int(res.get('message_id') or 0)
    if not mid:
        return
    base = str(res.get('text') or '')
    markup = _v147_final_markup(chat_id, rid)
    try:
        if res.get('photo'):
            await context.bot.edit_message_caption(chat_id=chat_id, message_id=mid, caption=_v147_result_caption_or_text(base, chat_id, rid, max_len=980), parse_mode=ParseMode.HTML, reply_markup=markup)
        else:
            await context.bot.edit_message_text(chat_id=chat_id, message_id=mid, text=_v147_result_caption_or_text(base, chat_id, rid), parse_mode=ParseMode.HTML, reply_markup=markup)
    except BadRequest as e:
        if 'not modified' not in str(e).lower():
            logger.warning('No pude actualizar resultado Tarot %s: %s', rid, e)
    except Exception:
        logger.exception('No pude actualizar resultado Tarot %s', rid)


# Override final para guardar message_id/texto y mantener reacciones/botones.
_old_v147_show_final = _v129_show_final
async def _v129_show_final(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any]) -> None:  # type: ignore[override]
    draws = session.get('draws', [])
    if not draws:
        return
    if bool(_v137_tarot_cfg(chat_id).get('tarot_keep_only_final', True)) if '_v137_tarot_cfg' in globals() else True:
        try:
            await _v137_delete_intermediate(context, chat_id, session, include_result=False)
        except Exception:
            pass
    result_id = secrets.token_hex(4)
    session['result_id'] = result_id
    cfg = _v129_tarot_cfg(chat_id)
    cards = [c['id'] for c in draws]
    text = _v138_result_text(user, session, draws) if '_v138_result_text' in globals() else _v130_result_text(user, session, draws)
    res = {
        'user_id': int(user.id),
        'user_name': display_name(user),
        'cards': cards,
        'likes': [],
        'flips': [],
        'ts': int(time.time()),
        'text': text,
    }
    cfg.setdefault('tarot_results', {})[result_id] = res
    _v147_result_op(chat_id, result_id)
    save_all_states()
    img = str((_v143_tarot_images(chat_id).get('result') if '_v143_tarot_images' in globals() else '') or '')
    try:
        if img:
            msg = await context.bot.send_photo(chat_id, photo=img, caption=_v147_result_caption_or_text(text, chat_id, result_id, max_len=980), parse_mode=ParseMode.HTML, reply_markup=_v147_final_markup(chat_id, result_id))
            res['photo'] = True
        else:
            msg = await context.bot.send_message(chat_id, _v147_result_caption_or_text(text, chat_id, result_id), parse_mode=ParseMode.HTML, reply_markup=_v147_final_markup(chat_id, result_id))
            res['photo'] = False
    except Exception:
        logger.exception('No pude enviar resultado Tarot V147')
        msg = await context.bot.send_message(chat_id, _v147_result_caption_or_text(text, chat_id, result_id), parse_mode=ParseMode.HTML, reply_markup=_v147_final_markup(chat_id, result_id))
        res['photo'] = False
    res['message_id'] = int(msg.message_id)
    session['final_msg_id'] = int(msg.message_id)
    try: await register_bot_message(chat_id, msg.message_id)
    except Exception: pass
    save_all_states()
    try:
        _v133_mark_tarot_finished(chat_id)
    except Exception:
        pass
    sec = int((_v139_tarot_cfg(chat_id).get('tarot_cleanup_result_sec', 0) if '_v139_tarot_cfg' in globals() else 0) or 0)
    if sec:
        # Se mantiene hasta el tiempo configurado. Guardar/IA no lo borran.
        asyncio.create_task(_v139_auto_delete(context.bot, chat_id, int(msg.message_id), sec) if '_v139_auto_delete' in globals() else _v137_safe_delete(context.bot, chat_id, int(msg.message_id)))


async def _v147_result_reaction_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|rr|'):
        return
    parts = q.data.split('|')
    chat_id = int(update.effective_chat.id)
    rid = parts[2] if len(parts) > 2 else ''
    kind = parts[3] if len(parts) > 3 else 'like'
    key = 'likes' if kind == 'like' else 'flips'
    op = _v147_result_op(chat_id, rid)
    uid = int(q.from_user.id)
    arr = [int(x) for x in op.get(key, [])]
    if uid in arr:
        await q.answer('Ya lo habías pulsado ✅')
    else:
        arr.append(uid); op[key] = arr; save_all_states(); await q.answer('Guardado ✨')
    await _v147_update_result_message(context, chat_id, rid)
    raise _V147Stop


# Guardar resumen: NO borra resultado, crea imagen descargable en el grupo y conserva botones del resultado.
async def _v147_tarot_save_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|save|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = q.data.split('|', 2)[2]
    try:
        cfg = _v129_tarot_cfg(chat_id)
        res = cfg.setdefault('tarot_results', {}).get(rid)
        if not isinstance(res, dict):
            await q.answer('No encuentro esta tirada.', show_alert=True); raise _V147Stop
        cards = list(res.get('cards') or [])
        if not cards:
            await q.answer('Esta tirada no tiene cartas guardadas.', show_alert=True); raise _V147Stop
        await q.answer('Creando imagen para guardar…')
        img = await _v139_make_result_image(context, chat_id, res.get('user_name') or display_name(q.from_user), cards) if '_v139_make_result_image' in globals() else await _v137_make_result_image(context, chat_id, res.get('user_name') or display_name(q.from_user), cards)
        if not img:
            await q.answer('No pude crear la imagen.', show_alert=True); raise _V147Stop
        msg = await context.bot.send_photo(chat_id, photo=img, caption='💾 Resumen listo. Toca la imagen y guárdala en tu galería.')
        try: await register_bot_message(chat_id, msg.message_id)
        except Exception: pass
        # No tocar/borrar el mensaje de resultado.
        sec = int((_v139_tarot_cfg(chat_id).get('tarot_cleanup_result_sec', 0) if '_v139_tarot_cfg' in globals() else 0) or 0)
        if sec:
            asyncio.create_task(_v139_auto_delete(context.bot, chat_id, int(msg.message_id), sec) if '_v139_auto_delete' in globals() else _v137_safe_delete(context.bot, chat_id, int(msg.message_id)))
        raise _V147Stop
    except _V147Stop:
        raise
    except Exception:
        logger.exception('Error guardar resumen Tarot V147')
        try: await q.answer('Error creando imagen. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V147Stop


# Opinión IA: mensaje independiente, no borra resultado, siempre con botones/recuentos.
async def _v147_tarot_ai_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|ai|'):
        return
    chat_id = int(update.effective_chat.id)
    rid = q.data.split('|', 2)[2]
    cfg = _v139_tarot_cfg(chat_id) if '_v139_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)
    res = cfg.setdefault('tarot_results', {}).get(rid)
    if not isinstance(res, dict):
        await q.answer('No encuentro esa tirada.', show_alert=True); raise _V147Stop
    ok, reason = _v139_can_use_ai(chat_id, int(q.from_user.id)) if '_v139_can_use_ai' in globals() else (True, '')
    store = _v146_ai_store(chat_id) if '_v146_ai_store' in globals() else cfg.setdefault('tarot_ai_opinions', {})
    cached = store.get(rid)
    if isinstance(cached, dict):
        await q.answer('Opinión ya generada ✅')
        img = str((_v143_tarot_images(chat_id).get('ai') if '_v143_tarot_images' in globals() else '') or '')
        await _v146_send_or_update_ai_message(context, chat_id, rid, cached, reply_to=None, image_id=img)
        raise _V147Stop
    if not ok:
        await q.answer(reason, show_alert=True); raise _V147Stop
    cards_ids = list(res.get('cards') or [])
    cards = []
    for cid in cards_ids:
        c = _v138_card_by_id(cid) if '_v138_card_by_id' in globals() else next((x for x in TAROT_CARDS_V129 if x['id']==cid), None)
        if c: cards.append(c)
    if not cards:
        await q.answer('Esta tirada no tiene cartas guardadas.', show_alert=True); raise _V147Stop
    user_name = str(res.get('user_name') or display_name(q.from_user))
    labels = ['Pasado','Presente','Futuro'] if len(cards)==3 else ['Carta del día']
    cards_txt = '\n'.join([f'{labels[i] if i < len(labels) else "Carta"}: {c["name"]} — {c.get("meaning", c.get("short", ""))}' for i,c in enumerate(cards)])
    prompt = (
        'Actúa como un tarotista profesional, cercano, elegante y claro. '
        'Interpreta la tirada para la persona consultante, no para el bot ni para EL PLAN. '
        'Puedes referirte a la persona como "la persona que ha hecho la tirada" o usar su nombre si queda natural. '
        'No digas que el bot consulta. No inventes datos personales. '
        'Haz una lectura breve, misteriosa y útil, con conclusión final.\n\n'
        f'Persona consultante: {user_name}\n'
        f'Cartas:\n{cards_txt}'
    )
    await q.answer('Consultando al tarotista IA…')
    wait = await context.bot.send_message(chat_id, f'🔮 Consultando al tarotista IA para <b>{h(user_name)}</b>…', parse_mode=ParseMode.HTML)
    try:
        ans = await (_v57_cerebrito_answer(chat_id, prompt, max_output_tokens=900) if '_v57_cerebrito_answer' in globals() else _ai_openai_response(chat_id, prompt, max_output_tokens=900))
        op = {'answer': ans, 'likes': [], 'flips': [], 'message_id': 0, 'ts': int(time.time()), 'result_id': rid}
        store[rid] = op; save_all_states()
        img = str((_v143_tarot_images(chat_id).get('ai') if '_v143_tarot_images' in globals() else '') or '')
        # Reutiliza el mensaje de "consultando" para la opinión; NO toca el resultado.
        try:
            if img:
                await wait.delete()
                sent_mid = await _v146_send_or_update_ai_message(context, chat_id, rid, op, reply_to=None, image_id=img)
            else:
                op['message_id'] = int(wait.message_id)
                await _v146_send_or_update_ai_message(context, chat_id, rid, op, reply_to=None, image_id='')
        except Exception:
            await _v146_send_or_update_ai_message(context, chat_id, rid, op, reply_to=None, image_id=img)
        try: _v139_ai_inc(chat_id, int(q.from_user.id))
        except Exception: pass
        sec = int(cfg.get('tarot_cleanup_ai_sec', 0) or 0)
        mid = int(op.get('message_id') or 0)
        if sec and mid:
            asyncio.create_task(_v139_auto_delete(context.bot, chat_id, mid, sec) if '_v139_auto_delete' in globals() else _v137_safe_delete(context.bot, chat_id, mid))
        save_all_states()
    except Exception as e:
        logger.exception('Error Opinión tarotista IA V147')
        try: await wait.edit_text(f'❌ Error IA: {type(e).__name__}')
        except Exception: pass
        try: await q.answer('Error IA. Revisa logs.', show_alert=True)
        except Exception: pass
    raise _V147Stop


# Forzar comandos/botones recurrentes a ejecutarse en el grupo del mensaje, no en un chat_id codificado antiguo.
async def _v147_reccmd_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not (q.data or '').startswith('reccmd|'):
        return
    parts = q.data.split('|', 2)
    if len(parts) < 3:
        return
    cmd = (_v112_clean_cmd(parts[2]) if '_v112_clean_cmd' in globals() else str(parts[2]).strip().lower().lstrip('/'))
    # Grupo real donde está el botón.
    real_chat_id = int(q.message.chat_id) if q.message else int(update.effective_chat.id)
    if cmd in {'vitamina','horoscopo','horóscopo','tiempecito','resumenia','historia','salseo'} or (_v112_ai_command_data(real_chat_id, cmd) if '_v112_ai_command_data' in globals() else None):
        data = _v112_ai_command_data(real_chat_id, cmd) if '_v112_ai_command_data' in globals() else None
        if isinstance(data, dict):
            try:
                needs = _v112_prompt_needs_query(data) if '_v112_prompt_needs_query' in globals() else any(x in str(data.get('prompt','')) for x in ('{query}','{consulta}','{texto}'))
                if needs:
                    await q.answer('Responde al mensaje 👇')
                    ask = _v112_ask_text(q.from_user, data) if '_v112_ask_text' in globals() else f'{q.from_user.mention_html()} {h(data.get("ask") or "Escribe el dato y envía.")}'
                    set_config_pending(q.from_user.id, {'kind': 'ai_custom_command_query_v112', 'chat_id': real_chat_id, 'cmd': cmd})
                    msg = await context.bot.send_message(chat_id=real_chat_id, text=ask, parse_mode=ParseMode.HTML, reply_markup=ForceReply(selective=True), reply_to_message_id=q.message.message_id if q.message else None)
                    try: _v85_schedule_delete(context, real_chat_id, msg.message_id, _v85_ask_delete_seconds(real_chat_id))
                    except Exception: pass
                else:
                    await q.answer('Ejecutando IA…')
                    await _v112_send_ai_result(context, real_chat_id, q.from_user, data, '', reply_to=None)
            except Exception:
                logger.exception('Error IA recurrente V147 /%s chat %s', cmd, real_chat_id)
                await q.answer('Error ejecutando IA. Mira logs.', show_alert=True)
            raise _V147Stop
    return


# DJ ON: activa directo, intenta abrir videochat y reproduce si hay cola.
async def _v147_dj_live_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or (q.data or '') not in {'panel_live_toggle','panel_pause_resume'}:
        return
    chat_id = int(update.effective_chat.id)
    st = get_state(chat_id)
    try:
        try:
            live_result = await VOICE.toggle_live(chat_id)
            st.live_enabled = bool(live_result)
        except Exception:
            st.live_enabled = not bool(st.live_enabled)
        save_all_states()
        url = None
        try: url = await build_live_join_url(context.bot, chat_id)
        except Exception: url = None
        if st.live_enabled and st.queue and not st.now_playing:
            try:
                await simulate_panel_next(chat_id, reason='live_on_auto_play')
            except Exception:
                logger.exception('No se pudo iniciar reproducción automática al activar LIVE')
        if url:
            try:
                await q.answer('Abriendo videochat…', url=url)
            except Exception:
                await q.answer('LIVE ON. Abre el videochat desde el nombre del grupo.', show_alert=True)
        else:
            await q.answer('LIVE ON. Pulsa el nombre del grupo y abre el videochat manualmente.', show_alert=True)
        try:
            await ensure_panel(context.bot, chat_id)
        except Exception:
            pass
        raise _V147Stop
    except _V147Stop:
        raise
    except Exception:
        logger.exception('Error DJ live V147')
        try: await q.answer('Error al activar directo. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V147Stop


# Likes de avisos de canciones con recuento dentro del mismo mensaje.
def _v147_dj_like_key_from_track(track: Track) -> str:
    try:
        return _dj_track_like_key_v20(asdict(track))
    except Exception:
        return track_key(asdict(track)) if 'track_key' in globals() else str(hash(track.title))


def _v147_dj_like_count(chat_id: int, key: str) -> int:
    row = admin_cfg(chat_id).setdefault('dj_track_likes', {}).get(key, {})
    return len(row.get('users') or [])


def _v147_dj_announce_text(chat_id: int, track: Track, key: str) -> str:
    txt = "🎧 <b>EN DIRECTO AHORA</b>\n\n" + f"🎶 <b>{h(track.title)}</b>"
    if track.performer:
        txt += f"\n👤 <i>{h(track.performer)}</i>"
    txt += f"\n\n❤️ Me gusta: <b>{_v147_dj_like_count(chat_id, key)}</b>"
    return txt


def _v147_dj_announce_markup(mid: int) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([[InlineKeyboardButton('❤️ Me gusta', callback_data=f'djlike_msg|{int(mid)}'), InlineKeyboardButton('🎛 Mesa', callback_data='panel_home')]])


async def _send_dj_now_announce_v24(bot, chat_id: int, track: Track) -> None:  # type: ignore[override]
    if not _dj_announce_enabled_v24(chat_id):
        return
    try:
        key = _v147_dj_like_key_from_track(track)
        cfg = admin_cfg(chat_id)
        likes = cfg.setdefault('dj_track_likes', {})
        row = likes.setdefault(key, {'title': track.title, 'users': [], 'track': asdict(track)})
        row['title'] = track.title; row['track'] = asdict(track)
        msg = await bot.send_message(chat_id=chat_id, text=_v147_dj_announce_text(chat_id, track, key), parse_mode=ParseMode.HTML)
        ann = cfg.setdefault('dj_announce_messages', {})
        ann[str(msg.message_id)] = {'key': key, 'track': asdict(track)}
        await bot.edit_message_reply_markup(chat_id=chat_id, message_id=msg.message_id, reply_markup=_v147_dj_announce_markup(msg.message_id))
        save_all_states()
        await register_bot_message(chat_id, msg.message_id)
    except Exception:
        logger.exception('No se pudo mandar aviso de canción V147')


async def _v147_djlike_msg_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('djlike_msg|'):
        return
    chat_id = int(update.effective_chat.id)
    try: mid = int(q.data.split('|')[1])
    except Exception: mid = int(q.message.message_id) if q.message else 0
    cfg = admin_cfg(chat_id)
    ann = cfg.setdefault('dj_announce_messages', {})
    info = ann.get(str(mid)) or {}
    track_data = info.get('track') or get_state(chat_id).now_playing
    if not track_data:
        await q.answer('No encuentro esta canción.', show_alert=True); raise _V147Stop
    track = Track(**track_data)
    key = info.get('key') or _v147_dj_like_key_from_track(track)
    likes = cfg.setdefault('dj_track_likes', {})
    row = likes.setdefault(key, {'title': track.title, 'users': [], 'track': asdict(track)})
    row['title'] = track.title; row['track'] = asdict(track)
    users = [int(x) for x in row.get('users', [])]
    uid = int(q.from_user.id)
    if uid in users:
        await q.answer('Ya le habías dado ❤️')
    else:
        users.append(uid); row['users'] = users; save_all_states(); await q.answer('❤️ Sumado')
    try:
        await context.bot.edit_message_text(chat_id=chat_id, message_id=mid, text=_v147_dj_announce_text(chat_id, track, key), parse_mode=ParseMode.HTML, reply_markup=_v147_dj_announce_markup(mid))
    except Exception:
        pass
    raise _V147Stop


# Imagen configurable encima de "Lectura del camino".
def _v147_assets_markup(chat_id: int) -> InlineKeyboardMarkup:
    base = _v132_assets_markup(chat_id) if '_v132_assets_markup' in globals() else InlineKeyboardMarkup([])
    rows = [list(r) for r in getattr(base, 'inline_keyboard', [])]
    rows.insert(2, [InlineKeyboardButton('🕯 Imagen lectura del camino', callback_data=f't32|up|{chat_id}|reading')])
    return InlineKeyboardMarkup(rows)


_old_v147_assets_markup = _v132_assets_markup if '_v132_assets_markup' in globals() else None
def _v132_assets_markup(chat_id: int) -> InlineKeyboardMarkup:  # type: ignore[override]
    if callable(_old_v147_assets_markup):
        rows = [list(r) for r in _old_v147_assets_markup(chat_id).inline_keyboard]
    else:
        rows = []
    if not any(any(getattr(b, 'callback_data', '') == f't32|up|{chat_id}|reading' for b in r) for r in rows):
        rows.insert(2, [InlineKeyboardButton('🕯 Imagen lectura del camino', callback_data=f't32|up|{chat_id}|reading')])
    return InlineKeyboardMarkup(rows)


_old_v147_tarot_images = _v143_tarot_images if '_v143_tarot_images' in globals() else _v130_tarot_images
def _v143_tarot_images(chat_id: int) -> Dict[str, Any]:  # type: ignore[override]
    imgs = _old_v147_tarot_images(chat_id)
    imgs.setdefault('reading', '')
    return imgs


_old_v147_save_image_target = _v143_save_image_target if '_v143_save_image_target' in globals() else None
async def _v147_save_image_target(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    pending = get_config_pending(update.effective_user.id) if update.effective_user else None
    if pending and pending.get('kind') in ('tarot_image_upload_v132','tarot_image_upload_v130') and str(pending.get('target')) == 'reading':
        # Reutilizamos el guardado genérico cambiando target permitido temporalmente.
        if not update.message or not (update.message.photo or update.message.document):
            await update.message.reply_html('Necesito una imagen PNG/JPG como foto o documento.')
            raise _V147Stop
        chat_id = int(pending.get('chat_id') or 0)
        src = None
        if update.message.photo: src = update.message.photo[-1].file_id
        elif update.message.document: src = update.message.document.file_id
        processed = await _v136_processed_tarot_image(context, chat_id, src, role='lobby') if '_v136_processed_tarot_image' in globals() else src
        try:
            preview = await context.bot.send_photo(update.effective_chat.id, photo=processed or src, caption='✅ Imagen recibida para Lectura del camino.')
            fid = preview.photo[-1].file_id if preview.photo else (processed or src)
            try:
                await asyncio.sleep(1.2); await context.bot.delete_message(update.effective_chat.id, preview.message_id)
            except Exception: pass
        except Exception:
            fid = processed or src
        _v143_tarot_images(chat_id)['reading'] = fid
        save_all_states(); pop_config_pending(update.effective_user.id)
        await update.message.reply_html('✅ Guardada imagen de <b>Lectura del camino</b>.')
        raise _V147Stop
    if callable(_old_v147_save_image_target):
        return await _old_v147_save_image_target(update, context)


_old_v147_send_pair = _v129_send_pair
async def _v129_send_pair(context: ContextTypes.DEFAULT_TYPE, chat_id: int, user, session: Dict[str, Any], *, new_pair: bool = True) -> None:  # type: ignore[override]
    # Si hay imagen de lectura, la usamos en el primer mensaje en lugar de texto pelado.
    if new_pair:
        try:
            await _v129_delete_msg(context.bot, chat_id, session.get('draws_msg_id'))
            await _v129_delete_msg(context.bot, chat_id, session.get('choice_msg_id'))
        except Exception: pass
        session['draws_msg_id'] = 0; session['choice_msg_id'] = 0
    img = str((_v143_tarot_images(chat_id).get('reading') if '_v143_tarot_images' in globals() else '') or '')
    if img:
        try:
            msg = await context.bot.send_photo(chat_id, photo=img, caption=_v129_draws_text(session)[:1000], parse_mode=ParseMode.HTML)
            session['draws_msg_id'] = int(msg.message_id)
            try: await register_bot_message(chat_id, msg.message_id)
            except Exception: pass
            # Ahora mandamos elección igual que el viejo, pero evitando que cree de nuevo draws: replicamos una parte simple.
            imgs = _v143_tarot_images(chat_id) if '_v143_tarot_images' in globals() else _v130_tarot_images(chat_id)
            back = str(imgs.get('back') or '')
            caption = _v129_choice_text(session, user)
            if back:
                try:
                    choice_msg = await context.bot.send_photo(chat_id, photo=back, caption=caption, parse_mode=ParseMode.HTML, reply_markup=_v129_choice_markup())
                except Exception:
                    choice_msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=_v129_choice_markup())
            else:
                choice_msg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML, reply_markup=_v129_choice_markup())
            session['choice_msg_id'] = int(choice_msg.message_id)
            try: await register_bot_message(chat_id, choice_msg.message_id)
            except Exception: pass
            return
        except Exception:
            logger.exception('No se pudo usar imagen lectura; fallback old')
    return await _old_v147_send_pair(context, chat_id, user, session, new_pair=new_pair)


# Barajeo corto definitivo.
async def _v147_tarot_start_router(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    q = update.callback_query
    if not q or not update.effective_chat or not (q.data or '').startswith('tar|start|'):
        return
    parts = q.data.split('|')
    chat_id = int(update.effective_chat.id); user = q.from_user
    mode = parts[2] if len(parts) > 2 else 'day'
    if mode not in ('ppf','day'): mode = 'day'
    try:
        try:
            locked, reason = _v133_is_chat_locked(chat_id, int(user.id))
            if locked:
                await q.answer(reason, show_alert=True); raise _V147Stop
            _v133_mark_tarot_started(chat_id, int(user.id))
        except _V147Stop: raise
        except Exception: pass
        ok, reason = _v129_can_play(chat_id, int(user.id), mode)
        if not ok:
            await q.answer(reason, show_alert=True); raise _V147Stop
        skey = _v129_session_key(chat_id, int(user.id))
        old = TAROT_SESSIONS_V129.get(skey)
        if isinstance(old, dict):
            try: await _v137_delete_intermediate(context, chat_id, old, include_result=False)
            except Exception: pass
        session = {'chat_id': chat_id, 'user_id': int(user.id), 'mode': mode, 'stage': 0, 'draws': [], 'deck': _v135_mystic_shuffle_deck(chat_id, int(user.id)) if '_v135_mystic_shuffle_deck' in globals() else [c['id'] for c in TAROT_CARDS_V129], 'started_ts': int(time.time()), 'lobby_msg_id': int(q.message.message_id) if q.message else 0}
        TAROT_SESSIONS_V129[skey] = session
        cfg = _v137_tarot_cfg(chat_id) if '_v137_tarot_cfg' in globals() else _v129_tarot_cfg(chat_id)
        await q.answer('Barajando…')
        if bool(cfg.get('tarot_delete_lobby_on_start', True)) and q.message:
            await _v137_safe_delete(context.bot, chat_id, q.message.message_id)
            session['lobby_msg_id'] = 0
        imgs = _v143_tarot_images(chat_id) if '_v143_tarot_images' in globals() else _v130_tarot_images(chat_id)
        shuffle_id = str(imgs.get('shuffle') or imgs.get('back') or '')
        stage = _v129_stage_name(session)
        caption = (
            f'🔮 <b>Las cartas se están mezclando para {h(stage)}</b>.\n\n'
            '🌙 Respira despacio. Concéntrate en lo que quieres entender.\n'
            '🃏 El taco se mueve, los arcanos se cruzan y algo empieza a colocarse.'
        )
        if shuffle_id:
            try:
                photo = await _v136_processed_tarot_image(context, chat_id, shuffle_id, role='shuffle') if '_v136_processed_tarot_image' in globals() else shuffle_id
                smsg = await context.bot.send_photo(chat_id, photo=photo or shuffle_id, caption=caption, parse_mode=ParseMode.HTML)
            except Exception:
                smsg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
        else:
            smsg = await context.bot.send_message(chat_id, caption, parse_mode=ParseMode.HTML)
        session['shuffle_msg_id'] = int(smsg.message_id)
        delay = int((_v141_tarot_cfg(chat_id).get('tarot_shuffle_seconds', 10) if '_v141_tarot_cfg' in globals() else cfg.get('tarot_shuffle_seconds', 10)) or 10)
        await asyncio.sleep(max(1, delay))
        if bool(cfg.get('tarot_delete_shuffle_msg', True)):
            await _v137_safe_delete(context.bot, chat_id, session.get('shuffle_msg_id')); session['shuffle_msg_id'] = 0
        await _v129_send_pair(context, chat_id, user, session, new_pair=True)
        raise _V147Stop
    except _V147Stop:
        raise
    except Exception:
        logger.exception('Error start Tarot V147')
        try: await q.answer('Error Tarot. Revisa logs.', show_alert=True)
        except Exception: pass
        raise _V147Stop


_old_build_application_v147 = build_application

def build_application() -> Application:  # type: ignore[override]
    app = _old_build_application_v147()
    # Tarot: prioridades más altas que todas las versiones viejas.
    app.add_handler(CallbackQueryHandler(_v147_tarot_start_router, pattern=r'^tar\|start\|'), group=-9000000000)
    app.add_handler(CallbackQueryHandler(_v147_tarot_save_router, pattern=r'^tar\|save\|'), group=-9000000000)
    app.add_handler(CallbackQueryHandler(_v147_tarot_ai_router, pattern=r'^tar\|ai\|'), group=-9000000000)
    app.add_handler(CallbackQueryHandler(_v146_ai_reaction_router, pattern=r'^tar\|air\|'), group=-9000000000)
    app.add_handler(CallbackQueryHandler(_v147_result_reaction_router, pattern=r'^tar\|rr\|'), group=-9000000000)
    app.add_handler(MessageHandler(filters.ChatType.PRIVATE & (filters.PHOTO | filters.Document.IMAGE), _v147_save_image_target), group=-9000000000)
    # IA/recurrentes por grupo real.
    app.add_handler(CallbackQueryHandler(_v147_reccmd_router, pattern=r'^reccmd\|'), group=-9000000000)
    # DJ.
    app.add_handler(CallbackQueryHandler(_v147_dj_live_router, pattern=r'^(panel_live_toggle|panel_pause_resume)$'), group=-9000000000)
    app.add_handler(CallbackQueryHandler(_v147_djlike_msg_router, pattern=r'^djlike_msg\|'), group=-9000000000)
    logger.info('V147 definitivo: Tarot/DJ/IA fixes cargado')
    return app


# Arranque real del bot al final V147.
def main() -> None:
    try:
        _v63_ensure_private_blocks()
    except Exception:
        pass
    try:
        _v72_ensure_dj_block()
    except Exception:
        pass
    try:
        _v110_ensure_manual_block()
    except Exception:
        pass
    try:
        _v129_ensure_tarot_block()
    except Exception:
        pass
    app = build_application()
    app.run_polling(drop_pending_updates=False)

if __name__ == "__main__":
    main()
